const { neon } = require("@neondatabase/serverless");
const sql = neon(process.env.DATABASE_URL);
(async () => {
  // Last QField photos by source
  const qf = await sql`
    SELECT source, MAX(created_at)::text as last_created, COUNT(*)::int as total
    FROM construction_qa_photos
    GROUP BY source
    ORDER BY last_created DESC
  `;
  console.log("=== construction_qa_photos by source ===");
  qf.forEach(r => console.log(r.source.padEnd(15), "last:", r.last_created, "total:", r.total));

