    SELECT MAX(created_at)::text as last_created, COUNT(*)::int as total
    FROM qfield_photo_validations
  `;
  console.log("\n=== qfield_photo_validations ===");
  console.log("Last entry:", qfv[0].last_created, "| Total:", qfv[0].total);

  // Last SharePoint ingest (check most recent sharepoint photo)
  const sp = await sql`
    SELECT MAX(created_at)::text as last_created, MAX(captured_at)::text as last_captured
    FROM construction_qa_photos
    WHERE source = ${"sharepoint"}
  `;
  console.log("\n=== Last SharePoint ingest ===");
  console.log("Last created_at:", sp[0].last_created);
  console.log("Last captured_at:", sp[0].last_captured);

  // Last QField ingest
  const qfi = await sql`
    SELECT MAX(created_at)::text as last_created, MAX(captured_at)::text as last_captured
    FROM construction_qa_photos
    WHERE source = ${"qfield"}
  `;
  console.log("\n=== Last QField ingest ===");
  console.log("Last created_at:", qfi[0].last_created);
  console.log("Last captured_at:", qfi[0].last_captured);

  // Recent activity log for ingestion events
  const activity = await sql`
    SELECT event_type, MAX(created_at)::text as last_at, COUNT(*)::int as cnt
    FROM construction_qa_activity
    WHERE event_type LIKE ${"photo%"}
    GROUP BY event_type
    ORDER BY last_at DESC
  `;
  console.log("\n=== Ingestion activity log ===");
  activity.forEach(a => console.log(a.event_type.padEnd(25), "last:", a.last_at, "count:", a.cnt));
})();
'

