const sql = neon(process.env.DATABASE_URL);
(async () => {
  // Check how many QField photos are NOT yet ingested
  const gap = await sql`
    SELECT COUNT(*)::int as cnt
    FROM qfield_photo_validations qpv
    WHERE qpv.feature_id IS NOT NULL
