          AND cqp.source = ${"qfield"}
      )
  `;
  console.log("QField photos pending ingestion:", gap[0].cnt);

  // When were they added?
  const recent = await sql`
    SELECT MIN(qpv.created_at)::text as oldest, MAX(qpv.created_at)::text as newest
    FROM qfield_photo_validations qpv
    WHERE qpv.feature_id IS NOT NULL
      AND NOT EXISTS (
        SELECT 1 FROM construction_qa_photos cqp
        WHERE cqp.storage_key = qpv.photo_key
          AND cqp.source = ${"qfield"}
      )
  `;
  if (recent[0].oldest) {
    console.log("Date range:", recent[0].oldest, "→", recent[0].newest);
  }
})();
'

