/**
 * Accounting Settings API
 * GET  ?key=reporting_currency — get setting value
 * PUT  { key, value } — update setting
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { getSetting, setSetting } from '@/modules/accounting/services/currencyService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    const { key } = req.query;
    if (!key) return apiResponse.badRequest(res, 'key is required');
    const value = await getSetting(key as string);
    return apiResponse.success(res, { key, value });
  }

  if (req.method === 'PUT') {
    const userId = (req as unknown as { user?: { id: string } }).user?.id || 'system';
    const { key, value } = req.body;
    if (!key || !value) return apiResponse.badRequest(res, 'key and value required');
    await setSetting(key, value, userId);
    return apiResponse.success(res, { updated: true });
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'PUT']);
}

export default withAuth(withErrorHandler(handler));

/**
 * Account Transactions Export API
 * GET — export general ledger account detail as CSV
 *   ?account_code=XXXX           (required)
 *   ?period_start=YYYY-MM-DD     (required)
 *   ?period_end=YYYY-MM-DD       (required)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import { getAccountTransactions } from '@/modules/accounting/services/transactionReportingService';

/** Escape a string value for safe embedding in a CSV cell. */
function csvCell(value: string): string {
  return `"${value.replace(/"/g, '""')}"`;
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);

  const accountCode = req.query.account_code as string;
  const periodStart = req.query.period_start as string;
  const periodEnd = req.query.period_end as string;

  if (!accountCode) return apiResponse.badRequest(res, 'account_code is required');
  if (!periodStart) return apiResponse.badRequest(res, 'period_start is required');
  if (!periodEnd) return apiResponse.badRequest(res, 'period_end is required');

  try {
    const report = await getAccountTransactions(accountCode, periodStart, periodEnd);

    const csvLines = [
      `Date,Entry Number,Description,Debit,Credit,Balance,Source`,
      // Opening balance sentinel row
      [
        csvCell(periodStart),
        csvCell(''),
        csvCell('Opening Balance'),
        '',
        '',
        report.openingBalance.toFixed(2),
        csvCell(''),
      ].join(','),
      // Transaction rows
      ...report.transactions.map(r =>
        [
          csvCell(r.date),
          csvCell(r.entryNumber),
          csvCell(r.description),
          r.debit > 0 ? r.debit.toFixed(2) : '',
          r.credit > 0 ? r.credit.toFixed(2) : '',
          r.balance.toFixed(2),
          csvCell(r.source),
        ].join(',')
      ),
      // Closing balance sentinel row
      [
        csvCell(periodEnd),
        csvCell(''),
        csvCell('Closing Balance'),
        '',
        '',
        report.closingBalance.toFixed(2),
        csvCell(''),
      ].join(','),
    ];

    const csv = csvLines.join('\n');
    const filename = `account-transactions-${accountCode}-${new Date().toISOString().split('T')[0]}.csv`;

    res.setHeader('Content-Type', 'text/csv');
    res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);
    return res.status(200).send(csv);
  } catch (err) {
    log.error('Failed to export account transactions', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, 'Failed to export account transactions');
  }
}

export default withAuth(withErrorHandler(handler));

/**
 * Adjustment Actions API
 * POST — approve, cancel
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import { approveAdjustment, cancelAdjustment } from '@/modules/accounting/services/adjustmentService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
  }

  try {
    const { action, id } = req.body;
    const userId = (req as unknown as { user?: { id: string } }).user?.id || req.body.userId;
    if (!action || !id) return apiResponse.badRequest(res, 'action and id are required');

    switch (action) {
      case 'approve': {
        if (!userId) return apiResponse.badRequest(res, 'userId is required');
        const item = await approveAdjustment(id, userId);
        return apiResponse.success(res, item);
      }
      case 'cancel':
        await cancelAdjustment(id);
        return apiResponse.success(res, { status: 'cancelled' });
      default:
        return apiResponse.badRequest(res, `Unknown action: ${action}`);
    }
  } catch (err) {
    const msg = err instanceof Error ? err.message : 'Action failed';
    log.error('Adjustment action failed', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, msg);
  }
}

export default withAuth(withErrorHandler(handler));

/**
 * Accounting Adjustments API
 * GET  — list adjustments (filter by ?entityType=customer|supplier)
 * POST — create adjustment
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import { getAdjustments, createAdjustment } from '@/modules/accounting/services/adjustmentService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    const { entityType, status, limit, offset } = req.query;
    const result = await getAdjustments({
      entityType: entityType as string,
      status: status as string,
      limit: limit ? Number(limit) : undefined,
      offset: offset ? Number(offset) : undefined,
    });
    return apiResponse.success(res, result);
  }

  if (req.method === 'POST') {
    const userId = (req as unknown as { user?: { id: string } }).user?.id || req.body.userId;
    if (!userId) return apiResponse.badRequest(res, 'userId is required');
    try {
      const item = await createAdjustment(req.body, userId);
      return apiResponse.success(res, item);
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Create failed';
      log.error('Adjustment create failed', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, msg);
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

export default withAuth(withErrorHandler(handler));

/**
 * AP Aging Export API
 * GET — export accounts payable aging report as CSV
 *   ?as_at_date=YYYY-MM-DD   (optional, defaults to today)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import { getAPAging } from '@/modules/accounting/services/apAgingService';

/** Escape a string value for safe embedding in a CSV cell. */
function csvCell(value: string): string {
  return `"${value.replace(/"/g, '""')}"`;
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);

  try {
    const asAtDate = req.query.as_at_date ? String(req.query.as_at_date) : undefined;

    const buckets = await getAPAging(asAtDate);

    const totalCurrent = buckets.reduce((s, r) => s + r.current, 0);
    const total30 = buckets.reduce((s, r) => s + r.days30, 0);
    const total60 = buckets.reduce((s, r) => s + r.days60, 0);
    const total90 = buckets.reduce((s, r) => s + r.days90, 0);
    const total120Plus = buckets.reduce((s, r) => s + r.days120Plus, 0);
    const grandTotal = buckets.reduce((s, r) => s + r.total, 0);

    const csvLines = [
      'Supplier,Current,30 Days,60 Days,90 Days,120+ Days,Total',
      ...buckets.map(r =>
        [
          csvCell(r.entityName),
          r.current.toFixed(2),
          r.days30.toFixed(2),
          r.days60.toFixed(2),
          r.days90.toFixed(2),
          r.days120Plus.toFixed(2),
          r.total.toFixed(2),
        ].join(',')
      ),
      [
        csvCell('TOTALS'),
        totalCurrent.toFixed(2),
        total30.toFixed(2),
        total60.toFixed(2),
        total90.toFixed(2),
        total120Plus.toFixed(2),
        grandTotal.toFixed(2),
      ].join(','),
    ];

    const csv = csvLines.join('\n');
    const filename = `ap-aging-${new Date().toISOString().split('T')[0]}.csv`;

    res.setHeader('Content-Type', 'text/csv');
    res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);
    return res.status(200).send(csv);
  } catch (err) {
    log.error('Failed to export AP aging', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, 'Failed to export AP aging');
  }
}

export default withAuth(withErrorHandler(handler));
/**
 * AP Aging Report API
 * GET /api/accounting/ap-aging - AP aging buckets by supplier
 * GET /api/accounting/ap-aging?supplier_id=123 - Aging detail for one supplier
