 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import { getAuditTrail } from '@/modules/accounting/services/transactionReportingService';

/** Escape a string value for safe embedding in a CSV cell. */
function csvCell(value: string): string {
  return `"${value.replace(/"/g, '""')}"`;
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);

  const periodStart = req.query.period_start as string;
  const periodEnd = req.query.period_end as string;

  if (!periodStart) return apiResponse.badRequest(res, 'period_start is required');
  if (!periodEnd) return apiResponse.badRequest(res, 'period_end is required');

  try {
    const rows = await getAuditTrail(periodStart, periodEnd);

    const totalDebit = rows.reduce((s, r) => s + r.totalDebit, 0);
    const totalCredit = rows.reduce((s, r) => s + r.totalCredit, 0);

    const csvLines = [
      'Entry Date,Entry Number,Description,Source,Status,Total Debit,Total Credit,Created By,Created At',
      ...rows.map(r =>
        [
          csvCell(r.entryDate),
          csvCell(r.entryNumber),
          csvCell(r.description),
          csvCell(r.source),
          csvCell(r.status),
          r.totalDebit.toFixed(2),
          r.totalCredit.toFixed(2),
          csvCell(r.createdBy),
          csvCell(r.createdAt),
        ].join(',')
      ),
      [
        csvCell(''),
        csvCell('TOTALS'),
        csvCell(''),
        csvCell(''),
        csvCell(''),
        totalDebit.toFixed(2),
        totalCredit.toFixed(2),
        csvCell(''),
        csvCell(''),
      ].join(','),
    ];

    const csv = csvLines.join('\n');
    const filename = `audit-trail-${new Date().toISOString().split('T')[0]}.csv`;

    res.setHeader('Content-Type', 'text/csv');
    res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);
    return res.status(200).send(csv);
  } catch (err) {
    log.error('Failed to export audit trail', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, 'Failed to export audit trail');
  }
}

export default withAuth(withErrorHandler(handler));
/**
 * Balance Sheet Export API
 * GET — export balance sheet as CSV
 *
 * Query params:
 *   as_at_date     YYYY-MM-DD  required
 *   cost_centre_id UUID        optional
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import { getBalanceSheet } from '@/modules/accounting/services/financialReportingService';

/** Escape a value for CSV — wraps in double-quotes and escapes internal quotes. */
function csvVal(value: string | number): string {
  const str = String(value);
  return `"${str.replace(/"/g, '""')}"`;
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method!, ['GET']);

  const asAtDate = req.query.as_at_date as string;
  const costCentreId = req.query.cost_centre_id as string | undefined;

  if (!asAtDate) return apiResponse.badRequest(res, 'as_at_date is required');

  try {
    const report = await getBalanceSheet(asAtDate, costCentreId || undefined);

    const csvLines: string[] = [
      'Section,Account Code,Account Name,Balance',
    ];

    // Assets
    for (const item of report.assets) {
      csvLines.push(
        `${csvVal('Assets')},${csvVal(item.accountCode)},${csvVal(item.accountName)},${Number(item.balance).toFixed(2)}`
      );
    }
    csvLines.push(`${csvVal('Assets')},${csvVal('')},${csvVal('Total Assets')},${Number(report.totalAssets).toFixed(2)}`);

    // Liabilities
    for (const item of report.liabilities) {
      csvLines.push(
        `${csvVal('Liabilities')},${csvVal(item.accountCode)},${csvVal(item.accountName)},${Number(item.balance).toFixed(2)}`
      );
    }
    csvLines.push(`${csvVal('Liabilities')},${csvVal('')},${csvVal('Total Liabilities')},${Number(report.totalLiabilities).toFixed(2)}`);

    // Equity
    for (const item of report.equity) {
      csvLines.push(
        `${csvVal('Equity')},${csvVal(item.accountCode)},${csvVal(item.accountName)},${Number(item.balance).toFixed(2)}`
      );
    }
    csvLines.push(`${csvVal('Equity')},${csvVal('')},${csvVal('Total Equity')},${Number(report.totalEquity).toFixed(2)}`);

    const csv = csvLines.join('\n');
    const filename = `balance-sheet-${new Date().toISOString().split('T')[0]}.csv`;

    res.setHeader('Content-Type', 'text/csv');
    res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);
    return res.status(200).send(csv);
  } catch (err) {
    log.error('Failed to export balance sheet', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, 'Failed to export balance sheet');
  }
}

export default withAuth(withErrorHandler(handler));

/**
 * Bank Accounts API
 * GET /api/accounting/bank-accounts - List bank GL accounts with transaction summaries
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'PUT') {
    try {
      const { id, bankAccountNumber } = req.body;
      if (!id) return apiResponse.badRequest(res, 'id is required');
      await sql`
        UPDATE gl_accounts
        SET bank_account_number = ${bankAccountNumber || null},
            updated_at = NOW()
        WHERE id = ${id} AND account_subtype = 'bank'
      `;
      return apiResponse.success(res, { updated: true });
    } catch (err) {
      log.error('Failed to update bank account', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, 'Failed to update bank account');
    }
  }

  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'PUT']);
  }

  try {
    const rows = await sql`
      SELECT
        ga.id,
        ga.account_code,
        ga.account_name,
        ga.description,
        ga.is_active,
        ga.bank_account_number,
        COALESCE(s.txn_count, 0)         AS txn_count,
        COALESCE(s.total_debits, 0)       AS total_debits,
        COALESCE(s.total_credits, 0)      AS total_credits,
        COALESCE(s.balance, 0)            AS balance,
        COALESCE(s.reconciled_balance, 0) AS reconciled_balance,
        COALESCE(s.unreconciled_balance, 0) AS unreconciled_balance,
        COALESCE(s.unreconciled_count, 0) AS unreconciled_count,
        s.first_date,
        s.last_date
      FROM gl_accounts ga
      LEFT JOIN LATERAL (
        SELECT
          COUNT(*)::INT                                             AS txn_count,
          SUM(CASE WHEN bt.amount < 0 THEN ABS(bt.amount) ELSE 0 END) AS total_debits,
          SUM(CASE WHEN bt.amount > 0 THEN bt.amount ELSE 0 END)      AS total_credits,
          SUM(bt.amount)                                               AS balance,
          -- Reconciled = transactions matched to a GL journal entry
          SUM(CASE WHEN bt.matched_journal_line_id IS NOT NULL THEN bt.amount ELSE 0 END) AS reconciled_balance,
          -- Unreconciled = imported/suggested but not yet matched
          SUM(CASE WHEN bt.matched_journal_line_id IS NULL AND bt.status != 'excluded' THEN bt.amount ELSE 0 END) AS unreconciled_balance,
          COUNT(CASE WHEN bt.status = 'imported' THEN 1 END)::INT     AS unreconciled_count,
          MIN(bt.transaction_date)                                     AS first_date,
          MAX(bt.transaction_date)                                     AS last_date
        FROM bank_transactions bt
        WHERE bt.bank_account_id = ga.id
      ) s ON TRUE
      WHERE ga.account_subtype = 'bank'
        AND ga.is_active = TRUE
      ORDER BY ga.account_code
    `;

    const accounts = rows.map(r => ({
      id: r.id,
      accountCode: r.account_code,
      accountName: r.account_name,
      description: r.description,
      bankAccountNumber: r.bank_account_number || null,
      isActive: r.is_active,
      txnCount: Number(r.txn_count),
      totalDebits: Number(r.total_debits),
      totalCredits: Number(r.total_credits),
      balance: Number(r.balance),
      reconciledBalance: Number(r.reconciled_balance),
      unreconciledBalance: Number(r.unreconciled_balance),
      unreconciledCount: Number(r.unreconciled_count),
      firstDate: r.first_date instanceof Date
        ? r.first_date.toISOString().split('T')[0]
        : r.first_date ? String(r.first_date).split('T')[0] : null,
      lastDate: r.last_date instanceof Date
        ? r.last_date.toISOString().split('T')[0]
        : r.last_date ? String(r.last_date).split('T')[0] : null,
    }));

    return apiResponse.success(res, accounts);
  } catch (err) {
    log.error('Failed to get bank accounts', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, 'Failed to get bank accounts');
  }
}

