/**
 * Bank Import Batches API
 * GET /api/accounting/bank-import-batches?bankAccountId=<uuid>
 * Returns the most recent import batches for a bank account, used by the
 * Statement Balance Widget to display opening/closing balances per statement.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';

// 🟢 WORKING: Import batch row shape returned from DB
type ImportBatchRow = {
  id: string;
  bank_account_id: string;
  statement_date: string | Date;
  bank_format: string | null;
  opening_balance: string | null;
  closing_balance: string | null;
  transaction_count: string | number;
  created_at: string | Date;
};

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
  }

  const { bankAccountId } = req.query;

  if (!bankAccountId || typeof bankAccountId !== 'string' || bankAccountId.trim() === '') {
    return apiResponse.badRequest(res, 'bankAccountId query parameter is required');
  }

  try {
    const rows = (await sql`
      SELECT
        id,
        bank_account_id,
        statement_date,
        bank_format,
        opening_balance,
        closing_balance,
        transaction_count,
        created_at
      FROM bank_import_batches
      WHERE bank_account_id = ${bankAccountId}::UUID
      ORDER BY created_at DESC
      LIMIT 20
    `) as ImportBatchRow[];

    const batches = rows.map(r => ({
      id: r.id,
      statementDate: r.statement_date instanceof Date
        ? r.statement_date.toISOString().split('T')[0]
        : String(r.statement_date).split('T')[0],
      bankFormat: r.bank_format ?? null,
      openingBalance: r.opening_balance !== null ? Number(r.opening_balance) : null,
      closingBalance: r.closing_balance !== null ? Number(r.closing_balance) : null,
      transactionCount: Number(r.transaction_count),
      createdAt: r.created_at instanceof Date
        ? r.created_at.toISOString()
        : String(r.created_at),
    }));

    return apiResponse.success(res, { batches });
  } catch (err) {
    log.error('Failed to get bank import batches', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, 'Failed to get bank import batches');
  }
}

export default withAuth(withErrorHandler(handler));

/**
 * Bank Transaction → Asset Cross-Module Linking API
 *
 * POST /api/accounting/bank-match-asset
 *   Body: { bankTransactionId, assetId }
 *
 * Links a bank transaction to an asset record, storing the reference on
 * both sides and marking the bank transaction as 'matched' when it was
 * previously 'imported'.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';

// ── Types ─────────────────────────────────────────────────────────────────────

interface PostBody {
  bankTransactionId?: string;
  assetId?: string;
}

// ── Handler ───────────────────────────────────────────────────────────────────

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['POST']);
  }

  const { bankTransactionId, assetId } = req.body as PostBody;

  // ── Validation ─────────────────────────────────────────────────────────────
  if (!bankTransactionId) return apiResponse.badRequest(res, 'bankTransactionId is required');
  if (!assetId) return apiResponse.badRequest(res, 'assetId is required');

  // ── Write reverse link on the asset ───────────────────────────────────────
  await sql`
    UPDATE assets
    SET bank_transaction_id = ${bankTransactionId}::UUID
    WHERE id = ${assetId}::UUID
  `;

  // ── Write forward link on the bank transaction ─────────────────────────────
  await sql`
    UPDATE bank_transactions
    SET
      linked_asset_id = ${assetId}::UUID,
      status = CASE WHEN status = 'imported' THEN 'matched' ELSE status END,
      updated_at = NOW()
    WHERE id = ${bankTransactionId}::UUID
  `;

  log.info('Linked bank tx to asset', { bankTransactionId, assetId }, 'bank-match-asset');

  return apiResponse.success(res, {
    linked: true,
    bankTransactionId,
    assetId,
  });
}

export default withAuth(withErrorHandler(handler));
/**
 * Bank Match Candidates API
 * GET /api/accounting/bank-match-candidates?bankTransactionId=<uuid>
 * Returns scored candidate matches from supplier invoices, purchase orders, and GL journal lines.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
import type { CandidateType, MatchCandidate } from '@/modules/accounting/types/bank-match.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

/** Score 0–50: how close the candidate amount is to the transaction amount */
function scoreAmount(txAmount: number, candidateAmount: number): number {
  const diff = Math.abs(Math.abs(txAmount) - Math.abs(candidateAmount));
  if (diff === 0) return 50;
  if (diff < 0.01) return 48;
  if (diff < 1) return 40;
  if (diff < 10) return 30;
  if (diff < 100) return 20;
  if (diff < 1000) return 10;
  return 0;
}

/** Score 0–30: how close the candidate date is to the transaction date */
function scoreDate(txDate: string, candidateDate: string): number {
  const tx = new Date(txDate).getTime();
  const cand = new Date(candidateDate).getTime();
  const diffDays = Math.abs(tx - cand) / (1000 * 60 * 60 * 24);
  if (diffDays === 0) return 30;
  if (diffDays <= 1) return 28;
  if (diffDays <= 3) return 24;
  if (diffDays <= 7) return 20;
  if (diffDays <= 14) return 14;
  if (diffDays <= 30) return 8;
  if (diffDays <= 60) return 4;
  return 0;
}

/** Score 0–20: simple word-overlap between description strings */
function scoreDescription(txDesc: string, candidateLabel: string): number {
  if (!txDesc || !candidateLabel) return 0;
  const txWords = new Set(txDesc.toLowerCase().split(/\W+/).filter(w => w.length > 2));
  const candWords = candidateLabel.toLowerCase().split(/\W+/).filter(w => w.length > 2);
  if (txWords.size === 0 || candWords.length === 0) return 0;
  const matches = candWords.filter(w => txWords.has(w)).length;
  const ratio = matches / Math.max(txWords.size, candWords.length);
  return Math.round(ratio * 20);
}

function fmtDate(val: unknown): string {
  if (val instanceof Date) return val.toISOString().split('T')[0]!;
  return val ? String(val).split('T')[0]! : '';
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['GET']);
  }

  const { bankTransactionId } = req.query;
  if (!bankTransactionId || typeof bankTransactionId !== 'string') {
    return apiResponse.badRequest(res, 'bankTransactionId query param is required');
  }

  try {
    // Fetch the bank transaction to get amount, date, description
    const txRows = (await sql`
      SELECT id, amount, transaction_date, description, reference
      FROM bank_transactions
      WHERE id = ${bankTransactionId}::UUID
    `) as Row[];

    if (txRows.length === 0) {
      return apiResponse.notFound(res, 'Bank transaction', bankTransactionId);
    }

    const tx = txRows[0]!;
    const txAmount = Number(tx.amount);
    const txDate = fmtDate(tx.transaction_date);
    const txDesc = String(tx.description ?? tx.reference ?? '');
    const absAmount = Math.abs(txAmount);

    const candidates: MatchCandidate[] = [];

    // ── 1. Supplier invoices ─────────────────────────────────────────────────
    const invoiceRows = (await sql`
      SELECT si.id, si.invoice_number, s.company_name AS supplier_name,
             si.total_amount, si.invoice_date
      FROM supplier_invoices si
      JOIN suppliers s ON s.id = si.supplier_id
      WHERE si.status IN ('approved', 'partially_paid')
      ORDER BY ABS(si.total_amount - ${absAmount}::NUMERIC) ASC
      LIMIT 20
    `) as Row[];

    for (const row of invoiceRows) {
      const label = `${String(row.supplier_name)} — Inv ${String(row.invoice_number)}`;
      const candAmount = Number(row.total_amount);
      const candDate = fmtDate(row.invoice_date);
      const score = scoreAmount(txAmount, candAmount)
        + scoreDate(txDate, candDate)
        + scoreDescription(txDesc, label);
      candidates.push({
        type: 'supplier_invoice',
        id: String(row.id),
        label,
        amount: candAmount,
        date: candDate,
        score,
      });
    }

    // ── 2. Purchase orders ───────────────────────────────────────────────────
    const poRows = (await sql`
      SELECT po.id, po.po_number, s.company_name AS supplier_name,
             po.total_amount, po.created_at
      FROM purchase_orders po
      JOIN suppliers s ON s.id = po.supplier_id
      WHERE po.status IN ('approved', 'partially_paid')
        AND po.bank_transaction_id IS NULL
      ORDER BY ABS(po.total_amount - ${absAmount}::NUMERIC) ASC
      LIMIT 20
    `) as Row[];

    for (const row of poRows) {
      const label = `${String(row.supplier_name)} — PO ${String(row.po_number)}`;
      const candAmount = Number(row.total_amount);
      const candDate = fmtDate(row.created_at);
      const score = scoreAmount(txAmount, candAmount)
        + scoreDate(txDate, candDate)
        + scoreDescription(txDesc, label);
      candidates.push({
        type: 'purchase_order',
        id: String(row.id),
        label,
        amount: candAmount,
        date: candDate,
        score,
      });
    }

    // ── 3. GL journal lines ──────────────────────────────────────────────────
    const jlRows = (await sql`
      SELECT jl.id, jl.description, jl.debit, jl.credit, je.entry_date
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      WHERE je.status = 'posted'
        AND jl.id NOT IN (
          SELECT matched_journal_line_id FROM bank_transactions
          WHERE matched_journal_line_id IS NOT NULL
        )
      ORDER BY ABS((jl.debit - jl.credit) - ${txAmount}::NUMERIC) ASC
      LIMIT 20
    `) as Row[];

    for (const row of jlRows) {
      const lineNet = Number(row.debit) - Number(row.credit);
      const label = String(row.description ?? 'Journal line');
      const candDate = fmtDate(row.entry_date);
      const score = scoreAmount(txAmount, lineNet)
        + scoreDate(txDate, candDate)
        + scoreDescription(txDesc, label);
      candidates.push({
        type: 'journal_line',
        id: String(row.id),
        label,
        amount: lineNet,
        date: candDate,
        score,
      });
    }

    // Sort all candidates by score descending
    candidates.sort((a, b) => b.score - a.score);

    log.info('Fetched bank match candidates', {
      bankTransactionId,
      count: candidates.length,
    }, 'accounting-api');

    return apiResponse.success(res, { candidates });
  } catch (err) {
    log.error('Failed to fetch bank match candidates', { bankTransactionId, error: err }, 'accounting-api');
    return apiResponse.internalError(res, err);
  }
}

export default withAuth(withErrorHandler(handler));
/**
 * Bank Match Confirm API
 * POST /api/accounting/bank-match-confirm
 * Body: { bankTransactionId, candidateType, candidateId }
 * Confirms a manual match selection from the FindMatchModal.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
import {
  allocateTransaction,
  matchTransaction,
} from '@/modules/accounting/services/bankReconciliationService';
import type { CandidateType } from '@/modules/accounting/types/bank-match.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['POST']);
  }

  const {
    bankTransactionId,
    candidateType,
    candidateId,
  } = req.body as {
    bankTransactionId?: string;
    candidateType?: CandidateType;
    candidateId?: string;
  };

  // @ts-expect-error — auth middleware attaches user
  const userId: string = req.user?.id ?? req.user?.userId ?? 'system';

  if (!bankTransactionId) return apiResponse.badRequest(res, 'bankTransactionId is required');
  if (!candidateType) return apiResponse.badRequest(res, 'candidateType is required');
  if (!candidateId) return apiResponse.badRequest(res, 'candidateId is required');

  const validTypes: CandidateType[] = ['supplier_invoice', 'purchase_order', 'journal_line'];
  if (!validTypes.includes(candidateType)) {
    return apiResponse.badRequest(res, `candidateType must be one of: ${validTypes.join(', ')}`);
  }

  try {
    if (candidateType === 'supplier_invoice') {
      // Look up the supplier invoice to derive the supplier entity id
      const invRows = (await sql`
        SELECT id, supplier_id, total_amount FROM supplier_invoices WHERE id = ${candidateId}::UUID
      `) as Row[];
      if (invRows.length === 0) {
        return apiResponse.notFound(res, 'Supplier invoice', candidateId);
      }
      const inv = invRows[0]!;
      const supplierId = String(inv.supplier_id);

      // Allocate the bank transaction against the AP account for this supplier
      await allocateTransaction(
        bankTransactionId,
        '', // contraAccountId unused when allocType is 'supplier'
        userId,
        undefined,
        'supplier',
        supplierId,
      );

      // Mark invoice as paid
      await sql`
        UPDATE supplier_invoices SET status = 'paid', updated_at = NOW()
        WHERE id = ${candidateId}::UUID
      `;

      log.info('Confirmed match: supplier invoice', { bankTransactionId, candidateId }, 'accounting-api');
    } else if (candidateType === 'purchase_order') {
      // Look up the PO to derive the supplier entity id
      const poRows = (await sql`
        SELECT id, supplier_id, total_amount FROM purchase_orders WHERE id = ${candidateId}::UUID
      `) as Row[];
      if (poRows.length === 0) {
        return apiResponse.notFound(res, 'Purchase order', candidateId);
      }
      const po = poRows[0]!;
      const supplierId = String(po.supplier_id);

      // Allocate against AP account for this supplier
      await allocateTransaction(
        bankTransactionId,
        '',
        userId,
        undefined,
        'supplier',
        supplierId,
      );

      // Link PO to bank transaction and mark as paid
      await sql`
        UPDATE purchase_orders
        SET bank_transaction_id = ${bankTransactionId}::UUID,
            status = 'paid',
            updated_at = NOW()
        WHERE id = ${candidateId}::UUID
      `;

      // Link bank transaction back to the PO
      await sql`
        UPDATE bank_transactions
        SET linked_po_id = ${candidateId}::UUID, updated_at = NOW()
        WHERE id = ${bankTransactionId}::UUID
      `;

      log.info('Confirmed match: purchase order', { bankTransactionId, candidateId }, 'accounting-api');
    } else {
      // journal_line — use the existing matchTransaction function
      await matchTransaction(bankTransactionId, candidateId);
      log.info('Confirmed match: journal line', { bankTransactionId, candidateId }, 'accounting-api');
    }

    return apiResponse.success(res, { matched: true, candidateType, candidateId });
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Match confirmation failed';
    log.error('Failed to confirm bank match', { bankTransactionId, candidateType, candidateId, error: err }, 'accounting-api');
    return apiResponse.badRequest(res, message);
  }
}

export default withAuth(withErrorHandler(handler));
/**
 * Bank Transaction → Fleet Cross-Module Linking API
 *
 * POST /api/accounting/bank-match-fleet
 *   Body: { bankTransactionId, fleetEntityType: 'fuel' | 'service', fleetEntityId }
 *
 * Links a bank transaction to either a fleet fuel transaction or a fleet
 * service history record, storing the reference on both sides and marking
 * the bank transaction as 'matched' when it was previously 'imported'.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';

// ── Types ─────────────────────────────────────────────────────────────────────

type FleetEntityType = 'fuel' | 'service';

interface PostBody {
  bankTransactionId?: string;
  fleetEntityType?: FleetEntityType;
  fleetEntityId?: string;
}

// ── Handler ───────────────────────────────────────────────────────────────────

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['POST']);
  }

  const { bankTransactionId, fleetEntityType, fleetEntityId } = req.body as PostBody;

  // ── Validation ─────────────────────────────────────────────────────────────
  if (!bankTransactionId) return apiResponse.badRequest(res, 'bankTransactionId is required');
  if (!fleetEntityId) return apiResponse.badRequest(res, 'fleetEntityId is required');
  if (!fleetEntityType || !['fuel', 'service'].includes(fleetEntityType)) {
    return apiResponse.badRequest(res, "fleetEntityType must be 'fuel' or 'service'");
  }

  if (fleetEntityType === 'fuel') {
    // ── Fuel transaction link ──────────────────────────────────────────────
    await sql`
      UPDATE fleet_fuel_transactions
      SET bank_transaction_id = ${bankTransactionId}::UUID
      WHERE id = ${fleetEntityId}::UUID
    `;

    await sql`
      UPDATE bank_transactions
      SET
        linked_fleet_fuel_id = ${fleetEntityId}::UUID,
        status = CASE WHEN status = 'imported' THEN 'matched' ELSE status END,
        updated_at = NOW()
      WHERE id = ${bankTransactionId}::UUID
    `;

    log.info('Linked bank tx to fleet fuel', { bankTransactionId, fleetEntityId }, 'bank-match-fleet');
    return apiResponse.success(res, {
      linked: true,
      bankTransactionId,
      fleetEntityType: 'fuel',
      fleetEntityId,
    });
  }

  // ── Service history link ───────────────────────────────────────────────────
  await sql`
    UPDATE fleet_service_history
    SET bank_transaction_id = ${bankTransactionId}::UUID
    WHERE id = ${fleetEntityId}::UUID
  `;

  await sql`
    UPDATE bank_transactions
    SET
      linked_fleet_service_id = ${fleetEntityId}::UUID,
      status = CASE WHEN status = 'imported' THEN 'matched' ELSE status END,
      updated_at = NOW()
    WHERE id = ${bankTransactionId}::UUID
  `;

  log.info('Linked bank tx to fleet service', { bankTransactionId, fleetEntityId }, 'bank-match-fleet');
  return apiResponse.success(res, {
    linked: true,
    bankTransactionId,
    fleetEntityType: 'service',
    fleetEntityId,
  });
}

export default withAuth(withErrorHandler(handler));

/**
 * Bank Reconciliation Report Data API
 * GET /api/accounting/bank-reconciliation-report?bankAccountId=<uuid>
 *
 * Returns matched and unmatched transaction data alongside statement balances
 * for rendering the PDF reconciliation report on the client.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';

// ─── Row types returned from DB ───────────────────────────────────────────────

type TxRow = {
  id: string;
  transaction_date: string | Date;
  description: string | null;
  reference: string | null;
  amount: string | number;
  journal_entry_number: string | null;
};

type BatchRow = {
  opening_balance: string | null;
  closing_balance: string | null;
  statement_date: string | Date;
};

type AccountRow = {
  account_name: string;
};

// ─── Helpers ──────────────────────────────────────────────────────────────────

function toDateStr(d: string | Date): string {
  if (d instanceof Date) return d.toISOString().split('T')[0] ?? '';
  return String(d).split('T')[0] ?? '';
}

async function fetchBankAccountName(bankAccountId: string): Promise<string> {
  const rows = (await sql`
    SELECT account_name
    FROM gl_accounts
    WHERE id = ${bankAccountId}::UUID
    LIMIT 1
  `) as AccountRow[];
  return rows[0]?.account_name ?? 'Unknown Account';
}

async function fetchLatestBatch(bankAccountId: string): Promise<BatchRow | null> {
  const rows = (await sql`
    SELECT opening_balance, closing_balance, statement_date
    FROM bank_import_batches
    WHERE bank_account_id = ${bankAccountId}::UUID
    ORDER BY created_at DESC
    LIMIT 1
  `) as BatchRow[];
  return rows[0] ?? null;
}

async function fetchMatchedTransactions(bankAccountId: string): Promise<TxRow[]> {
  return (await sql`
    SELECT
      bt.id,
      bt.transaction_date,
      bt.description,
      bt.reference,
      bt.amount,
      je.entry_number AS journal_entry_number
    FROM bank_transactions bt
    LEFT JOIN gl_journal_lines jl ON jl.id = bt.matched_journal_line_id
    LEFT JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
    WHERE bt.bank_account_id = ${bankAccountId}::UUID
      AND bt.status = 'matched'
    ORDER BY bt.transaction_date
  `) as TxRow[];
}

async function fetchUnmatchedTransactions(bankAccountId: string): Promise<TxRow[]> {
  return (await sql`
    SELECT
      bt.id,
      bt.transaction_date,
      bt.description,
      bt.reference,
      bt.amount,
      NULL::TEXT AS journal_entry_number
    FROM bank_transactions bt
    WHERE bt.bank_account_id = ${bankAccountId}::UUID
      AND bt.status = 'imported'
    ORDER BY bt.transaction_date
  `) as TxRow[];
}

// ─── Handler ──────────────────────────────────────────────────────────────────

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
  }

  const { bankAccountId } = req.query;

  if (!bankAccountId || typeof bankAccountId !== 'string' || bankAccountId.trim() === '') {
    return apiResponse.badRequest(res, 'bankAccountId query parameter is required');
  }

  try {
    // Parallel fetch: account name, latest batch, matched and unmatched transactions
    const [bankAccountName, latestBatch, matchedRows, unmatchedRows] = await Promise.all([
      fetchBankAccountName(bankAccountId),
      fetchLatestBatch(bankAccountId),
      fetchMatchedTransactions(bankAccountId),
      fetchUnmatchedTransactions(bankAccountId),
    ]);

    const mapTx = (row: TxRow) => ({
      date: toDateStr(row.transaction_date),
      description: row.description ?? '',
      amount: Number(row.amount),
      reference: row.reference ?? undefined,
      journalRef: row.journal_entry_number ?? undefined,
    });

    return apiResponse.success(res, {
      bankAccountName,
      statementDate: latestBatch ? toDateStr(latestBatch.statement_date) : '',
      openingBalance:
        latestBatch?.opening_balance !== null && latestBatch?.opening_balance !== undefined
          ? Number(latestBatch.opening_balance)
          : null,
      closingBalance:
        latestBatch?.closing_balance !== null && latestBatch?.closing_balance !== undefined
          ? Number(latestBatch.closing_balance)
          : null,
      matchedTransactions: matchedRows.map(mapTx),
      unmatchedTransactions: unmatchedRows.map(mapTx),
    });
  } catch (err) {
    log.error('Failed to get bank reconciliation report data', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, 'Failed to get bank reconciliation report data');
  }
}

export default withAuth(withErrorHandler(handler));
/**
 * Bank Reconciliation Actions API
 * POST /api/accounting/bank-reconciliations-action
 *   action: complete | adjustment
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  completeReconciliation,
  createAdjustmentEntry,
} from '@/modules/accounting/services/bankReconciliationService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
  }

  try {
    const { action, reconciliationId, userId: bodyUserId } = req.body;
    const userId = bodyUserId || (req as unknown as { user?: { id: string } }).user?.id;

    if (!action || !reconciliationId) {
      return apiResponse.badRequest(res, 'action and reconciliationId are required');
    }
    if (!userId) return apiResponse.badRequest(res, 'userId is required');

    switch (action) {
      case 'complete': {
        const recon = await completeReconciliation(reconciliationId, userId);
        return apiResponse.success(res, recon);
      }
      case 'adjustment': {
        const { bankAccountId, contraAccountId, amount, description } = req.body;
        if (!bankAccountId || !contraAccountId || amount === undefined || !description) {
          return apiResponse.badRequest(res, 'bankAccountId, contraAccountId, amount, and description are required');
        }
        const jeId = await createAdjustmentEntry(
          reconciliationId, bankAccountId, contraAccountId,
          Number(amount), description, userId
        );
        return apiResponse.success(res, { journalEntryId: jeId });
      }
      default:
        return apiResponse.badRequest(res, `Unknown action: ${action}`);
    }
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Action failed';
    log.error('Bank reconciliation action failed', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, message);
  }
}

export default withAuth(withErrorHandler(handler));
/**
 * Bank Reconciliations API
 * GET  /api/accounting/bank-reconciliations - List reconciliation sessions
 * POST /api/accounting/bank-reconciliations - Start new reconciliation
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  getReconciliations,
  getReconciliationById,
  startReconciliation,
} from '@/modules/accounting/services/bankReconciliationService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    try {
      const { bank_account_id, id } = req.query;

      if (id) {
        const recon = await getReconciliationById(String(id));
        if (!recon) return apiResponse.notFound(res, 'Reconciliation', String(id));
        return apiResponse.success(res, recon);
      }

      const result = await getReconciliations(
        bank_account_id ? String(bank_account_id) : undefined
      );
      return apiResponse.success(res, result);
    } catch (err) {
      log.error('Failed to get reconciliations', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, 'Failed to get reconciliations');
    }
  }

  if (req.method === 'POST') {
    try {
      const { bankAccountId, statementDate, statementBalance } = req.body;
      const userId = req.body.userId || (req as unknown as { user?: { id: string } }).user?.id;

      if (!bankAccountId || !statementDate || statementBalance === undefined) {
        return apiResponse.badRequest(res, 'bankAccountId, statementDate, and statementBalance are required');
      }
      if (!userId) return apiResponse.badRequest(res, 'userId is required');

      const recon = await startReconciliation(
        String(bankAccountId), String(statementDate),
        Number(statementBalance), userId
      );
      return apiResponse.created(res, recon);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to start reconciliation';
      log.error('Failed to start reconciliation', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, message);
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

export default withAuth(withErrorHandler(handler));

