/**
 * PRD-060: FibreFlow Accounting Module — Phase 4
 * Bank Reconciliation Service
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { detectBankFormat, parseFNBStatement, parseStandardBankStatement, parseNedbankStatement, parseABSAStatement, parseCapitecStatement } from '../utils/bankCsvParsers';
import { parseOfxStatement } from '../utils/bankOfxParser';
import { parseQifStatement } from '../utils/bankQifParser';
import { runAutoMatch } from '../utils/autoMatch';
import { createJournalEntry, postJournalEntry } from './journalEntryService';
import type { BankTransaction, BankReconciliation, AutoMatchResult, BankFormat, BankCsvParseResult } from '../types/bank.types';
import type { JournalLineInput } from '../types/gl.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// ── Import ───────────────────────────────────────────────────────────────────

export async function importBankStatement(
  csvContent: string,
  bankAccountId: string,
  statementDate: string,
  bankFormat?: BankFormat
): Promise<{ batchId: string; transactionCount: number; errors: Array<{ row: number; error: string }> }> {
  try {
    const format = bankFormat && bankFormat !== 'unknown' ? bankFormat : detectBankFormat(csvContent);
    let parseResult;

    switch (format) {
      case 'fnb':
        parseResult = parseFNBStatement(csvContent);
        break;
      case 'standard_bank':
        parseResult = parseStandardBankStatement(csvContent);
        break;
      case 'nedbank':
        parseResult = parseNedbankStatement(csvContent);
        break;
      case 'absa':
        parseResult = parseABSAStatement(csvContent);
        break;
      case 'capitec':
        parseResult = parseCapitecStatement(csvContent);
        break;
      case 'ofx':
        parseResult = parseOfxStatement(csvContent);
        break;
      case 'qif':
        parseResult = parseQifStatement(csvContent);
        break;
      default:
        throw new Error('Unable to detect bank format. Please specify the bank.');
    }

    if (parseResult.transactions.length === 0) {
      return { batchId: '', transactionCount: 0, errors: parseResult.errors };
    }

    const batchId = crypto.randomUUID();

    for (const tx of parseResult.transactions) {
      await sql`
        INSERT INTO bank_transactions (
          bank_account_id, transaction_date, value_date, amount,
          description, reference, import_batch_id
        ) VALUES (
          ${bankAccountId}::UUID, ${tx.transactionDate}, ${tx.valueDate || null},
          ${tx.amount}, ${tx.description}, ${tx.reference || null}, ${batchId}::UUID
        )
      `;
    }

    log.info('Imported bank statement', {
      batchId, format, count: parseResult.transactions.length,
    }, 'accounting');

    return {
      batchId,
      transactionCount: parseResult.transactions.length,
      errors: parseResult.errors,
    };
  } catch (err) {
    log.error('Failed to import bank statement', { error: err }, 'accounting');
    throw err;
  }
}

// ── Import from Pre-Parsed Result (PDF) ──────────────────────────────────────

/**
 * Persist an already-parsed set of transactions (e.g. from a PDF import).
 * Reuses the same INSERT logic as importBankStatement so behaviour is identical.
 */
export async function importParsedTransactions(
  parseResult: BankCsvParseResult,
  bankAccountId: string,
  statementDate: string,
): Promise<{ batchId: string; transactionCount: number; errors: Array<{ row: number; error: string }> }> {
  try {
    if (parseResult.transactions.length === 0) {
      return { batchId: '', transactionCount: 0, errors: parseResult.errors };
    }

    const batchId = crypto.randomUUID();

    for (const tx of parseResult.transactions) {
      await sql`
        INSERT INTO bank_transactions (
          bank_account_id, transaction_date, value_date, amount,
          description, reference, import_batch_id
        ) VALUES (
          ${bankAccountId}::UUID, ${tx.transactionDate}, ${tx.valueDate || null},
          ${tx.amount}, ${tx.description}, ${tx.reference || null}, ${batchId}::UUID
        )
      `;
    }

    log.info('Imported parsed bank statement', {
      batchId,
      format: parseResult.bankFormat,
      count: parseResult.transactions.length,
      statementDate,
    }, 'accounting');

    return {
      batchId,
      transactionCount: parseResult.transactions.length,
      errors: parseResult.errors,
    };
  } catch (err) {
    log.error('Failed to import parsed bank transactions', { error: err }, 'accounting');
    throw err;
  }
}

// ── Bank Transactions ────────────────────────────────────────────────────────

interface BankTxFilters {
  bankAccountId?: string;
  reconciliationId?: string;
  status?: string;
  fromDate?: string;
  toDate?: string;
  /** Minimum transaction amount (inclusive). Defaults to unbounded when absent. */
  fromAmount?: string;
  /** Maximum transaction amount (inclusive). Defaults to unbounded when absent. */
  toAmount?: string;
  search?: string;
  limit?: number;
  offset?: number;
}

export async function getBankTransactions(filters?: BankTxFilters): Promise<{
  transactions: BankTransaction[];
  total: number;
}> {
  try {
    const limit = filters?.limit || 100;
    const offset = filters?.offset || 0;
    let rows: Row[];
    let countRows: Row[];

    if (filters?.reconciliationId) {
      rows = (await sql`
        SELECT bt.*, ga.account_name AS bank_account_name,
               ga2.account_name AS suggested_gl_account_name,
               ga2.account_code AS suggested_gl_account_code,
               COALESCE(s2.name, s2.company_name) AS suggested_supplier_name,
               c2.company_name AS suggested_client_name,
               cc1.name AS cc1_name, cc2t.name AS cc2_name, dept.name AS bu_name
        FROM bank_transactions bt
        LEFT JOIN gl_accounts ga ON ga.id = bt.bank_account_id
        LEFT JOIN gl_accounts ga2 ON ga2.id = bt.suggested_gl_account_id
        LEFT JOIN suppliers s2 ON s2.id = bt.suggested_supplier_id
        LEFT JOIN clients c2 ON c2.id = bt.suggested_client_id
        LEFT JOIN cost_centres cc1 ON cc1.id = bt.cc1_id
        LEFT JOIN cost_centres cc2t ON cc2t.id = bt.cc2_id
        LEFT JOIN departments dept ON dept.id = bt.bu_id
        WHERE bt.reconciliation_id = ${filters.reconciliationId}::UUID
        ORDER BY bt.transaction_date DESC, bt.amount DESC
        LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM bank_transactions
        WHERE reconciliation_id = ${filters.reconciliationId}::UUID
      `) as Row[];
    } else if (filters?.bankAccountId && filters?.status) {
      // 🟢 WORKING: date range + amount range + full-text search via always-present params (no conditional SQL fragments)
      const searchPattern = filters.search ? `%${filters.search}%` : '%';
      const fromDateVal = filters.fromDate || '1900-01-01';
      const toDateVal = filters.toDate || '2099-12-31';
      const fromAmountVal = filters.fromAmount || '-999999999';
      const toAmountVal = filters.toAmount || '999999999';
      // 'imported' tab shows both imported and allocated (not-yet-reviewed) transactions
      const statusArr = filters.status === 'imported'
        ? ['imported', 'allocated']
        : [filters.status];
      rows = (await sql`
        SELECT bt.*, ga.account_name AS bank_account_name,
               ga2.account_name AS suggested_gl_account_name,
               ga2.account_code AS suggested_gl_account_code,
               COALESCE(s2.name, s2.company_name) AS suggested_supplier_name,
               c2.company_name AS suggested_client_name,
               cc1.name AS cc1_name, cc2t.name AS cc2_name, dept.name AS bu_name
        FROM bank_transactions bt
        LEFT JOIN gl_accounts ga ON ga.id = bt.bank_account_id
        LEFT JOIN gl_accounts ga2 ON ga2.id = bt.suggested_gl_account_id
        LEFT JOIN suppliers s2 ON s2.id = bt.suggested_supplier_id
        LEFT JOIN clients c2 ON c2.id = bt.suggested_client_id
        LEFT JOIN cost_centres cc1 ON cc1.id = bt.cc1_id
        LEFT JOIN cost_centres cc2t ON cc2t.id = bt.cc2_id
        LEFT JOIN departments dept ON dept.id = bt.bu_id
        WHERE bt.bank_account_id = ${filters.bankAccountId}::UUID
          AND bt.status = ANY(${statusArr}::TEXT[])
          AND bt.transaction_date >= ${fromDateVal}
          AND bt.transaction_date <= ${toDateVal}
          AND bt.amount >= ${fromAmountVal}::NUMERIC
          AND bt.amount <= ${toAmountVal}::NUMERIC
          AND (bt.description ILIKE ${searchPattern} OR bt.reference ILIKE ${searchPattern})
        ORDER BY bt.transaction_date DESC, bt.amount DESC
        LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM bank_transactions bt
        WHERE bt.bank_account_id = ${filters.bankAccountId}::UUID
          AND bt.status = ANY(${statusArr}::TEXT[])
          AND bt.transaction_date >= ${fromDateVal}
          AND bt.transaction_date <= ${toDateVal}
          AND bt.amount >= ${fromAmountVal}::NUMERIC
          AND bt.amount <= ${toAmountVal}::NUMERIC
          AND (bt.description ILIKE ${searchPattern} OR bt.reference ILIKE ${searchPattern})
      `) as Row[];
    } else if (filters?.bankAccountId) {
      rows = (await sql`
        SELECT bt.*, ga.account_name AS bank_account_name,
               ga2.account_name AS suggested_gl_account_name,
               ga2.account_code AS suggested_gl_account_code,
               COALESCE(s2.name, s2.company_name) AS suggested_supplier_name,
               c2.company_name AS suggested_client_name,
               cc1.name AS cc1_name, cc2t.name AS cc2_name, dept.name AS bu_name
        FROM bank_transactions bt
        LEFT JOIN gl_accounts ga ON ga.id = bt.bank_account_id
        LEFT JOIN gl_accounts ga2 ON ga2.id = bt.suggested_gl_account_id
        LEFT JOIN suppliers s2 ON s2.id = bt.suggested_supplier_id
        LEFT JOIN clients c2 ON c2.id = bt.suggested_client_id
        LEFT JOIN cost_centres cc1 ON cc1.id = bt.cc1_id
        LEFT JOIN cost_centres cc2t ON cc2t.id = bt.cc2_id
        LEFT JOIN departments dept ON dept.id = bt.bu_id
        WHERE bt.bank_account_id = ${filters.bankAccountId}::UUID
        ORDER BY bt.transaction_date DESC, bt.amount DESC
        LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM bank_transactions
        WHERE bank_account_id = ${filters.bankAccountId}::UUID
      `) as Row[];
    } else {
      rows = (await sql`
        SELECT bt.*, ga.account_name AS bank_account_name,
               ga2.account_name AS suggested_gl_account_name,
               ga2.account_code AS suggested_gl_account_code,
               COALESCE(s2.name, s2.company_name) AS suggested_supplier_name,
               c2.company_name AS suggested_client_name,
               cc1.name AS cc1_name, cc2t.name AS cc2_name, dept.name AS bu_name
        FROM bank_transactions bt
        LEFT JOIN gl_accounts ga ON ga.id = bt.bank_account_id
        LEFT JOIN gl_accounts ga2 ON ga2.id = bt.suggested_gl_account_id
        LEFT JOIN suppliers s2 ON s2.id = bt.suggested_supplier_id
        LEFT JOIN clients c2 ON c2.id = bt.suggested_client_id
        LEFT JOIN cost_centres cc1 ON cc1.id = bt.cc1_id
        LEFT JOIN cost_centres cc2t ON cc2t.id = bt.cc2_id
        LEFT JOIN departments dept ON dept.id = bt.bu_id
        ORDER BY bt.transaction_date DESC, bt.amount DESC
        LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`SELECT COUNT(*) AS cnt FROM bank_transactions`) as Row[];
    }

    return { transactions: rows.map(mapTxRow), total: Number(countRows[0]!.cnt) };
  } catch (err) {
    log.error('Failed to get bank transactions', { error: err }, 'accounting');
    throw err;
  }
}

// ── Match / Unmatch ──────────────────────────────────────────────────────────

export async function matchTransaction(
  bankTxId: string,
  journalLineId: string,
  reconciliationId?: string
): Promise<BankTransaction> {
  try {
    let rows: Row[];
    if (reconciliationId) {
      rows = (await sql`
        UPDATE bank_transactions
        SET status = 'matched',
            matched_journal_line_id = ${journalLineId}::UUID,
            reconciliation_id = ${reconciliationId}::UUID
        WHERE id = ${bankTxId}::UUID
        RETURNING *
      `) as Row[];
    } else {
      rows = (await sql`
        UPDATE bank_transactions
        SET status = 'matched',
            matched_journal_line_id = ${journalLineId}::UUID
        WHERE id = ${bankTxId}::UUID
        RETURNING *
      `) as Row[];
    }

    if (rows.length === 0) throw new Error(`Bank transaction ${bankTxId} not found`);

    // Update reconciled balance if part of a reconciliation
    if (reconciliationId) {
      await updateReconciledBalance(reconciliationId);
    }

    log.info('Matched bank transaction', { bankTxId, journalLineId }, 'accounting');
    return mapTxRow(rows[0]!);
  } catch (err) {
    log.error('Failed to match bank transaction', { bankTxId, error: err }, 'accounting');
    throw err;
  }
}

export async function unmatchTransaction(bankTxId: string): Promise<BankTransaction> {
  try {
    const existing = (await sql`SELECT reconciliation_id FROM bank_transactions WHERE id = ${bankTxId}::UUID`) as Row[];
    const reconId = existing[0]?.reconciliation_id ? String(existing[0].reconciliation_id) : null;

    const rows = (await sql`
      UPDATE bank_transactions
      SET status = 'imported',
          matched_journal_line_id = NULL,
          allocation_type = NULL,
          allocated_entity_name = NULL
      WHERE id = ${bankTxId}::UUID
      RETURNING *
    `) as Row[];

    if (rows.length === 0) throw new Error(`Bank transaction ${bankTxId} not found`);

    if (reconId) {
      await updateReconciledBalance(reconId);
    }

    log.info('Unmatched bank transaction', { bankTxId }, 'accounting');
    return mapTxRow(rows[0]!);
  } catch (err) {
    log.error('Failed to unmatch bank transaction', { bankTxId, error: err }, 'accounting');
    throw err;
  }
}

export async function excludeTransaction(bankTxId: string, reason?: string): Promise<BankTransaction> {
  try {
    const rows = (await sql`
      UPDATE bank_transactions
      SET status = 'excluded', exclude_reason = ${reason || null}
      WHERE id = ${bankTxId}::UUID
      RETURNING *
    `) as Row[];
    if (rows.length === 0) throw new Error(`Bank transaction ${bankTxId} not found`);
    log.info('Excluded bank transaction', { bankTxId, reason }, 'accounting');
    return mapTxRow(rows[0]!);
  } catch (err) {
    log.error('Failed to exclude bank transaction', { bankTxId, error: err }, 'accounting');
    throw err;
  }
}

// ── Delete ───────────────────────────────────────────────────────────────────

/**
 * Delete bank transactions — only imported (unallocated) transactions can be deleted.
 * Matched/reconciled transactions must be unmatched first.
 */
export async function deleteTransactions(bankTxIds: string[]): Promise<number> {
  if (bankTxIds.length === 0) return 0;
  try {
    const result = (await sql`
      DELETE FROM bank_transactions
      WHERE id = ANY(${bankTxIds}::UUID[])
        AND status = 'imported'
    `) as Row[];
    const deleted = result.count ?? bankTxIds.length;
    log.info('Deleted bank transactions', { count: deleted, ids: bankTxIds }, 'accounting');
    return deleted;
  } catch (err) {
    log.error('Failed to delete bank transactions', { bankTxIds, error: err }, 'accounting');
    throw err;
  }
}

// ── Bulk Accept ──────────────────────────────────────────────────────────────

/**
 * Mark a batch of imported transactions as 'matched' without creating journal entries.
 * Used for the Bulk Accept toolbar action — accepts transactions that don't need GL allocation.
 */
export async function bulkAcceptTransactions(ids: string[]): Promise<number> {
  if (ids.length === 0) return 0;
  try {
    // Move both imported (unallocated) and allocated transactions to reviewed
    const result = (await sql`
      UPDATE bank_transactions SET status = 'matched', updated_at = NOW()
      WHERE id = ANY(${ids}::UUID[]) AND status IN ('imported', 'allocated')
    `) as Row[];
    const count = (result as unknown as { count?: number }).count ?? ids.length;
    log.info('Bulk accepted bank transactions', { count, ids }, 'accounting');
    return count;
  } catch (err) {
    log.error('Failed to bulk accept bank transactions', { ids, error: err }, 'accounting');
    throw err;
  }
}

// ── Auto-Match ───────────────────────────────────────────────────────────────

export async function autoMatchTransactions(
  bankAccountId: string,
  reconciliationId?: string
): Promise<AutoMatchResult> {
  try {
    // Get unmatched bank transactions
    const bankTxRows = (await sql`
      SELECT id, amount, transaction_date, reference, description
      FROM bank_transactions
      WHERE bank_account_id = ${bankAccountId}::UUID AND status = 'imported'
      ORDER BY transaction_date
    `) as Row[];

    if (bankTxRows.length === 0) {
      return { matched: 0, unmatched: 0, candidates: [] };
    }

    // Get unmatched GL journal lines for this bank account (posted entries only)
    const glRows = (await sql`
      SELECT jl.id, jl.debit, jl.credit, jl.description,
        je.entry_date, je.entry_number, je.source_document_id
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      WHERE jl.gl_account_id = ${bankAccountId}::UUID
        AND je.status = 'posted'
        AND jl.id NOT IN (
          SELECT matched_journal_line_id FROM bank_transactions
          WHERE matched_journal_line_id IS NOT NULL
        )
      ORDER BY je.entry_date
    `) as Row[];

    const bankTxs = bankTxRows.map((r: Row) => ({
      id: String(r.id),
      amount: Number(r.amount),
      transactionDate: String(r.transaction_date),
      reference: r.reference ? String(r.reference) : undefined,
      description: r.description ? String(r.description) : undefined,
    }));

    const glLines = glRows.map((r: Row) => ({
      id: String(r.id),
      debit: Number(r.debit),
      credit: Number(r.credit),
      description: r.description ? String(r.description) : undefined,
      entryDate: String(r.entry_date),
      entryNumber: r.entry_number ? String(r.entry_number) : undefined,
      sourceDocumentId: r.source_document_id ? String(r.source_document_id) : undefined,
    }));

    const result = runAutoMatch(bankTxs, glLines);

    // Apply high-confidence matches automatically (>= 0.9)
    let matchedCount = 0;
    for (const match of result.matches) {
      if (match.confidence >= 0.9) {
        await matchTransaction(match.bankTransactionId, match.journalLineId, reconciliationId);
        matchedCount++;
      }
    }

    const lowConfidence = result.matches.filter(m => m.confidence < 0.9);

    log.info('Auto-match completed', {
      bankAccountId, autoMatched: matchedCount,
      candidates: lowConfidence.length, unmatched: result.unmatched.length,
    }, 'accounting');

    return {
      matched: matchedCount,
      unmatched: result.unmatched.length,
      candidates: lowConfidence,
    };
  } catch (err) {
    log.error('Failed to auto-match transactions', { error: err }, 'accounting');
    throw err;
  }
}

// ── Reconciliation CRUD ──────────────────────────────────────────────────────

export async function getReconciliations(bankAccountId?: string): Promise<BankReconciliation[]> {
  try {
    let rows: Row[];
    if (bankAccountId) {
      rows = (await sql`
        SELECT br.*, ga.account_name AS bank_account_name,
          (SELECT COUNT(*) FROM bank_transactions WHERE reconciliation_id = br.id AND status = 'matched') AS matched_count,
          (SELECT COUNT(*) FROM bank_transactions WHERE reconciliation_id = br.id AND status = 'imported') AS unmatched_count
        FROM bank_reconciliations br
        LEFT JOIN gl_accounts ga ON ga.id = br.bank_account_id
        WHERE br.bank_account_id = ${bankAccountId}::UUID
        ORDER BY br.statement_date DESC
      `) as Row[];
    } else {
      rows = (await sql`
        SELECT br.*, ga.account_name AS bank_account_name,
          (SELECT COUNT(*) FROM bank_transactions WHERE reconciliation_id = br.id AND status = 'matched') AS matched_count,
          (SELECT COUNT(*) FROM bank_transactions WHERE reconciliation_id = br.id AND status = 'imported') AS unmatched_count
        FROM bank_reconciliations br
        LEFT JOIN gl_accounts ga ON ga.id = br.bank_account_id
        ORDER BY br.statement_date DESC
      `) as Row[];
    }
    return rows.map(mapReconRow);
  } catch (err) {
    log.error('Failed to get reconciliations', { error: err }, 'accounting');
    throw err;
  }
}

export async function getReconciliationById(id: string): Promise<BankReconciliation | null> {
  try {
    const rows = (await sql`
      SELECT br.*, ga.account_name AS bank_account_name,
        (SELECT COUNT(*) FROM bank_transactions WHERE reconciliation_id = br.id AND status = 'matched') AS matched_count,
        (SELECT COUNT(*) FROM bank_transactions WHERE reconciliation_id = br.id AND status = 'imported') AS unmatched_count
      FROM bank_reconciliations br
      LEFT JOIN gl_accounts ga ON ga.id = br.bank_account_id
      WHERE br.id = ${id}::UUID
    `) as Row[];
    return rows.length > 0 ? mapReconRow(rows[0]!) : null;
  } catch (err) {
    log.error('Failed to get reconciliation', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function startReconciliation(
  bankAccountId: string,
  statementDate: string,
  statementBalance: number,
  userId: string
): Promise<BankReconciliation> {
  try {
    // Calculate current GL balance for this bank account
    const balRows = (await sql`
      SELECT COALESCE(SUM(jl.debit) - SUM(jl.credit), 0) AS gl_balance
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      WHERE jl.gl_account_id = ${bankAccountId}::UUID
        AND je.status = 'posted'
        AND je.entry_date <= ${statementDate}
    `) as Row[];

    const glBalance = Number(balRows[0]!.gl_balance);

    const rows = (await sql`
      INSERT INTO bank_reconciliations (
        bank_account_id, statement_date, statement_balance, gl_balance,
        reconciled_balance, started_by
      ) VALUES (
        ${bankAccountId}::UUID, ${statementDate}, ${statementBalance},
        ${glBalance}, ${glBalance}, ${userId}::UUID
      ) RETURNING *
    `) as Row[];

    // Link unmatched imported transactions to this reconciliation
    await sql`
      UPDATE bank_transactions
      SET reconciliation_id = ${rows[0]!.id}::UUID
      WHERE bank_account_id = ${bankAccountId}::UUID
        AND status = 'imported'
        AND reconciliation_id IS NULL
    `;

    log.info('Started bank reconciliation', {
      id: String(rows[0]!.id), bankAccountId, statementBalance, glBalance,
    }, 'accounting');

    return mapReconRow(rows[0]!);
  } catch (err) {
    log.error('Failed to start reconciliation', { error: err }, 'accounting');
    throw err;
  }
}

export async function completeReconciliation(id: string, userId: string): Promise<BankReconciliation> {
  try {
    const recon = await getReconciliationById(id);
    if (!recon) throw new Error(`Reconciliation ${id} not found`);
    if (recon.status === 'completed') throw new Error('Reconciliation already completed');
    if (Math.abs(recon.difference) > 0.01) {
      throw new Error(`Cannot complete: difference is R${recon.difference.toFixed(2)} (must be R0.00)`);
    }

    // Mark all matched transactions as reconciled
    await sql`
      UPDATE bank_transactions SET status = 'reconciled'
      WHERE reconciliation_id = ${id}::UUID AND status = 'matched'
    `;

    const rows = (await sql`
      UPDATE bank_reconciliations
      SET status = 'completed', completed_by = ${userId}::UUID, completed_at = NOW()
      WHERE id = ${id}::UUID RETURNING *
    `) as Row[];

    log.info('Completed bank reconciliation', { id }, 'accounting');
    return mapReconRow(rows[0]!);
  } catch (err) {
    log.error('Failed to complete reconciliation', { id, error: err }, 'accounting');
    throw err;
  }
}

// ── Adjustment Entry ─────────────────────────────────────────────────────────

export async function createAdjustmentEntry(
  reconciliationId: string,
  bankAccountId: string,
  contraAccountId: string,
  amount: number,
  description: string,
  userId: string
): Promise<string> {
  try {
    const lines: JournalLineInput[] = amount > 0
      ? [
          { glAccountId: bankAccountId, debit: amount, credit: 0, description },
          { glAccountId: contraAccountId, debit: 0, credit: amount, description },
        ]
      : [
          { glAccountId: contraAccountId, debit: Math.abs(amount), credit: 0, description },
          { glAccountId: bankAccountId, debit: 0, credit: Math.abs(amount), description },
        ];

    const recon = await getReconciliationById(reconciliationId);
    if (!recon) throw new Error(`Reconciliation ${reconciliationId} not found`);

    const je = await createJournalEntry({
      entryDate: recon.statementDate,
      description: `Bank recon adjustment: ${description}`,
      source: 'auto_bank_recon',
      sourceDocumentId: reconciliationId,
      lines,
    }, userId);
    await postJournalEntry(je.id, userId);

    // Update reconciled balance
    await updateReconciledBalance(reconciliationId);

    log.info('Created adjustment entry', { reconciliationId, journalEntryId: je.id }, 'accounting');
    return je.id;
  } catch (err) {
    log.error('Failed to create adjustment entry', { error: err }, 'accounting');
    throw err;
  }
}

// ── Allocate (Sage-style "Process Bank") ────────────────────────────────────

export type AllocationType = 'account' | 'supplier' | 'customer';

/** Look up a GL account by its code (e.g. '2110' for AP, '1120' for AR) */
async function glAccountByCode(code: string): Promise<string> {
  const rows = (await sql`
    SELECT id FROM gl_accounts WHERE account_code = ${code} AND is_active = TRUE LIMIT 1
  `) as Row[];
  if (rows.length === 0) throw new Error(`GL account ${code} not found`);
  return String(rows[0]!.id);
}

/**
 * Allocate a bank transaction — Sage Process Bank equivalent.
 * Supports three types:
 *   account  → DR/CR bank ↔ GL account
 *   supplier → DR Accounts Payable (2110), CR Bank (payment out)
 *   customer → DR Bank, CR Accounts Receivable (1120) (receipt in)
 */
export async function allocateTransaction(
  bankTxId: string,
  contraAccountId: string,
  userId: string,
  description?: string,
  allocType: AllocationType = 'account',
  entityId?: string,
  vatCode?: string,
  cc1Id?: string,
  cc2Id?: string,
  buId?: string,
): Promise<{ journalEntryId: string; bankTransaction: BankTransaction }> {
  // Get the bank transaction
  const txRows = (await sql`
    SELECT * FROM bank_transactions WHERE id = ${bankTxId}::UUID
  `) as Row[];
  if (txRows.length === 0) throw new Error(`Bank transaction ${bankTxId} not found`);
  const tx = txRows[0]!;

  if (tx.status !== 'imported') {
    throw new Error(`Transaction already ${tx.status} — cannot allocate`);
  }

  const totalAmount = Math.abs(Number(tx.amount));
  const bankAccountId = String(tx.bank_account_id);
  const txDate = tx.transaction_date instanceof Date
    ? tx.transaction_date.toISOString().split('T')[0]
    : String(tx.transaction_date).split('T')[0];
  const isSpent = Number(tx.amount) < 0;

  // VAT splitting: Standard (15%) splits into net + VAT
  const hasVat = vatCode === 'standard';
  const vatRate = hasVat ? 15 : 0;
  const netAmount = hasVat ? Math.round((totalAmount * 100 / 115) * 100) / 100 : totalAmount;
  const vatAmount = hasVat ? Math.round((totalAmount - netAmount) * 100) / 100 : 0;
  // VAT accounts: 1140 VAT Input (expenses/payments), 2120 VAT Output (sales/receipts)
  const vatAccountCode = isSpent ? '1140' : '2120';
  const mapVatType = vatCode === 'standard' ? 'standard' as const
    : vatCode === 'zero_rated' ? 'zero_rated' as const
    : vatCode === 'exempt' ? 'exempt' as const
    : undefined;

  let lines: JournalLineInput[];
  let source: import('../types/gl.types').GLEntrySource;
  let entryDesc: string;
  let allocEntityName: string | null = null;

  if (allocType === 'supplier' && entityId) {
    // Supplier payment: DR Accounts Payable, CR Bank (+ VAT Input if applicable)
    const apAccountId = await glAccountByCode('2110');
    const supRows = (await sql`SELECT name FROM suppliers WHERE id = ${Number(entityId)}`) as Row[];
    const supName = supRows.length > 0 ? String(supRows[0]!.name) : `Supplier #${entityId}`;
    allocEntityName = supName;
    entryDesc = description || `Payment to ${supName}`;
    source = 'auto_supplier_payment';
    lines = [
      { glAccountId: apAccountId, debit: netAmount, credit: 0, description: entryDesc, vatType: mapVatType },
      { glAccountId: bankAccountId, debit: 0, credit: totalAmount, description: entryDesc },
    ];
    if (hasVat) {
      const vatAcctId = await glAccountByCode(vatAccountCode);
      lines.splice(1, 0, { glAccountId: vatAcctId, debit: vatAmount, credit: 0, description: `VAT @ ${vatRate}%`, vatType: 'standard' });
    }
  } else if (allocType === 'customer' && entityId) {
    // Customer receipt: DR Bank, CR Accounts Receivable (+ VAT Output if applicable)
    const arAccountId = await glAccountByCode('1120');
    const custRows = (await sql`SELECT company_name FROM clients WHERE id = ${entityId}::UUID`) as Row[];
    const custName = custRows.length > 0 ? String(custRows[0]!.company_name) : `Customer #${entityId}`;
    allocEntityName = custName;
    entryDesc = description || `Receipt from ${custName}`;
    source = 'auto_payment';
    lines = [
      { glAccountId: bankAccountId, debit: totalAmount, credit: 0, description: entryDesc },
      { glAccountId: arAccountId, debit: 0, credit: netAmount, description: entryDesc, vatType: mapVatType },
    ];
    if (hasVat) {
      const vatAcctId = await glAccountByCode(vatAccountCode);
      lines.push({ glAccountId: vatAcctId, debit: 0, credit: vatAmount, description: `VAT @ ${vatRate}%`, vatType: 'standard' });
    }
  } else {
    // Standard GL account allocation
    const acctRows = (await sql`SELECT account_code, account_name FROM gl_accounts WHERE id = ${contraAccountId}::UUID`) as Row[];
    allocEntityName = acctRows.length > 0 ? `${acctRows[0]!.account_code} ${acctRows[0]!.account_name}` : null;
    entryDesc = description || tx.description || 'Bank allocation';
    source = 'auto_bank_recon';
    if (!isSpent) {
      // Money in: DR Bank (total), CR Contra (net), CR VAT Output (vat)
      lines = [
        { glAccountId: bankAccountId, debit: totalAmount, credit: 0, description: entryDesc },
        { glAccountId: contraAccountId, debit: 0, credit: netAmount, description: entryDesc, vatType: mapVatType },
      ];
      if (hasVat) {
        const vatAcctId = await glAccountByCode(vatAccountCode);
        lines.push({ glAccountId: vatAcctId, debit: 0, credit: vatAmount, description: `VAT @ ${vatRate}%`, vatType: 'standard' });
      }
    } else {
      // Money out: DR Contra (net), DR VAT Input (vat), CR Bank (total)
      lines = [
        { glAccountId: contraAccountId, debit: netAmount, credit: 0, description: entryDesc, vatType: mapVatType },
      ];
      if (hasVat) {
        const vatAcctId = await glAccountByCode(vatAccountCode);
        lines.push({ glAccountId: vatAcctId, debit: vatAmount, credit: 0, description: `VAT @ ${vatRate}%`, vatType: 'standard' });
      }
      lines.push({ glAccountId: bankAccountId, debit: 0, credit: totalAmount, description: entryDesc });
    }
  }

  // Attach CC1 (cost centre) and BU to contra (non-bank) lines
  const linesWithDims = lines.map(l =>
    l.glAccountId === bankAccountId ? l : { ...l, costCenterId: cc1Id || l.costCenterId, buId: buId || l.buId }
  );

  const je = await createJournalEntry({
    entryDate: txDate,
    description: entryDesc,
    source,
    sourceDocumentId: bankTxId,
    lines: linesWithDims,
  }, userId);
  await postJournalEntry(je.id, userId);

  // Find the bank-side journal line to match against
  const jeLines = (await sql`
    SELECT id FROM gl_journal_lines
    WHERE journal_entry_id = ${je.id}::UUID
      AND gl_account_id = ${bankAccountId}::UUID
    LIMIT 1
  `) as Row[];

  const journalLineId = jeLines.length > 0 ? String(jeLines[0]!.id) : null;

  // Mark as allocated (stays on New tab until explicitly reviewed); persist dimensions
  if (journalLineId) {
    await sql`
      UPDATE bank_transactions
      SET status = 'allocated',
          matched_journal_line_id = ${journalLineId}::UUID,
          allocation_type = ${allocType},
          allocated_entity_name = ${allocEntityName},
          cc1_id = ${cc1Id || null}::UUID,
          cc2_id = ${cc2Id || null}::UUID,
          bu_id = ${buId || null}::UUID,
          updated_at = NOW()
      WHERE id = ${bankTxId}::UUID
    `;
  }

  // Create customer_payments record so payment appears in customer statements
  if (allocType === 'customer' && entityId) {
    await sql`
      INSERT INTO customer_payments (
        client_id, payment_date, total_amount, payment_method,
        bank_reference, bank_account_id, description, status,
        gl_journal_entry_id, created_by, confirmed_by, confirmed_at
      ) VALUES (
        ${entityId}::UUID, ${txDate}, ${totalAmount}, 'eft',
        ${tx.reference || tx.bank_reference || tx.description || null},
        ${bankAccountId}::UUID, ${entryDesc}, 'confirmed',
        ${je.id}::UUID, ${userId}::UUID, ${userId}::UUID, NOW()
      )
    `;
  }

  log.info('Allocated bank transaction', {
    bankTxId, journalEntryId: je.id, allocType, entityId, contraAccountId,
  }, 'accounting');

  const updated = (await sql`SELECT * FROM bank_transactions WHERE id = ${bankTxId}::UUID`) as Row[];
  return { journalEntryId: je.id, bankTransaction: mapTxRow(updated[0]!) };
}

// ── Split Allocate ───────────────────────────────────────────────────────────

export interface SplitLine {
  contraAccountId: string;
  amount: number; // absolute amount for this line
  description?: string;
  vatCode?: string; // 'none' | 'standard' | 'zero_rated' | 'exempt'
}

/**
 * Split-allocate a bank transaction across multiple GL accounts.
 * Each split line may carry its own VAT treatment.
 * The sum of all line amounts must equal Math.abs(tx.amount).
 */
export async function splitAllocateTransaction(
  bankTxId: string,
  lines: SplitLine[],
  userId: string,
): Promise<{ journalEntryId: string; bankTransaction: BankTransaction }> {
  const txRows = (await sql`
    SELECT * FROM bank_transactions WHERE id = ${bankTxId}::UUID
  `) as Row[];
  if (txRows.length === 0) throw new Error(`Bank transaction ${bankTxId} not found`);
  const tx = txRows[0]!;

  if (tx.status !== 'imported') {
    throw new Error(`Transaction already ${tx.status} — cannot split allocate`);
  }

  if (!lines || lines.length === 0) throw new Error('At least one split line is required');

  const totalAmount = Math.abs(Number(tx.amount));
  const linesTotal = lines.reduce((sum, l) => sum + Number(l.amount), 0);
  // Allow 1-cent rounding tolerance
  if (Math.abs(linesTotal - totalAmount) > 0.01) {
    throw new Error(
      `Split lines total R${linesTotal.toFixed(2)} does not equal transaction amount R${totalAmount.toFixed(2)}`
    );
  }

  const bankAccountId = String(tx.bank_account_id);
  const txDate = tx.transaction_date instanceof Date
    ? tx.transaction_date.toISOString().split('T')[0]
    : String(tx.transaction_date).split('T')[0];
  const isSpent = Number(tx.amount) < 0;
  const entryDesc = tx.description || 'Split bank allocation';
  const journalLines: JournalLineInput[] = [];

  // Build contra lines for each split
  for (const line of lines) {
    const lineAmount = Number(line.amount);
    const hasVat = line.vatCode === 'standard';
    const netAmount = hasVat ? Math.round((lineAmount * 100 / 115) * 100) / 100 : lineAmount;
    const vatAmount = hasVat ? Math.round((lineAmount - netAmount) * 100) / 100 : 0;
    const vatAccountCode = isSpent ? '1140' : '2120';
    const lineDesc = line.description || entryDesc;
    const mapVatType = line.vatCode === 'standard' ? 'standard' as const
      : line.vatCode === 'zero_rated' ? 'zero_rated' as const
      : line.vatCode === 'exempt' ? 'exempt' as const
      : undefined;

    if (isSpent) {
      // Money out: DR contra (net), DR VAT Input (vat if standard)
      journalLines.push({
        glAccountId: line.contraAccountId,
        debit: netAmount, credit: 0,
        description: lineDesc,
        vatType: mapVatType,
      });
      if (hasVat) {
        const vatAcctId = await glAccountByCode(vatAccountCode);
        journalLines.push({
          glAccountId: vatAcctId,
          debit: vatAmount, credit: 0,
          description: `VAT @ 15%`,
          vatType: 'standard',
        });
      }
    } else {
      // Money in: CR contra (net), CR VAT Output (vat if standard)
      journalLines.push({
        glAccountId: line.contraAccountId,
        debit: 0, credit: netAmount,
        description: lineDesc,
        vatType: mapVatType,
      });
      if (hasVat) {
        const vatAcctId = await glAccountByCode(vatAccountCode);
        journalLines.push({
          glAccountId: vatAcctId,
          debit: 0, credit: vatAmount,
          description: `VAT @ 15%`,
          vatType: 'standard',
        });
      }
    }
  }

  // Add the bank side as a single balancing line
  if (isSpent) {
    journalLines.push({ glAccountId: bankAccountId, debit: 0, credit: totalAmount, description: entryDesc });
  } else {
    journalLines.unshift({ glAccountId: bankAccountId, debit: totalAmount, credit: 0, description: entryDesc });
  }

  const je = await createJournalEntry({
    entryDate: txDate,
    description: entryDesc,
    source: 'auto_bank_recon',
    sourceDocumentId: bankTxId,
    lines: journalLines,
  }, userId);
  await postJournalEntry(je.id, userId);

  // Find the bank-side journal line to match against
  const jeLines = (await sql`
    SELECT id FROM gl_journal_lines
    WHERE journal_entry_id = ${je.id}::UUID
      AND gl_account_id = ${bankAccountId}::UUID
    LIMIT 1
  `) as Row[];
  const journalLineId = jeLines.length > 0 ? String(jeLines[0]!.id) : null;

  if (journalLineId) {
    await sql`
      UPDATE bank_transactions
      SET status = 'allocated',
          matched_journal_line_id = ${journalLineId}::UUID,
          allocation_type = 'account',
          allocated_entity_name = 'Split allocation',
          updated_at = NOW()
      WHERE id = ${bankTxId}::UUID
    `;
  }

  log.info('Split-allocated bank transaction', {
    bankTxId, journalEntryId: je.id, lineCount: lines.length,
  }, 'accounting');

  const updated = (await sql`SELECT * FROM bank_transactions WHERE id = ${bankTxId}::UUID`) as Row[];
  return { journalEntryId: je.id, bankTransaction: mapTxRow(updated[0]!) };
}

// ── Reverse Reconciled ───────────────────────────────────────────────────────

/**
 * Reverse a matched or reconciled bank transaction.
 * - If a journal entry was created, it is reversed via reverseJournalEntry.
 * - The bank transaction is reset to 'imported' with all links cleared.
 */
export async function reverseReconciledTransaction(bankTxId: string, userId: string): Promise<void> {
  // 1. Fetch the bank transaction
  const txRows = (await sql`
    SELECT * FROM bank_transactions WHERE id = ${bankTxId}::UUID
  `) as Row[];
  const tx = txRows[0];
  if (!tx) throw new Error('Transaction not found');
  if (tx.status !== 'allocated' && tx.status !== 'matched' && tx.status !== 'reconciled') {
    throw new Error('Can only reverse allocated, matched, or reconciled transactions');
  }

  // 2. If there is a matched journal line, reverse the parent journal entry
  if (tx.matched_journal_line_id) {
    const jlRows = (await sql`
      SELECT journal_entry_id FROM gl_journal_lines WHERE id = ${tx.matched_journal_line_id}::UUID
    `) as Row[];
    if (jlRows.length > 0 && jlRows[0]!.journal_entry_id) {
      const { reverseJournalEntry } = await import('./journalEntryService');
      try {
        await reverseJournalEntry(String(jlRows[0]!.journal_entry_id), userId);
      } catch (e) {
        throw new Error(`Cannot reverse: ${e instanceof Error ? e.message : 'Journal reversal failed'}`);
      }
    }
  }

  // 3. Reset bank transaction to imported and clear all link fields
  await sql`
    UPDATE bank_transactions
    SET status = 'imported',
        matched_journal_line_id = NULL,
        reconciliation_id = NULL,
        linked_po_id = NULL,
        linked_asset_id = NULL,
        linked_fleet_fuel_id = NULL,
        linked_fleet_service_id = NULL,
        allocation_type = NULL,
        allocated_entity_name = NULL,
        updated_at = NOW()
    WHERE id = ${bankTxId}::UUID
  `;

  log.info('Reversed reconciled bank transaction', { bankTxId, userId }, 'accounting');
}

// ── Helpers ──────────────────────────────────────────────────────────────────

async function updateReconciledBalance(reconciliationId: string): Promise<void> {
  // Reconciled balance = sum of matched bank transaction amounts
  const sumRows = (await sql`
    SELECT COALESCE(SUM(amount), 0) AS matched_total
    FROM bank_transactions
    WHERE reconciliation_id = ${reconciliationId}::UUID
      AND status IN ('matched', 'reconciled')
  `) as Row[];

  const reconRows = (await sql`
    SELECT gl_balance FROM bank_reconciliations WHERE id = ${reconciliationId}::UUID
  `) as Row[];

  if (reconRows.length > 0) {
    const reconciledBalance = Number(reconRows[0]!.gl_balance) + Number(sumRows[0]!.matched_total);
    await sql`
      UPDATE bank_reconciliations SET reconciled_balance = ${reconciledBalance}
      WHERE id = ${reconciliationId}::UUID
    `;
  }
}

function fmtDate(val: unknown): string {
  if (val instanceof Date) return val.toISOString().split('T')[0] ?? '';
  return val ? String(val).split('T')[0] ?? '' : '';
}

function mapTxRow(row: Row): BankTransaction {
  return {
    id: String(row.id),
    bankAccountId: String(row.bank_account_id),
    transactionDate: fmtDate(row.transaction_date),
    valueDate: row.value_date ? fmtDate(row.value_date) : undefined,
    amount: Number(row.amount),
    description: row.description ? String(row.description) : undefined,
    reference: row.reference ? String(row.reference) : undefined,
    bankReference: row.bank_reference ? String(row.bank_reference) : undefined,
    status: String(row.status) as BankTransaction['status'],
    matchedJournalLineId: row.matched_journal_line_id ? String(row.matched_journal_line_id) : undefined,
    reconciliationId: row.reconciliation_id ? String(row.reconciliation_id) : undefined,
    importBatchId: row.import_batch_id ? String(row.import_batch_id) : undefined,
    excludeReason: row.exclude_reason ? String(row.exclude_reason) : undefined,
    notes: row.notes ? String(row.notes) : undefined,
    suggestedGlAccountId: row.suggested_gl_account_id ? String(row.suggested_gl_account_id) : undefined,
    suggestedCategory: row.suggested_category ? String(row.suggested_category) : undefined,
    suggestedCostCentre: row.suggested_cost_centre ? String(row.suggested_cost_centre) : undefined,
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
    bankAccountName: row.bank_account_name ? String(row.bank_account_name) : undefined,
    matchedEntryNumber: row.matched_entry_number ? String(row.matched_entry_number) : undefined,
    suggestedGlAccountName: row.suggested_gl_account_name ? String(row.suggested_gl_account_name) : undefined,
    suggestedGlAccountCode: row.suggested_gl_account_code ? String(row.suggested_gl_account_code) : undefined,
    suggestedSupplierId: row.suggested_supplier_id ? String(row.suggested_supplier_id) : undefined,
    suggestedSupplierName: row.suggested_supplier_name ? String(row.suggested_supplier_name) : undefined,
    suggestedClientId: row.suggested_client_id ? String(row.suggested_client_id) : undefined,
    suggestedClientName: row.suggested_client_name ? String(row.suggested_client_name) : undefined,
    suggestedVatCode: row.suggested_vat_code && row.suggested_vat_code !== 'none' ? String(row.suggested_vat_code) : undefined,
    cc1Id: row.cc1_id ? String(row.cc1_id) : undefined,
    cc2Id: row.cc2_id ? String(row.cc2_id) : undefined,
    buId: row.bu_id ? String(row.bu_id) : undefined,
    cc1Name: row.cc1_name ? String(row.cc1_name) : undefined,
    cc2Name: row.cc2_name ? String(row.cc2_name) : undefined,
    buName: row.bu_name ? String(row.bu_name) : undefined,
    allocationType: row.allocation_type ? String(row.allocation_type) as BankTransaction['allocationType'] : undefined,
    allocatedEntityName: row.allocated_entity_name ? String(row.allocated_entity_name) : undefined,
  };
}

function mapReconRow(row: Row): BankReconciliation {
  return {
    id: String(row.id),
    bankAccountId: String(row.bank_account_id),
    statementDate: fmtDate(row.statement_date),
    statementBalance: Number(row.statement_balance),
    glBalance: Number(row.gl_balance),
    reconciledBalance: Number(row.reconciled_balance),
    difference: Number(row.difference),
    status: String(row.status) as BankReconciliation['status'],
    startedBy: String(row.started_by),
    startedAt: String(row.started_at),
    completedBy: row.completed_by ? String(row.completed_by) : undefined,
    completedAt: row.completed_at ? String(row.completed_at) : undefined,
    notes: row.notes ? String(row.notes) : undefined,
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
    bankAccountName: row.bank_account_name ? String(row.bank_account_name) : undefined,
    matchedCount: row.matched_count !== undefined ? Number(row.matched_count) : undefined,
    unmatchedCount: row.unmatched_count !== undefined ? Number(row.unmatched_count) : undefined,
  };
}

/**
 * PRD-060: FibreFlow Accounting Module — Phase 5
 * Financial Reporting Service
 *
 * Income Statement, Balance Sheet, VAT Return, Project Profitability
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type {
  IncomeStatementReport,
  BalanceSheetReport,
  VATReturnReport,
  ProjectProfitabilityReport,
} from '../types/gl.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

interface ReportLineItem {
  accountCode: string;
  accountName: string;
  amount: number;
}

interface BSLineItem {
  accountCode: string;
  accountName: string;
  balance: number;
}

// ── Income Statement (P&L) ───────────────────────────────────────────────────

interface ISOptions {
  projectId?: string;
  costCentreId?: string;
}

/** Fetch P&L line items for a single period. Reused for comparative calls. */
async function fetchIncomeStatementRows(
  periodStart: string,
  periodEnd: string,
  opts: ISOptions
) {
  const projId = opts.projectId ?? null;
  const ccId = opts.costCentreId ?? null;

  const rows = (await sql`
    SELECT ga.account_code, ga.account_name, ga.account_type, ga.account_subtype,
      COALESCE(SUM(jl.debit), 0) AS total_debit,
      COALESCE(SUM(jl.credit), 0) AS total_credit
    FROM gl_journal_lines jl
    JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
    JOIN gl_accounts ga ON ga.id = jl.gl_account_id
    WHERE je.status = 'posted'
      AND je.entry_date >= ${periodStart}
      AND je.entry_date <= ${periodEnd}
      AND ga.account_type IN ('revenue', 'expense')
      AND (${projId}::TEXT IS NULL OR jl.project_id = ${projId}::UUID)
      AND (${ccId}::TEXT IS NULL OR jl.cost_center_id = ${ccId}::UUID)
    GROUP BY ga.id, ga.account_code, ga.account_name, ga.account_type, ga.account_subtype
    ORDER BY ga.account_code
  `) as Row[];

  const revenue: ReportLineItem[] = [];
  const costOfSales: ReportLineItem[] = [];
  const operatingExpenses: ReportLineItem[] = [];

  for (const r of rows) {
    const type = String(r.account_type);
    const subtype = r.account_subtype ? String(r.account_subtype) : '';
    const debit = Number(r.total_debit);
    const credit = Number(r.total_credit);

    if (type === 'revenue') {
      const amount = credit - debit;
      if (Math.abs(amount) > 0.001) {
        revenue.push({ accountCode: String(r.account_code), accountName: String(r.account_name), amount });
      }
    } else if (type === 'expense') {
      const amount = debit - credit;
      if (Math.abs(amount) > 0.001) {
        const item = { accountCode: String(r.account_code), accountName: String(r.account_name), amount };
        if (subtype === 'cost_of_sales') costOfSales.push(item);
        else operatingExpenses.push(item);
      }
    }
  }

  const totalRevenue = revenue.reduce((s, i) => s + i.amount, 0);
  const totalCostOfSales = costOfSales.reduce((s, i) => s + i.amount, 0);
  const grossProfit = totalRevenue - totalCostOfSales;
  const totalOperatingExpenses = operatingExpenses.reduce((s, i) => s + i.amount, 0);
  const netProfit = grossProfit - totalOperatingExpenses;

  return { revenue, costOfSales, operatingExpenses, totalRevenue, totalCostOfSales, grossProfit, totalOperatingExpenses, netProfit };
}

export async function getIncomeStatement(
  periodStart: string,
  periodEnd: string,
  opts: ISOptions = {},
  comparePeriod?: { start: string; end: string }
): Promise<IncomeStatementReport> {
  try {
    const current = await fetchIncomeStatementRows(periodStart, periodEnd, opts);

    const report: IncomeStatementReport = {
      periodStart,
      periodEnd,
      projectId: opts.projectId,
      costCentreId: opts.costCentreId,
      revenue: current.revenue,
      costOfSales: current.costOfSales,
      operatingExpenses: current.operatingExpenses,
      totalRevenue: current.totalRevenue,
      totalCostOfSales: current.totalCostOfSales,
      grossProfit: current.grossProfit,
      totalOperatingExpenses: current.totalOperatingExpenses,
      netProfit: current.netProfit,
    };

    if (comparePeriod) {
      const prior = await fetchIncomeStatementRows(comparePeriod.start, comparePeriod.end, opts);
      report.comparativePeriod = comparePeriod;
      report.priorTotalRevenue = prior.totalRevenue;
      report.priorTotalCostOfSales = prior.totalCostOfSales;
      report.priorGrossProfit = prior.grossProfit;
      report.priorTotalOperatingExpenses = prior.totalOperatingExpenses;
      report.priorNetProfit = prior.netProfit;

      const mergeLineItems = (curr: ReportLineItem[], prev: ReportLineItem[]) => {
        const priorMap = new Map(prev.map(p => [p.accountCode, p.amount]));
        return curr.map(c => {
          const pa = priorMap.get(c.accountCode) ?? 0;
          const variance = c.amount - pa;
          return { ...c, priorAmount: pa, variance, variancePct: pa !== 0 ? (variance / Math.abs(pa)) * 100 : 0 };
        });
      };
      report.revenue = mergeLineItems(current.revenue, prior.revenue);
      report.costOfSales = mergeLineItems(current.costOfSales, prior.costOfSales);
      report.operatingExpenses = mergeLineItems(current.operatingExpenses, prior.operatingExpenses);
    }

    return report;
  } catch (err) {
    log.error('Failed to generate income statement', { error: err }, 'accounting');
    throw err;
  }
}

// ── Balance Sheet ────────────────────────────────────────────────────────────

/** Fetch balance sheet data for a single date. Reused for comparative calls. */
async function fetchBalanceSheetData(asAtDate: string, costCentreId?: string) {
  const ccId = costCentreId ?? null;

  const rows = (await sql`
    SELECT ga.account_code, ga.account_name, ga.account_type, ga.normal_balance,
      COALESCE(SUM(jl.debit), 0) AS total_debit,
      COALESCE(SUM(jl.credit), 0) AS total_credit
    FROM gl_journal_lines jl
    JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
    JOIN gl_accounts ga ON ga.id = jl.gl_account_id
    WHERE je.status = 'posted'
      AND je.entry_date <= ${asAtDate}
      AND ga.account_type IN ('asset', 'liability', 'equity')
      AND ga.level >= 3
      AND (${ccId}::TEXT IS NULL OR jl.cost_center_id = ${ccId}::UUID)
    GROUP BY ga.id, ga.account_code, ga.account_name, ga.account_type, ga.normal_balance
    ORDER BY ga.account_code
  `) as Row[];

  const assets: BSLineItem[] = [];
  const liabilities: BSLineItem[] = [];
  const equity: BSLineItem[] = [];

  for (const r of rows) {
    const type = String(r.account_type);
    const normalBal = String(r.normal_balance);
    const debit = Number(r.total_debit);
    const credit = Number(r.total_credit);
    const balance = normalBal === 'debit' ? debit - credit : credit - debit;
    if (Math.abs(balance) < 0.01) continue;

    const item: BSLineItem = { accountCode: String(r.account_code), accountName: String(r.account_name), balance };
    if (type === 'asset') assets.push(item);
    else if (type === 'liability') liabilities.push(item);
    else if (type === 'equity') equity.push(item);
  }

  const retainedEarnings = await calculateRetainedEarnings(asAtDate, costCentreId);
  if (Math.abs(retainedEarnings) > 0.01) {
    const existing = equity.find(e => e.accountCode === '3200');
    if (existing) existing.balance += retainedEarnings;
    else equity.push({ accountCode: '3200', accountName: 'Retained Earnings (Current)', balance: retainedEarnings });
  }

  return { assets, liabilities, equity };
}

export async function getBalanceSheet(
  asAtDate: string,
  costCentreId?: string,
  compareDate?: string
): Promise<BalanceSheetReport> {
  try {
    const current = await fetchBalanceSheetData(asAtDate, costCentreId);

    const report: BalanceSheetReport = {
      asAtDate,
      costCentreId,
      assets: current.assets,
      liabilities: current.liabilities,
      equity: current.equity,
      totalAssets: current.assets.reduce((s, a) => s + a.balance, 0),
      totalLiabilities: current.liabilities.reduce((s, l) => s + l.balance, 0),
      totalEquity: current.equity.reduce((s, e) => s + e.balance, 0),
    };

    if (compareDate) {
      const prior = await fetchBalanceSheetData(compareDate, costCentreId);
      report.compareDate = compareDate;
      report.priorTotalAssets = prior.assets.reduce((s, a) => s + a.balance, 0);
      report.priorTotalLiabilities = prior.liabilities.reduce((s, l) => s + l.balance, 0);
      report.priorTotalEquity = prior.equity.reduce((s, e) => s + e.balance, 0);

      const mergeBSLines = (curr: BSLineItem[], prev: BSLineItem[]) => {
        const priorMap = new Map(prev.map(p => [p.accountCode, p.balance]));
        return curr.map(c => {
          const pb = priorMap.get(c.accountCode) ?? 0;
          const variance = c.balance - pb;
          return { ...c, priorBalance: pb, variance, variancePct: pb !== 0 ? (variance / Math.abs(pb)) * 100 : 0 };
        });
      };
      report.assets = mergeBSLines(current.assets, prior.assets);
      report.liabilities = mergeBSLines(current.liabilities, prior.liabilities);
      report.equity = mergeBSLines(current.equity, prior.equity);
    }

    return report;
  } catch (err) {
    log.error('Failed to generate balance sheet', { error: err }, 'accounting');
    throw err;
  }
}

async function calculateRetainedEarnings(asAtDate: string, costCentreId?: string): Promise<number> {
  const ccId = costCentreId ?? null;
  const rows = (await sql`
    SELECT
      COALESCE(SUM(CASE WHEN ga.account_type = 'revenue' THEN jl.credit - jl.debit ELSE 0 END), 0) AS revenue,
      COALESCE(SUM(CASE WHEN ga.account_type = 'expense' THEN jl.debit - jl.credit ELSE 0 END), 0) AS expenses
    FROM gl_journal_lines jl
    JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
    JOIN gl_accounts ga ON ga.id = jl.gl_account_id
    WHERE je.status = 'posted'
      AND je.entry_date <= ${asAtDate}
      AND ga.account_type IN ('revenue', 'expense')
      AND (${ccId}::TEXT IS NULL OR jl.cost_center_id = ${ccId}::UUID)
  `) as Row[];

  return Number(rows[0]!.revenue) - Number(rows[0]!.expenses);
}

// ── VAT201 Return (SA SARS) ─────────────────────────────────────────────────

interface VAT201BoxDef {
  box: string;
  label: string;
  accountType: 'liability' | 'asset';
  vatTypes: string[];
}

const OUTPUT_BOXES: VAT201BoxDef[] = [
  { box: '1',   label: 'Standard rated supplies',           accountType: 'liability', vatTypes: ['standard'] },
  { box: '1A',  label: 'Capital goods/services supplied',   accountType: 'liability', vatTypes: ['capital_goods'] },
  { box: '2',   label: 'Zero-rated supplies (domestic)',    accountType: 'liability', vatTypes: ['zero_rated'] },
  { box: '2A',  label: 'Zero-rated exports',                accountType: 'liability', vatTypes: ['export'] },
  { box: '3',   label: 'Exempt supplies',                   accountType: 'liability', vatTypes: ['exempt'] },
  { box: '12',  label: 'Imported services / other output',  accountType: 'liability', vatTypes: ['reverse_charge', 'imported'] },
];

const INPUT_BOXES: VAT201BoxDef[] = [
  { box: '14',      label: 'Capital goods/services purchased', accountType: 'asset', vatTypes: ['capital_goods'] },
  { box: '15',      label: 'Other goods/services purchased',   accountType: 'asset', vatTypes: ['standard'] },
  { box: '14A/15A', label: 'Goods imported',                   accountType: 'asset', vatTypes: ['imported'] },
  { box: '16',      label: 'Change in use',                    accountType: 'asset', vatTypes: ['reverse_charge'] },
  { box: '17',      label: 'Bad debts',                        accountType: 'asset', vatTypes: ['bad_debt'] },
  { box: '18',      label: 'Other adjustments',                accountType: 'asset', vatTypes: ['exempt', 'no_vat'] },
];

/** Line-level transaction shape used in drill-down arrays. */
interface VATDrillDown {
  journalEntryId: string;
  entryNumber: string;
  entryDate: string;
  description: string;
  sourceDocument?: string;
  amount: number;
}

/** Populated VAT201 box with transactions list. */
interface PopulatedBox {
  box: string;
  label: string;
  amount: number;
  transactions: VATDrillDown[];
}

export async function getVATReturn(
  periodStart: string,
  periodEnd: string
): Promise<VATReturnReport> {
  try {
    // Fetch every posted journal line that touches a VAT-control account within the
    // period. Two account codes are targeted: 2120 (Output VAT liability) and 1140
    // (Input VAT asset). The account_subtype = 'tax' guard catches any additional
    // tax sub-ledger accounts the chart of accounts may define in the future.
    const vatLines = (await sql`
      SELECT
        jl.id              AS line_id,
        jl.gl_account_id,
        jl.debit,
        jl.credit,
        jl.vat_type,
        jl.description     AS line_description,
        je.id              AS journal_entry_id,
        je.entry_number,
        je.entry_date,
        je.description     AS entry_description,
        je.source_document_id,
        ga.account_code,
        ga.account_name,
        ga.account_type
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      JOIN gl_accounts ga        ON ga.id  = jl.gl_account_id
      WHERE je.status = 'posted'
        AND je.entry_date >= ${periodStart}
        AND je.entry_date <= ${periodEnd}
        AND (
          ga.account_code IN ('1140', '2120')
          OR ga.account_subtype = 'tax'
        )
      ORDER BY je.entry_date, je.entry_number
    `) as Row[];

    /** Build a drill-down transaction object from a raw journal line. */
    const toDrillDown = (l: Row, signFn: (debit: number, credit: number) => number): VATDrillDown => ({
      journalEntryId: String(l.journal_entry_id),
      entryNumber:    String(l.entry_number),
      entryDate:      String(l.entry_date),
      description:    l.entry_description
        ? String(l.entry_description)
        : l.line_description
          ? String(l.line_description)
          : '',
      sourceDocument: l.source_document_id ? String(l.source_document_id) : undefined,
      amount: signFn(Number(l.debit), Number(l.credit)),
    });

    // ── Output Boxes ────────────────────────────────────────────────────────
    const outputBoxes: PopulatedBox[] = OUTPUT_BOXES.map((boxDef) => {
      const matching = vatLines.filter((l: Row) => {
        const isOutput =
          String(l.account_type) === 'liability' ||
          String(l.account_code) === '2120';
        const matchesType =
          l.vat_type != null && boxDef.vatTypes.includes(String(l.vat_type));
        return isOutput && matchesType;
      });

      // Output VAT: credit increases the liability; net = credit - debit.
      const transactions = matching.map((l: Row) =>
        toDrillDown(l, (d, c) => c - d)
      );
      const amount = transactions.reduce((s, t) => s + t.amount, 0);
      return { box: boxDef.box, label: boxDef.label, amount, transactions };
    });

    // Unclassified output lines (vat_type IS NULL) default to Box 1 — standard.
    const unclassifiedOutput = vatLines.filter((l: Row) => {
      const isOutput =
        String(l.account_type) === 'liability' ||
        String(l.account_code) === '2120';
      return isOutput && l.vat_type == null;
    });
    if (unclassifiedOutput.length > 0) {
      const box1 = outputBoxes.find((b) => b.box === '1');
      if (box1) {
        const extra = unclassifiedOutput.map((l: Row) =>
          toDrillDown(l, (d, c) => c - d)
        );
        box1.amount += extra.reduce((s, t) => s + t.amount, 0);
        box1.transactions.push(...extra);
      }
    }

    // ── Input Boxes ──────────────────────────────────────────────────────────
    const inputBoxes: PopulatedBox[] = INPUT_BOXES.map((boxDef) => {
      const matching = vatLines.filter((l: Row) => {
        const isInput =
          String(l.account_type) === 'asset' ||
          String(l.account_code) === '1140';
        const matchesType =
          l.vat_type != null && boxDef.vatTypes.includes(String(l.vat_type));
        return isInput && matchesType;
      });

      // Input VAT: debit increases the asset; net = debit - credit.
      const transactions = matching.map((l: Row) =>
        toDrillDown(l, (d, c) => d - c)
      );
      const amount = transactions.reduce((s, t) => s + t.amount, 0);
      return { box: boxDef.box, label: boxDef.label, amount, transactions };
    });

    // Unclassified input lines (vat_type IS NULL) default to Box 15 — standard purchases.
    const unclassifiedInput = vatLines.filter((l: Row) => {
      const isInput =
        String(l.account_type) === 'asset' ||
        String(l.account_code) === '1140';
      return isInput && l.vat_type == null;
    });
    if (unclassifiedInput.length > 0) {
      const box15 = inputBoxes.find((b) => b.box === '15');
      if (box15) {
        const extra = unclassifiedInput.map((l: Row) =>
          toDrillDown(l, (d, c) => d - c)
        );
        box15.amount += extra.reduce((s, t) => s + t.amount, 0);
        box15.transactions.push(...extra);
      }
    }

    // ── Totals ───────────────────────────────────────────────────────────────
    const totalOutputTax = outputBoxes.reduce((s, b) => s + b.amount, 0);
    const totalInputTax  = inputBoxes.reduce((s, b) => s + b.amount, 0);
    const netVAT         = totalOutputTax - totalInputTax;

    // Legacy compatibility fields — summarise non-zero boxes as account-like lines.
    const outputDetails = outputBoxes
      .filter((b) => Math.abs(b.amount) > 0.001)
      .map((b) => ({ accountCode: b.box, accountName: b.label, amount: b.amount }));
    const inputDetails = inputBoxes
      .filter((b) => Math.abs(b.amount) > 0.001)
      .map((b) => ({ accountCode: b.box, accountName: b.label, amount: b.amount }));

    return {
      periodStart,
      periodEnd,
      outputBoxes,
      totalOutputTax,
      inputBoxes,
      totalInputTax,
      netVAT,
      outputVAT: totalOutputTax,
      inputVAT:  totalInputTax,
      outputDetails,
      inputDetails,
    };
  } catch (err) {
    log.error('Failed to generate VAT return', { error: err }, 'accounting');
    throw err;
  }
}

// ── Project Profitability ────────────────────────────────────────────────────

export async function getProjectProfitability(
  periodStart: string,
  periodEnd: string
): Promise<ProjectProfitabilityReport[]> {
  try {
    // Get all projects with journal activity in the period
    const projectRows = (await sql`
      SELECT DISTINCT jl.project_id, p.project_name
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      LEFT JOIN projects p ON p.id = jl.project_id
      WHERE je.status = 'posted'
        AND je.entry_date >= ${periodStart}
        AND je.entry_date <= ${periodEnd}
        AND jl.project_id IS NOT NULL
      ORDER BY p.project_name
    `) as Row[];

    const reports: ProjectProfitabilityReport[] = [];

    for (const proj of projectRows) {
      const projectId = String(proj.project_id);
      const projectName = proj.project_name ? String(proj.project_name) : 'Unknown Project';

      const rows = (await sql`
        SELECT ga.account_code, ga.account_name, ga.account_type,
          COALESCE(SUM(jl.debit), 0) AS total_debit,
          COALESCE(SUM(jl.credit), 0) AS total_credit
        FROM gl_journal_lines jl
        JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
        JOIN gl_accounts ga ON ga.id = jl.gl_account_id
        WHERE je.status = 'posted'
          AND je.entry_date >= ${periodStart}
          AND je.entry_date <= ${periodEnd}
          AND jl.project_id = ${projectId}::UUID
          AND ga.account_type IN ('revenue', 'expense')
        GROUP BY ga.id, ga.account_code, ga.account_name, ga.account_type
        ORDER BY ga.account_code
      `) as Row[];

      const revenueLines: ReportLineItem[] = [];
      const costLines: ReportLineItem[] = [];

      for (const r of rows) {
        const type = String(r.account_type);
        const debit = Number(r.total_debit);
        const credit = Number(r.total_credit);

        if (type === 'revenue') {
          const amount = credit - debit;
          if (Math.abs(amount) > 0.001) {
            revenueLines.push({ accountCode: String(r.account_code), accountName: String(r.account_name), amount });
          }
        } else if (type === 'expense') {
          const amount = debit - credit;
          if (Math.abs(amount) > 0.001) {
            costLines.push({ accountCode: String(r.account_code), accountName: String(r.account_name), amount });
          }
        }
      }

      const revenue = revenueLines.reduce((s, r) => s + r.amount, 0);
      const costs = costLines.reduce((s, c) => s + c.amount, 0);
      const profit = revenue - costs;
      const margin = revenue > 0 ? (profit / revenue) * 100 : 0;

      reports.push({
        projectId,
        projectName,
        periodStart,
        periodEnd,
        revenue,
        costs,
        profit,
        margin: Math.round(margin * 100) / 100,
        revenueLines,
        costLines,
      });
    }

    // Sort by profit DESC
    reports.sort((a, b) => b.profit - a.profit);
    return reports;
  } catch (err) {
    log.error('Failed to generate project profitability', { error: err }, 'accounting');
    throw err;
  }
}

/**
 * PRD-060: FibreFlow Accounting Module — Phase 2
 * Supplier Invoice Service
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { createJournalEntry, postJournalEntry } from './journalEntryService';
import { getAccountByCode } from './chartOfAccountsService';
import { validateThreeWayMatch } from '../utils/threeWayMatch';
import type {
  SupplierInvoice,
  SupplierInvoiceItem,
  SupplierInvoiceCreateInput,
  SupplierInvoiceStatus,
  InvoiceMatchStatus,
} from '../types/ap.types';
import type { JournalLineInput, VatType } from '../types/gl.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

interface InvoiceFilters {
  status?: SupplierInvoiceStatus;
  supplierId?: number;
  matchStatus?: InvoiceMatchStatus;
  limit?: number;
  offset?: number;
}

export async function getSupplierInvoices(filters?: InvoiceFilters): Promise<{
  invoices: SupplierInvoice[];
  total: number;
}> {
  try {
    const limit = filters?.limit || 50;
    const offset = filters?.offset || 0;
    let rows: Row[];
    let countRows: Row[];

    if (filters?.status && filters?.supplierId) {
      rows = (await sql`
        SELECT si.*, s.name AS supplier_name, po.po_number
        FROM supplier_invoices si
        LEFT JOIN suppliers s ON s.id = si.supplier_id
        LEFT JOIN purchase_orders po ON po.id = si.purchase_order_id
        WHERE si.status = ${filters.status} AND si.supplier_id = ${filters.supplierId}
        ORDER BY si.invoice_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM supplier_invoices
        WHERE status = ${filters.status} AND supplier_id = ${filters.supplierId}
      `) as Row[];
    } else if (filters?.status) {
      rows = (await sql`
        SELECT si.*, s.name AS supplier_name, po.po_number
        FROM supplier_invoices si
        LEFT JOIN suppliers s ON s.id = si.supplier_id
        LEFT JOIN purchase_orders po ON po.id = si.purchase_order_id
        WHERE si.status = ${filters.status}
        ORDER BY si.invoice_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM supplier_invoices WHERE status = ${filters.status}
      `) as Row[];
    } else if (filters?.supplierId) {
      rows = (await sql`
        SELECT si.*, s.name AS supplier_name, po.po_number
        FROM supplier_invoices si
        LEFT JOIN suppliers s ON s.id = si.supplier_id
        LEFT JOIN purchase_orders po ON po.id = si.purchase_order_id
        WHERE si.supplier_id = ${filters.supplierId}
        ORDER BY si.invoice_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM supplier_invoices WHERE supplier_id = ${filters.supplierId}
      `) as Row[];
    } else {
      rows = (await sql`
        SELECT si.*, s.name AS supplier_name, po.po_number
        FROM supplier_invoices si
        LEFT JOIN suppliers s ON s.id = si.supplier_id
        LEFT JOIN purchase_orders po ON po.id = si.purchase_order_id
        ORDER BY si.invoice_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`SELECT COUNT(*) AS cnt FROM supplier_invoices`) as Row[];
    }

    return { invoices: rows.map(mapInvoiceRow), total: Number(countRows[0]!.cnt) };
  } catch (err) {
    log.error('Failed to get supplier invoices', { error: err }, 'accounting');
    throw err;
  }
}

export async function getSupplierInvoiceById(
  id: string
): Promise<(SupplierInvoice & { items: SupplierInvoiceItem[] }) | null> {
  try {
    const rows = (await sql`
      SELECT si.*, s.name AS supplier_name, po.po_number
      FROM supplier_invoices si
      LEFT JOIN suppliers s ON s.id = si.supplier_id
      LEFT JOIN purchase_orders po ON po.id = si.purchase_order_id
      WHERE si.id = ${id}
    `) as Row[];
    if (rows.length === 0) return null;

    const itemRows = (await sql`
      SELECT sii.*, a.account_code, a.account_name
      FROM supplier_invoice_items sii
      LEFT JOIN gl_accounts a ON a.id = sii.gl_account_id
      WHERE sii.supplier_invoice_id = ${id}
      ORDER BY sii.created_at
    `) as Row[];

    return { ...mapInvoiceRow(rows[0]!), items: itemRows.map(mapItemRow) };
  } catch (err) {
    log.error('Failed to get supplier invoice', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function createSupplierInvoice(
  input: SupplierInvoiceCreateInput,
  userId: string
): Promise<SupplierInvoice> {
  try {
    const invoiceTaxRate = input.taxRate ?? 15;
    let subtotal = 0;
    let totalTax = 0;

    const computedItems = input.items.map(item => {
      const lineTotal = Math.round(item.quantity * item.unitPrice * 100) / 100;
      const itemTaxRate = item.taxRate ?? invoiceTaxRate;
      const itemTax = Math.round(lineTotal * itemTaxRate / 100 * 100) / 100;
      subtotal += lineTotal;
      totalTax += itemTax;
      return { ...item, lineTotal, taxAmount: itemTax, taxRate: itemTaxRate };
    });

    subtotal = Math.round(subtotal * 100) / 100;
    totalTax = Math.round(totalTax * 100) / 100;
    const totalAmount = subtotal + totalTax;

    const dueDate = input.dueDate || calculateDueDate(input.invoiceDate, input.paymentTerms);

    const rows = (await sql`
      INSERT INTO supplier_invoices (
        invoice_number, supplier_id, purchase_order_id, grn_id,
        invoice_date, due_date, subtotal, tax_rate, tax_amount,
        total_amount, payment_terms, reference, project_id,
        cost_center_id, notes, created_by
      ) VALUES (
        ${input.invoiceNumber}, ${input.supplierId},
        ${input.purchaseOrderId || null}, ${input.grnId || null},
        ${input.invoiceDate}, ${dueDate || null},
        ${subtotal}, ${invoiceTaxRate}, ${totalTax}, ${totalAmount},
        ${input.paymentTerms || null}, ${input.reference || null},
        ${input.projectId || null}, ${input.costCenterId || null},
        ${input.notes || null}, ${userId}::UUID
      ) RETURNING *
    `) as Row[];

    const invoiceId = String(rows[0]!.id);

    for (const item of computedItems) {
      await sql`
        INSERT INTO supplier_invoice_items (
          supplier_invoice_id, po_item_id, description, quantity,
          unit_price, tax_rate, tax_amount, line_total,
          gl_account_id, project_id, cost_center_id, vat_classification
        ) VALUES (
          ${invoiceId}::UUID, ${item.poItemId || null}, ${item.description},
          ${item.quantity}, ${item.unitPrice}, ${item.taxRate},
          ${item.taxAmount}, ${item.lineTotal},
          ${item.glAccountId || null}, ${item.projectId || null},
          ${item.costCenterId || null},
          ${item.vatClassification || (item.taxRate > 0 ? 'standard' : 'zero_rated')}
        )
      `;
    }

    log.info('Created supplier invoice', { invoiceId, invoiceNumber: input.invoiceNumber }, 'accounting');
    return mapInvoiceRow(rows[0]!);
  } catch (err) {
    log.error('Failed to create supplier invoice', { error: err }, 'accounting');
    throw err;
  }
}

export async function approveSupplierInvoice(
  id: string,
  userId: string
): Promise<SupplierInvoice> {
  try {
    const invoice = await getSupplierInvoiceById(id);
    if (!invoice) throw new Error(`Supplier invoice ${id} not found`);
    if (invoice.status !== 'draft' && invoice.status !== 'pending_approval') {
      throw new Error(`Cannot approve invoice with status: ${invoice.status}`);
    }

    // Auto-post GL entry: DR Expense + DR VAT Input, CR Accounts Payable
    const apAccount = await getAccountByCode('2110');
    const vatAccount = await getAccountByCode('1140');
    if (!apAccount) throw new Error('Accounts Payable account (2110) not found');
    if (!vatAccount) throw new Error('VAT Input account (1140) not found');

    const defaultExpenseAccount = await getAccountByCode('5100');
    const lines: JournalLineInput[] = [];

    for (const item of invoice.items) {
      const glAccountId = item.glAccountId || defaultExpenseAccount?.id;
      if (!glAccountId) throw new Error('No GL account for invoice item and no default expense account');
      lines.push({
        glAccountId,
        debit: item.lineTotal,
        credit: 0,
        description: item.description,
        projectId: item.projectId || invoice.projectId,
        costCenterId: item.costCenterId || invoice.costCenterId,
      });
    }

    if (invoice.taxAmount > 0) {
      lines.push({
        glAccountId: vatAccount.id,
        debit: invoice.taxAmount,
        credit: 0,
        description: `VAT on ${invoice.invoiceNumber}`,
        vatType: 'standard',
      });
    }

    lines.push({
      glAccountId: apAccount.id,
      debit: 0,
      credit: invoice.totalAmount,
      description: `AP: ${invoice.invoiceNumber}`,
    });

    const journalEntry = await createJournalEntry({
      entryDate: invoice.invoiceDate,
      description: `Supplier invoice ${invoice.invoiceNumber}`,
      source: 'auto_supplier_invoice',
      sourceDocumentId: id,
      lines,
    }, userId);

    await postJournalEntry(journalEntry.id, userId);

    const updated = (await sql`
      UPDATE supplier_invoices
      SET status = 'approved', approved_by = ${userId}::UUID, approved_at = NOW(),
          gl_journal_entry_id = ${journalEntry.id}::UUID
      WHERE id = ${id}
      RETURNING *
    `) as Row[];

    log.info('Approved supplier invoice', { id, journalEntryId: journalEntry.id }, 'accounting');
    return mapInvoiceRow(updated[0]!);
  } catch (err) {
    log.error('Failed to approve supplier invoice', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function cancelSupplierInvoice(id: string): Promise<SupplierInvoice> {
  try {
    const invoice = await getSupplierInvoiceById(id);
    if (!invoice) throw new Error(`Supplier invoice ${id} not found`);
    if (invoice.status === 'paid' || invoice.status === 'partially_paid') {
      throw new Error('Cannot cancel invoice with payments');
    }
    const rows = (await sql`
      UPDATE supplier_invoices SET status = 'cancelled' WHERE id = ${id} RETURNING *
    `) as Row[];
    return mapInvoiceRow(rows[0]!);
  } catch (err) {
    log.error('Failed to cancel supplier invoice', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function performThreeWayMatch(invoiceId: string) {
  try {
    const invoice = await getSupplierInvoiceById(invoiceId);
    if (!invoice) throw new Error(`Invoice ${invoiceId} not found`);
    if (!invoice.purchaseOrderId) throw new Error('Invoice has no linked PO');

    const poItems = (await sql`
      SELECT * FROM purchase_order_items WHERE purchase_order_id = ${invoice.purchaseOrderId}
    `) as Row[];

    const grnItems = invoice.grnId
      ? ((await sql`
          SELECT * FROM goods_receipt_items WHERE grn_id = ${invoice.grnId}
        `) as Row[])
      : [];

    const results = invoice.items.map(item => {
      const poItem = item.poItemId ? poItems.find((p: Row) => String(p.id) === item.poItemId) : null;
      const grnItem = poItem ? grnItems.find((g: Row) => String(g.po_item_id) === String(poItem.id)) : null;

      return {
        itemDescription: item.description,
        match: validateThreeWayMatch({
          poQuantity: poItem ? Number(poItem.quantity_ordered) : 0,
          poUnitPrice: poItem ? Number(poItem.unit_price) : 0,
          grnQuantityReceived: grnItem ? Number(grnItem.quantity_received) : 0,
          invoiceQuantity: item.quantity,
          invoiceUnitPrice: item.unitPrice,
        }),
      };
    });

    const overallStatus = results.every(r => r.match.status === 'fully_matched')
      ? 'fully_matched'
      : results.some(r => r.match.status === 'po_matched') ? 'po_matched'
      : results.some(r => r.match.status === 'grn_matched') ? 'grn_matched'
      : 'unmatched';

    await sql`
      UPDATE supplier_invoices SET match_status = ${overallStatus} WHERE id = ${invoiceId}
    `;

    return { invoiceId, matchStatus: overallStatus, itemResults: results };
  } catch (err) {
    log.error('Failed to perform 3-way match', { invoiceId, error: err }, 'accounting');
    throw err;
  }
}

function calculateDueDate(invoiceDate: string, paymentTerms?: string): string | null {
  if (!paymentTerms) return null;
  const match = paymentTerms.match(/net(\d+)/i);
  if (!match) return null;
  const date = new Date(invoiceDate);
  date.setDate(date.getDate() + Number(match[1]));
  return date.toISOString().split('T')[0]!;
}

function mapInvoiceRow(row: Row): SupplierInvoice {
  return {
    id: String(row.id),
    invoiceNumber: String(row.invoice_number),
    supplierId: String(row.supplier_id),
    purchaseOrderId: row.purchase_order_id ? String(row.purchase_order_id) : undefined,
    grnId: row.grn_id ? String(row.grn_id) : undefined,
    invoiceDate: String(row.invoice_date),
    dueDate: row.due_date ? String(row.due_date) : undefined,
    receivedDate: row.received_date ? String(row.received_date) : undefined,
    subtotal: Number(row.subtotal),
    taxRate: Number(row.tax_rate),
    taxAmount: Number(row.tax_amount),
    totalAmount: Number(row.total_amount),
    amountPaid: Number(row.amount_paid),
    balance: Number(row.balance),
    paymentTerms: row.payment_terms ? String(row.payment_terms) : undefined,
    currency: String(row.currency),
    reference: row.reference ? String(row.reference) : undefined,
    status: String(row.status) as SupplierInvoice['status'],
    matchStatus: String(row.match_status) as SupplierInvoice['matchStatus'],
    projectId: row.project_id ? String(row.project_id) : undefined,
    costCenterId: row.cost_center_id ? String(row.cost_center_id) : undefined,
    glJournalEntryId: row.gl_journal_entry_id ? String(row.gl_journal_entry_id) : undefined,
    sageInvoiceId: row.sage_invoice_id ? String(row.sage_invoice_id) : undefined,
    notes: row.notes ? String(row.notes) : undefined,
    createdBy: String(row.created_by),
    approvedBy: row.approved_by ? String(row.approved_by) : undefined,
    approvedAt: row.approved_at ? String(row.approved_at) : undefined,
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
    supplierName: row.supplier_name ? String(row.supplier_name) : undefined,
    poNumber: row.po_number ? String(row.po_number) : undefined,
  };
}

function mapItemRow(row: Row): SupplierInvoiceItem {
  return {
    id: String(row.id),
    supplierInvoiceId: String(row.supplier_invoice_id),
    poItemId: row.po_item_id ? String(row.po_item_id) : undefined,
    description: String(row.description),
    quantity: Number(row.quantity),
    unitPrice: Number(row.unit_price),
    taxRate: Number(row.tax_rate),
    taxAmount: Number(row.tax_amount),
    lineTotal: Number(row.line_total),
    glAccountId: row.gl_account_id ? String(row.gl_account_id) : undefined,
    projectId: row.project_id ? String(row.project_id) : undefined,
    costCenterId: row.cost_center_id ? String(row.cost_center_id) : undefined,
    vatClassification: row.vat_classification ? String(row.vat_classification) as VatType : undefined,
    createdAt: String(row.created_at),
  };
}

