/**
 * Bank Rules Action API
 * POST — delete, toggle, or apply rules
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { deleteRule, deleteRules, toggleRule, applyRules, updateRule } from '@/modules/accounting/services/bankRulesService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') return apiResponse.methodNotAllowed(res, req.method!);

  const userId = (req as AuthenticatedNextApiRequest).user.id;
  const { action, id, ids, isActive, bankAccountId } = req.body;

  try {
    switch (action) {
      case 'delete':
        if (!id) return apiResponse.badRequest(res, 'id required');
        await deleteRule(id);
        return apiResponse.success(res, { deleted: true });

      case 'deleteMany': {
        if (!Array.isArray(ids) || ids.length === 0) return apiResponse.badRequest(res, 'ids array required');
        const count = await deleteRules(ids);
        return apiResponse.success(res, { deleted: count });
      }

      case 'toggle':
        if (!id) return apiResponse.badRequest(res, 'id required');
        await toggleRule(id, isActive !== false);
        return apiResponse.success(res, { toggled: true });

      case 'update': {
        if (!id) return apiResponse.badRequest(res, 'id required');
        const updated = await updateRule(id, req.body);
        return apiResponse.success(res, updated);
      }

      case 'apply': {
        if (!bankAccountId) return apiResponse.badRequest(res, 'bankAccountId required');
        const result = await applyRules(bankAccountId, userId);
        return apiResponse.success(res, result);
      }

      default:
        return apiResponse.badRequest(res, `Unknown action: ${action}`);
    }
  } catch (err) {
    log.error('Bank rules action failed', { action, error: err }, 'accounting-api');
    return apiResponse.badRequest(res, err instanceof Error ? err.message : 'Action failed');
  }
}

export default withAuth(withErrorHandler(handler));
/**
 * Bank Rules Preview API
 * GET — returns count of transactions matching a pattern
 * Query params: bankAccountId, pattern, matchType, matchField
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { sql } from '@/lib/neon';

type Row = Record<string, unknown>;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method!, ['GET']);
  }

  const { bankAccountId, pattern, matchType = 'contains', matchField = 'description' } = req.query;

  if (!pattern || typeof pattern !== 'string') {
    return apiResponse.badRequest(res, 'pattern is required');
  }

  const raw = pattern.trim();
  if (!raw) return apiResponse.success(res, { matchCount: 0 });

  // Build ILIKE pattern
  let ilike: string;
  if (matchType === 'starts_with') ilike = `${raw}%`;
  else if (matchType === 'ends_with') ilike = `%${raw}`;
  else if (matchType === 'exact') ilike = raw;
  else ilike = `%${raw}%`;

  const bid = typeof bankAccountId === 'string' ? bankAccountId : null;
  const field = typeof matchField === 'string' ? matchField : 'description';

  // Explicit query branches: bankAccountId × matchField (no conditional SQL)
  let rows: Row[];

  if (bid && field === 'description') {
    rows = (await sql`SELECT COUNT(*)::INT AS cnt FROM bank_transactions WHERE bank_account_id = ${bid}::UUID AND description ILIKE ${ilike}`) as Row[];
  } else if (bid && field === 'reference') {
    rows = (await sql`SELECT COUNT(*)::INT AS cnt FROM bank_transactions WHERE bank_account_id = ${bid}::UUID AND reference ILIKE ${ilike}`) as Row[];
  } else if (bid && field === 'both') {
    rows = (await sql`SELECT COUNT(*)::INT AS cnt FROM bank_transactions WHERE bank_account_id = ${bid}::UUID AND (description ILIKE ${ilike} OR reference ILIKE ${ilike})`) as Row[];
  } else if (field === 'reference') {
    rows = (await sql`SELECT COUNT(*)::INT AS cnt FROM bank_transactions WHERE reference ILIKE ${ilike}`) as Row[];
  } else if (field === 'both') {
    rows = (await sql`SELECT COUNT(*)::INT AS cnt FROM bank_transactions WHERE description ILIKE ${ilike} OR reference ILIKE ${ilike}`) as Row[];
  } else {
    rows = (await sql`SELECT COUNT(*)::INT AS cnt FROM bank_transactions WHERE description ILIKE ${ilike}`) as Row[];
  }

  return apiResponse.success(res, { matchCount: Number(rows[0]?.cnt || 0) });
}

export default withAuth(withErrorHandler(handler));
/**
 * Bank Rules Seed API
 * POST /api/accounting/bank-rules-seed
 *   Seed categorisation rules from a Category Map (JSON array).
 *
 * Body: { entries: [{ originalCategory, standardCategory, glCode }] }
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

interface CategoryMapEntry {
  originalCategory: string;
  standardCategory: string;
  glCode: number | string;
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
  }

  try {
    const userId = String((req as unknown as Record<string, unknown>).userId || '');
    const { entries } = req.body as { entries: CategoryMapEntry[] };

    if (!Array.isArray(entries) || entries.length === 0) {
      return apiResponse.badRequest(res, 'entries array is required');
    }

    let created = 0;
    let skipped = 0;
    const missingGlCodes: (number | string)[] = [];

    for (const entry of entries) {
      const pattern = String(entry.originalCategory || '').toLowerCase().trim();
      if (!pattern) { skipped++; continue; }

      const glCode = String(entry.glCode).trim();
      if (!glCode) { skipped++; continue; }

      // Look up GL account by account_code
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const glRows = (await sql`
        SELECT id FROM gl_accounts WHERE account_code = ${glCode} LIMIT 1
      `) as any[];

      if (glRows.length === 0) {
        missingGlCodes.push(entry.glCode);
        skipped++;
        continue;
      }

      const glAccountId = String(glRows[0].id);
      const ruleName = String(entry.standardCategory || entry.originalCategory).trim();

      // UPSERT — skip if match_pattern already exists
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const existing = (await sql`
        SELECT id FROM bank_categorisation_rules
        WHERE LOWER(match_pattern) = ${pattern} LIMIT 1
      `) as any[];

      if (existing.length > 0) {
        skipped++;
        continue;
      }

      await sql`
        INSERT INTO bank_categorisation_rules (
          rule_name, match_field, match_type, match_pattern,
          gl_account_id, auto_create_entry, priority, created_by
        ) VALUES (
          ${ruleName}, 'description', 'contains', ${pattern},
          ${glAccountId}::UUID, false, 100, ${userId || null}
        )
      `;
      created++;
    }

    log.info('Seeded bank categorisation rules', { created, skipped, missingGlCodes: missingGlCodes.length }, 'accounting');

    return apiResponse.success(res, {
      created,
      skipped,
      missingGlCodes: missingGlCodes.length > 0 ? missingGlCodes : undefined,
    });
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Failed to seed bank rules';
    log.error('Failed to seed bank rules', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, message);
  }
}

export default withAuth(withErrorHandler(handler));
/**
 * Bank Categorisation Rules API
 * GET  — list all rules
 * POST — create a new rule
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { getRules, createRule } from '@/modules/accounting/services/bankRulesService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const userId = (req as AuthenticatedNextApiRequest).user.id;

  if (req.method === 'GET') {
    const rules = await getRules();
    return apiResponse.success(res, { items: rules });
  }

  if (req.method === 'POST') {
    const { ruleName, matchField, matchType, matchPattern, glAccountId, supplierId, clientId, descriptionTemplate, priority, autoCreateEntry, vatCode } = req.body;
    if (!ruleName || !matchField || !matchType || !matchPattern) {
      return apiResponse.badRequest(res, 'ruleName, matchField, matchType, and matchPattern are required');
    }
    if (!glAccountId && !supplierId && !clientId) {
      return apiResponse.badRequest(res, 'Either glAccountId, supplierId, or clientId is required');
    }
    const rule = await createRule({
      ruleName, matchField, matchType, matchPattern, glAccountId: glAccountId || undefined,
      supplierId: supplierId || undefined,
      clientId: clientId || undefined,
      descriptionTemplate: descriptionTemplate || undefined,
      priority: priority || 100,
      autoCreateEntry: autoCreateEntry !== false,
      vatCode: vatCode || 'none',
    }, userId);
    return apiResponse.success(res, rule);
  }

  return apiResponse.methodNotAllowed(res, req.method!);
}

export default withAuth(withErrorHandler(handler));

