/**
 * Bank Transfers API
 * POST /api/accounting/bank-transfers - Transfer between bank accounts
 * Creates a balanced journal entry: DR destination bank, CR source bank
 * Sage equivalent: Banking > Transfers
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { createLoggedSql } from '@/lib/db-logger';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';

const sql = createLoggedSql(process.env.DATABASE_URL!);

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
  }

  const userId = (req as AuthenticatedNextApiRequest).user.id;
  const { fromAccountId, toAccountId, amount, reference, transferDate } = req.body;

  if (!fromAccountId || !toAccountId || !amount) {
    return apiResponse.validationError(res, {
      fromAccountId: !fromAccountId ? 'Required' : undefined,
      toAccountId: !toAccountId ? 'Required' : undefined,
      amount: !amount ? 'Required' : undefined,
    });
  }

  if (fromAccountId === toAccountId) {
    return apiResponse.badRequest(res, 'Source and destination accounts must be different');
  }

  if (Number(amount) <= 0) {
    return apiResponse.badRequest(res, 'Transfer amount must be positive');
  }

  try {
    // Verify both accounts exist and are bank accounts
    const accounts = await sql`
      SELECT id, account_code, account_name, account_subtype
      FROM gl_accounts
      WHERE id IN (${fromAccountId}, ${toAccountId})
    `;

    if (accounts.length !== 2) {
      return apiResponse.badRequest(res, 'One or both accounts not found');
    }

    const fromAcct = accounts.find(a => a.id === fromAccountId);
    const toAcct = accounts.find(a => a.id === toAccountId);

    // Get current fiscal period
    const [period] = await sql`
      SELECT id FROM fiscal_periods
      WHERE status = 'open'
      ORDER BY start_date DESC
      LIMIT 1
    `;

    // Create journal entry
    const entryRef = reference || `Transfer: ${fromAcct?.account_name} → ${toAcct?.account_name}`;
    const txDate = transferDate || new Date().toISOString().split('T')[0];

    const [entry] = await sql`
      INSERT INTO gl_journal_entries (
        id, entry_number, entry_date, description,
        source, status, fiscal_period_id,
        total_debit, total_credit,
        created_by, created_at
      ) VALUES (
        gen_random_uuid(),
        'TXF-' || LPAD((SELECT COALESCE(MAX(CAST(SUBSTRING(entry_number FROM 5) AS INTEGER)), 0) + 1 FROM gl_journal_entries WHERE entry_number LIKE 'TXF-%')::text, 4, '0'),
        ${txDate}, ${entryRef},
        'bank_transfer', 'posted', ${period?.id || null},
        ${Number(amount)}, ${Number(amount)},
        ${userId}, NOW()
      )
      RETURNING *
    `;

    // Create journal lines: DR destination, CR source
    await sql`
      INSERT INTO gl_journal_lines (id, journal_entry_id, gl_account_id, debit, credit, description, created_at)
      VALUES
        (gen_random_uuid(), ${entry.id}, ${toAccountId}, ${Number(amount)}, 0, ${`Transfer from ${fromAcct?.account_name}`}, NOW()),
        (gen_random_uuid(), ${entry.id}, ${fromAccountId}, 0, ${Number(amount)}, ${`Transfer to ${toAcct?.account_name}`}, NOW())
    `;

    log.info('Bank transfer completed', {
      entryId: entry.id,
      from: fromAcct?.account_code,
      to: toAcct?.account_code,
      amount,
      module: 'accounting',
    });

    return apiResponse.success(res, {
      journalEntry: entry,
      message: `Transferred R${Number(amount).toFixed(2)} from ${fromAcct?.account_name} to ${toAcct?.account_name}`,
    });
  } catch (err) {
    log.error('Failed to process bank transfer', { error: err, module: 'accounting' });
    return apiResponse.databaseError(res, err, 'Failed to process bank transfer');
  }
}

export default withAuth(withErrorHandler(handler));
/**
 * Bank Transaction Attachments API
 *
 * GET  /api/accounting/bank-tx-attachments?bankTransactionId=<uuid>
 *   → List all attachments for a bank transaction, newest first.
 *
 * POST /api/accounting/bank-tx-attachments
 *   Body: { bankTransactionId, fileName, fileData (base64 data URL), fileSize? }
 *   → Store an attachment. Small receipts (≤ 2 MB) are kept as data URLs in file_url.
 *
 * DELETE /api/accounting/bank-tx-attachments?id=<uuid>
 *   → Remove a single attachment record.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';

// ── Local Types ───────────────────────────────────────────────────────────────

// Neon's sql tagged template returns a union type. Casting through unknown[]
// is the project-standard pattern (see bankReconciliationService.ts Row = any).
// eslint-disable-next-line @typescript-eslint/no-explicit-any
type SqlRow = Record<string, any>;

interface PostBody {
  bankTransactionId?: string;
  fileName?: string;
  fileData?: string; // base64 data URL: "data:<mime>;base64,<data>"
  fileSize?: number;
}

// ── Constants ─────────────────────────────────────────────────────────────────

/** 2 MB limit — data URLs expand ~33 % in transit, so clamp at 2 MB of raw bytes */
const MAX_FILE_SIZE_BYTES = 2 * 1024 * 1024;

/** Allowed MIME types derived from the data URL header */
const ALLOWED_MIME_TYPES = ['image/jpeg', 'image/png', 'application/pdf'];

// ── Helpers ───────────────────────────────────────────────────────────────────

/** Extract the MIME type from a base64 data URL string */
function extractMime(dataUrl: string): string | null {
  const match = dataUrl.match(/^data:([a-zA-Z0-9]+\/[a-zA-Z0-9.+-]+);base64,/);
  return match ? match[1] ?? null : null;
}

/** Rough byte size estimate for a base64-encoded data URL */
function estimateDataUrlBytes(dataUrl: string): number {
  const base64Part = dataUrl.split(',')[1] ?? '';
  return Math.ceil((base64Part.length * 3) / 4);
}

// ── Handler ───────────────────────────────────────────────────────────────────

async function handler(req: NextApiRequest, res: NextApiResponse) {
  // @ts-expect-error — auth middleware attaches user
  const userId: string | null = req.user?.id ?? req.user?.userId ?? null;

  // ── GET ────────────────────────────────────────────────────────────────────
  if (req.method === 'GET') {
    const { bankTransactionId } = req.query;

    if (!bankTransactionId || typeof bankTransactionId !== 'string') {
      return apiResponse.badRequest(res, 'bankTransactionId query param is required');
    }

    const rows = (await sql`
      SELECT
        id,
        bank_transaction_id,
        file_url,
        file_name,
        file_size,
        uploaded_by,
        created_at
      FROM bank_transaction_attachments
      WHERE bank_transaction_id = ${bankTransactionId}::UUID
      ORDER BY created_at DESC
    `) as SqlRow[];

    log.info('Listed bank tx attachments', { bankTransactionId, count: rows.length }, 'bank-tx-attachments');
    return apiResponse.success(res, rows);
  }

  // ── POST ───────────────────────────────────────────────────────────────────
  if (req.method === 'POST') {
    const { bankTransactionId, fileName, fileData, fileSize } = req.body as PostBody;

    if (!bankTransactionId) return apiResponse.badRequest(res, 'bankTransactionId is required');
    if (!fileName) return apiResponse.badRequest(res, 'fileName is required');
    if (!fileData || typeof fileData !== 'string') {
      return apiResponse.badRequest(res, 'fileData (base64 data URL) is required');
    }

    // Validate MIME type
    const mime = extractMime(fileData);
    if (!mime || !ALLOWED_MIME_TYPES.includes(mime)) {
      return apiResponse.badRequest(res, `File type not allowed. Accepted: ${ALLOWED_MIME_TYPES.join(', ')}`);
    }

    // Validate file size
    const byteSize = fileSize ?? estimateDataUrlBytes(fileData);
    if (byteSize > MAX_FILE_SIZE_BYTES) {
      return apiResponse.badRequest(res, 'File exceeds the 2 MB size limit');
    }

    const insertRows = (await sql`
      INSERT INTO bank_transaction_attachments
        (bank_transaction_id, file_url, file_name, file_size, uploaded_by)
      VALUES
        (
          ${bankTransactionId}::UUID,
          ${fileData},
          ${fileName},
          ${byteSize},
          ${userId}::UUID
        )
      RETURNING
        id, bank_transaction_id, file_url, file_name, file_size, uploaded_by, created_at
    `) as SqlRow[];

    const attachment = insertRows[0];
    log.info('Uploaded bank tx attachment', { bankTransactionId, fileName, byteSize }, 'bank-tx-attachments');
    return apiResponse.created(res, attachment, 'Attachment uploaded');
  }

  // ── DELETE ─────────────────────────────────────────────────────────────────
  if (req.method === 'DELETE') {
    const { id } = req.query;

    if (!id || typeof id !== 'string') {
      return apiResponse.badRequest(res, 'id query param is required');
    }

    const deleteRows = (await sql`
      DELETE FROM bank_transaction_attachments
      WHERE id = ${id}::UUID
      RETURNING id
    `) as SqlRow[];

    if (!deleteRows || deleteRows.length === 0) {
      return apiResponse.notFound(res, 'Attachment', id);
    }

    log.info('Deleted bank tx attachment', { id }, 'bank-tx-attachments');
    return apiResponse.success(res, { deleted: id });
  }

  return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['GET', 'POST', 'DELETE']);
}

export default withAuth(withErrorHandler(handler));

/**
 * Batch Payment Actions API
 * POST — approve, process, cancel
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  approveBatch,
  processBatch,
  cancelBatch,
} from '@/modules/accounting/services/batchPaymentService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
  }

  try {
    const { action, id } = req.body;
    const userId = (req as unknown as { user?: { id: string } }).user?.id || req.body.userId;
    if (!action || !id) return apiResponse.badRequest(res, 'action and id are required');

    switch (action) {
      case 'approve': {
        if (!userId) return apiResponse.badRequest(res, 'userId is required');
        await approveBatch(id, userId);
        return apiResponse.success(res, { status: 'approved' });
      }
      case 'process': {
        if (!userId) return apiResponse.badRequest(res, 'userId is required');
        await processBatch(id, userId);
        return apiResponse.success(res, { status: 'processed' });
      }
      case 'cancel':
        await cancelBatch(id);
        return apiResponse.success(res, { status: 'cancelled' });
      default:
        return apiResponse.badRequest(res, `Unknown action: ${action}`);
    }
  } catch (err) {
    const msg = err instanceof Error ? err.message : 'Action failed';
    log.error('Batch payment action failed', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, msg);
  }
}

export default withAuth(withErrorHandler(handler));
/**
 * Supplier Batch Payments API
 * GET  — list batches
 * POST — create batch
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import { getBatches, getBatchById, createBatch } from '@/modules/accounting/services/batchPaymentService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    const { id, status, limit, offset } = req.query;

    // Single batch by ID
    if (id) {
      const batch = await getBatchById(id as string);
      if (!batch) return apiResponse.notFound(res, 'Batch', id as string);
      return apiResponse.success(res, batch);
    }

    const result = await getBatches({
      status: status as string,
      limit: limit ? Number(limit) : undefined,
      offset: offset ? Number(offset) : undefined,
    });
    return apiResponse.success(res, result);
  }

  if (req.method === 'POST') {
    const userId = (req as unknown as { user?: { id: string } }).user?.id || req.body.userId;
    if (!userId) return apiResponse.badRequest(res, 'userId is required');
    try {
      const item = await createBatch(req.body, userId);
      return apiResponse.success(res, item);
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Create failed';
      log.error('Batch payment create failed', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, msg);
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

export default withAuth(withErrorHandler(handler));

