/**
 * Debtors Manager Service
 * Sage-parity collections/aging dashboard for AR
 *
 * Queries customer_invoices and customer_payments (existing tables).
 * No new migration required.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// ── Types ─────────────────────────────────────────────────────────────────────

export interface DebtorSummary {
  clientId: string;
  clientName: string;
  current: number;
  days30: number;
  days60: number;
  days90: number;
  days90Plus: number;
  totalOutstanding: number;
  invoiceCount: number;
}

export interface DebtorInvoice {
  id: string;
  invoiceNumber: string;
  invoiceDate: string;
  dueDate: string | null;
  totalAmount: number;
  amountPaid: number;
  outstanding: number;
  daysOverdue: number;
  status: string;
  agingBucket: 'current' | 'days30' | 'days60' | 'days90' | 'days90Plus';
}

export interface OverdueInvoice {
  id: string;
  invoiceNumber: string;
  clientId: string;
  clientName: string;
  invoiceDate: string;
  dueDate: string;
  totalAmount: number;
  amountPaid: number;
  outstanding: number;
  daysOverdue: number;
  status: string;
}

export interface CollectionStats {
  totalOutstanding: number;
  totalOverdue: number;
  avgDaysOutstanding: number;
  collectionRate: number;
  clientCount: number;
  overdueCount: number;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function classifyBucket(daysOverdue: number): DebtorInvoice['agingBucket'] {
  if (daysOverdue <= 0) return 'current';
  if (daysOverdue <= 30) return 'days30';
  if (daysOverdue <= 60) return 'days60';
  if (daysOverdue <= 90) return 'days90';
  return 'days90Plus';
}

// ── Debtors Summary ───────────────────────────────────────────────────────────

/**
 * Aggregate outstanding invoices by customer with aging buckets.
 * Buckets: current (not yet due), 1-30, 31-60, 61-90, 90+ days overdue.
 */
export async function getDebtorsSummary(): Promise<DebtorSummary[]> {
  try {
    const rows = (await sql`
      SELECT
        ci.client_id,
        c.company_name AS client_name,
        COUNT(ci.id)::int AS invoice_count,
        SUM(
          CASE WHEN ci.due_date IS NULL OR ci.due_date >= CURRENT_DATE
               THEN (ci.total_amount - ci.amount_paid) ELSE 0 END
        ) AS current,
        SUM(
          CASE WHEN ci.due_date IS NOT NULL
                AND ci.due_date < CURRENT_DATE
                AND (CURRENT_DATE - ci.due_date) <= 30
               THEN (ci.total_amount - ci.amount_paid) ELSE 0 END
        ) AS days30,
        SUM(
          CASE WHEN ci.due_date IS NOT NULL
                AND (CURRENT_DATE - ci.due_date) BETWEEN 31 AND 60
               THEN (ci.total_amount - ci.amount_paid) ELSE 0 END
        ) AS days60,
        SUM(
          CASE WHEN ci.due_date IS NOT NULL
                AND (CURRENT_DATE - ci.due_date) BETWEEN 61 AND 90
               THEN (ci.total_amount - ci.amount_paid) ELSE 0 END
        ) AS days90,
        SUM(
          CASE WHEN ci.due_date IS NOT NULL
                AND (CURRENT_DATE - ci.due_date) > 90
               THEN (ci.total_amount - ci.amount_paid) ELSE 0 END
        ) AS days90_plus,
        SUM(ci.total_amount - ci.amount_paid) AS total_outstanding
      FROM customer_invoices ci
      JOIN clients c ON c.id = ci.client_id
      WHERE ci.status IN ('approved', 'sent', 'partially_paid', 'overdue')
        AND (ci.total_amount - ci.amount_paid) > 0
      GROUP BY ci.client_id, c.company_name
      ORDER BY total_outstanding DESC
    `) as Row[];

    return rows.map((r: Row) => ({
      clientId: String(r.client_id),
      clientName: String(r.client_name),
      current: Number(r.current),
      days30: Number(r.days30),
      days60: Number(r.days60),
      days90: Number(r.days90),
      days90Plus: Number(r.days90_plus),
      totalOutstanding: Number(r.total_outstanding),
      invoiceCount: Number(r.invoice_count),
    }));
  } catch (err) {
    log.error('getDebtorsSummary failed', { error: err }, 'accounting');
    throw err;
  }
}

// ── Debtor Detail ─────────────────────────────────────────────────────────────

/**
 * List outstanding invoices for a specific customer with age and amounts.
 */
export async function getDebtorDetail(clientId: string): Promise<DebtorInvoice[]> {
  try {
    const rows = (await sql`
      SELECT
        ci.id,
        ci.invoice_number,
        ci.invoice_date,
        ci.due_date,
        ci.total_amount,
        ci.amount_paid,
        (ci.total_amount - ci.amount_paid) AS outstanding,
        ci.status,
        CASE
          WHEN ci.due_date IS NULL THEN 0
          ELSE GREATEST(0, (CURRENT_DATE - ci.due_date)::int)
        END AS days_overdue
      FROM customer_invoices ci
      WHERE ci.client_id = ${clientId}::UUID
        AND ci.status IN ('approved', 'sent', 'partially_paid', 'overdue')
        AND (ci.total_amount - ci.amount_paid) > 0
      ORDER BY ci.due_date ASC NULLS LAST, ci.invoice_date ASC
    `) as Row[];

    return rows.map((r: Row) => {
      const daysOverdue = Number(r.days_overdue);
      return {
        id: String(r.id),
        invoiceNumber: String(r.invoice_number),
        invoiceDate: String(r.invoice_date),
        dueDate: r.due_date ? String(r.due_date) : null,
        totalAmount: Number(r.total_amount),
        amountPaid: Number(r.amount_paid),
        outstanding: Number(r.outstanding),
        daysOverdue,
        status: String(r.status),
        agingBucket: classifyBucket(daysOverdue),
      };
    });
  } catch (err) {
    log.error('getDebtorDetail failed', { clientId, error: err }, 'accounting');
    throw err;
  }
}

// ── Overdue Invoices ──────────────────────────────────────────────────────────

/**
 * List all overdue invoices sorted by age descending.
 * Optionally filter to invoices overdue by at least daysOverdue days.
 */
export async function getOverdueInvoices(daysOverdue?: number): Promise<OverdueInvoice[]> {
  const minDays = daysOverdue ?? 1;

  try {
    const rows = (await sql`
      SELECT
        ci.id,
        ci.invoice_number,
        ci.client_id,
        c.company_name AS client_name,
        ci.invoice_date,
        ci.due_date,
        ci.total_amount,
        ci.amount_paid,
        (ci.total_amount - ci.amount_paid) AS outstanding,
        (CURRENT_DATE - ci.due_date)::int AS days_overdue,
        ci.status
      FROM customer_invoices ci
      JOIN clients c ON c.id = ci.client_id
      WHERE ci.due_date IS NOT NULL
        AND ci.due_date < CURRENT_DATE
        AND (CURRENT_DATE - ci.due_date) >= ${minDays}
        AND ci.status IN ('approved', 'sent', 'partially_paid', 'overdue')
        AND (ci.total_amount - ci.amount_paid) > 0
      ORDER BY days_overdue DESC, ci.total_amount DESC
    `) as Row[];

    return rows.map((r: Row) => ({
      id: String(r.id),
      invoiceNumber: String(r.invoice_number),
      clientId: String(r.client_id),
      clientName: String(r.client_name),
      invoiceDate: String(r.invoice_date),
      dueDate: String(r.due_date),
      totalAmount: Number(r.total_amount),
      amountPaid: Number(r.amount_paid),
      outstanding: Number(r.outstanding),
      daysOverdue: Number(r.days_overdue),
      status: String(r.status),
    }));
  } catch (err) {
    log.error('getOverdueInvoices failed', { daysOverdue, error: err }, 'accounting');
    throw err;
  }
}

// ── Collection Stats ──────────────────────────────────────────────────────────

/**
 * Aggregate collection metrics: total outstanding, total overdue,
 * average days outstanding, and collection rate.
 */
export async function getCollectionStats(): Promise<CollectionStats> {
  try {
    const rows = (await sql`
      SELECT
        SUM(ci.total_amount - ci.amount_paid)                            AS total_outstanding,
        SUM(CASE WHEN ci.due_date < CURRENT_DATE
                 THEN (ci.total_amount - ci.amount_paid) ELSE 0 END)     AS total_overdue,
        COALESCE(AVG(
          CASE WHEN ci.due_date IS NOT NULL AND ci.due_date < CURRENT_DATE
               THEN (CURRENT_DATE - ci.due_date)::numeric END
        ), 0)                                                             AS avg_days_outstanding,
        COUNT(DISTINCT ci.client_id)::int                                AS client_count,
        COUNT(CASE WHEN ci.due_date < CURRENT_DATE THEN 1 END)::int      AS overdue_count
      FROM customer_invoices ci
      WHERE ci.status IN ('approved', 'sent', 'partially_paid', 'overdue')
        AND (ci.total_amount - ci.amount_paid) > 0
    `) as Row[];

    const rateRows = (await sql`
      SELECT
        SUM(ci.total_amount)  AS invoiced,
        SUM(ci.amount_paid)   AS collected
      FROM customer_invoices ci
      WHERE ci.status NOT IN ('draft', 'cancelled')
    `) as Row[];

    const r = rows[0] ?? {};
    const rate = rateRows[0] ?? {};
    const invoiced = Number(rate.invoiced ?? 0);
    const collected = Number(rate.collected ?? 0);

    return {
      totalOutstanding: Number(r.total_outstanding ?? 0),
      totalOverdue: Number(r.total_overdue ?? 0),
      avgDaysOutstanding: Math.round(Number(r.avg_days_outstanding ?? 0)),
      collectionRate: invoiced > 0 ? Math.round((collected / invoiced) * 100 * 10) / 10 : 0,
      clientCount: Number(r.client_count ?? 0),
      overdueCount: Number(r.overdue_count ?? 0),
    };
  } catch (err) {
    log.error('getCollectionStats failed', { error: err }, 'accounting');
    throw err;
  }
}

/**
 * PRD-060: FibreFlow Accounting Module
 * AP/AR Aging Bucket Calculations
 *
 * Calculates aging buckets: Current, 30, 60, 90, 120+ days
 * Used for both Accounts Payable and Accounts Receivable.
 */

import type { AgingBucket, AgingBucketName, AgingInvoice } from '../types/ap.types';

/**
 * Classify a single invoice into an aging bucket based on due date.
 *
 * - Current: not yet due (due date >= as-at date)
 * - 30 days: 1-30 days overdue
 * - 60 days: 31-60 days overdue
 * - 90 days: 61-90 days overdue
 * - 120+ days: 91+ days overdue
 */
export function getAgingBucket(dueDate: Date, asAtDate: Date): AgingBucketName {
  const diffMs = asAtDate.getTime() - dueDate.getTime();
  const daysOverdue = Math.floor(diffMs / (1000 * 60 * 60 * 24));

  if (daysOverdue <= 0) return 'current';
  if (daysOverdue <= 30) return 'days30';
  if (daysOverdue <= 60) return 'days60';
  if (daysOverdue <= 90) return 'days90';
  return 'days120Plus';
}

/**
 * Calculate aging buckets for a set of invoices, grouped by entity (supplier or client).
 *
 * - Excludes zero-balance invoices
 * - Groups by entityId
 * - Sorts by total descending
 */
export function calculateAgingBuckets(
  invoices: AgingInvoice[],
  asAtDate: Date
): AgingBucket[] {
  // Filter out zero-balance invoices
  const outstanding = invoices.filter(inv => inv.balance > 0);

  if (outstanding.length === 0) return [];

  // Group by entity
  const grouped = new Map<string, AgingBucket>();

  for (const inv of outstanding) {
    const bucket = getAgingBucket(new Date(inv.dueDate), asAtDate);

    if (!grouped.has(inv.entityId)) {
      grouped.set(inv.entityId, {
        entityId: inv.entityId,
        entityName: inv.entityName,
        current: 0,
        days30: 0,
        days60: 0,
        days90: 0,
        days120Plus: 0,
        total: 0,
      });
    }

    const entry = grouped.get(inv.entityId)!;
    entry[bucket] += inv.balance;
    entry.total += inv.balance;
  }

  // Sort by total descending
  return Array.from(grouped.values()).sort((a, b) => b.total - a.total);
}

/**
 * PRD-060: FibreFlow Accounting Module
 * Double-Entry Validation Utilities
 *
 * Core validation logic for journal entries ensuring
 * fundamental accounting equation integrity.
 */

import type { JournalLineInput, JournalValidationResult, LineValidationResult } from '../types/gl.types';

/**
 * Validate a single journal line.
 * Rules:
 * - Must have a valid glAccountId
 * - Debit and credit must be >= 0
 * - Exactly one of debit/credit must be > 0 (not both, not neither)
 */
export function validateJournalLine(line: JournalLineInput): LineValidationResult {
  if (!line.glAccountId || line.glAccountId.trim() === '') {
    return { valid: false, error: 'GL account ID is required' };
  }

  if (line.debit < 0 || line.credit < 0) {
    return { valid: false, error: 'Debit and credit amounts cannot be negative' };
  }

  if (line.debit > 0 && line.credit > 0) {
    return { valid: false, error: 'A line must have either debit or credit, not both. One must be zero.' };
  }

  if (line.debit === 0 && line.credit === 0) {
    return { valid: false, error: 'A line must have a non-zero debit or credit amount' };
  }

  return { valid: true };
}

/**
 * Validate an entire journal entry (set of lines).
 * Rules:
 * - Must have at least 2 lines
 * - Each line must pass individual validation
 * - Total debits must equal total credits (exact match, no tolerance)
 */
export function validateJournalEntry(lines: JournalLineInput[]): JournalValidationResult {
  const errors: string[] = [];

  if (!lines || lines.length === 0) {
    return {
      valid: false,
      totalDebit: 0,
      totalCredit: 0,
      difference: 0,
      errors: ['Journal entry must have at least one line'],
    };
  }

  if (lines.length < 2) {
    errors.push('Journal entry must have at least 2 lines for double-entry');
  }

  // Validate individual lines
  for (let i = 0; i < lines.length; i++) {
    const lineResult = validateJournalLine(lines[i]!);
    if (!lineResult.valid) {
      errors.push(`Line ${i + 1}: ${lineResult.error}`);
    }
  }

  // Calculate totals using fixed-point arithmetic to avoid floating-point issues
  const totalDebit = roundToCents(
    lines.reduce((sum, line) => sum + (line.debit || 0), 0)
  );
  const totalCredit = roundToCents(
    lines.reduce((sum, line) => sum + (line.credit || 0), 0)
  );
  const difference = roundToCents(Math.abs(totalDebit - totalCredit));

  if (difference > 0) {
    errors.push(
      `Entry is not balanced: total debit R${totalDebit.toFixed(2)} != total credit R${totalCredit.toFixed(2)} (difference: R${difference.toFixed(2)})`
    );
  }

  return {
    valid: errors.length === 0,
    totalDebit,
    totalCredit,
    difference,
    errors,
  };
}

/**
 * Generate a journal entry number in format JE-YYYY-NNNNN
 */
export function formatJournalEntryNumber(year: number, sequence: number): string {
  return `JE-${year}-${String(sequence).padStart(5, '0')}`;
}

/**
 * Generate a supplier payment number in format PAY-YYYY-NNNNN
 */
export function formatPaymentNumber(prefix: string, year: number, sequence: number): string {
  return `${prefix}-${year}-${String(sequence).padStart(5, '0')}`;
}

/**
 * Round to 2 decimal places (cents) to avoid floating-point arithmetic issues
 */
export function roundToCents(value: number): number {
  return Math.round(value * 100) / 100;
}

/**
 * PRD-060: FibreFlow Accounting Module
 * Payment Allocation Validation
 *
 * Validates that payment allocations across invoices are correct:
 * - No overpayment per invoice
 * - Total allocations don't exceed payment amount
 * - No duplicate invoice allocations
 * - All referenced invoices exist
 */

import type {
  PaymentAllocationInput,
  PaymentAllocationResult,
  InvoiceForAllocation,
} from '../types/ap.types';

/**
 * Validate payment allocations against invoices.
 */
export function validatePaymentAllocations(
  paymentAmount: number,
  allocations: PaymentAllocationInput[],
  invoices: InvoiceForAllocation[]
): PaymentAllocationResult {
  const errors: string[] = [];
  const invoiceMap = new Map(invoices.map(inv => [inv.id, inv]));
  const resultAllocations: PaymentAllocationResult['allocations'] = [];

  // Check for duplicate invoice IDs
  const invoiceIds = allocations.map(a => a.invoiceId);
  const duplicates = invoiceIds.filter((id, i) => invoiceIds.indexOf(id) !== i);
  if (duplicates.length > 0) {
    errors.push(`Duplicate invoice allocations: ${duplicates.join(', ')}`);
    return {
      valid: false,
      allocations: [],
      totalAllocated: 0,
      unallocated: paymentAmount,
      errors,
    };
  }

  let totalAllocated = 0;

  for (const alloc of allocations) {
    // Validate amount is positive
    if (alloc.amount <= 0) {
      errors.push(`Allocation amount must be positive (invoice: ${alloc.invoiceId}, amount: ${alloc.amount})`);
      continue;
    }

    // Validate invoice exists
    const invoice = invoiceMap.get(alloc.invoiceId);
    if (!invoice) {
      errors.push(`Invoice not found: ${alloc.invoiceId}`);
      continue;
    }

    // Validate doesn't exceed invoice balance
    if (alloc.amount > invoice.balance) {
      errors.push(
        `Allocation R${alloc.amount.toFixed(2)} exceeds invoice ${invoice.invoiceNumber} balance of R${invoice.balance.toFixed(2)}`
      );
      continue;
    }

    const newBalance = Math.round((invoice.balance - alloc.amount) * 100) / 100;

    resultAllocations.push({
      invoiceId: alloc.invoiceId,
      amount: alloc.amount,
      newBalance,
      fullyPaid: newBalance === 0,
    });

    totalAllocated += alloc.amount;
  }

  // Check total allocations don't exceed payment amount
  totalAllocated = Math.round(totalAllocated * 100) / 100;
  if (totalAllocated > paymentAmount) {
    errors.push(
      `Total allocations R${totalAllocated.toFixed(2)} exceed payment amount R${paymentAmount.toFixed(2)}`
    );
  }

  const unallocated = Math.round((paymentAmount - totalAllocated) * 100) / 100;

  return {
    valid: errors.length === 0,
    allocations: resultAllocations,
    totalAllocated,
    unallocated: Math.max(0, unallocated),
    errors,
  };
}

