/**
 * Cost Centres Action API
 * POST — update, toggle, or delete a cost centre
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  updateCostCentre, toggleCostCentre, deleteCostCentre,
} from '@/modules/accounting/services/costCentreService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') return apiResponse.methodNotAllowed(res, req.method!, ['POST']);

  const { action, id, ...data } = req.body;
  if (!id) return apiResponse.badRequest(res, 'id required');

  try {
    switch (action) {
      case 'update':
        const updated = await updateCostCentre(id, data);
        return apiResponse.success(res, updated);
      case 'toggle':
        await toggleCostCentre(id, data.isActive !== false);
        return apiResponse.success(res, { toggled: true });
      case 'delete':
        await deleteCostCentre(id);
        return apiResponse.success(res, { deleted: true });
      default:
        return apiResponse.badRequest(res, `Unknown action: ${action}`);
    }
  } catch (err) {
    log.error('Cost centre action failed', { action, error: err }, 'accounting-api');
    return apiResponse.badRequest(res, err instanceof Error ? err.message : 'Action failed');
  }
}

export default withAuth(withErrorHandler(handler));
/**
 * Cost Centres Export API
 * GET — export cost centres as CSV
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';

const sql = neon(process.env.DATABASE_URL!);

function csvCell(v: string): string { return `"${String(v || '').replace(/"/g, '""')}"`; }

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);

  try {
    const rows = await sql`
      SELECT code, name, description, department, is_active
      FROM cost_centres ORDER BY code
    `;

    const csvLines = [
      'Code,Name,Description,Department,Active',
      ...rows.map((r: Record<string, unknown>) => [
        csvCell(String(r.code)),
        csvCell(String(r.name)),
        csvCell(String(r.description || '')),
        csvCell(String(r.department || '')),
        r.is_active ? 'Yes' : 'No',
      ].join(',')),
    ];

    res.setHeader('Content-Type', 'text/csv');
    res.setHeader('Content-Disposition', `attachment; filename="cost-centres-${new Date().toISOString().split('T')[0]}.csv"`);
    return res.status(200).send(csvLines.join('\n'));
  } catch (err) {
    log.error('Cost centres export failed', { error: err });
    return apiResponse.badRequest(res, 'Failed to export cost centres');
  }
}

export default withAuth(handler);
/**
 * Cost Centres API
 * GET  — list all cost centres
 * POST — create a new cost centre
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { getCostCentres, createCostCentre, type CcType } from '@/modules/accounting/services/costCentreService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const userId = (req as AuthenticatedNextApiRequest).user.id;

  if (req.method === 'GET') {
    const activeOnly = req.query.active === 'true';
    const ccType = req.query.cc_type as CcType | undefined;
    const items = await getCostCentres(activeOnly, ccType);
    return apiResponse.success(res, { items });
  }

  if (req.method === 'POST') {
    const { code, name, description, department, ccType } = req.body;
    if (!code || !name) return apiResponse.badRequest(res, 'code and name are required');
    try {
      const cc = await createCostCentre({ code, name, description, department, ccType }, userId);
      return apiResponse.success(res, cc);
    } catch (err) {
      log.error('Failed to create cost centre', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, err instanceof Error ? err.message : 'Failed');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST']);
}

export default withAuth(withErrorHandler(handler));

/**
 * Credit Note Actions API
 * POST /api/accounting/credit-notes-action
 *   action: approve
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import { approveCreditNote, cancelCreditNote } from '@/modules/accounting/services/creditNoteService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
  }

  try {
    const { action, creditNoteId, userId: bodyUserId, reason } = req.body;
    const userId = bodyUserId || (req as unknown as { user?: { id: string } }).user?.id;

    if (!action || !creditNoteId) {
      return apiResponse.badRequest(res, 'action and creditNoteId are required');
    }

    if (!userId) return apiResponse.badRequest(res, 'userId is required');

    switch (action) {
      case 'approve': {
        const creditNote = await approveCreditNote(creditNoteId, userId);
        return apiResponse.success(res, creditNote);
      }
      case 'cancel': {
        const cancelled = await cancelCreditNote(creditNoteId, userId, reason);
        return apiResponse.success(res, cancelled);
      }
      default:
        return apiResponse.badRequest(res, `Unknown action: ${action}`);
    }
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Action failed';
    log.error('Credit note action failed', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, message);
  }
}

export default withAuth(withErrorHandler(handler));
/**
 * Credit Notes API
 * GET  /api/accounting/credit-notes - List credit notes (with filters)
 * POST /api/accounting/credit-notes - Create draft credit note
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  getCreditNotes,
  getCreditNoteById,
  createCreditNote,
} from '@/modules/accounting/services/creditNoteService';
import type { CreditNoteStatus } from '@/modules/accounting/types/ar.types';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    try {
      const { id, type, status, limit, offset } = req.query;
      if (id) {
        const note = await getCreditNoteById(id as string);
        if (!note) return apiResponse.notFound(res, 'Credit Note', id as string);
        return apiResponse.success(res, note);
      }
      const result = await getCreditNotes({
        type: type as 'customer' | 'supplier' | undefined,
        status: status as CreditNoteStatus | undefined,
        limit: limit ? Number(limit) : undefined,
        offset: offset ? Number(offset) : undefined,
      });
      return apiResponse.success(res, result);
    } catch (err) {
      log.error('Failed to get credit notes', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, 'Failed to get credit notes');
    }
  }

  if (req.method === 'POST') {
    try {
      const { type, clientId, customerInvoiceId, supplierId, supplierInvoiceId,
        creditDate, reason, subtotal, taxRate, projectId } = req.body;

      if (!type || !creditDate || subtotal === undefined) {
        return apiResponse.badRequest(res, 'type, creditDate, and subtotal are required');
      }

      const userId = req.body.userId || (req as unknown as { user?: { id: string } }).user?.id;
      if (!userId) return apiResponse.badRequest(res, 'userId is required');

      const creditNote = await createCreditNote({
        type,
        clientId: clientId || undefined,
        customerInvoiceId: customerInvoiceId || undefined,
        supplierId: supplierId || undefined,
        supplierInvoiceId: supplierInvoiceId || undefined,
        creditDate,
        reason: reason || undefined,
        subtotal: Number(subtotal),
        taxRate: taxRate !== undefined ? Number(taxRate) : undefined,
        projectId: projectId || undefined,
      }, userId);

      return apiResponse.created(res, creditNote);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to create credit note';
      log.error('Failed to create credit note', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, message);
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

