/**
 * PRD-060: FibreFlow Accounting Module
 * Bank Transaction Auto-Match Algorithm
 *
 * Four-tier matching strategy:
 *   Tier 0: Rule-based match via bank_categorisation_rules (confidence 1.0)
 *   Tier 1: Exact reference match (confidence 1.0)
 *   Tier 2: Amount + date within 3 days (confidence 0.9)
 *   Tier 3: Amount only match (confidence 0.7)
 */

import type { AutoMatchCandidate } from '../types/bank.types';

interface BankTxForMatch {
  id: string;
  amount: number;
  transactionDate: string;
  reference?: string;
  description?: string;
}

interface JournalLineForMatch {
  id: string;
  debit: number;
  credit: number;
  description?: string;
  entryDate: string;
  entryNumber?: string;
  sourceDocumentId?: string;
}

/**
 * Find match candidates for a single bank transaction against unmatched GL journal lines.
 * Returns candidates sorted by confidence DESC.
 */
export function findMatchCandidates(
  bankTx: BankTxForMatch,
  glLines: JournalLineForMatch[],
  threshold: number = 0.7
): AutoMatchCandidate[] {
  const candidates: AutoMatchCandidate[] = [];
  const txAmount = Math.abs(bankTx.amount);
  const isDeposit = bankTx.amount > 0;

  for (const line of glLines) {
    // For deposits, match against credit lines; for withdrawals, match against debit lines
    const lineAmount = isDeposit ? line.credit : line.debit;
    if (lineAmount <= 0) continue;

    const amountMatch = Math.abs(txAmount - lineAmount) < 0.02;
    if (!amountMatch) continue;

    // Tier 1: Exact reference match
    if (bankTx.reference && bankTx.reference.trim().length > 2) {
      const ref = bankTx.reference.toLowerCase().trim();
      const lineDesc = (line.description || '').toLowerCase();
      const entryNum = (line.entryNumber || '').toLowerCase();
      const sourceDoc = (line.sourceDocumentId || '').toLowerCase();

      if (lineDesc.includes(ref) || entryNum.includes(ref) || ref.includes(entryNum) || sourceDoc.includes(ref)) {
        candidates.push({
          bankTransactionId: bankTx.id,
          journalLineId: line.id,
          confidence: 1.0,
          matchReason: 'exact_reference',
        });
        continue;
      }
    }

    // Check description-based reference match
    if (bankTx.description && bankTx.description.trim().length > 3) {
      const desc = bankTx.description.toLowerCase().trim();
      const lineDesc = (line.description || '').toLowerCase();
      if (lineDesc.length > 3 && (desc.includes(lineDesc) || lineDesc.includes(desc))) {
        candidates.push({
          bankTransactionId: bankTx.id,
          journalLineId: line.id,
          confidence: 0.95,
          matchReason: 'exact_reference',
        });
        continue;
      }
    }

    // Tier 2: Amount + date within 3 days
    const daysDiff = Math.abs(dateDiffDays(bankTx.transactionDate, line.entryDate));
    if (daysDiff <= 3) {
      candidates.push({
        bankTransactionId: bankTx.id,
        journalLineId: line.id,
        confidence: 0.9,
        matchReason: 'amount_date',
      });
      continue;
    }

    // Tier 3: Amount only
    candidates.push({
      bankTransactionId: bankTx.id,
      journalLineId: line.id,
      confidence: 0.7,
      matchReason: 'amount_only',
    });
  }

  return candidates
    .filter(c => c.confidence >= threshold)
    .sort((a, b) => b.confidence - a.confidence);
}

/**
 * Run auto-match across multiple bank transactions.
 * Returns best single match per bank transaction (highest confidence).
 * Prevents duplicate GL line matches.
 */
export function runAutoMatch(
  bankTxs: BankTxForMatch[],
  glLines: JournalLineForMatch[],
  threshold: number = 0.7
): { matches: AutoMatchCandidate[]; unmatched: string[] } {
  const matches: AutoMatchCandidate[] = [];
  const usedGlLines = new Set<string>();
  const unmatched: string[] = [];

  // Sort bank transactions by amount DESC for better matching priority
  const sorted = [...bankTxs].sort((a, b) => Math.abs(b.amount) - Math.abs(a.amount));

  for (const tx of sorted) {
    const availableLines = glLines.filter(l => !usedGlLines.has(l.id));
    const candidates = findMatchCandidates(tx, availableLines, threshold);

    if (candidates.length > 0) {
      const best = candidates[0]!;
      matches.push(best);
      usedGlLines.add(best.journalLineId);
    } else {
      unmatched.push(tx.id);
    }
  }

  return { matches, unmatched };
}

function dateDiffDays(dateA: string, dateB: string): number {
  const a = new Date(dateA);
  const b = new Date(dateB);
  return Math.round((a.getTime() - b.getTime()) / (1000 * 60 * 60 * 24));
}

/**
 * PRD-060: FibreFlow Accounting Module — Phase 3
 * Credit Note Service (Customer & Supplier)
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { createJournalEntry, postJournalEntry, reverseJournalEntry } from './journalEntryService';
import { getAccountByCode } from './chartOfAccountsService';
import type { CreditNote, CreditNoteCreateInput, CreditNoteStatus } from '../types/ar.types';
import type { JournalLineInput } from '../types/gl.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

interface CreditNoteFilters {
  type?: 'customer' | 'supplier';
  status?: CreditNoteStatus;
  limit?: number;
  offset?: number;
}

export async function getCreditNotes(filters?: CreditNoteFilters): Promise<{
  creditNotes: CreditNote[];
  total: number;
}> {
  try {
    const limit = filters?.limit || 50;
    const offset = filters?.offset || 0;
    let rows: Row[];
    let countRows: Row[];

    if (filters?.type) {
      rows = (await sql`
        SELECT cn.*, c.company_name AS client_name, COALESCE(s.company_name, s.name) AS supplier_name,
          COALESCE(ci.invoice_number, si.invoice_number) AS invoice_number
        FROM credit_notes cn
        LEFT JOIN clients c ON c.id = cn.client_id
        LEFT JOIN suppliers s ON s.id = cn.supplier_id
        LEFT JOIN customer_invoices ci ON ci.id = cn.customer_invoice_id
        LEFT JOIN supplier_invoices si ON si.id = cn.supplier_invoice_id
        WHERE cn.type = ${filters.type}
        ORDER BY cn.credit_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM credit_notes WHERE type = ${filters.type}
      `) as Row[];
    } else {
      rows = (await sql`
        SELECT cn.*, c.company_name AS client_name, COALESCE(s.company_name, s.name) AS supplier_name,
          COALESCE(ci.invoice_number, si.invoice_number) AS invoice_number
        FROM credit_notes cn
        LEFT JOIN clients c ON c.id = cn.client_id
        LEFT JOIN suppliers s ON s.id = cn.supplier_id
        LEFT JOIN customer_invoices ci ON ci.id = cn.customer_invoice_id
        LEFT JOIN supplier_invoices si ON si.id = cn.supplier_invoice_id
        ORDER BY cn.credit_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`SELECT COUNT(*) AS cnt FROM credit_notes`) as Row[];
    }

    return { creditNotes: rows.map(mapRow), total: Number(countRows[0]!.cnt) };
  } catch (err) {
    log.error('Failed to get credit notes', { error: err }, 'accounting');
    throw err;
  }
}

export async function getCreditNoteById(id: string): Promise<CreditNote | null> {
  const rows = (await sql`
    SELECT cn.*, c.company_name AS client_name, COALESCE(s.company_name, s.name) AS supplier_name,
      COALESCE(ci.invoice_number, si.invoice_number) AS invoice_number
    FROM credit_notes cn
    LEFT JOIN clients c ON c.id = cn.client_id
    LEFT JOIN suppliers s ON s.id = cn.supplier_id
    LEFT JOIN customer_invoices ci ON ci.id = cn.customer_invoice_id
    LEFT JOIN supplier_invoices si ON si.id = cn.supplier_invoice_id
    WHERE cn.id = ${id}::UUID
  `) as Row[];
  return rows.length > 0 ? mapRow(rows[0]) : null;
}

export async function createCreditNote(
  input: CreditNoteCreateInput,
  userId: string
): Promise<CreditNote> {
  try {
    const taxRate = input.taxRate ?? 15;
    const taxAmount = Math.round(input.subtotal * taxRate / 100 * 100) / 100;
    const totalAmount = input.subtotal + taxAmount;

    const rows = (await sql`
      INSERT INTO credit_notes (
        type, client_id, customer_invoice_id, supplier_id, supplier_invoice_id,
        credit_date, reason, subtotal, tax_rate, tax_amount, total_amount,
        project_id, created_by
      ) VALUES (
        ${input.type}, ${input.clientId || null}, ${input.customerInvoiceId || null},
        ${input.supplierId ? Number(input.supplierId) : null},
        ${input.supplierInvoiceId || null},
        ${input.creditDate}, ${input.reason || null},
        ${input.subtotal}, ${taxRate}, ${taxAmount}, ${totalAmount},
        ${input.projectId || null}, ${userId}::UUID
      ) RETURNING *
    `) as Row[];

    log.info('Created credit note', { id: String(rows[0]!.id), type: input.type }, 'accounting');
    return mapRow(rows[0]!);
  } catch (err) {
    log.error('Failed to create credit note', { error: err }, 'accounting');
    throw err;
  }
}

export async function approveCreditNote(id: string, userId: string): Promise<CreditNote> {
  try {
    const cnRows = (await sql`SELECT * FROM credit_notes WHERE id = ${id}`) as Row[];
    if (cnRows.length === 0) throw new Error(`Credit note ${id} not found`);
    const cn = cnRows[0]!;
    if (String(cn.status) !== 'draft') throw new Error(`Cannot approve credit note with status: ${cn.status}`);

    let lines: JournalLineInput[];

    if (String(cn.type) === 'customer') {
      // Customer CN: DR Revenue, CR Accounts Receivable
      const revenueAccount = await getAccountByCode('4100');
      const arAccount = await getAccountByCode('1120');
      const vatAccount = await getAccountByCode('2120');
      if (!revenueAccount || !arAccount) throw new Error('GL accounts 4100/1120 not found');

      lines = [
        { glAccountId: revenueAccount.id, debit: Number(cn.subtotal), credit: 0,
          description: `Credit note ${cn.credit_note_number}` },
      ];
      if (Number(cn.tax_amount) > 0 && vatAccount) {
        lines.push({ glAccountId: vatAccount.id, debit: Number(cn.tax_amount), credit: 0,
          description: `VAT reversal: ${cn.credit_note_number}` });
      }
      lines.push({ glAccountId: arAccount.id, debit: 0, credit: Number(cn.total_amount),
        description: `AR credit: ${cn.credit_note_number}` });

      // Reduce invoice balance
      if (cn.customer_invoice_id) {
        await sql`
          UPDATE customer_invoices SET amount_paid = amount_paid + ${Number(cn.total_amount)}
          WHERE id = ${cn.customer_invoice_id}::UUID
        `;
      }
    } else {
      // Supplier CN: DR Accounts Payable, CR Expense
      const apAccount = await getAccountByCode('2110');
      const expenseAccount = await getAccountByCode('5100');
      const vatAccount = await getAccountByCode('1140');
      if (!apAccount || !expenseAccount) throw new Error('GL accounts 2110/5100 not found');

      lines = [
        { glAccountId: apAccount.id, debit: Number(cn.total_amount), credit: 0,
          description: `AP credit: ${cn.credit_note_number}` },
      ];
      if (Number(cn.tax_amount) > 0 && vatAccount) {
        lines.push({ glAccountId: vatAccount.id, debit: 0, credit: Number(cn.tax_amount),
          description: `VAT reversal: ${cn.credit_note_number}` });
      }
      lines.push({ glAccountId: expenseAccount.id, debit: 0, credit: Number(cn.subtotal),
        description: `Expense credit: ${cn.credit_note_number}` });

      // Reduce supplier invoice balance
      if (cn.supplier_invoice_id) {
        await sql`
          UPDATE supplier_invoices SET amount_paid = amount_paid + ${Number(cn.total_amount)}
          WHERE id = ${cn.supplier_invoice_id}::UUID
        `;
      }
    }

    const je = await createJournalEntry({
      entryDate: String(cn.credit_date),
      description: `Credit note ${cn.credit_note_number}`,
      source: 'auto_credit_note',
      sourceDocumentId: id,
      lines,
    }, userId);
    await postJournalEntry(je.id, userId);

    const updated = (await sql`
      UPDATE credit_notes SET status = 'approved', approved_by = ${userId}::UUID,
        approved_at = NOW(), gl_journal_entry_id = ${je.id}::UUID
      WHERE id = ${id} RETURNING *
    `) as Row[];

    log.info('Approved credit note', { id, journalEntryId: je.id }, 'accounting');
    return mapRow(updated[0]!);
  } catch (err) {
    log.error('Failed to approve credit note', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function cancelCreditNote(
  id: string,
  userId: string,
  reason?: string
): Promise<CreditNote> {
  try {
    const cnRows = (await sql`SELECT * FROM credit_notes WHERE id = ${id}`) as Row[];
    if (cnRows.length === 0) throw new Error(`Credit note ${id} not found`);
    const cn = cnRows[0]!;
    if (String(cn.status) !== 'approved') {
      throw new Error(`Cannot cancel credit note with status: ${cn.status}`);
    }

    // Reverse GL journal entry
    if (cn.gl_journal_entry_id) {
      await reverseJournalEntry(String(cn.gl_journal_entry_id), userId);
    }

    // Reverse invoice balance adjustments
    if (String(cn.type) === 'customer' && cn.customer_invoice_id) {
      await sql`
        UPDATE customer_invoices
        SET amount_paid = GREATEST(0, amount_paid - ${Number(cn.total_amount)})
        WHERE id = ${cn.customer_invoice_id}::UUID
      `;
      await sql`
        UPDATE customer_invoices SET status = CASE
          WHEN amount_paid <= 0.01 THEN 'approved'
          WHEN amount_paid < total_amount THEN 'partially_paid'
          ELSE status
        END
        WHERE id = ${cn.customer_invoice_id}::UUID
      `;
    } else if (String(cn.type) === 'supplier' && cn.supplier_invoice_id) {
      await sql`
        UPDATE supplier_invoices
        SET amount_paid = GREATEST(0, amount_paid - ${Number(cn.total_amount)})
        WHERE id = ${cn.supplier_invoice_id}::UUID
      `;
    }

    const updated = (await sql`
      UPDATE credit_notes
      SET status = 'cancelled', cancelled_by = ${userId}::UUID,
          cancelled_at = NOW(), cancel_reason = ${reason || null}
      WHERE id = ${id} RETURNING *
    `) as Row[];

    log.info('Cancelled credit note', { id, reason }, 'accounting');
    return mapRow(updated[0]!);
  } catch (err) {
    log.error('Failed to cancel credit note', { id, error: err }, 'accounting');
    throw err;
  }
}

function mapRow(row: Row): CreditNote {
  return {
    id: String(row.id),
    creditNoteNumber: row.credit_note_number ? String(row.credit_note_number) : '',
    type: String(row.type) as CreditNote['type'],
    clientId: row.client_id ? String(row.client_id) : undefined,
    customerInvoiceId: row.customer_invoice_id ? String(row.customer_invoice_id) : undefined,
    supplierId: row.supplier_id ? String(row.supplier_id) : undefined,
    supplierInvoiceId: row.supplier_invoice_id ? String(row.supplier_invoice_id) : undefined,
    creditDate: String(row.credit_date),
    reason: row.reason ? String(row.reason) : undefined,
    subtotal: Number(row.subtotal),
    taxRate: Number(row.tax_rate),
    taxAmount: Number(row.tax_amount),
    totalAmount: Number(row.total_amount),
    status: String(row.status) as CreditNoteStatus,
    glJournalEntryId: row.gl_journal_entry_id ? String(row.gl_journal_entry_id) : undefined,
    projectId: row.project_id ? String(row.project_id) : undefined,
    createdBy: String(row.created_by),
    approvedBy: row.approved_by ? String(row.approved_by) : undefined,
    approvedAt: row.approved_at ? String(row.approved_at) : undefined,
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
    clientName: row.client_name ? String(row.client_name) : undefined,
    supplierName: row.supplier_name ? String(row.supplier_name) : undefined,
    invoiceNumber: row.invoice_number ? String(row.invoice_number) : undefined,
  };
}

/**
 * PRD-060 Phase 6: Sage Data Importers
 * Ledger transaction → GL journal entries
 * Supplier invoices → AP supplier_invoices
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { MigrationRun } from './sageMigrationService';
import { startRun, completeRun, failRun } from './sageMigrationService';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// ── Ledger Transaction Import ───────────────────────────────────────────────

/**
 * Import sage_ledger_transactions as GL journal entries
 * Groups by document_number + transaction_date into balanced entries
 */
export async function importLedgerTransactions(userId: string): Promise<MigrationRun> {
  const runId = await startRun('ledger_import', userId);

  try {
    const groups = (await sql`
      SELECT slt.document_number, slt.transaction_date, slt.description,
        COUNT(*) AS line_count
      FROM sage_ledger_transactions slt
      JOIN sage_accounts sa ON sa.sage_account_id = slt.sage_account_id
      WHERE slt.migration_status = 'pending'
        AND sa.gl_account_id IS NOT NULL
      GROUP BY slt.document_number, slt.transaction_date, slt.description
      ORDER BY slt.transaction_date
    `) as Row[];

    let succeeded = 0;
    let failed = 0;
    let skipped = 0;

    for (const group of groups) {
      try {
        const lines = (await sql`
          SELECT slt.id, slt.sage_account_id, slt.debit, slt.credit,
            slt.description, slt.reference, slt.ff_project_id,
            sa.gl_account_id
          FROM sage_ledger_transactions slt
          JOIN sage_accounts sa ON sa.sage_account_id = slt.sage_account_id
          WHERE slt.document_number = ${group.document_number}
            AND slt.transaction_date = ${group.transaction_date}
            AND slt.migration_status = 'pending'
            AND sa.gl_account_id IS NOT NULL
        `) as Row[];

        if (lines.length === 0) { skipped++; continue; }

        const totalDebit = lines.reduce((s: number, l: Row) => s + Number(l.debit || 0), 0);
        const totalCredit = lines.reduce((s: number, l: Row) => s + Number(l.credit || 0), 0);

        if (Math.abs(totalDebit - totalCredit) > 0.02) {
          for (const line of lines) {
            await sql`UPDATE sage_ledger_transactions SET migration_status = 'failed' WHERE id = ${line.id}`;
          }
          failed++;
          continue;
        }

        const entryRef = group.document_number
          ? `SAGE-${group.document_number}`
          : `SAGE-${group.transaction_date}`;

        const entry = (await sql`
          INSERT INTO gl_journal_entries (
            entry_number, entry_date, description, source, status, created_by
          ) VALUES (
            ${entryRef}, ${group.transaction_date},
            ${group.description || `Sage import: ${entryRef}`},
            'manual', 'posted', ${userId}
          ) RETURNING id
        `) as Row[];

        const entryId = String(entry[0].id);

        for (const line of lines) {
          const debit = Number(line.debit || 0);
          const credit = Number(line.credit || 0);
          if (debit === 0 && credit === 0) continue;

          const projectId = line.ff_project_id || null;
          if (projectId) {
            await sql`
              INSERT INTO gl_journal_lines (journal_entry_id, gl_account_id, debit, credit, description, project_id)
              VALUES (${entryId}::UUID, ${line.gl_account_id}::UUID, ${debit}, ${credit},
                ${line.description || group.description || ''}, ${projectId}::UUID)
            `;
          } else {
            await sql`
              INSERT INTO gl_journal_lines (journal_entry_id, gl_account_id, debit, credit, description)
              VALUES (${entryId}::UUID, ${line.gl_account_id}::UUID, ${debit}, ${credit},
                ${line.description || group.description || ''})
            `;
          }

          await sql`
            UPDATE sage_ledger_transactions
            SET migration_status = 'imported', gl_journal_entry_id = ${entryId}::UUID
            WHERE id = ${line.id}
          `;
        }

        succeeded++;
      } catch (err) {
        log.error('Failed to import ledger group', { docNum: group.document_number, error: err }, 'accounting');
        failed++;
      }
    }

    return await completeRun(runId, groups.length, succeeded, failed, skipped);
  } catch (err) {
    await failRun(runId, err);
    throw err;
  }
}

// ── Supplier Invoice Import ─────────────────────────────────────────────────

/**
 * Import sage_supplier_invoices into the supplier_invoices table.
 * Matches Sage's approach: invoices are standalone AP documents,
 * no separate GL journal entries are created per invoice.
 */
export async function importSupplierInvoices(userId: string): Promise<MigrationRun> {
  const runId = await startRun('invoice_import', userId);

  try {
    const sageInvoices = (await sql`
      SELECT id, sage_invoice_id, sage_supplier_id, invoice_number,
        invoice_date, due_date, subtotal, tax_amount, total_amount,
        outstanding_amount, status, ff_purchase_order_id, supplier_id,
        raw_data, line_items
      FROM sage_supplier_invoices
      WHERE migration_status = 'pending'
      ORDER BY invoice_date
    `) as Row[];

    let succeeded = 0;
    let failed = 0;
    let skipped = 0;

    for (const inv of sageInvoices) {
      try {
        const totalAmount = Number(inv.total_amount || 0);
        if (totalAmount === 0) { skipped++; continue; }

        let supplierId = inv.supplier_id;
        if (!supplierId && inv.ff_purchase_order_id) {
          const po = (await sql`SELECT supplier_id FROM purchase_orders WHERE id = ${inv.ff_purchase_order_id}`) as Row[];
          supplierId = po[0]?.supplier_id;
        }

        if (!supplierId) {
          await sql`UPDATE sage_supplier_invoices SET migration_status = 'failed' WHERE id = ${inv.id}`;
          failed++;
          continue;
        }

        const subtotal = Number(inv.subtotal || 0) || totalAmount / 1.15;
        const taxAmount = Number(inv.tax_amount || 0) || totalAmount - subtotal;
        const taxRate = subtotal > 0
          ? Math.round((taxAmount / subtotal) * 100 * 100) / 100
          : 15;

        let projectId: string | null = null;
        if (inv.ff_purchase_order_id) {
          const po = (await sql`SELECT project_id FROM purchase_orders WHERE id = ${inv.ff_purchase_order_id}`) as Row[];
          projectId = po[0]?.project_id || null;
        }

        const isPaid = inv.status === 'paid' || Number(inv.outstanding_amount || 0) === 0;

        // Extract reference from raw_data if available
        const rawObj = parseJson(inv.raw_data);
        const reference = rawObj?.Reference || null;

        const newInv = (await sql`
          INSERT INTO supplier_invoices (
            invoice_number, supplier_id, purchase_order_id, project_id,
            invoice_date, due_date, subtotal, tax_rate, tax_amount, total_amount,
            amount_paid, status, sage_invoice_id, reference, created_by
          ) VALUES (
            ${inv.invoice_number || `SAGE-${inv.sage_invoice_id}`},
            ${supplierId}, ${inv.ff_purchase_order_id || null}, ${projectId},
            ${inv.invoice_date}, ${inv.due_date || inv.invoice_date},
            ${subtotal.toFixed(2)}, ${taxRate}, ${taxAmount.toFixed(2)}, ${totalAmount},
            ${isPaid ? totalAmount : 0}, ${isPaid ? 'paid' : 'approved'},
            ${inv.sage_invoice_id}, ${reference}, ${userId}
          ) RETURNING id
        `) as Row[];

        const newInvoiceId = String(newInv[0].id);

        // Insert line items from raw_data
        const lines = parseRawData(inv.raw_data, inv.line_items);
        if (lines && Array.isArray(lines) && lines.length > 0) {
          for (const line of lines) {
            const qty = Number(line.Quantity || 1);
            const price = Number(line.UnitPriceExclusive || 0);
            const lineTax = Number(line.Tax || 0);
            const lineTotal = Number(line.Exclusive || line.Total || price * qty);
            const lineTaxPct = Number(line.TaxPercentage || 0) * 100;

            if (projectId) {
              await sql`
                INSERT INTO supplier_invoice_items (
                  supplier_invoice_id, description, quantity, unit_price,
                  tax_rate, tax_amount, line_total, project_id
                ) VALUES (
                  ${newInvoiceId}::UUID, ${line.Description || 'Line item'},
                  ${qty}, ${price}, ${lineTaxPct}, ${lineTax}, ${lineTotal},
                  ${projectId}::UUID
                )
              `;
            } else {
              await sql`
                INSERT INTO supplier_invoice_items (
                  supplier_invoice_id, description, quantity, unit_price,
                  tax_rate, tax_amount, line_total
                ) VALUES (
                  ${newInvoiceId}::UUID, ${line.Description || 'Line item'},
                  ${qty}, ${price}, ${lineTaxPct}, ${lineTax}, ${lineTotal}
                )
              `;
            }
          }
        }

        await sql`
          UPDATE sage_supplier_invoices
          SET migration_status = 'imported', gl_supplier_invoice_id = ${newInvoiceId}::UUID
          WHERE id = ${inv.id}
        `;

        succeeded++;
      } catch (err) {
        log.error('Failed to import sage invoice', { invoiceId: inv.id, error: err }, 'accounting');
        await sql`UPDATE sage_supplier_invoices SET migration_status = 'failed' WHERE id = ${inv.id}`;
        failed++;
      }
    }

    return await completeRun(runId, sageInvoices.length, succeeded, failed, skipped);
  } catch (err) {
    await failRun(runId, err);
    throw err;
  }
}

// ── Helpers ─────────────────────────────────────────────────────────────────

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function parseRawData(rawData: unknown, lineItems: unknown): any[] | null {
  // Try raw_data.Lines first (full Sage response with includeDetail)
  const raw = parseJson(rawData);
  if (raw?.Lines && Array.isArray(raw.Lines) && raw.Lines.length > 0) {
    return raw.Lines;
  }
  // Fall back to line_items JSONB column
  const items = parseJson(lineItems);
  if (Array.isArray(items) && items.length > 0) return items;
  return null;
}

function parseJson(val: unknown): Record<string, unknown> | null {
  if (!val) return null;
  if (typeof val === 'string') {
    try { return JSON.parse(val); } catch { return null; }
  }
  return val as Record<string, unknown>;
}

/**
 * PRD-060: FibreFlow Accounting Module
 * Bank CSV Statement Parsers
 *
 * Parsers for South African bank statement CSV formats:
 * - FNB (First National Bank)
 * - Standard Bank
 * - Nedbank
 * - ABSA
 * - Capitec
 */

import type { ParsedBankTransaction, BankCsvParseResult, BankFormat } from '../types/bank.types';

/**
 * Parse a CSV string into lines, handling quoted fields.
 */
function parseCsvLines(csv: string): string[][] {
  if (!csv || csv.trim() === '') return [];

  const lines = csv.trim().split('\n');
  return lines.map(line => {
    const fields: string[] = [];
    let current = '';
    let inQuotes = false;

    for (let i = 0; i < line.length; i++) {
      const char = line[i];
      if (char === '"') {
        inQuotes = !inQuotes;
      } else if (char === ',' && !inQuotes) {
        fields.push(current.trim());
        current = '';
      } else {
        current += char;
      }
    }
    fields.push(current.trim());
    return fields;
  });
}

/**
 * Parse amount string, handling thousand separators and negative values.
 */
function parseAmount(value: string): number | null {
  if (!value || value.trim() === '') return null;
  const cleaned = value.replace(/[,\s]/g, '').replace(/^["']|["']$/g, '');
  const num = parseFloat(cleaned);
  return isNaN(num) ? null : num;
}

/**
 * Convert date string to YYYY-MM-DD format.
 */
function normalizeDate(dateStr: string, format: 'yyyy/mm/dd' | 'dd/mm/yyyy' | 'yyyy-mm-dd'): string | null {
  const cleaned = dateStr.trim().replace(/^["']|["']$/g, '').trim();
  if (!cleaned) return null;

  let year: string, month: string, day: string;

  if (format === 'yyyy/mm/dd') {
    const parts = cleaned.split('/');
    if (parts.length !== 3) return null;
    year = parts[0]!; month = parts[1]!; day = parts[2]!;
  } else if (format === 'dd/mm/yyyy') {
    const parts = cleaned.split('/');
    if (parts.length !== 3) return null;
    day = parts[0]!; month = parts[1]!; year = parts[2]!;
  } else if (format === 'yyyy-mm-dd') {
    const parts = cleaned.split('-');
    if (parts.length !== 3) return null;
    year = parts[0]!; month = parts[1]!; day = parts[2]!;
  } else {
    return null;
  }

  // Validate
  const y = parseInt(year, 10);
  const m = parseInt(month, 10);
  const d = parseInt(day, 10);
  if (isNaN(y) || isNaN(m) || isNaN(d)) return null;
  if (m < 1 || m > 12 || d < 1 || d > 31) return null;

  return `${year.padStart(4, '0')}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
}

// ── FNB Parser ───────────────────────────────────────────────────────────────

/**
 * Parse FNB bank statement CSV.
 * Expected columns: Date, Description, Amount, Balance, Reference
 * Date format: YYYY/MM/DD
 * Amount: single column (positive = credit, negative = debit)
 */
export function parseFNBStatement(csv: string): BankCsvParseResult {
  const result: BankCsvParseResult = {
    transactions: [],
    errors: [],
    bankFormat: 'fnb',
  };

  const lines = parseCsvLines(csv);
  if (lines.length <= 1) return result; // Empty or header only

  // Skip header (row 0)
  for (let i = 1; i < lines.length; i++) {
    const fields = lines[i]!;
    if (fields.length < 3) {
      result.errors.push({ row: i + 1, error: 'Insufficient columns' });
      continue;
    }

    const date = normalizeDate(fields[0]!, 'yyyy/mm/dd');
    if (!date) {
      result.errors.push({ row: i + 1, error: `Invalid date: ${fields[0]}` });
      continue;
    }

    const amount = parseAmount(fields[2]!);
    if (amount === null) {
      result.errors.push({ row: i + 1, error: `Invalid amount: ${fields[2]}` });
      continue;
    }

    const tx: ParsedBankTransaction = {
      transactionDate: date,
      amount,
      description: fields[1]!.trim(),
      reference: fields.length > 4 ? fields[4]!.trim() || undefined : undefined,
      balance: fields.length > 3 ? parseAmount(fields[3]!) ?? undefined : undefined,
    };

    result.transactions.push(tx);
  }

  return result;
}

// ── Standard Bank Parser ─────────────────────────────────────────────────────

/**
 * Parse Standard Bank statement CSV.
 * Expected columns: Date, Description, Debit, Credit, Balance
 * Date format: DD/MM/YYYY
 * Separate debit/credit columns
 */
export function parseStandardBankStatement(csv: string): BankCsvParseResult {
  const result: BankCsvParseResult = {
    transactions: [],
    errors: [],
    bankFormat: 'standard_bank',
  };

  const lines = parseCsvLines(csv);
  if (lines.length <= 1) return result;

  for (let i = 1; i < lines.length; i++) {
    const fields = lines[i]!;
    if (fields.length < 4) {
      result.errors.push({ row: i + 1, error: 'Insufficient columns' });
      continue;
    }

    const date = normalizeDate(fields[0]!, 'dd/mm/yyyy');
    if (!date) {
      result.errors.push({ row: i + 1, error: `Invalid date: ${fields[0]}` });
      continue;
    }

    const debit = parseAmount(fields[2]!);
    const credit = parseAmount(fields[3]!);

    let amount: number;
    if (credit !== null && credit > 0) {
      amount = credit;
    } else if (debit !== null && debit > 0) {
      amount = -debit;
    } else if (credit === null && debit === null) {
      result.errors.push({ row: i + 1, error: 'No debit or credit amount' });
      continue;
    } else {
      amount = 0;
    }

    const tx: ParsedBankTransaction = {
      transactionDate: date,
      amount,
      description: fields[1]!.trim(),
      balance: fields.length > 4 ? parseAmount(fields[4]!) ?? undefined : undefined,
    };

    result.transactions.push(tx);
  }

  return result;
}

// ── Nedbank Parser ───────────────────────────────────────────────────────────

/**
 * Parse Nedbank statement CSV.
 * Expected columns: Transaction Date, Value Date, Transaction Description, Debit Amount, Credit Amount, Balance
 * Date format: YYYY-MM-DD
 */
export function parseNedbankStatement(csv: string): BankCsvParseResult {
  const result: BankCsvParseResult = {
    transactions: [],
    errors: [],
    bankFormat: 'nedbank',
  };

  const lines = parseCsvLines(csv);
  if (lines.length <= 1) return result;

  for (let i = 1; i < lines.length; i++) {
    const fields = lines[i]!;
    if (fields.length < 5) {
      result.errors.push({ row: i + 1, error: 'Insufficient columns' });
      continue;
    }

    const date = normalizeDate(fields[0]!, 'yyyy-mm-dd');
    if (!date) {
      result.errors.push({ row: i + 1, error: `Invalid date: ${fields[0]}` });
      continue;
    }

    const valueDate = normalizeDate(fields[1]!, 'yyyy-mm-dd');
    const debit = parseAmount(fields[3]!);
    const credit = parseAmount(fields[4]!);

    let amount: number;
    if (credit !== null && credit > 0) {
      amount = credit;
    } else if (debit !== null && debit > 0) {
      amount = -debit;
    } else {
      amount = 0;
    }

    const tx: ParsedBankTransaction = {
      transactionDate: date,
      valueDate: valueDate || undefined,
      amount,
      description: fields[2]!.trim(),
      balance: fields.length > 5 ? parseAmount(fields[5]!) ?? undefined : undefined,
    };

    result.transactions.push(tx);
  }

  return result;
}

// ── ABSA Parser ──────────────────────────────────────────────────────────────

/**
 * Parse ABSA bank statement CSV.
 * Expected columns: Account Number,Date,Description1,Description2,Amount,Balance
 * Date format: YYYY/MM/DD
 * Amount: single column with quoted strings, negative values in parentheses or with minus sign
 *
 * Example row:
 *   4087xxxxxx,2026/01/15,"POS Purchase","Woolworths Food","-1234.56","45678.90"
 */
export function parseABSAStatement(csv: string): BankCsvParseResult {
  const result: BankCsvParseResult = {
    transactions: [],
    errors: [],
    bankFormat: 'absa',
  };

  const lines = parseCsvLines(csv);
  if (lines.length <= 1) return result;

  // Skip header (row 0)
  for (let i = 1; i < lines.length; i++) {
    const fields = lines[i]!;
    // Minimum: AccountNumber, Date, Description1, Description2, Amount
    if (fields.length < 5) {
      if (fields.every(f => f === '')) continue; // skip blank lines
      result.errors.push({ row: i + 1, error: 'Insufficient columns' });
      continue;
    }

    // Column 1 = Date (YYYY/MM/DD)
    const date = normalizeDate(fields[1]!, 'yyyy/mm/dd');
    if (!date) {
      result.errors.push({ row: i + 1, error: `Invalid date: ${fields[1]}` });
      continue;
    }

    // Column 4 = Amount (column index 4)
    const amount = parseAmount(fields[4]!);
    if (amount === null) {
      result.errors.push({ row: i + 1, error: `Invalid amount: ${fields[4]}` });
      continue;
    }

    // Combine Description1 + Description2 for a richer description
    const desc1 = fields[2]!.trim();
    const desc2 = fields[3]!.trim();
    const description = desc2 ? `${desc1} ${desc2}`.trim() : desc1;

    const tx: ParsedBankTransaction = {
      transactionDate: date,
      amount,
      description,
      balance: fields.length > 5 ? parseAmount(fields[5]!) ?? undefined : undefined,
    };

    result.transactions.push(tx);
  }

  return result;
}

// ── Capitec Parser ────────────────────────────────────────────────────────────

/**
 * Parse Capitec bank statement CSV.
 * Expected columns: Date,Description,Debit,Credit,Balance
 * Date format: DD/MM/YYYY
 * Separate debit/credit columns (similar to Standard Bank but different header casing)
 */
export function parseCapitecStatement(csv: string): BankCsvParseResult {
  const result: BankCsvParseResult = {
    transactions: [],
    errors: [],
    bankFormat: 'capitec',
  };

  const lines = parseCsvLines(csv);
  if (lines.length <= 1) return result;

  for (let i = 1; i < lines.length; i++) {
    const fields = lines[i]!;
    // Skip blank lines
    if (fields.every(f => f === '')) continue;
    if (fields.length < 4) {
      result.errors.push({ row: i + 1, error: 'Insufficient columns' });
      continue;
    }

    const date = normalizeDate(fields[0]!, 'dd/mm/yyyy');
    if (!date) {
      result.errors.push({ row: i + 1, error: `Invalid date: ${fields[0]}` });
      continue;
    }

    const debit = parseAmount(fields[2]!);
    const credit = parseAmount(fields[3]!);

    let amount: number;
    if (credit !== null && credit > 0) {
      amount = credit;
    } else if (debit !== null && debit > 0) {
      amount = -debit;
    } else if (credit === null && debit === null) {
      result.errors.push({ row: i + 1, error: 'No debit or credit amount' });
      continue;
    } else {
      amount = 0;
    }

    const tx: ParsedBankTransaction = {
      transactionDate: date,
      amount,
      description: fields[1]!.trim(),
      balance: fields.length > 4 ? parseAmount(fields[4]!) ?? undefined : undefined,
    };

    result.transactions.push(tx);
  }

  return result;
}

// ── Format Detection ─────────────────────────────────────────────────────────

/**
 * Detect bank format from CSV header line.
 * Returns 'ofx' or 'qif' when the content matches those non-CSV formats.
 */
export function detectBankFormat(csv: string): BankFormat {
  if (!csv || csv.trim() === '') return 'unknown';

  const trimmed = csv.trim();

  // OFX: starts with OFXHEADER: or <OFX>
  if (trimmed.startsWith('OFXHEADER:') || trimmed.startsWith('<OFX>') || trimmed.startsWith('<ofx>')) {
    return 'ofx';
  }

  // QIF: first non-blank line starts with !Type: or !Account
  const firstNonBlank = trimmed.split('\n').find(l => l.trim().length > 0) ?? '';
  if (firstNonBlank.startsWith('!Type:') || firstNonBlank.startsWith('!Account') || firstNonBlank.startsWith('!type:')) {
    return 'qif';
  }

  const firstLine = trimmed.split('\n')[0]!.toLowerCase();

  // ABSA: "Account Number,Date,Description1,Description2,Amount,Balance"
  if (firstLine.includes('account number') && firstLine.includes('description1')) {
    return 'absa';
  }

  // FNB: "Date","Description","Amount","Balance","Reference"
  if (firstLine.includes('"date"') && firstLine.includes('"amount"') && firstLine.includes('"reference"')) {
    return 'fnb';
  }

  // Nedbank: Transaction Date,Value Date,Transaction Description,...
  if (firstLine.includes('transaction date') && firstLine.includes('value date')) {
    return 'nedbank';
  }

  // Capitec: Date,Description,Debit,Credit,Balance (no extra qualifier columns)
  // Must be checked before Standard Bank since header is similar but Capitec has no extra columns.
  if (
    firstLine.includes('date') &&
    firstLine.includes('description') &&
    firstLine.includes('debit') &&
    firstLine.includes('credit') &&
    firstLine.includes('balance') &&
    !firstLine.includes('transaction date') &&
    !firstLine.includes('value date')
  ) {
    // Disambiguate: Standard Bank may include "Batch No" or similar extra fields.
    // Capitec typically has exactly 5 columns; Standard Bank also 5 — default to capitec
    // when header exactly matches Date,Description,Debit,Credit,Balance.
    const cols = firstLine.split(',').map(s => s.trim().replace(/"/g, ''));
    if (cols.length === 5 && cols[0] === 'date' && cols[1] === 'description') {
      return 'capitec';
    }
    return 'standard_bank';
  }

  // Standard Bank: Date,Description,Debit,Credit,Balance (fallback for variations)
  if (firstLine.includes('date') && firstLine.includes('debit') && firstLine.includes('credit')) {
    return 'standard_bank';
  }

  return 'unknown';
}

