/**
 * Customer Payment Actions API
 * POST /api/accounting/customer-payments-action
 *   action: confirm
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import { confirmCustomerPayment, cancelCustomerPayment } from '@/modules/accounting/services/customerPaymentService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
  }

  try {
    const { action, paymentId, userId: bodyUserId, reason } = req.body;
    const userId = bodyUserId || (req as unknown as { user?: { id: string } }).user?.id;

    if (!action || !paymentId) {
      return apiResponse.badRequest(res, 'action and paymentId are required');
    }

    if (!userId) return apiResponse.badRequest(res, 'userId is required');

    switch (action) {
      case 'confirm': {
        const payment = await confirmCustomerPayment(paymentId, userId);
        return apiResponse.success(res, payment);
      }
      case 'cancel': {
        const cancelled = await cancelCustomerPayment(paymentId, userId, reason);
        return apiResponse.success(res, cancelled);
      }
      default:
        return apiResponse.badRequest(res, `Unknown action: ${action}`);
    }
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Action failed';
    log.error('Customer payment action failed', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, message);
  }
}

export default withAuth(withErrorHandler(handler));
/**
 * Customer Payments Export API
 * GET — export customer payments as CSV
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';

const sql = neon(process.env.DATABASE_URL!);

function csvCell(v: string): string { return `"${String(v || '').replace(/"/g, '""')}"`; }

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);

  try {
    const { status } = req.query;

    let rows;
    if (status && status !== '') {
      rows = await sql`
        SELECT cp.payment_number, c.company_name AS client_name,
          cp.payment_date, cp.total_amount,
          COALESCE((SELECT SUM(cpa.amount_allocated) FROM customer_payment_allocations cpa WHERE cpa.payment_id = cp.id), 0) AS allocated_amount,
          cp.payment_method, cp.bank_reference, cp.status
        FROM customer_payments cp
        LEFT JOIN clients c ON c.id = cp.client_id
        WHERE cp.status = ${status as string}
        ORDER BY cp.payment_date DESC
      `;
    } else {
      rows = await sql`
        SELECT cp.payment_number, c.company_name AS client_name,
          cp.payment_date, cp.total_amount,
          COALESCE((SELECT SUM(cpa.amount_allocated) FROM customer_payment_allocations cpa WHERE cpa.payment_id = cp.id), 0) AS allocated_amount,
          cp.payment_method, cp.bank_reference, cp.status
        FROM customer_payments cp
        LEFT JOIN clients c ON c.id = cp.client_id
        ORDER BY cp.payment_date DESC
      `;
    }

    const csvLines = [
      'Payment #,Client,Date,Amount,Allocated,Unallocated,Method,Bank Ref,Status',
      ...rows.map((r: Record<string, unknown>) => {
        const total = Number(r.total_amount || 0);
        const allocated = Number(r.allocated_amount || 0);
        return [
          csvCell(String(r.payment_number)),
          csvCell(String(r.client_name || '')),
          csvCell(String(r.payment_date)),
          total.toFixed(2),
          allocated.toFixed(2),
          (total - allocated).toFixed(2),
          csvCell(String(r.payment_method || '')),
          csvCell(String(r.bank_reference || '')),
          csvCell(String(r.status)),
        ].join(',');
      }),
    ];

    res.setHeader('Content-Type', 'text/csv');
    res.setHeader('Content-Disposition', `attachment; filename="customer-payments-${new Date().toISOString().split('T')[0]}.csv"`);
    return res.status(200).send(csvLines.join('\n'));
  } catch (err) {
    log.error('Customer payments export failed', { error: err });
    return apiResponse.badRequest(res, 'Failed to export customer payments');
  }
}

export default withAuth(handler);
/**
 * Customer Payments API
 * GET  /api/accounting/customer-payments - List payments (with filters)
 * POST /api/accounting/customer-payments - Create payment with allocations
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  getCustomerPayments,
  getCustomerPaymentById,
  createCustomerPayment,
} from '@/modules/accounting/services/customerPaymentService';
import type { CustomerPaymentStatus } from '@/modules/accounting/types/ar.types';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    try {
      const { id, status, client_id, limit, offset } = req.query;

      // Single payment by ID
      if (id) {
        const payment = await getCustomerPaymentById(String(id));
        if (!payment) return apiResponse.notFound(res, 'Payment', String(id));
        return apiResponse.success(res, payment);
      }

      const result = await getCustomerPayments({
        status: status as CustomerPaymentStatus | undefined,
        clientId: client_id ? String(client_id) : undefined,
        limit: limit ? Number(limit) : undefined,
        offset: offset ? Number(offset) : undefined,
      });
      return apiResponse.success(res, result);
    } catch (err) {
      log.error('Failed to get customer payments', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, 'Failed to get customer payments');
    }
  }

  if (req.method === 'POST') {
    try {
      const { clientId, paymentDate, totalAmount, paymentMethod, bankReference,
        bankAccountId, description, projectId, allocations } = req.body;

      if (!clientId || !paymentDate || !totalAmount || !allocations || !Array.isArray(allocations)) {
        return apiResponse.badRequest(res, 'clientId, paymentDate, totalAmount, and allocations are required');
      }

      const userId = req.body.userId || (req as unknown as { user?: { id: string } }).user?.id;
      if (!userId) return apiResponse.badRequest(res, 'userId is required');

      const payment = await createCustomerPayment({
        clientId: String(clientId),
        paymentDate,
        totalAmount: Number(totalAmount),
        paymentMethod: paymentMethod || 'eft',
        bankReference: bankReference || undefined,
        bankAccountId: bankAccountId || undefined,
        description: description || undefined,
        projectId: projectId || undefined,
        allocations: allocations.map((a: { invoiceId: string; amount: number }) => ({
          invoiceId: String(a.invoiceId),
          amount: Number(a.amount),
        })),
      }, userId);

      return apiResponse.created(res, payment);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to create customer payment';
      log.error('Failed to create customer payment', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, message);
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

export default withAuth(withErrorHandler(handler));

