/**
 * Customer Quotes Action API
 * POST — perform actions on a quote (send, accept, decline, convert)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { updateQuoteStatus, convertToInvoice } from '@/modules/accounting/services/quoteService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);

  const { id, action } = req.body;
  if (!id || !action) return apiResponse.badRequest(res, 'id and action are required');

  const userId = (req as unknown as { user?: { id: string } }).user?.id;

  switch (action) {
    case 'send': {
      const quote = await updateQuoteStatus(id, 'sent');
      if (!quote) return apiResponse.notFound(res, 'Quote', id);
      return apiResponse.success(res, quote);
    }
    case 'accept': {
      const quote = await updateQuoteStatus(id, 'accepted');
      if (!quote) return apiResponse.notFound(res, 'Quote', id);
      return apiResponse.success(res, quote);
    }
    case 'decline': {
      const quote = await updateQuoteStatus(id, 'declined');
      if (!quote) return apiResponse.notFound(res, 'Quote', id);
      return apiResponse.success(res, quote);
    }
    case 'convert': {
      const result = await convertToInvoice(id, userId);
      if (!result) return apiResponse.badRequest(res, 'Quote must be accepted to convert');
      return apiResponse.success(res, result);
    }
    default:
      return apiResponse.badRequest(res, `Unknown action: ${action}`);
  }
}

export default withAuth(withErrorHandler(handler));
/**
 * Customer Quotes API
 * GET  — list quotes (search, status, limit, offset)
 * POST — create quote
 * PUT  — update quote (requires id in body)
 * DELETE — delete quote (requires id in body)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { getQuotes, getQuote, createQuote, updateQuote, deleteQuote } from '@/modules/accounting/services/quoteService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    const { id, status, search, limit, offset } = req.query;
    if (id) {
      const quote = await getQuote(id as string);
      if (!quote) return apiResponse.notFound(res, 'Quote', id as string);
      return apiResponse.success(res, quote);
    }
    const result = await getQuotes({
      status: status as string,
      search: search as string,
      limit: limit ? Number(limit) : undefined,
      offset: offset ? Number(offset) : undefined,
    });
    return apiResponse.success(res, result);
  }

  if (req.method === 'POST') {
    const userId = (req as unknown as { user?: { id: string } }).user?.id || req.body.userId;
    const quote = await createQuote(req.body, userId);
    return apiResponse.created(res, quote);
  }

  if (req.method === 'PUT') {
    const { id, ...input } = req.body;
    if (!id) return apiResponse.badRequest(res, 'id is required');
    const quote = await updateQuote(id, input);
    if (!quote) return apiResponse.badRequest(res, 'Quote not found or not in draft status');
    return apiResponse.success(res, quote);
  }

  if (req.method === 'DELETE') {
    const { id } = req.body;
    if (!id) return apiResponse.badRequest(res, 'id is required');
    const deleted = await deleteQuote(id);
    if (!deleted) return apiResponse.badRequest(res, 'Quote not found or not in draft status');
    return apiResponse.success(res, { deleted: true });
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST', 'PUT', 'DELETE']);
}

export default withAuth(withErrorHandler(handler));

/**
 * Customer Report Export API
 * GET — export customer transaction summary as CSV
 *   ?period_start=YYYY-MM-DD
 *   ?period_end=YYYY-MM-DD
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import { getCustomerReport } from '@/modules/accounting/services/transactionReportingService';

/** Escape a string value for safe embedding in a CSV cell. */
function csvCell(value: string): string {
  return `"${value.replace(/"/g, '""')}"`;
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);

  const periodStart = req.query.period_start as string;
  const periodEnd = req.query.period_end as string;

  if (!periodStart) return apiResponse.badRequest(res, 'period_start is required');
  if (!periodEnd) return apiResponse.badRequest(res, 'period_end is required');

  try {
    const rows = await getCustomerReport(periodStart, periodEnd);

    const totalInvoiced = rows.reduce((s, r) => s + r.totalInvoiced, 0);
    const totalPaid = rows.reduce((s, r) => s + r.totalPaid, 0);
    const totalBalance = rows.reduce((s, r) => s + r.balance, 0);

    const csvLines = [
      'Client Name,Invoice Count,Total Invoiced,Total Paid,Balance',
      ...rows.map(r =>
        [
          csvCell(r.clientName),
          r.invoiceCount,
          r.totalInvoiced.toFixed(2),
          r.totalPaid.toFixed(2),
          r.balance.toFixed(2),
        ].join(',')
      ),
      [
        csvCell('TOTALS'),
        rows.reduce((s, r) => s + r.invoiceCount, 0),
        totalInvoiced.toFixed(2),
        totalPaid.toFixed(2),
        totalBalance.toFixed(2),
      ].join(','),
    ];

    const csv = csvLines.join('\n');
    const filename = `customer-report-${new Date().toISOString().split('T')[0]}.csv`;

    res.setHeader('Content-Type', 'text/csv');
    res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);
    return res.status(200).send(csv);
  } catch (err) {
    log.error('Failed to export customer report', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, 'Failed to export customer report');
  }
}

export default withAuth(withErrorHandler(handler));
/**
 * Customer Statement Detail API
 * GET /api/accounting/customer-statement-detail?client_id=UUID
 * Returns full transaction-level statement with running balance
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { createLoggedSql } from '@/lib/db-logger';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';

const sql = createLoggedSql(process.env.DATABASE_URL!);

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
  }

  const clientId = req.query.client_id as string;
  if (!clientId) {
    return apiResponse.badRequest(res, 'client_id is required');
  }

  try {
    // Get client info
    const clientRows = (await sql`
      SELECT id, company_name, email, phone FROM clients WHERE id = ${clientId}::UUID
    `) as Row[];
    if (clientRows.length === 0) {
      return apiResponse.notFound(res, 'Client', clientId);
    }
    const client = clientRows[0];

    // Get invoices
    const invoices = (await sql`
      SELECT id, invoice_number, invoice_date, reference, total_amount, status
      FROM customer_invoices
      WHERE client_id = ${clientId}::UUID AND status != 'cancelled'
      ORDER BY invoice_date
    `) as Row[];

    // Get confirmed payments — includes both allocated and unallocated (bank-sourced)
    const payments = (await sql`
      SELECT cp.id, cp.payment_number, cp.payment_date, cp.bank_reference,
        COALESCE(SUM(cpa.amount_allocated), cp.total_amount) AS amount_allocated
      FROM customer_payments cp
      LEFT JOIN customer_payment_allocations cpa ON cpa.payment_id = cp.id
      WHERE cp.client_id = ${clientId}::UUID AND cp.status IN ('confirmed', 'reconciled')
      GROUP BY cp.id, cp.payment_number, cp.payment_date, cp.bank_reference, cp.total_amount
    `) as Row[];

    // Get approved customer credit notes
    const creditNotes = (await sql`
      SELECT id, credit_note_number, credit_date, reason, total_amount
      FROM credit_notes
      WHERE client_id = ${clientId}::UUID AND type = 'customer' AND status = 'approved'
    `) as Row[];

    // Normalize date to YYYY-MM-DD regardless of input format
    function toISODate(val: unknown): string {
      if (!val) return '1970-01-01';
      if (val instanceof Date) return val.toISOString().split('T')[0];
      const s = String(val);
      if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.split('T')[0];
      const d = new Date(s);
      return isNaN(d.getTime()) ? '1970-01-01' : d.toISOString().split('T')[0];
    }

    // Build transaction list
    interface Transaction {
      id: number | string;
      date: string;
      type: 'invoice' | 'payment' | 'credit_note';
      reference: string;
      description: string;
      debit: number;
      credit: number;
      balance: number;
    }

    const transactions: Transaction[] = [];

    for (const inv of invoices) {
      transactions.push({
        id: inv.id,
        date: toISODate(inv.invoice_date),
        type: 'invoice',
        reference: String(inv.invoice_number),
        description: inv.reference ? String(inv.reference) : '',
        debit: Number(inv.total_amount),
        credit: 0,
        balance: 0,
      });
    }

    for (const pmt of payments) {
      transactions.push({
        id: pmt.id,
        date: toISODate(pmt.payment_date),
        type: 'payment',
        reference: String(pmt.payment_number),
        description: pmt.bank_reference ? String(pmt.bank_reference) : '',
        debit: 0,
        credit: Number(pmt.amount_allocated),
        balance: 0,
      });
    }

    for (const cn of creditNotes) {
      transactions.push({
        id: cn.id,
        date: toISODate(cn.credit_date),
        type: 'credit_note',
        reference: String(cn.credit_note_number),
        description: cn.reason ? String(cn.reason) : '',
        debit: 0,
        credit: Number(cn.total_amount),
        balance: 0,
      });
    }

    // Sort chronologically, invoices before payments on same date
    transactions.sort((a, b) => {
      if (a.date !== b.date) return a.date < b.date ? -1 : 1;
      const typeOrder: Record<string, number> = { invoice: 0, credit_note: 1, payment: 2 };
      return (typeOrder[a.type] ?? 9) - (typeOrder[b.type] ?? 9);
    });

    // Calculate running balance
    let runningBalance = 0;
    let totalInvoiced = 0;
    let totalPaid = 0;
    let totalCredits = 0;

    for (const txn of transactions) {
      runningBalance += txn.debit - txn.credit;
      txn.balance = runningBalance;
      totalInvoiced += txn.debit;
      if (txn.type === 'payment') totalPaid += txn.credit;
      if (txn.type === 'credit_note') totalCredits += txn.credit;
    }

    return apiResponse.success(res, {
      client: {
        id: String(client.id),
        name: String(client.company_name),
        email: client.email ? String(client.email) : null,
        phone: client.phone ? String(client.phone) : null,
      },
      transactions,
      summary: {
        totalInvoiced,
        totalPaid,
        totalCredits,
        balance: runningBalance,
      },
    });
  } catch (err) {
    log.error('Failed to fetch customer statement detail', { clientId, error: err, module: 'accounting' });
    return apiResponse.databaseError(res, err, 'Failed to fetch customer statement');
  }
}

export default withAuth(withErrorHandler(handler));
/**
 * Customer Statements API
 * GET /api/accounting/customer-statements - Customer balances summary
 * Sage equivalent: Customers > Reports > Statements
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { createLoggedSql } from '@/lib/db-logger';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';

const sql = createLoggedSql(process.env.DATABASE_URL!);

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
  }

  try {
    const customers = await sql`
      SELECT
        ci.client_id,
        c.company_name as client_name,
        SUM(ci.total_amount::numeric) as total_invoiced,
        COALESCE(paid.total_paid, 0) as total_paid,
        SUM(ci.total_amount::numeric) - COALESCE(paid.total_paid, 0) as balance,
        paid.last_payment_date,
        COUNT(*)::int as invoice_count
      FROM customer_invoices ci
      LEFT JOIN clients c ON c.id = ci.client_id
      LEFT JOIN (
        SELECT client_id,
          SUM(total_amount::numeric) as total_paid,
          MAX(payment_date) as last_payment_date
        FROM customer_payments
        WHERE status IN ('confirmed', 'reconciled')
        GROUP BY client_id
      ) paid ON paid.client_id = ci.client_id
      WHERE ci.status != 'cancelled'
      GROUP BY ci.client_id, c.company_name, paid.total_paid, paid.last_payment_date
      HAVING SUM(ci.total_amount::numeric) > 0
      ORDER BY SUM(ci.total_amount::numeric) - COALESCE(paid.total_paid, 0) DESC
    `;

    return apiResponse.success(res, {
      customers: customers.map(c => ({
        ...c,
        total_invoiced: Number(c.total_invoiced),
        total_paid: Number(c.total_paid),
        balance: Number(c.balance),
        invoice_count: Number(c.invoice_count),
      })),
    });
  } catch (err) {
    log.error('Failed to fetch customer statements', { error: err, module: 'accounting' });
    return apiResponse.databaseError(res, err, 'Failed to fetch customer statements');
  }
}

export default withAuth(withErrorHandler(handler));

