/**
 * DRC VAT Export API
 * GET — export DRC VAT history as CSV
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';

const sql = neon(process.env.DATABASE_URL!);

function csvCell(v: string): string { return `"${String(v || '').replace(/"/g, '""')}"`; }

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);

  try {
    // Load VAT rate from settings (default 15%)
    let vatRate = 0.15;
    try {
      const settingRows = await sql`SELECT value FROM app_settings WHERE key = 'vat_rate'`;
      if (settingRows[0]?.value) {
        const rate = Number(settingRows[0].value);
        if (rate > 0 && rate < 1) vatRate = rate;
      }
    } catch { /* use default */ }

    const rows = await sql`
      SELECT si.invoice_number, s.company_name AS supplier_name,
        si.total_amount, si.invoice_date,
        COALESCE(si.total_amount * ${vatRate}, 0) AS vat_amount
      FROM supplier_invoices si
      JOIN suppliers s ON s.id = si.supplier_id
      WHERE si.is_drc = true
      ORDER BY si.invoice_date DESC
    `;

    const csvLines = [
      'Invoice,Supplier,Date,Amount (excl),VAT (15%)',
      ...rows.map((r: Record<string, unknown>) => [
        csvCell(String(r.invoice_number)),
        csvCell(String(r.supplier_name)),
        csvCell(String(r.invoice_date)),
        Number(r.total_amount || 0).toFixed(2),
        Number(r.vat_amount || 0).toFixed(2),
      ].join(',')),
    ];

    res.setHeader('Content-Type', 'text/csv');
    res.setHeader('Content-Disposition', `attachment; filename="drc-vat-${new Date().toISOString().split('T')[0]}.csv"`);
    return res.status(200).send(csvLines.join('\n'));
  } catch (err) {
    log.error('DRC VAT export failed', { error: err });
    return apiResponse.badRequest(res, 'Failed to export DRC VAT data');
  }
}

export default withAuth(handler);
/**
 * DRC (Domestic Reverse Charge) VAT API
 * GET  — list eligible invoices and DRC history
 * POST — apply DRC VAT to a supplier invoice
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  getDRCEligibleInvoices, getDRCHistory, applyDRCVat,
} from '@/modules/accounting/services/drcVatService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const userId = (req as AuthenticatedNextApiRequest).user.id;

  if (req.method === 'GET') {
    const tab = req.query.tab as string;
    if (tab === 'history') {
      const items = await getDRCHistory();
      return apiResponse.success(res, { items });
    }
    const items = await getDRCEligibleInvoices();
    return apiResponse.success(res, { items });
  }

  if (req.method === 'POST') {
    const { supplierInvoiceId } = req.body;
    if (!supplierInvoiceId) return apiResponse.badRequest(res, 'supplierInvoiceId required');
    try {
      const result = await applyDRCVat(supplierInvoiceId, userId);
      return apiResponse.success(res, result);
    } catch (err) {
      log.error('Failed to apply DRC VAT', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, err instanceof Error ? err.message : 'Failed');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method!);
}

export default withAuth(withErrorHandler(handler));
/**
 * Dunning Communications API
 * GET: List dunning communications (optionally filter by client_id)
 * POST: Create a new dunning communication
 * PUT: Update status (e.g. mark as sent)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { withErrorHandler } from '@/lib/api-error-handler';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = Record<string, any>;

export default withAuth(withErrorHandler(async (req: NextApiRequest, res: NextApiResponse) => {
  switch (req.method) {
    case 'GET': {
      const { client_id, status: filterStatus, limit: limitStr } = req.query;
      const rowLimit = Math.min(parseInt(limitStr as string, 10) || 100, 500);

      if (client_id) {
        const rows = (await sql`
          SELECT dc.*, c.company_name as client_name,
                 u.first_name || ' ' || u.last_name as created_by_name
          FROM dunning_communications dc
          JOIN clients c ON c.id = dc.client_id
          LEFT JOIN users u ON u.id = dc.created_by
          WHERE dc.client_id = ${client_id as string}
          ORDER BY dc.created_at DESC
          LIMIT ${rowLimit}
        `) as Row[];
        return apiResponse.success(res, rows);
      }

      if (filterStatus) {
        const rows = (await sql`
          SELECT dc.*, c.company_name as client_name,
                 u.first_name || ' ' || u.last_name as created_by_name
          FROM dunning_communications dc
          JOIN clients c ON c.id = dc.client_id
          LEFT JOIN users u ON u.id = dc.created_by
          WHERE dc.status = ${filterStatus as string}
          ORDER BY dc.created_at DESC
          LIMIT ${rowLimit}
        `) as Row[];
        return apiResponse.success(res, rows);
      }

      const rows = (await sql`
        SELECT dc.*, c.company_name as client_name,
               u.first_name || ' ' || u.last_name as created_by_name
        FROM dunning_communications dc
        JOIN clients c ON c.id = dc.client_id
        LEFT JOIN users u ON u.id = dc.created_by
        ORDER BY dc.created_at DESC
        LIMIT ${rowLimit}
      `) as Row[];
      return apiResponse.success(res, rows);
    }

    case 'POST': {
      const {
        client_id, type = 'reminder', level = 1,
        subject, body, total_overdue = 0,
        invoices_included = [], sent_via = 'email', sent_to
      } = req.body;

      if (!client_id || !subject || !body) {
        return apiResponse.badRequest(res, 'client_id, subject, and body are required');
      }

      const userId = (req as NextApiRequest & { user?: { id: string } }).user?.id || null;

      const rows = (await sql`
        INSERT INTO dunning_communications (
          client_id, type, level, subject, body, total_overdue,
          invoices_included, sent_via, sent_to, status, created_by
        ) VALUES (
          ${client_id}, ${type}, ${level}, ${subject}, ${body},
          ${total_overdue}, ${invoices_included}, ${sent_via},
          ${sent_to || null}, 'draft', ${userId}
        )
        RETURNING *
      `) as Row[];

      log.info('Dunning communication created', { client_id, type, level }, 'accounting');
      return apiResponse.success(res, rows[0], 'Communication created', 201);
    }

    case 'PUT': {
      const { id, status: newStatus, sent_at } = req.body;
      if (!id) return apiResponse.badRequest(res, 'id is required');

      const rows = (await sql`
        UPDATE dunning_communications
        SET status = COALESCE(${newStatus || null}, status),
            sent_at = COALESCE(${sent_at || null}, sent_at)
        WHERE id = ${id}
        RETURNING *
      `) as Row[];
      if (rows.length === 0) return apiResponse.notFound(res, 'Communication', id);
      return apiResponse.success(res, rows[0]);
    }

    default:
      return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST', 'PUT']);
  }
}));

