/**
 * Exchange Rates API
 * GET  — list rates (optional from/to currency filters)
 * POST — set/update rate for a date
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import {
  getExchangeRates,
  setExchangeRate,
  getLatestRate,
  convertAmount,
} from '@/modules/accounting/services/currencyService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const userId = (req as AuthenticatedNextApiRequest).user.id;

  if (req.method === 'GET') {
    const { from, to, convert, amount, date } = req.query;

    // Convert endpoint: ?convert=true&from=USD&to=ZAR&amount=100&date=2026-02-26
    if (convert === 'true' && from && to && amount) {
      const result = await convertAmount(
        Number(amount), String(from), String(to), date ? String(date) : undefined
      );
      if (!result) return apiResponse.notFound(res, 'Exchange rate', `${from}/${to}`);
      return apiResponse.success(res, result);
    }

    // Latest rate: ?from=USD&to=ZAR&latest=true
    if (req.query.latest === 'true' && from && to) {
      const rate = await getLatestRate(String(from), String(to), date ? String(date) : undefined);
      if (rate === null) return apiResponse.notFound(res, 'Exchange rate', `${from}/${to}`);
      return apiResponse.success(res, { from, to, rate });
    }

    // List rates
    const rates = await getExchangeRates({
      fromCurrency: from ? String(from) : undefined,
      toCurrency: to ? String(to) : undefined,
      limit: req.query.limit ? Number(req.query.limit) : undefined,
    });
    return apiResponse.success(res, rates);
  }

  if (req.method === 'POST') {
    const { fromCurrency, toCurrency, rate, effectiveDate, source } = req.body;
    if (!fromCurrency || !toCurrency || !rate || !effectiveDate) {
      return apiResponse.badRequest(res, 'fromCurrency, toCurrency, rate, effectiveDate required');
    }
    const result = await setExchangeRate(
      { fromCurrency, toCurrency, rate: Number(rate), effectiveDate, source },
      userId
    );
    return apiResponse.success(res, result);
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

export default withAuth(withErrorHandler(handler));
/**
 * Fiscal Period Actions API
 * POST /api/accounting/fiscal-periods-action - Close, lock, or reopen a period
 * Body: { id, action: 'close' | 'lock' | 'reopen', userId? }
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  closePeriod,
  lockPeriod,
  reopenPeriod,
} from '@/modules/accounting/services/fiscalPeriodService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    res.setHeader('Allow', ['POST']);
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
  }

  try {
    const { id, action, userId } = req.body;
    if (!id || !action) {
      return apiResponse.badRequest(res, 'id and action are required');
    }

    let result;
    switch (action) {
      case 'close':
        if (!userId) return apiResponse.badRequest(res, 'userId required for close action');
        result = await closePeriod(id, userId);
        break;
      case 'lock':
        result = await lockPeriod(id);
        break;
      case 'reopen':
        result = await reopenPeriod(id);
        break;
      default:
        return apiResponse.badRequest(res, `Invalid action: ${action}. Use close, lock, or reopen`);
    }

    return apiResponse.success(res, result);
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Failed to perform period action';
    log.error('Failed to perform period action', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, message);
  }
}

export default withAuth(withErrorHandler(handler));
/**
 * Fiscal Periods API
 * GET  /api/accounting/fiscal-periods - List periods (optionally by year)
 * POST /api/accounting/fiscal-periods - Create fiscal year (12 monthly periods)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  getFiscalPeriods,
  getCurrentFiscalPeriod,
  createFiscalYear,
} from '@/modules/accounting/services/fiscalPeriodService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    try {
      const { year, current } = req.query;

      if (current === 'true') {
        const period = await getCurrentFiscalPeriod();
        return apiResponse.success(res, period);
      }

      const fiscalYear = year ? Number(year) : undefined;
      const periods = await getFiscalPeriods(fiscalYear);
      return apiResponse.success(res, periods);
    } catch (err) {
      log.error('Failed to get fiscal periods', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, 'Failed to get fiscal periods');
    }
  }

  if (req.method === 'POST') {
    try {
      const { year } = req.body;
      if (!year || isNaN(Number(year))) {
        return apiResponse.badRequest(res, 'year is required and must be a number');
      }
      const periods = await createFiscalYear(Number(year));
      return apiResponse.success(res, periods);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to create fiscal year';
      log.error('Failed to create fiscal year', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, message);
    }
  }

  res.setHeader('Allow', ['GET', 'POST']);
  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

export default withAuth(withErrorHandler(handler));

