/**
 * Income Statement Export API
 * GET — export income statement (P&L) as CSV
 *
 * Query params:
 *   period_start   YYYY-MM-DD  required
 *   period_end     YYYY-MM-DD  required
 *   cost_centre_id UUID        optional
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import { getIncomeStatement } from '@/modules/accounting/services/financialReportingService';

/** Escape a value for CSV — wraps in double-quotes and escapes internal quotes. */
function csvVal(value: string | number): string {
  const str = String(value);
  return `"${str.replace(/"/g, '""')}"`;
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method!, ['GET']);

  const periodStart = req.query.period_start as string;
  const periodEnd = req.query.period_end as string;
  const costCentreId = req.query.cost_centre_id as string | undefined;

  if (!periodStart) return apiResponse.badRequest(res, 'period_start is required');
  if (!periodEnd) return apiResponse.badRequest(res, 'period_end is required');

  try {
    const report = await getIncomeStatement(periodStart, periodEnd, {
      costCentreId: costCentreId || undefined,
    });

    const csvLines: string[] = [
      'Section,Account Code,Account Name,Amount',
    ];

    // Revenue lines
    for (const item of report.revenue) {
      csvLines.push(
        `${csvVal('Revenue')},${csvVal(item.accountCode)},${csvVal(item.accountName)},${Number(item.amount).toFixed(2)}`
      );
    }
    csvLines.push(`${csvVal('Revenue')},${csvVal('')},${csvVal('Total Revenue')},${Number(report.totalRevenue).toFixed(2)}`);

    // Cost of Sales lines
    for (const item of report.costOfSales) {
      csvLines.push(
        `${csvVal('Cost of Sales')},${csvVal(item.accountCode)},${csvVal(item.accountName)},${Number(item.amount).toFixed(2)}`
      );
    }
    csvLines.push(`${csvVal('Cost of Sales')},${csvVal('')},${csvVal('Total Cost of Sales')},${Number(report.totalCostOfSales).toFixed(2)}`);

    // Gross Profit summary
    csvLines.push(`${csvVal('Summary')},${csvVal('')},${csvVal('Gross Profit')},${Number(report.grossProfit).toFixed(2)}`);

    // Operating Expenses lines
    for (const item of report.operatingExpenses) {
      csvLines.push(
        `${csvVal('Operating Expenses')},${csvVal(item.accountCode)},${csvVal(item.accountName)},${Number(item.amount).toFixed(2)}`
      );
    }
    csvLines.push(`${csvVal('Operating Expenses')},${csvVal('')},${csvVal('Total Operating Expenses')},${Number(report.totalOperatingExpenses).toFixed(2)}`);

    // Net Profit summary
    csvLines.push(`${csvVal('Summary')},${csvVal('')},${csvVal('Net Profit')},${Number(report.netProfit).toFixed(2)}`);

    const csv = csvLines.join('\n');
    const filename = `income-statement-${new Date().toISOString().split('T')[0]}.csv`;

    res.setHeader('Content-Type', 'text/csv');
    res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);
    return res.status(200).send(csv);
  } catch (err) {
    log.error('Failed to export income statement', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, 'Failed to export income statement');
  }
}

export default withAuth(withErrorHandler(handler));
/**
 * Item Adjustments API
 * GET  — list stock items with current quantities
 * POST — create stock adjustment (increase/decrease)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';

const sql = neon(process.env.DATABASE_URL!);

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    try {
      const rows = await sql`
        SELECT id, item_code, name AS item_name, uom, category,
          qty_available AS current_quantity, standard_cost
        FROM stock_items WHERE is_active = true ORDER BY name
      `;
      return apiResponse.success(res, rows);
    } catch (err) {
      log.error('Failed to fetch items for adjustments', { error: err });
      return apiResponse.badRequest(res, 'Failed to fetch items');
    }
  }

  if (req.method === 'POST') {
    try {
      const { itemId, adjustmentType, quantity, reason, date } = req.body as {
        itemId?: string;
        adjustmentType?: 'increase' | 'decrease';
        quantity?: number;
        reason?: string;
        date?: string;
      };

      if (!itemId) return apiResponse.badRequest(res, 'itemId is required');
      if (!adjustmentType || !['increase', 'decrease'].includes(adjustmentType)) {
        return apiResponse.badRequest(res, 'adjustmentType must be increase or decrease');
      }
      if (!quantity || Number(quantity) <= 0) return apiResponse.badRequest(res, 'quantity must be positive');
      if (!reason) return apiResponse.badRequest(res, 'reason is required');

      const [item] = await sql`
        SELECT id, name, qty_available FROM stock_items WHERE id = ${itemId}
      `;
      if (!item) return apiResponse.notFound(res, 'Stock item', itemId);

      const currentQty = Number(item.qty_available || 0);
      const qty = Number(quantity);
      const newQty = adjustmentType === 'increase' ? currentQty + qty : currentQty - qty;

      if (newQty < 0) {
        return apiResponse.badRequest(res, `Cannot decrease by ${qty} — current qty is ${currentQty}`);
      }

      await sql`UPDATE stock_items SET qty_available = ${newQty} WHERE id = ${itemId}`;

      log.info('Stock item adjusted', { itemId, adjustmentType, quantity: qty, newQty });

      return apiResponse.success(res, {
        itemId,
        adjustmentType,
        quantity: qty,
        previousQuantity: currentQty,
        newQuantity: newQty,
      });
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Adjustment failed';
      log.error('Item adjustment failed', { error: err });
      return apiResponse.badRequest(res, message);
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

export default withAuth(handler);
/**
 * Item Opening Balances API
 * GET  — list active stock items with current qty and cost
 * POST — set opening balances (quantity + unit cost)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';

const sql = neon(process.env.DATABASE_URL!);

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    try {
      const rows = await sql`
        SELECT id, item_code, name, category, uom, qty_available, standard_cost, list_price
        FROM stock_items WHERE is_active = true ORDER BY name
      `;
      return apiResponse.success(res, rows);
    } catch (err) {
      log.error('Failed to fetch items for opening balances', { error: err });
      return apiResponse.badRequest(res, 'Failed to fetch items');
    }
  }

  if (req.method === 'POST') {
    try {
      const { items } = req.body as {
        items?: { itemId: string; quantity: number; unitCost: number }[];
      };

      if (!items || !Array.isArray(items) || items.length === 0) {
        return apiResponse.badRequest(res, 'items array is required');
      }

      for (const entry of items) {
        if (!entry.itemId || entry.quantity == null || entry.unitCost == null) {
          return apiResponse.badRequest(res, 'Each entry needs itemId, quantity, and unitCost');
        }
      }

      for (const entry of items) {
        await sql`
          UPDATE stock_items
          SET qty_available = ${Number(entry.quantity)},
              standard_cost = ${Number(entry.unitCost)}
          WHERE id = ${entry.itemId}
        `;
      }

      log.info('Item opening balances set', { count: items.length });
      return apiResponse.success(res, { updated: items.length });
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to set opening balances';
      log.error('Item opening balances failed', { error: err });
      return apiResponse.badRequest(res, message);
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

export default withAuth(handler);
