/**
 * Recurring Invoice Service
 * Phase 1 Sage Alignment: Auto-generate customer invoices on schedule
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type {
  RecurringInvoice,
  RecurringInvoiceCreateInput,
} from '../types/ar.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

export async function getRecurringInvoices(filters?: {
  status?: string;
  clientId?: string;
  limit?: number;
  offset?: number;
}): Promise<{ items: RecurringInvoice[]; total: number }> {
  const limit = filters?.limit || 50;
  const offset = filters?.offset || 0;
  let rows: Row[];
  let countRows: Row[];

  if (filters?.clientId) {
    rows = (await sql`
      SELECT ri.*, c.company_name AS client_name
      FROM recurring_invoices ri LEFT JOIN clients c ON c.id = ri.client_id
      WHERE ri.client_id = ${filters.clientId}::UUID
      ORDER BY ri.created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM recurring_invoices WHERE client_id = ${filters.clientId}::UUID
    `) as Row[];
  } else if (filters?.status) {
    rows = (await sql`
      SELECT ri.*, c.company_name AS client_name
      FROM recurring_invoices ri LEFT JOIN clients c ON c.id = ri.client_id
      WHERE ri.status = ${filters.status}
      ORDER BY ri.created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM recurring_invoices WHERE status = ${filters.status}
    `) as Row[];
  } else {
    rows = (await sql`
      SELECT ri.*, c.company_name AS client_name
      FROM recurring_invoices ri LEFT JOIN clients c ON c.id = ri.client_id
      ORDER BY ri.created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`SELECT COUNT(*) AS cnt FROM recurring_invoices`) as Row[];
  }

  return { items: rows.map(mapRow), total: Number(countRows[0]?.cnt || 0) };
}

export async function createRecurringInvoice(
  input: RecurringInvoiceCreateInput,
  userId: string
): Promise<RecurringInvoice> {
  const taxRate = input.taxRate ?? 15;
  const subtotal = input.lineItems.reduce(
    (s, li) => s + li.quantity * li.unitPrice, 0
  );
  const taxAmount = Math.round(subtotal * (taxRate / 100) * 100) / 100;
  const totalAmount = subtotal + taxAmount;

  const rows = (await sql`
    INSERT INTO recurring_invoices (
      template_name, client_id, project_id, frequency, next_run_date,
      end_date, description, line_items, subtotal, tax_rate, tax_amount,
      total_amount, payment_terms, created_by
    ) VALUES (
      ${input.templateName}, ${input.clientId}::UUID,
      ${input.projectId || null}, ${input.frequency}, ${input.nextRunDate},
      ${input.endDate || null}, ${input.description || null},
      ${JSON.stringify(input.lineItems)}::JSONB, ${subtotal}, ${taxRate},
      ${taxAmount}, ${totalAmount}, ${input.paymentTerms || '30 days'}, ${userId}::UUID
    ) RETURNING *
  `) as Row[];

  log.info('Created recurring invoice', { id: rows[0]?.id }, 'accounting');
  return mapRow(rows[0]!);
}

export async function updateRecurringStatus(
  id: string,
  status: 'paused' | 'active' | 'cancelled'
): Promise<void> {
  await sql`UPDATE recurring_invoices SET status = ${status} WHERE id = ${id}`;
  log.info('Updated recurring invoice status', { id, status }, 'accounting');
}

export async function generateInvoiceFromRecurring(
  id: string,
  userId: string
): Promise<string> {
  const rows = (await sql`SELECT * FROM recurring_invoices WHERE id = ${id}`) as Row[];
  if (!rows[0]) throw new Error('Recurring invoice not found');
  const ri = rows[0];
  if (ri.status !== 'active') throw new Error('Recurring invoice is not active');

  const inv = (await sql`
    INSERT INTO customer_invoices (
      client_id, project_id, invoice_date, due_date, subtotal,
      tax_amount, total_amount, status, description, created_by
    ) VALUES (
      ${ri.client_id}::UUID, ${ri.project_id || null},
      CURRENT_DATE, CURRENT_DATE + INTERVAL '30 days',
      ${Number(ri.subtotal)}, ${Number(ri.tax_amount)}, ${Number(ri.total_amount)},
      'approved', ${ri.description || ri.template_name}, ${userId}::UUID
    ) RETURNING id
  `) as Row[];

  const nextDate = advanceDate(String(ri.next_run_date), String(ri.frequency));
  const endDate = ri.end_date ? String(ri.end_date) : null;
  const newStatus = endDate && nextDate > endDate ? 'completed' : 'active';

  await sql`
    UPDATE recurring_invoices
    SET last_run_date = CURRENT_DATE, next_run_date = ${nextDate}::DATE,
        run_count = run_count + 1, status = ${newStatus}
    WHERE id = ${id}
  `;

  log.info('Generated invoice from recurring', { recurringId: id, invoiceId: inv[0]?.id }, 'accounting');
  return String(inv[0]!.id);
}

function advanceDate(dateStr: string, frequency: string): string {
  const d = new Date(dateStr);
  switch (frequency) {
    case 'weekly': d.setDate(d.getDate() + 7); break;
    case 'monthly': d.setMonth(d.getMonth() + 1); break;
    case 'quarterly': d.setMonth(d.getMonth() + 3); break;
    case 'annually': d.setFullYear(d.getFullYear() + 1); break;
  }
  return d.toISOString().split('T')[0]!;
}

function mapRow(row: Row): RecurringInvoice {
  return {
    id: String(row.id),
    templateName: String(row.template_name),
    clientId: String(row.client_id),
    projectId: row.project_id ? String(row.project_id) : undefined,
    frequency: String(row.frequency) as RecurringInvoice['frequency'],
    nextRunDate: String(row.next_run_date),
    endDate: row.end_date ? String(row.end_date) : undefined,
    lastRunDate: row.last_run_date ? String(row.last_run_date) : undefined,
    runCount: Number(row.run_count),
    status: String(row.status) as RecurringInvoice['status'],
    description: row.description ? String(row.description) : undefined,
    lineItems: Array.isArray(row.line_items) ? row.line_items : JSON.parse(row.line_items || '[]'),
    subtotal: Number(row.subtotal),
    taxRate: Number(row.tax_rate),
    taxAmount: Number(row.tax_amount),
    totalAmount: Number(row.total_amount),
    paymentTerms: row.payment_terms ? String(row.payment_terms) : undefined,
    createdBy: String(row.created_by),
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
    clientName: row.client_name ? String(row.client_name) : undefined,
  };
}

/**
 * Phase 4: Cross-Module GL Integration Hooks
 * - PO approved → DR Materials + VAT Input, CR AP (commitment accounting)
 * - Asset depreciation → DR Depreciation Expense, CR Accumulated Depreciation
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

const ACCOUNTS = {
  VAT_INPUT: '1140',
  ACCUM_DEPRECIATION: '1230',
  AP: '2110',
  MATERIALS: '5100',
  DEPRECIATION_EXPENSE: '5800',
} as const;

async function getAccountId(code: string): Promise<string> {
  const rows = (await sql`SELECT id FROM gl_accounts WHERE account_code = ${code} LIMIT 1`) as Row[];
  if (!rows[0]) throw new Error(`GL account ${code} not found`);
  return String(rows[0].id);
}

// ── Purchase Order Approved → GL (Commitment Accounting) ────────────────────

export async function postPurchaseOrderToGL(
  poId: string,
  userId: string
): Promise<string | null> {
  try {
    const po = (await sql`
      SELECT id, po_number, total_amount, tax_amount, project_id, gl_journal_entry_id
      FROM purchase_orders WHERE id = ${poId}
    `) as Row[];

    if (!po[0]) { log.warn('PO not found for GL posting', { poId }, 'accounting'); return null; }
    if (po[0].gl_journal_entry_id) return String(po[0].gl_journal_entry_id);

    const totalAmount = Number(po[0].total_amount || 0);
    const taxAmount = Number(po[0].tax_amount || 0);
    const netAmount = totalAmount - taxAmount;
    if (totalAmount === 0) return null;

    const materialsId = await getAccountId(ACCOUNTS.MATERIALS);
    const apId = await getAccountId(ACCOUNTS.AP);
    const vatInputId = await getAccountId(ACCOUNTS.VAT_INPUT);
    const projectId = po[0].project_id ? String(po[0].project_id) : null;

    const entry = (await sql`
      INSERT INTO gl_journal_entries (
        entry_number, entry_date, description, source, status, created_by
      ) VALUES (
        ${`PO-${po[0].po_number}`}, CURRENT_DATE,
        ${`Purchase order ${po[0].po_number} approved — commitment`},
        'auto_purchase_order', 'posted', ${userId}
      ) RETURNING id
    `) as Row[];

    const entryId = String(entry[0].id);

    if (projectId) {
      await sql`
        INSERT INTO gl_journal_lines (journal_entry_id, gl_account_id, debit, credit, description, project_id)
        VALUES (${entryId}::UUID, ${materialsId}::UUID, ${netAmount}, 0,
          ${`PO ${po[0].po_number} materials`}, ${projectId}::UUID)
      `;
      if (taxAmount > 0.01) {
        await sql`
          INSERT INTO gl_journal_lines (journal_entry_id, gl_account_id, debit, credit, description, project_id)
          VALUES (${entryId}::UUID, ${vatInputId}::UUID, ${taxAmount}, 0,
            ${`PO ${po[0].po_number} VAT`}, ${projectId}::UUID)
        `;
      }
      await sql`
        INSERT INTO gl_journal_lines (journal_entry_id, gl_account_id, debit, credit, description, project_id)
        VALUES (${entryId}::UUID, ${apId}::UUID, 0, ${totalAmount},
          ${`PO ${po[0].po_number}`}, ${projectId}::UUID)
      `;
    } else {
      await sql`
        INSERT INTO gl_journal_lines (journal_entry_id, gl_account_id, debit, credit, description)
        VALUES (${entryId}::UUID, ${materialsId}::UUID, ${netAmount}, 0, ${`PO ${po[0].po_number} materials`})
      `;
      if (taxAmount > 0.01) {
        await sql`
          INSERT INTO gl_journal_lines (journal_entry_id, gl_account_id, debit, credit, description)
          VALUES (${entryId}::UUID, ${vatInputId}::UUID, ${taxAmount}, 0, ${`PO ${po[0].po_number} VAT`})
        `;
      }
      await sql`
        INSERT INTO gl_journal_lines (journal_entry_id, gl_account_id, debit, credit, description)
        VALUES (${entryId}::UUID, ${apId}::UUID, 0, ${totalAmount}, ${`PO ${po[0].po_number}`})
      `;
    }

    await sql`UPDATE purchase_orders SET gl_journal_entry_id = ${entryId}::UUID WHERE id = ${poId}`;

    log.info('PO GL posted', { poId, entryId, totalAmount }, 'accounting');
    return entryId;
  } catch (err) {
    log.error('Failed to post PO to GL', { poId, error: err }, 'accounting');
    return null;
  }
}

// ── Asset Depreciation → GL ────────────────────────────────────────────────

export async function postAssetDepreciationToGL(
  assetId: string,
  depreciationAmount: number,
  userId: string
): Promise<string | null> {
  try {
    if (depreciationAmount <= 0) return null;

    const asset = (await sql`
      SELECT id, asset_number, name FROM assets WHERE id = ${assetId}
    `) as Row[];

    if (!asset[0]) { log.warn('Asset not found for depreciation GL', { assetId }, 'accounting'); return null; }

    const depExpenseId = await getAccountId(ACCOUNTS.DEPRECIATION_EXPENSE);
    const accumDepId = await getAccountId(ACCOUNTS.ACCUM_DEPRECIATION);

    const entry = (await sql`
      INSERT INTO gl_journal_entries (
        entry_number, entry_date, description, source, status, created_by
      ) VALUES (
        ${`DEP-${asset[0].asset_number}-${new Date().toISOString().slice(0, 7)}`}, CURRENT_DATE,
        ${`Depreciation: ${asset[0].name} (${asset[0].asset_number})`},
        'auto_depreciation', 'posted', ${userId}
      ) RETURNING id
    `) as Row[];

    const entryId = String(entry[0].id);

    await sql`
      INSERT INTO gl_journal_lines (journal_entry_id, gl_account_id, debit, credit, description)
      VALUES (${entryId}::UUID, ${depExpenseId}::UUID, ${depreciationAmount}, 0,
        ${`Depreciation: ${asset[0].asset_number}`})
    `;
    await sql`
      INSERT INTO gl_journal_lines (journal_entry_id, gl_account_id, debit, credit, description)
      VALUES (${entryId}::UUID, ${accumDepId}::UUID, 0, ${depreciationAmount},
        ${`Depreciation: ${asset[0].asset_number}`})
    `;

    await sql`
      UPDATE assets SET
        accumulated_depreciation = COALESCE(accumulated_depreciation, 0) + ${depreciationAmount},
        current_book_value = COALESCE(purchase_price, 0) - (COALESCE(accumulated_depreciation, 0) + ${depreciationAmount}),
        updated_at = NOW()
      WHERE id = ${assetId}
    `;

    log.info('Asset depreciation GL posted', { assetId, entryId, depreciationAmount }, 'accounting');
    return entryId;
  } catch (err) {
    log.error('Failed to post asset depreciation to GL', { assetId, error: err }, 'accounting');
    return null;
  }
}

