/**
 * Currency & Exchange Rate Service
 * Multi-currency foundation for accounting
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

export interface Currency {
  code: string;
  name: string;
  symbol: string;
  decimalPlaces: number;
  isActive: boolean;
}

export interface ExchangeRate {
  id: string;
  fromCurrency: string;
  toCurrency: string;
  rate: number;
  effectiveDate: string;
  source: string;
}

// ── Currencies ──────────────────────────────────────────────────────────────

export async function getCurrencies(activeOnly = true): Promise<Currency[]> {
  const rows = activeOnly
    ? ((await sql`SELECT * FROM currencies WHERE is_active = true ORDER BY code`) as Row[])
    : ((await sql`SELECT * FROM currencies ORDER BY code`) as Row[]);
  return rows.map(mapCurrency);
}

export async function createCurrency(input: {
  code: string; name: string; symbol: string; decimalPlaces?: number;
}): Promise<Currency> {
  const rows = (await sql`
    INSERT INTO currencies (code, name, symbol, decimal_places)
    VALUES (${input.code.toUpperCase()}, ${input.name}, ${input.symbol}, ${input.decimalPlaces || 2})
    RETURNING *
  `) as Row[];
  log.info('Created currency', { code: input.code }, 'accounting');
  return mapCurrency(rows[0]!);
}

export async function toggleCurrency(code: string, isActive: boolean): Promise<void> {
  await sql`UPDATE currencies SET is_active = ${isActive} WHERE code = ${code}`;
}

// ── Exchange Rates ──────────────────────────────────────────────────────────

export async function getExchangeRates(filters?: {
  fromCurrency?: string; toCurrency?: string; limit?: number;
}): Promise<ExchangeRate[]> {
  const limit = filters?.limit || 100;

  if (filters?.fromCurrency && filters?.toCurrency) {
    const rows = (await sql`
      SELECT * FROM exchange_rates
      WHERE from_currency = ${filters.fromCurrency} AND to_currency = ${filters.toCurrency}
      ORDER BY effective_date DESC LIMIT ${limit}
    `) as Row[];
    return rows.map(mapRate);
  }
  if (filters?.fromCurrency) {
    const rows = (await sql`
      SELECT * FROM exchange_rates
      WHERE from_currency = ${filters.fromCurrency}
      ORDER BY effective_date DESC LIMIT ${limit}
    `) as Row[];
    return rows.map(mapRate);
  }
  const rows = (await sql`
    SELECT * FROM exchange_rates ORDER BY effective_date DESC LIMIT ${limit}
  `) as Row[];
  return rows.map(mapRate);
}

export async function getLatestRate(
  fromCurrency: string, toCurrency: string, asOfDate?: string
): Promise<number | null> {
  const date = asOfDate || new Date().toISOString().split('T')[0]!;
  const rows = (await sql`
    SELECT rate FROM exchange_rates
    WHERE from_currency = ${fromCurrency} AND to_currency = ${toCurrency}
      AND effective_date <= ${date}::DATE
    ORDER BY effective_date DESC LIMIT 1
  `) as Row[];
  return rows[0] ? Number(rows[0].rate) : null;
}

export async function setExchangeRate(input: {
  fromCurrency: string; toCurrency: string; rate: number;
  effectiveDate: string; source?: string;
}, userId: string): Promise<ExchangeRate> {
  const rows = (await sql`
    INSERT INTO exchange_rates (from_currency, to_currency, rate, effective_date, source, created_by)
    VALUES (${input.fromCurrency}, ${input.toCurrency}, ${input.rate},
            ${input.effectiveDate}::DATE, ${input.source || 'manual'}, ${userId}::UUID)
    ON CONFLICT (from_currency, to_currency, effective_date)
    DO UPDATE SET rate = EXCLUDED.rate, source = EXCLUDED.source, created_by = EXCLUDED.created_by
    RETURNING *
  `) as Row[];
  log.info('Set exchange rate', {
    pair: `${input.fromCurrency}/${input.toCurrency}`,
    rate: input.rate, date: input.effectiveDate,
  }, 'accounting');
  return mapRate(rows[0]!);
}

export async function convertAmount(
  amount: number, fromCurrency: string, toCurrency: string, asOfDate?: string
): Promise<{ converted: number; rate: number } | null> {
  if (fromCurrency === toCurrency) return { converted: amount, rate: 1 };
  const rate = await getLatestRate(fromCurrency, toCurrency, asOfDate);
  if (rate === null) return null;
  return { converted: Math.round(amount * rate * 100) / 100, rate };
}

// ── Settings ────────────────────────────────────────────────────────────────

export async function getSetting(key: string): Promise<string | null> {
  const rows = (await sql`
    SELECT setting_value FROM accounting_settings WHERE setting_key = ${key}
  `) as Row[];
  return rows[0] ? String(rows[0].setting_value) : null;
}

export async function setSetting(key: string, value: string, userId: string): Promise<void> {
  await sql`
    INSERT INTO accounting_settings (setting_key, setting_value, updated_by)
    VALUES (${key}, ${value}, ${userId}::UUID)
    ON CONFLICT (setting_key) DO UPDATE SET setting_value = EXCLUDED.setting_value,
      updated_by = EXCLUDED.updated_by, updated_at = NOW()
  `;
}

// ── Helpers ─────────────────────────────────────────────────────────────────

function mapCurrency(row: Row): Currency {
  return {
    code: String(row.code),
    name: String(row.name),
    symbol: String(row.symbol),
    decimalPlaces: Number(row.decimal_places),
    isActive: Boolean(row.is_active),
  };
}

function mapRate(row: Row): ExchangeRate {
  return {
    id: String(row.id),
    fromCurrency: String(row.from_currency),
    toCurrency: String(row.to_currency),
    rate: Number(row.rate),
    effectiveDate: row.effective_date instanceof Date
      ? row.effective_date.toISOString().split('T')[0]!
      : String(row.effective_date).split('T')[0]!,
    source: String(row.source || 'manual'),
  };
}

/**
 * DRC (Domestic Reverse Charge) VAT Service
 * Phase 5: Handle DRC VAT for supplier invoices
 *
 * DRC applies when a supplier provides certain services and the recipient
 * (FibreFlow) is responsible for accounting for VAT on those supplies.
 * Instead of the supplier charging VAT, the buyer self-accounts:
 *   DR Input VAT (1140)   — claimable
 *   CR Output VAT (2120)  — payable (net effect = zero)
 *
 * The invoice amount stays the same but both sides of VAT are recorded.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { createJournalEntry, postJournalEntry } from './journalEntryService';
import type { JournalLineInput } from '../types/gl.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

const DEFAULT_VAT_RATE = 0.15; // SA VAT rate
const VAT_INPUT_CODE = '1140';
const VAT_OUTPUT_CODE = '2120';

/** Load VAT rate from app_settings, falling back to 15% */
async function getVatRate(): Promise<number> {
  try {
    const rows = (await sql`SELECT value FROM app_settings WHERE key = 'vat_rate'`) as Row[];
    if (rows[0]?.value) {
      const rate = Number(rows[0].value);
      if (rate > 0 && rate < 1) return rate;
    }
  } catch { /* use default */ }
  return DEFAULT_VAT_RATE;
}

export interface DRCResult {
  supplierInvoiceId: string;
  vatAmount: number;
  journalEntryId: string;
}

/**
 * Apply DRC VAT to a supplier invoice.
 * Creates a journal entry: DR Input VAT, CR Output VAT.
 */
export async function applyDRCVat(
  supplierInvoiceId: string,
  userId: string
): Promise<DRCResult> {
  // Get invoice details
  const invoices = (await sql`
    SELECT si.id, si.invoice_number, si.total_amount, si.is_drc
    FROM supplier_invoices si
    WHERE si.id = ${supplierInvoiceId}::UUID
  `) as Row[];

  if (!invoices[0]) throw new Error('Supplier invoice not found');
  const inv = invoices[0];

  if (inv.is_drc) throw new Error('DRC VAT already applied to this invoice');

  const totalExclVat = Number(inv.total_amount);
  const vatRate = await getVatRate();
  const vatAmount = Math.round(totalExclVat * vatRate * 100) / 100;

  // Get VAT account IDs
  const accounts = (await sql`
    SELECT id, account_code FROM gl_accounts
    WHERE account_code IN (${VAT_INPUT_CODE}, ${VAT_OUTPUT_CODE})
  `) as Row[];

  const inputVatId = accounts.find((a: Row) => a.account_code === VAT_INPUT_CODE)?.id;
  const outputVatId = accounts.find((a: Row) => a.account_code === VAT_OUTPUT_CODE)?.id;

  if (!inputVatId || !outputVatId) {
    throw new Error('VAT GL accounts (1140/2120) not found in chart of accounts');
  }

  const description = `DRC VAT: ${inv.invoice_number} (R${vatAmount.toFixed(2)})`;

  const lines: JournalLineInput[] = [
    { glAccountId: String(inputVatId), debit: vatAmount, credit: 0, description },
    { glAccountId: String(outputVatId), debit: 0, credit: vatAmount, description },
  ];

  const je = await createJournalEntry({
    entryDate: new Date().toISOString().split('T')[0],
    description,
    source: 'auto_vat_adjustment',
    sourceDocumentId: supplierInvoiceId,
    lines,
  }, userId);

  await postJournalEntry(je.id, userId);

  // Mark invoice as DRC processed
  await sql`
    UPDATE supplier_invoices SET is_drc = true WHERE id = ${supplierInvoiceId}::UUID
  `;

  log.info('Applied DRC VAT', {
    supplierInvoiceId, vatAmount, journalEntryId: je.id,
  }, 'accounting');

  return { supplierInvoiceId, vatAmount, journalEntryId: je.id };
}

/**
 * Get all DRC-eligible supplier invoices (not yet processed).
 */
export async function getDRCEligibleInvoices(): Promise<Array<{
  id: string; invoiceNumber: string; supplierName: string;
  totalAmount: number; vatAmount: number; invoiceDate: string;
}>> {
  const rows = (await sql`
    SELECT si.id, si.invoice_number, si.total_amount, si.invoice_date,
           s.company_name as supplier_name
    FROM supplier_invoices si
    LEFT JOIN suppliers s ON s.id = si.supplier_id
    WHERE si.status IN ('approved', 'partially_paid', 'paid')
      AND (si.is_drc IS NULL OR si.is_drc = false)
    ORDER BY si.invoice_date DESC
  `) as Row[];

  const vatRate = await getVatRate();
  return rows.map((r: Row) => ({
    id: String(r.id),
    invoiceNumber: String(r.invoice_number),
    supplierName: String(r.supplier_name || 'Unknown'),
    totalAmount: Number(r.total_amount),
    vatAmount: Math.round(Number(r.total_amount) * vatRate * 100) / 100,
    invoiceDate: String(r.invoice_date).split('T')[0],
  }));
}

/**
 * Get DRC VAT history (already processed).
 */
export async function getDRCHistory(): Promise<Array<{
  id: string; invoiceNumber: string; supplierName: string;
  totalAmount: number; invoiceDate: string;
}>> {
  const rows = (await sql`
    SELECT si.id, si.invoice_number, si.total_amount, si.invoice_date,
           s.company_name as supplier_name
    FROM supplier_invoices si
    LEFT JOIN suppliers s ON s.id = si.supplier_id
    WHERE si.is_drc = true
    ORDER BY si.invoice_date DESC
  `) as Row[];

  return rows.map((r: Row) => ({
    id: String(r.id),
    invoiceNumber: String(r.invoice_number),
    supplierName: String(r.supplier_name || 'Unknown'),
    totalAmount: Number(r.total_amount),
    invoiceDate: String(r.invoice_date).split('T')[0],
  }));
}

