/**
 * Sage Customer Invoice Importer
 * Moves sage_customer_invoices → customer_invoices + customer_invoice_items
 * Matches Sage's approach: invoices are standalone AR documents,
 * no separate GL journal entries are created per invoice.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { MigrationRun } from './sageMigrationService';
import { startRun, completeRun, failRun } from './sageMigrationService';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

/**
 * Import sage_customer_invoices into customer_invoices with line items
 */
export async function importCustomerInvoices(userId: string): Promise<MigrationRun> {
  const runId = await startRun('customer_invoice_import', userId);

  try {
    const sageInvoices = (await sql`
      SELECT id, sage_invoice_id, sage_customer_id, client_id,
        invoice_number, invoice_date, due_date,
        subtotal, tax_amount, total_amount, outstanding_amount,
        status, raw_data
      FROM sage_customer_invoices
      WHERE migration_status = 'pending'
      ORDER BY invoice_date
    `) as Row[];

    let succeeded = 0;
    let failed = 0;
    let skipped = 0;

    for (const inv of sageInvoices) {
      try {
        const totalAmount = Number(inv.total_amount || 0);
        if (totalAmount === 0) { skipped++; continue; }

        const clientId = inv.client_id;
        if (!clientId) {
          await sql`
            UPDATE sage_customer_invoices SET migration_status = 'failed'
            WHERE id = ${inv.id}
          `;
          failed++;
          continue;
        }

        const subtotal = Number(inv.subtotal || 0) || totalAmount / 1.15;
        const taxAmount = Number(inv.tax_amount || 0) || totalAmount - subtotal;
        const taxRate = subtotal > 0
          ? Math.round((taxAmount / subtotal) * 100 * 100) / 100
          : 15;
        const isPaid = inv.status === 'paid'
          || Number(inv.outstanding_amount || 0) === 0;

        // Extract reference from raw_data
        const rawData = parseRawData(inv.raw_data);
        const reference = rawData?.Reference || inv.invoice_number || null;

        const newInv = (await sql`
          INSERT INTO customer_invoices (
            invoice_number, client_id, invoice_date, due_date,
            billing_period_start, billing_period_end,
            subtotal, tax_rate, tax_amount, total_amount,
            amount_paid, status, sage_invoice_id, reference, created_by
          ) VALUES (
            ${inv.invoice_number || `SAGE-${inv.sage_invoice_id}`},
            ${clientId}::UUID,
            ${inv.invoice_date}, ${inv.due_date || inv.invoice_date},
            ${inv.invoice_date}, ${inv.due_date || inv.invoice_date},
            ${subtotal.toFixed(2)}, ${taxRate}, ${taxAmount.toFixed(2)},
            ${totalAmount},
            ${isPaid ? totalAmount : 0},
            ${isPaid ? 'paid' : 'approved'},
            ${inv.sage_invoice_id},
            ${reference},
            ${userId}
          ) RETURNING id
        `) as Row[];

        const newInvoiceId = String(newInv[0].id);

        // Insert line items from raw_data
        const lines = rawData?.Lines;
        if (lines && Array.isArray(lines) && lines.length > 0) {
          for (const line of lines) {
            const qty = Number(line.Quantity || 1);
            const price = Number(line.UnitPriceExclusive || 0);
            const lineTax = Number(line.Tax || 0);
            const lineTotal = Number(line.Exclusive || line.Total || price * qty);

            await sql`
              INSERT INTO customer_invoice_items (
                invoice_id, description, unit_price, quantity,
                tax_amount, line_total, income_type
              ) VALUES (
                ${newInvoiceId}::UUID,
                ${line.Description || 'Line item'},
                ${price}, ${qty}, ${lineTax}, ${lineTotal}, 'other'
              )
            `;
          }
        }

        await sql`
          UPDATE sage_customer_invoices
          SET migration_status = 'imported',
              gl_customer_invoice_id = ${newInvoiceId}::UUID
          WHERE id = ${inv.id}
        `;

        succeeded++;
      } catch (err) {
        log.error('Failed to import customer invoice',
          { invoiceId: inv.id, error: err }, 'accounting');
        await sql`
          UPDATE sage_customer_invoices SET migration_status = 'failed'
          WHERE id = ${inv.id}
        `;
        failed++;
      }
    }

    return await completeRun(runId, sageInvoices.length, succeeded, failed, skipped);
  } catch (err) {
    await failRun(runId, err);
    throw err;
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function parseRawData(rawData: unknown): any {
  if (!rawData) return null;
  if (typeof rawData === 'string') {
    try { return JSON.parse(rawData); } catch { return null; }
  }
  return rawData;
}

/**
 * Budget Management Service
 * Phase 5: Create and manage budgets per GL account per fiscal year
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

const MONTHS = ['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'] as const;

export interface BudgetEntry {
  id: string;
  glAccountId: string;
  accountCode: string;
  accountName: string;
  accountType: string;
  fiscalYear: number;
  annualAmount: number;
  months: number[];
  notes?: string;
  createdAt: string;
}

export interface BudgetInput {
  glAccountId: string;
  fiscalYear: number;
  annualAmount: number;
  months?: number[];
  notes?: string;
}

export async function getBudgets(fiscalYear: number): Promise<BudgetEntry[]> {
  const rows = (await sql`
    SELECT b.*, ga.account_code, ga.account_name, ga.account_type
    FROM accounting_budgets b
    JOIN gl_accounts ga ON ga.id = b.gl_account_id
    WHERE b.fiscal_year = ${fiscalYear}
    ORDER BY ga.account_code
  `) as Row[];
  return rows.map(mapRow);
}

export async function upsertBudget(input: BudgetInput, userId: string): Promise<BudgetEntry> {
  const months = input.months || distributeEvenly(input.annualAmount);

  const rows = (await sql`
    INSERT INTO accounting_budgets (
      gl_account_id, fiscal_year, annual_amount,
      jan, feb, mar, apr, may, jun, jul, aug, sep, oct, nov, "dec",
      notes, created_by
    ) VALUES (
      ${input.glAccountId}::UUID, ${input.fiscalYear}, ${input.annualAmount},
      ${months[0]}, ${months[1]}, ${months[2]}, ${months[3]},
      ${months[4]}, ${months[5]}, ${months[6]}, ${months[7]},
      ${months[8]}, ${months[9]}, ${months[10]}, ${months[11]},
      ${input.notes || null}, ${userId}::UUID
    )
    ON CONFLICT (gl_account_id, fiscal_year)
    DO UPDATE SET
      annual_amount = EXCLUDED.annual_amount,
      jan = EXCLUDED.jan, feb = EXCLUDED.feb, mar = EXCLUDED.mar,
      apr = EXCLUDED.apr, may = EXCLUDED.may, jun = EXCLUDED.jun,
      jul = EXCLUDED.jul, aug = EXCLUDED.aug, sep = EXCLUDED.sep,
      oct = EXCLUDED.oct, nov = EXCLUDED.nov, "dec" = EXCLUDED."dec",
      notes = EXCLUDED.notes
    RETURNING *
  `) as Row[];

  // Re-query with join
  const result = (await sql`
    SELECT b.*, ga.account_code, ga.account_name, ga.account_type
    FROM accounting_budgets b
    JOIN gl_accounts ga ON ga.id = b.gl_account_id
    WHERE b.id = ${rows[0].id}::UUID
  `) as Row[];

  log.info('Upserted budget', {
    glAccountId: input.glAccountId, fiscalYear: input.fiscalYear,
    annualAmount: input.annualAmount,
  }, 'accounting');
  return mapRow(result[0]);
}

export async function deleteBudget(id: string): Promise<void> {
  await sql`DELETE FROM accounting_budgets WHERE id = ${id}::UUID`;
}

export async function copyBudgets(fromYear: number, toYear: number, userId: string): Promise<number> {
  const existing = (await sql`
    SELECT gl_account_id, annual_amount,
           jan, feb, mar, apr, may, jun, jul, aug, sep, oct, nov, "dec", notes
    FROM accounting_budgets WHERE fiscal_year = ${fromYear}
  `) as Row[];

  let count = 0;
  for (const row of existing) {
    await sql`
      INSERT INTO accounting_budgets (
        gl_account_id, fiscal_year, annual_amount,
        jan, feb, mar, apr, may, jun, jul, aug, sep, oct, nov, "dec",
        notes, created_by
      ) VALUES (
        ${row.gl_account_id}::UUID, ${toYear}, ${row.annual_amount},
        ${row.jan}, ${row.feb}, ${row.mar}, ${row.apr},
        ${row.may}, ${row.jun}, ${row.jul}, ${row.aug},
        ${row.sep}, ${row.oct}, ${row.nov}, ${row.dec},
        ${row.notes || null}, ${userId}::UUID
      )
      ON CONFLICT (gl_account_id, fiscal_year) DO NOTHING
    `;
    count++;
  }
  log.info('Copied budgets', { fromYear, toYear, count }, 'accounting');
  return count;
}

function distributeEvenly(annual: number): number[] {
  const monthly = Math.round((annual / 12) * 100) / 100;
  const arr = Array(12).fill(monthly) as number[];
  // Adjust last month for rounding
  const sum = arr.slice(0, 11).reduce((s, v) => s + v, 0);
  arr[11] = Math.round((annual - sum) * 100) / 100;
  return arr;
}

function mapRow(row: Row): BudgetEntry {
  return {
    id: String(row.id),
    glAccountId: String(row.gl_account_id),
    accountCode: String(row.account_code || ''),
    accountName: String(row.account_name || ''),
    accountType: String(row.account_type || ''),
    fiscalYear: Number(row.fiscal_year),
    annualAmount: Number(row.annual_amount),
    months: MONTHS.map(m => Number(row[m] || 0)),
    notes: row.notes ? String(row.notes) : undefined,
    createdAt: String(row.created_at),
  };
}

