/**
 * Budget vs Actual Report API
 * GET /api/accounting/reports-budget-vs-actual?period=current|ytd|full_year
 * Sage equivalent: Reports > Budget vs Actual
 *
 * Reads budgets from gl_accounts.budget_amount column (if exists)
 * or from app_settings key 'accounting_budgets'.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { createLoggedSql } from '@/lib/db-logger';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';

const sql = createLoggedSql(process.env.DATABASE_URL!);

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
  }

  try {
    const { period = 'ytd' } = req.query;

    // Determine date range
    let startDate: string;
    let endDate: string;
    const now = new Date();

    if (period === 'current') {
      startDate = new Date(now.getFullYear(), now.getMonth(), 1).toISOString().split('T')[0];
      endDate = now.toISOString().split('T')[0];
    } else {
      // YTD or full_year — use fiscal year start
      const [fy] = await sql`
        SELECT MIN(start_date) as start_date, MAX(end_date) as end_date
        FROM fiscal_periods
        WHERE fiscal_year = (SELECT fiscal_year FROM fiscal_periods WHERE status = 'open' ORDER BY start_date DESC LIMIT 1)
      `;
      startDate = fy?.start_date?.toString().split('T')[0] || `${now.getFullYear()}-03-01`;
      endDate = period === 'full_year'
        ? (fy?.end_date?.toString().split('T')[0] || `${now.getFullYear() + 1}-02-28`)
        : now.toISOString().split('T')[0];
    }

    // Load budgets from accounting_budgets table
    // Determine which month columns to sum based on period
    let budgets: Record<string, number> = {};
    try {
      const fiscalYear = new Date(startDate).getFullYear();
      const startMonth = new Date(startDate).getMonth(); // 0-based
      const endMonth = new Date(endDate).getMonth();
      const monthCols = ['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'];

      const budgetRows = await sql`
        SELECT ab.gl_account_id, ga.account_code,
          ab.jan, ab.feb, ab.mar, ab.apr, ab.may, ab.jun,
          ab.jul, ab.aug, ab.sep, ab.oct, ab.nov, ab.dec
        FROM accounting_budgets ab
        JOIN gl_accounts ga ON ga.id = ab.gl_account_id
        WHERE ab.fiscal_year = ${fiscalYear}
      `;
      for (const row of budgetRows) {
        let total = 0;
        for (let m = startMonth; m <= endMonth; m++) {
          total += Number(row[monthCols[m]] || 0);
        }
        budgets[row.account_code] = total;
        budgets[row.gl_account_id] = total;
      }
    } catch {
      // No budgets configured yet — fall back to app_settings
      try {
        const [row] = await sql`SELECT value FROM app_settings WHERE key = 'accounting_budgets'`;
        if (row?.value) {
          budgets = typeof row.value === 'string' ? JSON.parse(row.value) : row.value;
        }
      } catch { /* no budgets */ }
    }

    // Get actual GL balances for expense and revenue accounts
    const actuals = await sql`
      SELECT
        ga.id, ga.account_code, ga.account_name, ga.account_type,
        COALESCE(SUM(
          CASE
            WHEN ga.account_type = 'expense' THEN jl.debit - jl.credit
            WHEN ga.account_type = 'revenue' THEN jl.credit - jl.debit
            ELSE jl.debit - jl.credit
          END
        ), 0)::numeric as actual_amount
      FROM gl_accounts ga
      LEFT JOIN gl_journal_lines jl ON jl.gl_account_id = ga.id
      LEFT JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
        AND je.status = 'posted'
        AND je.entry_date >= ${startDate}
        AND je.entry_date <= ${endDate}
      WHERE ga.level = 3
        AND ga.is_active = true
        AND ga.account_type IN ('expense', 'revenue')
      GROUP BY ga.id, ga.account_code, ga.account_name, ga.account_type
      ORDER BY ga.account_code
    `;

    const lines = actuals.map(a => {
      const budgetAmount = Number(budgets[a.account_code] || budgets[a.id] || 0);
      const actualAmount = Number(a.actual_amount);
      // Revenue: positive variance = good (actual > budget)
      // Expense: positive variance = good (actual < budget, i.e. under budget)
      const variance = a.account_type === 'revenue'
        ? actualAmount - budgetAmount
        : budgetAmount - actualAmount;
      const variancePct = budgetAmount > 0
        ? (variance / budgetAmount) * 100
        : actualAmount > 0 ? -100 : 0;

      return {
        account_code: a.account_code,
        account_name: a.account_name,
        account_type: a.account_type,
        budget_amount: budgetAmount,
        actual_amount: actualAmount,
        variance,
        variance_pct: variancePct,
      };
    });

    const report = {
      period: `${startDate} to ${endDate}`,
      lines,
      total_budget: lines.reduce((s, l) => s + l.budget_amount, 0),
      total_actual: lines.reduce((s, l) => s + l.actual_amount, 0),
      total_variance: lines.reduce((s, l) => s + l.variance, 0),
    };

    return apiResponse.success(res, { report });
  } catch (err) {
    log.error('Failed to generate budget vs actual report', { error: err, module: 'accounting' });
    return apiResponse.databaseError(res, err, 'Failed to generate budget vs actual report');
  }
}

export default withAuth(withErrorHandler(handler));
/**
 * Cash Flow Statement API
 * GET /api/accounting/reports-cash-flow?start_date=&end_date=
 * Sage equivalent: Reports > Cash Flow Statement
 *
 * Derives cash flow from GL journal lines using account subtypes:
 * - Operating: revenue, expense, receivable, payable changes
 * - Investing: asset account changes (non-cash)
 * - Financing: equity and loan changes
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { createLoggedSql } from '@/lib/db-logger';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';

const sql = createLoggedSql(process.env.DATABASE_URL!);

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
  }

  try {
    const { start_date, end_date } = req.query;

    const startDate = (start_date as string) || new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0];
    const endDate = (end_date as string) || new Date().toISOString().split('T')[0];

    // Check if account_subtype column exists (may not be populated)
    let hasSubtype = false;
    try {
      await sql`SELECT account_subtype FROM gl_accounts LIMIT 1`;
      hasSubtype = true;
    } catch {
      // Column doesn't exist
    }

    // Get opening cash balance (bank accounts at start_date)
    let openingBalance = 0;
    try {
      if (hasSubtype) {
        const [openingCash] = await sql`
          SELECT COALESCE(SUM(
            CASE WHEN ga.normal_balance = 'debit' THEN jl.debit - jl.credit ELSE jl.credit - jl.debit END
          ), 0)::numeric as balance
          FROM gl_journal_lines jl
          JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
          JOIN gl_accounts ga ON ga.id = jl.gl_account_id
          WHERE ga.account_subtype = 'bank'
            AND je.status = 'posted'
            AND je.entry_date < ${startDate}
        `;
        openingBalance = Number(openingCash?.balance || 0);
      } else {
        // Fall back to account_name matching for bank accounts
        const [openingCash] = await sql`
          SELECT COALESCE(SUM(
            CASE WHEN ga.normal_balance = 'debit' THEN jl.debit - jl.credit ELSE jl.credit - jl.debit END
          ), 0)::numeric as balance
          FROM gl_journal_lines jl
          JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
          JOIN gl_accounts ga ON ga.id = jl.gl_account_id
          WHERE (ga.account_name ILIKE '%bank%' OR ga.account_code LIKE '11%')
            AND ga.account_type = 'asset'
            AND je.status = 'posted'
            AND je.entry_date < ${startDate}
        `;
        openingBalance = Number(openingCash?.balance || 0);
      }
    } catch {
      openingBalance = 0;
    }

    // Operating Activities: Net Income + changes in working capital
    const [netIncome] = await sql`
      SELECT
        COALESCE(SUM(CASE WHEN ga.account_type = 'revenue' THEN jl.credit - jl.debit ELSE 0 END), 0)::numeric
        - COALESCE(SUM(CASE WHEN ga.account_type = 'expense' THEN jl.debit - jl.credit ELSE 0 END), 0)::numeric
        as net_income
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      JOIN gl_accounts ga ON ga.id = jl.gl_account_id
      WHERE je.status = 'posted'
        AND je.entry_date >= ${startDate}
        AND je.entry_date <= ${endDate}
        AND ga.account_type IN ('revenue', 'expense')
    `;

    // Changes in AR (receivable) — use subtype or fallback to account name
    let arChangeVal = 0;
    try {
      if (hasSubtype) {
        const [arChange] = await sql`
          SELECT COALESCE(SUM(jl.credit - jl.debit), 0)::numeric as change
          FROM gl_journal_lines jl
          JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
          JOIN gl_accounts ga ON ga.id = jl.gl_account_id
          WHERE ga.account_subtype = 'receivable'
            AND je.status = 'posted'
            AND je.entry_date >= ${startDate}
            AND je.entry_date <= ${endDate}
        `;
        arChangeVal = Number(arChange?.change || 0);
      } else {
        const [arChange] = await sql`
          SELECT COALESCE(SUM(jl.credit - jl.debit), 0)::numeric as change
          FROM gl_journal_lines jl
          JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
          JOIN gl_accounts ga ON ga.id = jl.gl_account_id
          WHERE ga.account_name ILIKE '%receivable%'
            AND je.status = 'posted'
            AND je.entry_date >= ${startDate}
            AND je.entry_date <= ${endDate}
        `;
        arChangeVal = Number(arChange?.change || 0);
      }
    } catch { arChangeVal = 0; }

    // Changes in AP (payable)
    let apChangeVal = 0;
    try {
      if (hasSubtype) {
        const [apChange] = await sql`
          SELECT COALESCE(SUM(jl.credit - jl.debit), 0)::numeric as change
          FROM gl_journal_lines jl
          JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
          JOIN gl_accounts ga ON ga.id = jl.gl_account_id
          WHERE ga.account_subtype = 'payable'
            AND je.status = 'posted'
            AND je.entry_date >= ${startDate}
            AND je.entry_date <= ${endDate}
        `;
        apChangeVal = Number(apChange?.change || 0);
      } else {
        const [apChange] = await sql`
          SELECT COALESCE(SUM(jl.credit - jl.debit), 0)::numeric as change
          FROM gl_journal_lines jl
          JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
          JOIN gl_accounts ga ON ga.id = jl.gl_account_id
          WHERE ga.account_name ILIKE '%payable%'
            AND je.status = 'posted'
            AND je.entry_date >= ${startDate}
            AND je.entry_date <= ${endDate}
        `;
        apChangeVal = Number(apChange?.change || 0);
      }
    } catch { apChangeVal = 0; }

    // Investing: fixed asset changes
    let investingChangeVal = 0;
    try {
      if (hasSubtype) {
        const [investingChange] = await sql`
          SELECT COALESCE(SUM(jl.credit - jl.debit), 0)::numeric as change
          FROM gl_journal_lines jl
          JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
          JOIN gl_accounts ga ON ga.id = jl.gl_account_id
          WHERE ga.account_subtype IN ('fixed_asset', 'other_asset')
            AND je.status = 'posted'
            AND je.entry_date >= ${startDate}
            AND je.entry_date <= ${endDate}
        `;
        investingChangeVal = Number(investingChange?.change || 0);
      } else {
        const [investingChange] = await sql`
          SELECT COALESCE(SUM(jl.credit - jl.debit), 0)::numeric as change
          FROM gl_journal_lines jl
          JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
          JOIN gl_accounts ga ON ga.id = jl.gl_account_id
          WHERE ga.account_type = 'asset'
            AND ga.account_name NOT ILIKE '%bank%'
            AND ga.account_name NOT ILIKE '%receivable%'
            AND ga.account_name NOT ILIKE '%cash%'
            AND je.status = 'posted'
            AND je.entry_date >= ${startDate}
            AND je.entry_date <= ${endDate}
        `;
        investingChangeVal = Number(investingChange?.change || 0);
      }
    } catch { investingChangeVal = 0; }

    // Financing: equity + loan changes
    let financingChangeVal = 0;
    try {
      if (hasSubtype) {
        const [financingChange] = await sql`
          SELECT COALESCE(SUM(jl.credit - jl.debit), 0)::numeric as change
          FROM gl_journal_lines jl
          JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
          JOIN gl_accounts ga ON ga.id = jl.gl_account_id
          WHERE ga.account_type = 'equity'
            AND (ga.account_subtype IS NULL OR ga.account_subtype != 'retained_earnings')
            AND je.status = 'posted'
            AND je.entry_date >= ${startDate}
            AND je.entry_date <= ${endDate}
        `;
        financingChangeVal = Number(financingChange?.change || 0);
      } else {
        const [financingChange] = await sql`
          SELECT COALESCE(SUM(jl.credit - jl.debit), 0)::numeric as change
          FROM gl_journal_lines jl
          JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
          JOIN gl_accounts ga ON ga.id = jl.gl_account_id
          WHERE ga.account_type = 'equity'
            AND ga.account_name NOT ILIKE '%retained%'
            AND je.status = 'posted'
            AND je.entry_date >= ${startDate}
            AND je.entry_date <= ${endDate}
        `;
        financingChangeVal = Number(financingChange?.change || 0);
      }
    } catch { financingChangeVal = 0; }

    const operatingTotal = Number(netIncome?.net_income || 0) + arChangeVal + apChangeVal;
    const investingTotal = investingChangeVal;
    const financingTotal = financingChangeVal;
    const netChange = operatingTotal + investingTotal + financingTotal;

    const report = {
      period_start: startDate,
      period_end: endDate,
      opening_cash: openingBalance,
      sections: [
        {
          section: 'Operating Activities',
          items: [
            { label: 'Net Income', amount: Number(netIncome?.net_income || 0) },
            { label: 'Change in Accounts Receivable', amount: arChangeVal },
            { label: 'Change in Accounts Payable', amount: apChangeVal },
          ],
          total: operatingTotal,
        },
        {
          section: 'Investing Activities',
          items: [
            { label: 'Fixed Asset Changes', amount: investingChangeVal },
          ],
          total: investingTotal,
        },
        {
          section: 'Financing Activities',
          items: [
            { label: 'Equity Changes', amount: financingChangeVal },
          ],
          total: financingTotal,
        },
      ],
      net_change: netChange,
      closing_cash: openingBalance + netChange,
    };

    return apiResponse.success(res, { report });
  } catch (err) {
    log.error('Failed to generate cash flow statement', { error: err, module: 'accounting' });
    return apiResponse.databaseError(res, err, 'Failed to generate cash flow statement');
  }
}

