        row.priorDebitBalance = prior?.debitBalance ?? 0;
        row.priorCreditBalance = prior?.creditBalance ?? 0;
      }
    }

    return apiResponse.success(res, {
      fiscalPeriodId,
      comparePeriodId,
      rows,
      totalDebit,
      totalCredit,
    });
  } catch (err) {
