                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Customer Credit Notes</h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">
                  {total} credit note{total !== 1 ? 's' : ''} recorded
