import { NextApiRequest, NextApiResponse } from 'next';
import { log } from '@/lib/logger';

/**
 * Standard API Response Types
 */
export interface ApiSuccessResponse<T = any> {
  success: true;
  data: T;
  message?: string;
  meta?: {
    timestamp?: string;
    requestId?: string;
    [key: string]: any;
  };
}

export interface ApiErrorResponse {
  success: false;
  error: {
    code: string;
    message: string;
    details?: any;
  };
  meta?: {
    timestamp?: string;
    requestId?: string;
    [key: string]: any;
  };
}

export interface ApiPaginatedResponse<T = any> extends ApiSuccessResponse<T[]> {
  pagination: {
    page: number;
    pageSize: number;
    total: number;
    totalPages: number;
  };
}

export type ApiResponse<T = any> = ApiSuccessResponse<T> | ApiErrorResponse;

/**
 * Standard error codes
 */
export enum ErrorCode {
  // Client errors (400-499)
  BAD_REQUEST = 'BAD_REQUEST',
  UNAUTHORIZED = 'UNAUTHORIZED',
  FORBIDDEN = 'FORBIDDEN',
  NOT_FOUND = 'NOT_FOUND',
  METHOD_NOT_ALLOWED = 'METHOD_NOT_ALLOWED',
  CONFLICT = 'CONFLICT',
  VALIDATION_ERROR = 'VALIDATION_ERROR',
  RATE_LIMIT = 'RATE_LIMIT',
  PAYLOAD_TOO_LARGE = 'PAYLOAD_TOO_LARGE',

  // Server errors (500-599)
  INTERNAL_ERROR = 'INTERNAL_ERROR',
  DATABASE_ERROR = 'DATABASE_ERROR',
  SERVICE_UNAVAILABLE = 'SERVICE_UNAVAILABLE',
  GATEWAY_TIMEOUT = 'GATEWAY_TIMEOUT',

  // Business logic errors
  BUSINESS_RULE_VIOLATION = 'BUSINESS_RULE_VIOLATION',
  INSUFFICIENT_PERMISSIONS = 'INSUFFICIENT_PERMISSIONS',
  RESOURCE_LOCKED = 'RESOURCE_LOCKED',
  DEPENDENCY_ERROR = 'DEPENDENCY_ERROR',
}

/**
 * HTTP status code mapping
 */
const STATUS_CODE_MAP: Record<ErrorCode, number> = {
  // Client errors
  [ErrorCode.BAD_REQUEST]: 400,
  [ErrorCode.UNAUTHORIZED]: 401,
  [ErrorCode.FORBIDDEN]: 403,
  [ErrorCode.NOT_FOUND]: 404,
  [ErrorCode.METHOD_NOT_ALLOWED]: 405,
  [ErrorCode.CONFLICT]: 409,
  [ErrorCode.VALIDATION_ERROR]: 422,
  [ErrorCode.RATE_LIMIT]: 429,
  [ErrorCode.PAYLOAD_TOO_LARGE]: 413,

  // Server errors
  [ErrorCode.INTERNAL_ERROR]: 500,
  [ErrorCode.DATABASE_ERROR]: 500,
  [ErrorCode.SERVICE_UNAVAILABLE]: 503,
  [ErrorCode.GATEWAY_TIMEOUT]: 504,

  // Business logic errors (usually 400 or 422)
  [ErrorCode.BUSINESS_RULE_VIOLATION]: 422,
  [ErrorCode.INSUFFICIENT_PERMISSIONS]: 403,
  [ErrorCode.RESOURCE_LOCKED]: 423,
  [ErrorCode.DEPENDENCY_ERROR]: 424,
};

/**
 * API Response Helper Class
 */
export class ApiResponseHelper {
  private static generateMeta(additionalMeta?: Record<string, any>) {
    return {
      timestamp: new Date().toISOString(),
      ...additionalMeta,
    };
  }

  /**
   * Send success response
   */
  static success<T>(
    res: NextApiResponse,
    data: T,
    message?: string,
    statusCode = 200,
    meta?: Record<string, any>
  ): void {
    const response: ApiSuccessResponse<T> = {
      success: true,
      data,
      ...(message && { message }),
      meta: this.generateMeta(meta),
    };

    res.status(statusCode).json(response);
  }

  /**
   * Send created response (201)
   */
  static created<T>(
    res: NextApiResponse,
    data: T,
    message = 'Resource created successfully',
    meta?: Record<string, any>
  ): void {
    this.success(res, data, message, 201, meta);
  }

  /**
   * Send no content response (204)
   */
  static noContent(res: NextApiResponse): void {
    res.status(204).end();
  }

  /**
   * Send paginated response
   */
  static paginated<T>(
    res: NextApiResponse,
    data: T[],
    pagination: {
      page: number;
      pageSize: number;
      total: number;
    },
    message?: string,
    meta?: Record<string, any>
  ): void {
    const totalPages = Math.ceil(pagination.total / pagination.pageSize);

    const response: ApiPaginatedResponse<T> = {
      success: true,
      data,
      pagination: {
        ...pagination,
        totalPages,
      },
      ...(message && { message }),
      meta: this.generateMeta(meta),
    };

    res.status(200).json(response);
  }

  /**
   * Send error response
   */
  static error(
    res: NextApiResponse,
    code: ErrorCode,
    message: string,
    details?: any,
    meta?: Record<string, any>
  ): void {
    const statusCode = STATUS_CODE_MAP[code] || 500;

    const response: ApiErrorResponse = {
      success: false,
      error: {
        code,
        message,
        ...(details && { details }),
      },
      meta: this.generateMeta(meta),
    };

    res.status(statusCode).json(response);
  }

  /**
   * Send bad request error response (400)
   */
  static badRequest(
    res: NextApiResponse,
    message: string,
    details?: any
  ): void {
    this.error(res, ErrorCode.BAD_REQUEST, message, details);
  }

  /**
   * Send validation error response
   */
  static validationError(
    res: NextApiResponse,
    errors: Record<string, string | string[]>,
    message = 'Validation failed'
  ): void {
    this.error(res, ErrorCode.VALIDATION_ERROR, message, errors);
  }

  /**
   * Send not found error response
   */
  static notFound(
    res: NextApiResponse,
    resource: string,
    identifier?: string | number
  ): void {
    const message = identifier
      ? `${resource} with identifier '${identifier}' not found`
      : `${resource} not found`;

    this.error(res, ErrorCode.NOT_FOUND, message);
  }

  /**
   * Send unauthorized error response
   */
  static unauthorized(
    res: NextApiResponse,
    message = 'Authentication required'
  ): void {
    this.error(res, ErrorCode.UNAUTHORIZED, message);
  }

  /**
   * Send forbidden error response
   */
  static forbidden(
    res: NextApiResponse,
    message = 'You do not have permission to perform this action'
  ): void {
    this.error(res, ErrorCode.FORBIDDEN, message);
  }

  /**
   * Send method not allowed error response
   */
  static methodNotAllowed(
    res: NextApiResponse,
    method: string,
    allowedMethods: string[]
  ): void {
    res.setHeader('Allow', allowedMethods.join(', '));
    this.error(
      res,
      ErrorCode.METHOD_NOT_ALLOWED,
      `Method ${method} not allowed. Allowed methods: ${allowedMethods.join(', ')}`
    );
  }

  /**
   * Send internal server error response
   */
  static internalError(
    res: NextApiResponse,
    error: Error | unknown,
    message = 'An internal error occurred'
  ): void {
    // Log the actual error for debugging
    log.error('Internal Server Error', error instanceof Error ? { message: error.message, stack: error.stack } : { error }, 'ApiResponse');

    // In production, don't expose internal error details
    const isDevelopment = process.env.NODE_ENV === 'development';
    const errorDetails = isDevelopment && error instanceof Error
      ? { stack: error.stack, originalMessage: error.message }
      : undefined;

    this.error(res, ErrorCode.INTERNAL_ERROR, message, errorDetails);
  }

  /**
   * Send database error response
   */
  static databaseError(
    res: NextApiResponse,
    error: Error | unknown,
    message = 'A database error occurred'
  ): void {
    // Log the actual error for debugging
    log.error('Database Error', error instanceof Error ? { message: error.message } : { error }, 'ApiResponse');

    // In production, don't expose database error details
    const isDevelopment = process.env.NODE_ENV === 'development';
    const errorDetails = isDevelopment && error instanceof Error
      ? { originalMessage: error.message }
      : undefined;

    this.error(res, ErrorCode.DATABASE_ERROR, message, errorDetails);
  }

  /**
   * Handle CORS headers
   */
  static setCorsHeaders(
    res: NextApiResponse,
    origin = '',
    methods = ['GET', 'POST', 'PUT', 'DELETE', 'PATCH', 'OPTIONS'],
    headers = ['Content-Type', 'Authorization']
  ): void {
    const allowedOrigins = [
      'https://app.fibreflow.app',
      'https://vf.fibreflow.app',
      'https://dev.fibreflow.app',
      // Only include localhost origins in development
      ...(process.env.NODE_ENV === 'development' ? [
        'http://localhost:3004',
        'http://localhost:3005',
      ] : []),
    ];
    const safeOrigin = origin && allowedOrigins.includes(origin) ? origin : '';
    if (!safeOrigin) return;
    res.setHeader('Access-Control-Allow-Origin', safeOrigin);
    res.setHeader('Access-Control-Allow-Methods', methods.join(', '));
    res.setHeader('Access-Control-Allow-Headers', headers.join(', '));
  }

  /**
   * Handle OPTIONS request for CORS
   */
  static handleOptions(req: NextApiRequest, res: NextApiResponse): void {
    this.setCorsHeaders(res, req.headers.origin || '');
    res.status(200).end();
  }
}

/**
 * Convenience exports for common responses
 */
export const apiResponse = {
  success: ApiResponseHelper.success.bind(ApiResponseHelper),
  created: ApiResponseHelper.created.bind(ApiResponseHelper),
  noContent: ApiResponseHelper.noContent.bind(ApiResponseHelper),
  paginated: ApiResponseHelper.paginated.bind(ApiResponseHelper),
  error: ApiResponseHelper.error.bind(ApiResponseHelper),
  badRequest: ApiResponseHelper.badRequest.bind(ApiResponseHelper),
  validationError: ApiResponseHelper.validationError.bind(ApiResponseHelper),
  notFound: ApiResponseHelper.notFound.bind(ApiResponseHelper),
  unauthorized: ApiResponseHelper.unauthorized.bind(ApiResponseHelper),
  forbidden: ApiResponseHelper.forbidden.bind(ApiResponseHelper),
  methodNotAllowed: ApiResponseHelper.methodNotAllowed.bind(ApiResponseHelper),
  internalError: ApiResponseHelper.internalError.bind(ApiResponseHelper),
  databaseError: ApiResponseHelper.databaseError.bind(ApiResponseHelper),
  setCorsHeaders: ApiResponseHelper.setCorsHeaders.bind(ApiResponseHelper),
  handleOptions: ApiResponseHelper.handleOptions.bind(ApiResponseHelper),
};

export default apiResponse;

/**
 * Bank Rules Action API
 * POST — delete, toggle, or apply rules
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { deleteRule, deleteRules, toggleRule, applyRules, updateRule } from '@/modules/accounting/services/bankRulesService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') return apiResponse.methodNotAllowed(res, req.method!);

  const userId = (req as AuthenticatedNextApiRequest).user.id;
  const { action, id, ids, isActive, bankAccountId } = req.body;

  try {
    switch (action) {
      case 'delete':
        if (!id) return apiResponse.badRequest(res, 'id required');
        await deleteRule(id);
        return apiResponse.success(res, { deleted: true });

      case 'deleteMany': {
        if (!Array.isArray(ids) || ids.length === 0) return apiResponse.badRequest(res, 'ids array required');
        const count = await deleteRules(ids);
        return apiResponse.success(res, { deleted: count });
      }

      case 'toggle':
        if (!id) return apiResponse.badRequest(res, 'id required');
        await toggleRule(id, isActive !== false);
        return apiResponse.success(res, { toggled: true });

      case 'update': {
        if (!id) return apiResponse.badRequest(res, 'id required');
        const updated = await updateRule(id, req.body);
        return apiResponse.success(res, updated);
      }

      case 'apply': {
        if (!bankAccountId) return apiResponse.badRequest(res, 'bankAccountId required');
        const result = await applyRules(bankAccountId, userId);
        return apiResponse.success(res, result);
      }

      default:
        return apiResponse.badRequest(res, `Unknown action: ${action}`);
    }
  } catch (err) {
    log.error('Bank rules action failed', { action, error: err }, 'accounting-api');
    return apiResponse.badRequest(res, err instanceof Error ? err.message : 'Action failed');
  }
}

export default withAuth(withErrorHandler(handler));

/**
 * Bank Categorisation Rules API
 * GET  — list all rules
 * POST — create a new rule
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { getRules, createRule } from '@/modules/accounting/services/bankRulesService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const userId = (req as AuthenticatedNextApiRequest).user.id;

  if (req.method === 'GET') {
    const rules = await getRules();
    return apiResponse.success(res, { items: rules });
  }

  if (req.method === 'POST') {
    const { ruleName, matchField, matchType, matchPattern, glAccountId, supplierId, clientId, descriptionTemplate, priority, autoCreateEntry, vatCode } = req.body;
    if (!ruleName || !matchField || !matchType || !matchPattern) {
      return apiResponse.badRequest(res, 'ruleName, matchField, matchType, and matchPattern are required');
    }
    if (!glAccountId && !supplierId && !clientId) {
      return apiResponse.badRequest(res, 'Either glAccountId, supplierId, or clientId is required');
    }
    const rule = await createRule({
      ruleName, matchField, matchType, matchPattern, glAccountId: glAccountId || undefined,
      supplierId: supplierId || undefined,
      clientId: clientId || undefined,
      descriptionTemplate: descriptionTemplate || undefined,
      priority: priority || 100,
      autoCreateEntry: autoCreateEntry !== false,
      vatCode: vatCode || 'none',
    }, userId);
    return apiResponse.success(res, rule);
  }

  return apiResponse.methodNotAllowed(res, req.method!);
}

export default withAuth(withErrorHandler(handler));

/**
 * Budget Action API
 * POST — delete budget or copy budgets between years
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { deleteBudget, copyBudgets } from '@/modules/accounting/services/budgetService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') return apiResponse.methodNotAllowed(res, req.method!);

  const userId = (req as AuthenticatedNextApiRequest).user.id;
  const { action, id, fromYear, toYear } = req.body;

  try {
    switch (action) {
      case 'delete':
        if (!id) return apiResponse.badRequest(res, 'id required');
        await deleteBudget(id);
        return apiResponse.success(res, { deleted: true });
      case 'copy':
        if (!fromYear || !toYear) return apiResponse.badRequest(res, 'fromYear and toYear required');
        const count = await copyBudgets(Number(fromYear), Number(toYear), userId);
        return apiResponse.success(res, { copied: count });
      default:
        return apiResponse.badRequest(res, `Unknown action: ${action}`);
    }
  } catch (err) {
    log.error('Budget action failed', { action, error: err }, 'accounting-api');
    return apiResponse.badRequest(res, err instanceof Error ? err.message : 'Action failed');
  }
}

export default withAuth(withErrorHandler(handler));

/**
 * Budget Management API
 * GET  — list budgets for a fiscal year
 * POST — upsert a budget entry
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { getBudgets, upsertBudget } from '@/modules/accounting/services/budgetService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const userId = (req as AuthenticatedNextApiRequest).user.id;

  if (req.method === 'GET') {
    const fiscalYear = Number(req.query.fiscal_year) || new Date().getFullYear();
    const items = await getBudgets(fiscalYear);
    return apiResponse.success(res, { items, fiscalYear });
  }

  if (req.method === 'POST') {
    const { glAccountId, fiscalYear, annualAmount, months, notes } = req.body;
    if (!glAccountId || !fiscalYear || annualAmount == null) {
      return apiResponse.badRequest(res, 'glAccountId, fiscalYear, and annualAmount are required');
    }
    try {
      const entry = await upsertBudget({
        glAccountId, fiscalYear: Number(fiscalYear),
        annualAmount: Number(annualAmount),
        months: months || undefined, notes,
      }, userId);
      return apiResponse.success(res, entry);
    } catch (err) {
      log.error('Failed to upsert budget', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, err instanceof Error ? err.message : 'Failed');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method!);
}

export default withAuth(withErrorHandler(handler));

/**
 * DRC (Domestic Reverse Charge) VAT API
 * GET  — list eligible invoices and DRC history
 * POST — apply DRC VAT to a supplier invoice
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  getDRCEligibleInvoices, getDRCHistory, applyDRCVat,
} from '@/modules/accounting/services/drcVatService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const userId = (req as AuthenticatedNextApiRequest).user.id;

  if (req.method === 'GET') {
    const tab = req.query.tab as string;
    if (tab === 'history') {
      const items = await getDRCHistory();
      return apiResponse.success(res, { items });
    }
    const items = await getDRCEligibleInvoices();
    return apiResponse.success(res, { items });
  }

  if (req.method === 'POST') {
    const { supplierInvoiceId } = req.body;
    if (!supplierInvoiceId) return apiResponse.badRequest(res, 'supplierInvoiceId required');
    try {
      const result = await applyDRCVat(supplierInvoiceId, userId);
      return apiResponse.success(res, result);
    } catch (err) {
      log.error('Failed to apply DRC VAT', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, err instanceof Error ? err.message : 'Failed');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method!);
}

export default withAuth(withErrorHandler(handler));

/**
 * Trial Balance Export API
 * GET — export trial balance as CSV
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import { getTrialBalance } from '@/modules/accounting/services/journalEntryService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method!);

  const fiscalPeriodId = req.query.fiscal_period_id as string;
  if (!fiscalPeriodId) return apiResponse.badRequest(res, 'fiscal_period_id is required');

  try {
    const rows = await getTrialBalance(fiscalPeriodId);
    const totalDebit = rows.reduce((s, r) => s + r.debitBalance, 0);
    const totalCredit = rows.reduce((s, r) => s + r.creditBalance, 0);

    const csvLines = [
      'Account Code,Account Name,Account Type,Normal Balance,Debit,Credit',
      ...rows.map(r =>
        `"${r.accountCode}","${r.accountName}","${r.accountType}","${r.normalBalance}",${r.debitBalance.toFixed(2)},${r.creditBalance.toFixed(2)}`
      ),
      `"","TOTALS","","",${totalDebit.toFixed(2)},${totalCredit.toFixed(2)}`,
    ];

    const csv = csvLines.join('\n');
    const filename = `trial-balance-${new Date().toISOString().split('T')[0]}.csv`;

    res.setHeader('Content-Type', 'text/csv');
    res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);
    return res.status(200).send(csv);
  } catch (err) {
    log.error('Failed to export trial balance', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, 'Failed to export trial balance');
  }
}

export default withAuth(withErrorHandler(handler));

/**
 * Customer Invoice Create API (standalone, not project-linked)
 * POST — create invoice with line items
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);

  const { clientId, invoiceDate, dueDate, billingPeriodStart, billingPeriodEnd, taxRate, notes, items } = req.body;
  if (!clientId) return apiResponse.badRequest(res, 'clientId is required');
  if (!items || !Array.isArray(items) || items.length === 0) return apiResponse.badRequest(res, 'items required');

  const userId = (req as unknown as { user?: { id: string } }).user?.id || 'system';

  // Auto-generate invoice number
  const maxRows = (await sql`
    SELECT invoice_number FROM customer_invoices ORDER BY created_at DESC LIMIT 1
  `) as Row[];
  let nextNum = 1;
  if (maxRows.length > 0) {
    const match = maxRows[0].invoice_number?.match(/(\d+)$/);
    if (match) nextNum = parseInt(match[1], 10) + 1;
  }
  const invoiceNumber = `INV-${String(nextNum).padStart(5, '0')}`;

  // Calculate totals
  const rate = taxRate ?? 15;
  let subtotal = 0;
  for (const item of items) {
    subtotal += (item.quantity || 1) * item.unitPrice;
  }
  subtotal = Math.round(subtotal * 100) / 100;
  const taxAmount = Math.round(subtotal * (rate / 100) * 100) / 100;
  const totalAmount = subtotal + taxAmount;

  const today = new Date().toISOString().split('T')[0];
  const invDate = invoiceDate || today;
  const bpStart = billingPeriodStart || invDate;
  const bpEnd = billingPeriodEnd || invDate;

  // Find project from client (use first project if exists)
  const projRows = (await sql`
    SELECT id FROM projects WHERE client_id = ${clientId}::UUID LIMIT 1
  `) as Row[];
  const projectId = projRows[0]?.id || clientId;

  const invRows = (await sql`
    INSERT INTO customer_invoices (
      invoice_number, project_id, client_id, billing_period_start, billing_period_end,
      subtotal, tax_rate, tax_amount, total_amount, invoice_date, due_date,
      notes, status, created_by
    ) VALUES (
      ${invoiceNumber}, ${projectId}::UUID, ${clientId}::UUID, ${bpStart}, ${bpEnd},
      ${subtotal}, ${rate}, ${taxAmount}, ${totalAmount}, ${invDate},
      ${dueDate || null}, ${notes || null}, 'draft', ${userId}
    ) RETURNING id
  `) as Row[];

  const invoiceId = invRows[0].id;

  for (const item of items) {
    const lineTotal = Math.round((item.quantity || 1) * item.unitPrice * 100) / 100;
    const lineTax = Math.round(lineTotal * (rate / 100) * 100) / 100;
    await sql`
      INSERT INTO customer_invoice_items (invoice_id, drop_number, description, unit_price, quantity, tax_amount, line_total, income_type)
      VALUES (${invoiceId}::UUID, ${item.dropNumber || 'MANUAL'}, ${item.description}, ${item.unitPrice},
        ${item.quantity || 1}, ${lineTax}, ${lineTotal}, ${item.incomeType || 'other'})
    `;
  }

  log.info('Customer invoice created', { invoiceNumber, totalAmount });
  return apiResponse.created(res, { id: invoiceId, invoiceNumber });
}

export default withAuth(withErrorHandler(handler));

