import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';

const sql = neon(process.env.DATABASE_URL!);

export default withAuth(async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method!, ['GET']);

  try {
    const from = (req.query.from as string) || new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0];
    const to = (req.query.to as string) || new Date().toISOString().split('T')[0];
    const format = req.query.format as string;

    const rows = await sql`
      SELECT
        cii.description AS name,
        cii.income_type AS category,
        COUNT(cii.id)::int AS times_sold,
        COALESCE(SUM(cii.quantity), 0)::numeric AS qty_sold,
        COALESCE(SUM(cii.line_total), 0)::numeric AS total_revenue
      FROM customer_invoice_items cii
      JOIN customer_invoices ci ON ci.id = cii.invoice_id
      WHERE ci.invoice_date >= ${from}
        AND ci.invoice_date <= ${to}
        AND ci.status != 'cancelled'
      GROUP BY cii.description, cii.income_type
      ORDER BY total_revenue DESC
    `;

    const data = rows.map(r => ({
      id: '',
      itemCode: '',
      name: r.name || 'Unnamed',
      category: r.category || '',
      timesSold: Number(r.times_sold),
      qtySold: Number(r.qty_sold),
      totalRevenue: Number(r.total_revenue),
      avgPrice: Number(r.qty_sold) > 0 ? Number(r.total_revenue) / Number(r.qty_sold) : 0,
    }));

    if (format === 'csv') {
      const header = 'Item Code,Name,Category,Times Sold,Qty Sold,Total Revenue,Avg Price';
      const csvRows = data.map(r =>
        `"${r.itemCode}","${r.name}","${r.category}",${r.timesSold},${r.qtySold},${r.totalRevenue.toFixed(2)},${r.avgPrice.toFixed(2)}`
      );
      res.setHeader('Content-Type', 'text/csv');
      res.setHeader('Content-Disposition', `attachment; filename="sales-by-item-${from}-${to}.csv"`);
      return res.send([header, ...csvRows].join('\n'));
    }

    return apiResponse.success(res, data);
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : String(err);
    log.error('Sales by item report error', { error: message });
    return apiResponse.badRequest(res, 'Failed to generate report');
  }
});

/**
 * Supplier Payment Allocations API
 * GET  — List existing allocations (audit trail)
 * POST — Allocate payments against outstanding supplier invoices
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';

const sql = neon(process.env.DATABASE_URL!);

interface AllocationItem {
  invoiceId: string;
  amount: number;
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method === 'GET') {
    try {
      const paymentId = req.query.payment_id as string | undefined;
      const supplierId = req.query.supplier_id as string | undefined;

      let rows;
      if (paymentId) {
        rows = await sql`
          SELECT spa.id, spa.payment_id, spa.invoice_id, spa.amount_allocated AS amount,
            spa.created_at AS allocated_at, sp.payment_number, si.invoice_number,
            s.company_name AS supplier_name
          FROM supplier_payment_allocations spa
          JOIN supplier_payments sp ON sp.id = spa.payment_id
          JOIN supplier_invoices si ON si.id = spa.invoice_id
          JOIN suppliers s ON s.id = sp.supplier_id
          WHERE spa.payment_id = ${paymentId}
          ORDER BY spa.created_at DESC
        `;
      } else if (supplierId) {
        rows = await sql`
          SELECT spa.id, spa.payment_id, spa.invoice_id, spa.amount_allocated AS amount,
            spa.created_at AS allocated_at, sp.payment_number, si.invoice_number,
            s.company_name AS supplier_name
          FROM supplier_payment_allocations spa
          JOIN supplier_payments sp ON sp.id = spa.payment_id
          JOIN supplier_invoices si ON si.id = spa.invoice_id
          JOIN suppliers s ON s.id = sp.supplier_id
          WHERE sp.supplier_id = ${supplierId}
          ORDER BY spa.created_at DESC
          LIMIT 200
        `;
      } else {
        rows = await sql`
          SELECT spa.id, spa.payment_id, spa.invoice_id, spa.amount_allocated AS amount,
            spa.created_at AS allocated_at, sp.payment_number, si.invoice_number,
            s.company_name AS supplier_name
          FROM supplier_payment_allocations spa
          JOIN supplier_payments sp ON sp.id = spa.payment_id
          JOIN supplier_invoices si ON si.id = spa.invoice_id
          JOIN suppliers s ON s.id = sp.supplier_id
          ORDER BY spa.created_at DESC
          LIMIT 200
        `;
      }

      return apiResponse.success(res, rows);
    } catch (err) {
      log.error('Failed to get supplier allocations', { error: err });
      return apiResponse.badRequest(res, 'Failed to get allocations');
    }
  }

  if (req.method === 'POST') {
    try {
      const { paymentId, allocations } = req.body as {
        paymentId?: string;
        allocations?: AllocationItem[];
      };

      if (!paymentId) return apiResponse.badRequest(res, 'paymentId is required');
      if (!allocations || !Array.isArray(allocations) || allocations.length === 0) {
        return apiResponse.badRequest(res, 'allocations array is required');
      }

      for (const alloc of allocations) {
        if (!alloc.invoiceId || !alloc.amount || alloc.amount <= 0) {
          return apiResponse.badRequest(res, 'Each allocation needs invoiceId and positive amount');
        }
      }

      const paymentRows = await sql`
        SELECT sp.id, sp.supplier_id, sp.total_amount, sp.status,
          COALESCE((SELECT SUM(amount_allocated) FROM supplier_payment_allocations WHERE payment_id = sp.id), 0) AS allocated_amount
        FROM supplier_payments sp WHERE sp.id = ${paymentId}
      `;
      const payment = paymentRows[0];
      if (!payment) return apiResponse.notFound(res, 'Payment', paymentId);
      if (payment.status === 'cancelled') {
        return apiResponse.badRequest(res, 'Cannot allocate a cancelled payment');
      }

      const currentAllocated = Number(payment.allocated_amount || 0);
      const totalPayment = Number(payment.total_amount);
      const allocTotal = allocations.reduce((s, a) => s + a.amount, 0);

      if (currentAllocated + allocTotal > totalPayment + 0.01) {
        return apiResponse.badRequest(res, `Allocation total (${allocTotal}) exceeds available balance (${(totalPayment - currentAllocated).toFixed(2)})`);
      }

      const results: { invoiceId: string; amount: number; newStatus: string }[] = [];

      for (const alloc of allocations) {
        const invoiceRows = await sql`
          SELECT id, supplier_id, total_amount, amount_paid, status
          FROM supplier_invoices WHERE id = ${alloc.invoiceId}
        `;
        const invoice = invoiceRows[0];
        if (!invoice) {
          return apiResponse.badRequest(res, `Invoice ${alloc.invoiceId} not found`);
        }
        if (invoice.supplier_id !== payment.supplier_id) {
          return apiResponse.badRequest(res, `Invoice ${alloc.invoiceId} belongs to a different supplier`);
        }

        const outstanding = Number(invoice.total_amount) - Number(invoice.amount_paid || 0);
        if (alloc.amount > outstanding + 0.01) {
          return apiResponse.badRequest(res, `Allocation ${alloc.amount} exceeds outstanding ${outstanding.toFixed(2)} for invoice ${alloc.invoiceId}`);
        }

        await sql`
          INSERT INTO supplier_payment_allocations (payment_id, invoice_id, amount_allocated)
          VALUES (${paymentId}, ${alloc.invoiceId}, ${alloc.amount})
        `;

        const newPaid = Number(invoice.amount_paid || 0) + alloc.amount;
        const invoiceTotal = Number(invoice.total_amount);
        const newStatus = newPaid >= invoiceTotal - 0.01 ? 'paid' : 'partially_paid';

        await sql`
          UPDATE supplier_invoices
          SET amount_paid = ${newPaid}, status = ${newStatus}
          WHERE id = ${alloc.invoiceId}
        `;

        results.push({ invoiceId: alloc.invoiceId, amount: alloc.amount, newStatus });
      }

      const newAllocated = currentAllocated + allocTotal;
      const paymentStatus = newAllocated >= totalPayment - 0.01 ? 'reconciled' : 'approved';

      await sql`
        UPDATE supplier_payments
        SET status = ${paymentStatus}
        WHERE id = ${paymentId}
      `;

      log.info('Supplier allocations created', {
        paymentId,
        count: results.length,
        total: allocTotal,
      });

      return apiResponse.success(res, {
        paymentId,
        allocations: results,
        newAllocatedAmount: newAllocated,
        paymentStatus,
      });
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Allocation failed';
      log.error('Supplier allocation failed', { error: err });
      return apiResponse.badRequest(res, message);
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

export default withAuth(handler);

/**
 * Supplier Categories API
 * GET: List categories with supplier count
 * POST: Create category
 * PUT: Update category
 * DELETE: Remove category
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { sql } from '@/lib/neon';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = Record<string, any>;

export default withAuth(async function handler(req: NextApiRequest, res: NextApiResponse) {

  try {
    if (req.method === 'GET') {
      const rows = (await sql`
        SELECT sc.id, sc.name, sc.description, sc.created_at,
               COUNT(s.id)::int AS supplier_count
        FROM supplier_categories sc
        LEFT JOIN suppliers s ON LOWER(s.category) = LOWER(sc.name)
        GROUP BY sc.id
        ORDER BY sc.name
      `) as Row[];
      return apiResponse.success(res, rows.map((r: Row) => ({
        id: r.id, name: r.name, description: r.description || '',
        supplierCount: Number(r.supplier_count) || 0,
      })));
    }

    if (req.method === 'POST') {
      const { name, description } = req.body;
      if (!name?.trim()) return apiResponse.badRequest(res, 'Name is required');
      const rows = (await sql`
        INSERT INTO supplier_categories (name, description)
        VALUES (${name.trim()}, ${description || ''})
        RETURNING id, name, description
      `) as Row[];
      return apiResponse.success(res, rows[0]);
    }

    if (req.method === 'PUT') {
      const { id, name, description } = req.body;
      if (!id || !name?.trim()) return apiResponse.badRequest(res, 'ID and name are required');
      await sql`
        UPDATE supplier_categories
        SET name = ${name.trim()}, description = ${description || ''}
        WHERE id = ${id}
      `;
      return apiResponse.success(res, { id, name, description });
    }

    if (req.method === 'DELETE') {
      const { id } = req.body;
      if (!id) return apiResponse.badRequest(res, 'ID is required');
      await sql`DELETE FROM supplier_categories WHERE id = ${id}`;
      return apiResponse.success(res, { deleted: true });
    }

    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST', 'PUT', 'DELETE']);
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : String(err);
    if (message.includes('does not exist')) {
      return apiResponse.success(res, []);
    }
    log.error('supplier-categories API error', { error: message });
    return apiResponse.internalError(res, err, 'Failed to process request');
  }
});

/**
 * VAT Adjustments Export API
 * GET — export VAT adjustments as CSV
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { neon } from '@neondatabase/serverless';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth } from '@/lib/auth';
import { log } from '@/lib/logger';

const sql = neon(process.env.DATABASE_URL!);

function csvCell(v: string): string { return `"${String(v || '').replace(/"/g, '""')}"`; }

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);

  try {
    const rows = await sql`
      SELECT adjustment_number, adjustment_date, vat_period,
        adjustment_type, amount, reason, status
      FROM vat_adjustments ORDER BY adjustment_date DESC
    `;

    const csvLines = [
      'Adjustment No,Date,VAT Period,Type,Amount,Reason,Status',
      ...rows.map((r: Record<string, unknown>) => [
        csvCell(String(r.adjustment_number)),
        csvCell(String(r.adjustment_date)),
        csvCell(String(r.vat_period || '')),
        csvCell(String(r.adjustment_type)),
        Number(r.amount || 0).toFixed(2),
        csvCell(String(r.reason || '')),
        csvCell(String(r.status)),
      ].join(',')),
    ];

    res.setHeader('Content-Type', 'text/csv');
    res.setHeader('Content-Disposition', `attachment; filename="vat-adjustments-${new Date().toISOString().split('T')[0]}.csv"`);
    return res.status(200).send(csvLines.join('\n'));
  } catch (err) {
    log.error('VAT adjustments export failed', { error: err });
    return apiResponse.badRequest(res, 'Failed to export VAT adjustments');
  }
}

export default withAuth(handler);

/**
