/**
 * New Journal Entry Page
 * Create a manual journal entry with balanced debit/credit lines
 */

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/router';
import Link from 'next/link';
import { AppLayout } from '@/components/layout/AppLayout';
import { log } from '@/lib/logger';
import {
  ArrowLeft,
  Plus,
  Trash2,
  Loader2,
  AlertCircle,
  CheckCircle2,
  Save,
} from 'lucide-react';
import type { GLAccount } from '@/modules/accounting/types/gl.types';

interface LineInput {
  key: string;
  accountId: string;
  description: string;
  debitAmount: string;
  creditAmount: string;
}

const emptyLine = (): LineInput => ({
  key: crypto.randomUUID(),
  accountId: '',
  description: '',
  debitAmount: '',
  creditAmount: '',
});

export default function NewJournalEntryPage() {
  const router = useRouter();
  const [accounts, setAccounts] = useState<GLAccount[]>([]);
  const [entryDate, setEntryDate] = useState(new Date().toISOString().split('T')[0]!);
  const [description, setDescription] = useState('');
  const [lines, setLines] = useState<LineInput[]>([emptyLine(), emptyLine()]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);

  useEffect(() => {
    loadAccounts();
  }, []);

  const loadAccounts = async () => {
    try {
      const res = await fetch('/api/accounting/chart-of-accounts');
      const data = await res.json();
      const list = data.data || data || [];
      // Only show leaf accounts (no children / subtype level) for journal lines
      setAccounts(list.filter((a: GLAccount) => a.isActive));
    } catch (err) {
      log.error('Failed to load accounts', { error: err }, 'accounting-ui');
    }
  };

  const addLine = useCallback(() => {
    setLines(prev => [...prev, emptyLine()]);
  }, []);

  const removeLine = useCallback((key: string) => {
    setLines(prev => prev.length > 2 ? prev.filter(l => l.key !== key) : prev);
  }, []);

  const updateLine = useCallback((key: string, field: keyof LineInput, value: string) => {
    setLines(prev => prev.map(l => {
      if (l.key !== key) return l;
      const updated = { ...l, [field]: value };
      // If user enters debit, clear credit and vice versa
      if (field === 'debitAmount' && value) updated.creditAmount = '';
      if (field === 'creditAmount' && value) updated.debitAmount = '';
      return updated;
    }));
  }, []);

  const totalDebit = lines.reduce((s, l) => s + (parseFloat(l.debitAmount) || 0), 0);
  const totalCredit = lines.reduce((s, l) => s + (parseFloat(l.creditAmount) || 0), 0);
  const isBalanced = Math.abs(totalDebit - totalCredit) < 0.01 && totalDebit > 0;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    if (!isBalanced) {
      setError('Journal entry must be balanced (total debits must equal total credits)');
      return;
    }

    const validLines = lines.filter(l => l.accountId && (parseFloat(l.debitAmount) || parseFloat(l.creditAmount)));
    if (validLines.length < 2) {
      setError('At least 2 lines with amounts are required');
      return;
    }

    setIsSubmitting(true);
    try {
      const res = await fetch('/api/accounting/journal-entries', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          entryDate,
          description,
          source: 'manual',
          createdBy: 'system',
          lines: validLines.map(l => ({
            glAccountId: l.accountId,
            description: l.description,
            debit: parseFloat(l.debitAmount) || 0,
            credit: parseFloat(l.creditAmount) || 0,
          })),
        }),
      });

      if (!res.ok) {
        const errData = await res.json();
        throw new Error(errData.message || 'Failed to create journal entry');
      }

      const data = await res.json();
      const entry = data.data || data;
      setSuccess(true);
      setTimeout(() => {
        router.push(`/accounting/journal-entries/${entry.id}`);
      }, 1000);
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Failed to create journal entry';
      setError(msg);
      log.error('Failed to create journal entry', { error: err }, 'accounting-ui');
    } finally {
      setIsSubmitting(false);
    }
  };

  const formatCurrency = (num: number) =>
    num === 0 ? '-' : `R ${num.toLocaleString('en-ZA', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <div className="flex items-center gap-3">
            <Link
              href="/accounting?tab=journal-entries"
              className="p-2 rounded-lg hover:bg-[var(--ff-bg-tertiary)] transition-colors"
            >
              <ArrowLeft className="h-5 w-5 text-[var(--ff-text-secondary)]" />
            </Link>
            <div>
              <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">New Journal Entry</h1>
              <p className="text-sm text-[var(--ff-text-secondary)]">Create a manual journal entry</p>
            </div>
          </div>
        </div>

        <div className="p-6 max-w-5xl">
          <form onSubmit={handleSubmit} className="space-y-6">
            {/* Error/Success */}
            {error && (
              <div className="bg-red-500/10 border border-red-500/30 rounded-lg p-4 flex items-start gap-3">
                <AlertCircle className="h-5 w-5 text-red-400 mt-0.5 flex-shrink-0" />
                <p className="text-sm text-red-400">{error}</p>
              </div>
            )}
            {success && (
              <div className="bg-emerald-500/10 border border-emerald-500/30 rounded-lg p-4 flex items-start gap-3">
                <CheckCircle2 className="h-5 w-5 text-emerald-400 mt-0.5 flex-shrink-0" />
                <p className="text-sm text-emerald-400">Journal entry created successfully. Redirecting...</p>
              </div>
            )}

            {/* Entry Header */}
            <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-[var(--ff-text-primary)] mb-1">
                    Entry Date <span className="text-red-400">*</span>
                  </label>
                  <input
                    type="date"
                    value={entryDate}
                    onChange={e => setEntryDate(e.target.value)}
                    required
                    className="ff-input"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-[var(--ff-text-primary)] mb-1">
                    Description
                  </label>
                  <input
                    type="text"
                    value={description}
                    onChange={e => setDescription(e.target.value)}
                    placeholder="e.g. Monthly rent accrual"
                    className="ff-input"
                  />
                </div>
              </div>
            </div>

            {/* Journal Lines */}
            <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
              <div className="px-6 py-4 border-b border-[var(--ff-border-light)] flex items-center justify-between">
                <h3 className="text-lg font-semibold text-[var(--ff-text-primary)]">Journal Lines</h3>
                <button
                  type="button"
                  onClick={addLine}
                  className="inline-flex items-center gap-1.5 px-3 py-1.5 text-sm font-medium text-emerald-600 bg-emerald-500/10 rounded-lg hover:bg-emerald-500/20 transition-colors"
                >
                  <Plus className="h-4 w-4" />
                  Add Line
                </button>
              </div>

              <div className="overflow-x-auto">
                <table className="w-full">
                  <thead>
                    <tr className="bg-[var(--ff-bg-tertiary)] border-b border-[var(--ff-border-light)]">
                      <th className="px-4 py-3 text-left text-xs font-semibold uppercase tracking-wider text-[var(--ff-text-secondary)] w-10">#</th>
                      <th className="px-4 py-3 text-left text-xs font-semibold uppercase tracking-wider text-[var(--ff-text-secondary)]">Account</th>
                      <th className="px-4 py-3 text-left text-xs font-semibold uppercase tracking-wider text-[var(--ff-text-secondary)]">Description</th>
                      <th className="px-4 py-3 text-right text-xs font-semibold uppercase tracking-wider text-[var(--ff-text-secondary)] w-36">Debit</th>
                      <th className="px-4 py-3 text-right text-xs font-semibold uppercase tracking-wider text-[var(--ff-text-secondary)] w-36">Credit</th>
                      <th className="px-4 py-3 w-10"></th>
                    </tr>
                  </thead>
                  <tbody>
                    {lines.map((line, idx) => (
                      <tr key={line.key} className="border-b border-[var(--ff-border-light)]">
                        <td className="px-4 py-2 text-sm text-[var(--ff-text-tertiary)]">{idx + 1}</td>
                        <td className="px-4 py-2">
                          <select
                            value={line.accountId}
                            onChange={e => updateLine(line.key, 'accountId', e.target.value)}
                            className="ff-select text-sm py-1.5"
                            required
                          >
                            <option value="">Select account...</option>
                            {accounts.map(a => (
                              <option key={a.id} value={a.id}>
                                {a.accountCode} - {a.accountName}
                              </option>
                            ))}
                          </select>
                        </td>
                        <td className="px-4 py-2">
                          <input
                            type="text"
                            value={line.description}
                            onChange={e => updateLine(line.key, 'description', e.target.value)}
                            placeholder="Line description"
                            className="ff-input text-sm py-1.5"
                          />
                        </td>
                        <td className="px-4 py-2">
                          <input
                            type="number"
                            value={line.debitAmount}
                            onChange={e => updateLine(line.key, 'debitAmount', e.target.value)}
                            placeholder="0.00"
                            step="0.01"
                            min="0"
                            className="ff-input text-sm py-1.5 text-right"
                          />
                        </td>
                        <td className="px-4 py-2">
                          <input
                            type="number"
                            value={line.creditAmount}
                            onChange={e => updateLine(line.key, 'creditAmount', e.target.value)}
                            placeholder="0.00"
                            step="0.01"
                            min="0"
                            className="ff-input text-sm py-1.5 text-right"
                          />
                        </td>
                        <td className="px-4 py-2">
                          <button
                            type="button"
                            onClick={() => removeLine(line.key)}
                            disabled={lines.length <= 2}
                            className="p-1.5 rounded text-[var(--ff-text-tertiary)] hover:text-red-400 hover:bg-red-500/10 transition-colors disabled:opacity-30 disabled:cursor-not-allowed"
                          >
                            <Trash2 className="h-4 w-4" />
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                  <tfoot>
                    <tr className="bg-[var(--ff-bg-tertiary)] border-t-2 border-[var(--ff-border-medium)]">
                      <td colSpan={3} className="px-4 py-3 text-sm font-semibold text-[var(--ff-text-primary)]">
                        Total
                      </td>
                      <td className="px-4 py-3 text-sm text-right font-bold text-[var(--ff-text-primary)]">
                        {formatCurrency(totalDebit)}
                      </td>
                      <td className="px-4 py-3 text-sm text-right font-bold text-[var(--ff-text-primary)]">
                        {formatCurrency(totalCredit)}
                      </td>
                      <td></td>
                    </tr>
                    <tr>
                      <td colSpan={6} className="px-4 py-2">
                        <div className={`flex items-center gap-2 text-sm ${isBalanced ? 'text-emerald-400' : totalDebit === 0 && totalCredit === 0 ? 'text-[var(--ff-text-tertiary)]' : 'text-red-400'}`}>
                          {isBalanced ? (
                            <>
                              <CheckCircle2 className="h-4 w-4" />
                              Entry is balanced
                            </>
                          ) : totalDebit === 0 && totalCredit === 0 ? (
                            'Enter debit and credit amounts'
                          ) : (
                            <>
                              <AlertCircle className="h-4 w-4" />
                              Out of balance by {formatCurrency(Math.abs(totalDebit - totalCredit))}
                            </>
                          )}
                        </div>
                      </td>
                    </tr>
                  </tfoot>
                </table>
              </div>
            </div>

            {/* Actions */}
            <div className="flex items-center justify-end gap-3">
              <Link
                href="/accounting?tab=journal-entries"
                className="px-4 py-2 text-sm font-medium text-[var(--ff-text-secondary)] bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg hover:bg-[var(--ff-bg-tertiary)] transition-colors"
              >
                Cancel
              </Link>
              <button
                type="submit"
                disabled={isSubmitting || !isBalanced}
                className="inline-flex items-center gap-2 px-6 py-2 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 transition-colors text-sm font-medium disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {isSubmitting ? (
                  <Loader2 className="h-4 w-4 animate-spin" />
                ) : (
                  <Save className="h-4 w-4" />
                )}
                Create Journal Entry
              </button>
            </div>
          </form>
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * Create Supplier Invoice Page
 * PRD-060 Phase 2: Capture invoice with line items
 */

import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import { ArrowLeft, Receipt, Plus, Trash2, Loader2 } from 'lucide-react';

interface LineItem {
  key: string;
  description: string;
  quantity: number;
  unitPrice: number;
  taxRate: number;
  glAccountId: string;
}

interface Supplier { id: number; name: string }
interface GLAccount { id: string; accountCode: string; accountName: string }

function formatCurrency(amount: number): string {
  return new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(amount);
}

export default function NewSupplierInvoicePage() {
  const router = useRouter();
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [glAccounts, setGLAccounts] = useState<GLAccount[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState('');

  const [form, setForm] = useState({
    invoiceNumber: '',
    supplierId: '',
    invoiceDate: new Date().toISOString().split('T')[0],
    dueDate: '',
    paymentTerms: 'net30',
    reference: '',
    notes: '',
    taxRate: 15,
  });

  const [lines, setLines] = useState<LineItem[]>([
    { key: crypto.randomUUID(), description: '', quantity: 1, unitPrice: 0, taxRate: 15, glAccountId: '' },
  ]);

  useEffect(() => {
    Promise.all([
      fetch('/api/suppliers').then(r => r.json()),
      fetch('/api/accounting/chart-of-accounts').then(r => r.json()),
    ]).then(([suppRes, accRes]) => {
      const suppData = suppRes.data || suppRes;
      setSuppliers(Array.isArray(suppData) ? suppData : suppData.suppliers || []);
      const accData = accRes.data || accRes;
      setGLAccounts(Array.isArray(accData) ? accData.filter((a: GLAccount) => a.accountCode >= '5000') : []);
    });
  }, []);

  const addLine = () => {
    setLines(prev => [...prev, {
      key: crypto.randomUUID(), description: '', quantity: 1, unitPrice: 0,
      taxRate: form.taxRate, glAccountId: '',
    }]);
  };

  const updateLine = (key: string, field: keyof LineItem, value: string | number) => {
    setLines(prev => prev.map(l => l.key === key ? { ...l, [field]: value } : l));
  };

  const removeLine = (key: string) => {
    if (lines.length <= 1) return;
    setLines(prev => prev.filter(l => l.key !== key));
  };

  const subtotal = lines.reduce((sum, l) => sum + l.quantity * l.unitPrice, 0);
  const totalTax = lines.reduce((sum, l) => sum + (l.quantity * l.unitPrice * l.taxRate / 100), 0);
  const total = subtotal + totalTax;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    setError('');
    try {
      const res = await fetch('/api/accounting/supplier-invoices', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          invoiceNumber: form.invoiceNumber,
          supplierId: form.supplierId,
          invoiceDate: form.invoiceDate,
          dueDate: form.dueDate || undefined,
          paymentTerms: form.paymentTerms || undefined,
          reference: form.reference || undefined,
          notes: form.notes || undefined,
          taxRate: form.taxRate,
          items: lines.map(l => ({
            description: l.description,
            quantity: l.quantity,
            unitPrice: l.unitPrice,
            taxRate: l.taxRate,
            glAccountId: l.glAccountId || undefined,
          })),
        }),
      });

      if (!res.ok) {
        const err = await res.json();
        throw new Error(err.error?.message || 'Failed to create invoice');
      }

      const json = await res.json();
      const invoice = json.data || json;
      router.push(`/accounting/supplier-invoices/${invoice.id}`);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to create invoice');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <Link href="/accounting/supplier-invoices" className="inline-flex items-center gap-1 text-sm text-[var(--ff-text-secondary)] hover:text-emerald-600 mb-3">
            <ArrowLeft className="h-4 w-4" /> Back to Supplier Invoices
          </Link>
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-lg bg-emerald-500/10">
              <Receipt className="h-6 w-6 text-emerald-500" />
            </div>
            <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">New Supplier Invoice</h1>
          </div>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-6 max-w-5xl">
          {error && (
            <div className="p-3 bg-red-500/10 rounded-lg text-red-400 text-sm">{error}</div>
          )}

          {/* Invoice Details */}
          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-6">
            <h3 className="text-lg font-semibold text-[var(--ff-text-primary)] mb-4">Invoice Details</h3>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Invoice Number *</label>
                <input type="text" required value={form.invoiceNumber}
                  onChange={e => setForm(f => ({ ...f, invoiceNumber: e.target.value }))}
                  className="ff-input w-full" placeholder="INV-001" />
              </div>
              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Supplier *</label>
                <select required value={form.supplierId}
                  onChange={e => setForm(f => ({ ...f, supplierId: e.target.value }))}
                  className="ff-select w-full">
                  <option value="">Select supplier...</option>
                  {suppliers.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Invoice Date *</label>
                <input type="date" required value={form.invoiceDate}
                  onChange={e => setForm(f => ({ ...f, invoiceDate: e.target.value }))}
                  className="ff-input w-full" />
              </div>
              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Payment Terms</label>
                <select value={form.paymentTerms}
                  onChange={e => setForm(f => ({ ...f, paymentTerms: e.target.value }))}
                  className="ff-select w-full">
                  <option value="">None</option>
                  <option value="immediate">Immediate</option>
                  <option value="net30">Net 30</option>
                  <option value="net60">Net 60</option>
                  <option value="net90">Net 90</option>
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Reference</label>
                <input type="text" value={form.reference}
                  onChange={e => setForm(f => ({ ...f, reference: e.target.value }))}
                  className="ff-input w-full" placeholder="PO ref or delivery note" />
              </div>
              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">VAT Rate (%)</label>
                <input type="number" step="0.01" value={form.taxRate}
                  onChange={e => setForm(f => ({ ...f, taxRate: Number(e.target.value) }))}
                  className="ff-input w-full" />
              </div>
            </div>
          </div>

          {/* Line Items */}
          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-6">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-semibold text-[var(--ff-text-primary)]">Line Items</h3>
              <button type="button" onClick={addLine}
                className="inline-flex items-center gap-1 text-sm text-emerald-600 hover:text-emerald-700 font-medium">
                <Plus className="h-4 w-4" /> Add Line
              </button>
            </div>
            <div className="space-y-3">
              {lines.map((line, idx) => (
                <div key={line.key} className="grid grid-cols-12 gap-2 items-end">
                  <div className="col-span-4">
                    {idx === 0 && <label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Description *</label>}
                    <input type="text" required value={line.description}
                      onChange={e => updateLine(line.key, 'description', e.target.value)}
                      className="ff-input w-full text-sm" placeholder="Item description" />
                  </div>
                  <div className="col-span-1">
                    {idx === 0 && <label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Qty</label>}
                    <input type="number" step="0.01" min="0.01" required value={line.quantity}
                      onChange={e => updateLine(line.key, 'quantity', Number(e.target.value))}
                      className="ff-input w-full text-sm text-right" />
                  </div>
                  <div className="col-span-2">
                    {idx === 0 && <label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Unit Price</label>}
                    <input type="number" step="0.01" min="0" required value={line.unitPrice}
                      onChange={e => updateLine(line.key, 'unitPrice', Number(e.target.value))}
                      className="ff-input w-full text-sm text-right" />
                  </div>
                  <div className="col-span-2">
                    {idx === 0 && <label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">GL Account</label>}
                    <select value={line.glAccountId}
                      onChange={e => updateLine(line.key, 'glAccountId', e.target.value)}
                      className="ff-select w-full text-sm">
                      <option value="">Default (5100)</option>
                      {glAccounts.map(a => (
                        <option key={a.id} value={a.id}>{a.accountCode} - {a.accountName}</option>
                      ))}
                    </select>
                  </div>
                  <div className="col-span-2">
                    {idx === 0 && <label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Line Total</label>}
                    <div className="ff-input w-full text-sm text-right bg-[var(--ff-bg-tertiary)] font-mono">
                      {formatCurrency(line.quantity * line.unitPrice)}
                    </div>
                  </div>
                  <div className="col-span-1 flex justify-center">
                    {lines.length > 1 && (
                      <button type="button" onClick={() => removeLine(line.key)}
                        className="p-1 text-red-400 hover:text-red-300">
                        <Trash2 className="h-4 w-4" />
                      </button>
                    )}
                  </div>
                </div>
              ))}
            </div>

            {/* Totals */}
            <div className="mt-4 pt-4 border-t border-[var(--ff-border-light)] flex justify-end">
              <div className="w-64 space-y-2">
                <div className="flex justify-between text-sm">
                  <span className="text-[var(--ff-text-secondary)]">Subtotal</span>
                  <span className="font-mono text-[var(--ff-text-primary)]">{formatCurrency(subtotal)}</span>
                </div>
                <div className="flex justify-between text-sm">
                  <span className="text-[var(--ff-text-secondary)]">VAT</span>
                  <span className="font-mono text-[var(--ff-text-primary)]">{formatCurrency(totalTax)}</span>
                </div>
                <div className="flex justify-between text-base font-bold border-t border-[var(--ff-border-medium)] pt-2">
                  <span className="text-[var(--ff-text-primary)]">Total</span>
                  <span className="font-mono text-emerald-500">{formatCurrency(total)}</span>
                </div>
              </div>
            </div>
          </div>

          {/* Notes */}
          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-6">
            <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Notes</label>
            <textarea value={form.notes} onChange={e => setForm(f => ({ ...f, notes: e.target.value }))}
              className="ff-input w-full" rows={3} placeholder="Optional notes..." />
          </div>

          {/* Submit */}
          <div className="flex justify-end gap-3">
            <Link href="/accounting/supplier-invoices"
              className="px-4 py-2 border border-[var(--ff-border-medium)] rounded-lg text-[var(--ff-text-secondary)] hover:bg-[var(--ff-bg-tertiary)] text-sm font-medium">
              Cancel
            </Link>
            <button type="submit" disabled={isSubmitting}
              className="inline-flex items-center gap-2 px-6 py-2 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 text-sm font-medium disabled:opacity-50">
              {isSubmitting && <Loader2 className="h-4 w-4 animate-spin" />}
              Create Invoice
            </button>
          </div>
        </form>
      </div>
    </AppLayout>
  );
}

/**
 * Create Customer Payment Page
 * PRD-060 Phase 3: Payment with invoice allocation
 */

import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import { ArrowLeft, Wallet, Loader2, Plus, Trash2 } from 'lucide-react';

interface Client { id: string; company_name: string }
interface OutstandingInvoice {
  id: string;
  invoice_number: string;
  total_amount: number;
  amount_paid: number;
}

interface Allocation { key: string; invoiceId: string; amount: number }

function formatCurrency(amount: number): string {
  return new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(amount);
}

export default function NewCustomerPaymentPage() {
  const router = useRouter();
  const [clients, setClients] = useState<Client[]>([]);
  const [invoices, setInvoices] = useState<OutstandingInvoice[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState('');

  const [form, setForm] = useState({
    clientId: '',
    paymentDate: new Date().toISOString().split('T')[0],
    paymentMethod: 'eft',
    bankReference: '',
    description: '',
  });

  const [allocations, setAllocations] = useState<Allocation[]>([
    { key: crypto.randomUUID(), invoiceId: '', amount: 0 },
  ]);

  useEffect(() => {
    fetch('/api/clients').then(r => r.json()).then(res => {
      const data = res.data || res;
      setClients(Array.isArray(data) ? data : data.clients || []);
    });
  }, []);

  // Load outstanding invoices when client changes
  useEffect(() => {
    if (!form.clientId) { setInvoices([]); return; }
    fetch(`/api/customer-invoices?client_id=${form.clientId}&status=approved&status=sent&status=partially_paid&status=overdue`)
      .then(r => r.json())
      .then(res => {
        const data = res.data || res;
        const list = Array.isArray(data) ? data : data.invoices || [];
        setInvoices(list.filter((inv: OutstandingInvoice) =>
          Number(inv.total_amount) - Number(inv.amount_paid) > 0.01
        ));
      });
  }, [form.clientId]);

  const totalAllocated = allocations.reduce((s, a) => s + (a.amount || 0), 0);

  const addAllocation = () => {
    setAllocations(prev => [...prev, { key: crypto.randomUUID(), invoiceId: '', amount: 0 }]);
  };

  const removeAllocation = (key: string) => {
    setAllocations(prev => prev.filter(a => a.key !== key));
  };

  const updateAllocation = (key: string, field: 'invoiceId' | 'amount', value: string | number) => {
    setAllocations(prev => prev.map(a => a.key === key ? { ...a, [field]: value } : a));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setIsSubmitting(true);

    try {
      const res = await fetch('/api/accounting/customer-payments', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          clientId: form.clientId,
          paymentDate: form.paymentDate,
          totalAmount: totalAllocated,
          paymentMethod: form.paymentMethod,
          bankReference: form.bankReference || undefined,
          description: form.description || undefined,
          allocations: allocations
            .filter(a => a.invoiceId && a.amount > 0)
            .map(a => ({ invoiceId: a.invoiceId, amount: a.amount })),
        }),
      });

      const json = await res.json();
      if (!res.ok) throw new Error(json.message || json.error || 'Failed to create payment');
      router.push('/accounting/customer-payments');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to create payment');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4">
            <Link href="/accounting/customer-payments" className="inline-flex items-center gap-1 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] mb-2">
              <ArrowLeft className="h-4 w-4" /> Back to Payments
            </Link>
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-emerald-500/10">
                <Wallet className="h-6 w-6 text-emerald-500" />
              </div>
              <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Record Customer Payment</h1>
            </div>
          </div>
        </div>

        <form onSubmit={handleSubmit} className="p-6 max-w-4xl space-y-6">
          {error && (
            <div className="p-3 rounded-lg bg-red-500/10 text-red-400 text-sm">{error}</div>
          )}

          {/* Payment Details */}
          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-6 space-y-4">
            <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">Payment Details</h2>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Client *</label>
                <select
                  value={form.clientId}
                  onChange={e => setForm(f => ({ ...f, clientId: e.target.value }))}
                  className="ff-select w-full"
                  required
                >
                  <option value="">Select client...</option>
                  {clients.map(c => <option key={c.id} value={c.id}>{c.company_name}</option>)}
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Payment Date *</label>
                <input
                  type="date"
                  value={form.paymentDate}
                  onChange={e => setForm(f => ({ ...f, paymentDate: e.target.value }))}
                  className="ff-input w-full"
                  required
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Payment Method</label>
                <select
                  value={form.paymentMethod}
                  onChange={e => setForm(f => ({ ...f, paymentMethod: e.target.value }))}
                  className="ff-select w-full"
                >
                  <option value="eft">EFT</option>
                  <option value="cheque">Cheque</option>
                  <option value="cash">Cash</option>
                  <option value="card">Card</option>
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Bank Reference</label>
                <input
                  type="text"
                  value={form.bankReference}
                  onChange={e => setForm(f => ({ ...f, bankReference: e.target.value }))}
                  className="ff-input w-full"
                  placeholder="e.g. REF123456"
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Description</label>
              <input
                type="text"
                value={form.description}
                onChange={e => setForm(f => ({ ...f, description: e.target.value }))}
                className="ff-input w-full"
                placeholder="Optional payment description"
              />
            </div>
          </div>

          {/* Invoice Allocations */}
          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-6 space-y-4">
            <div className="flex items-center justify-between">
              <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">Invoice Allocations</h2>
              <button
                type="button"
                onClick={addAllocation}
                className="inline-flex items-center gap-1 text-sm text-emerald-500 hover:text-emerald-400"
              >
                <Plus className="h-4 w-4" /> Add Line
              </button>
            </div>

            {invoices.length === 0 && form.clientId && (
              <p className="text-sm text-[var(--ff-text-tertiary)]">No outstanding invoices for this client</p>
            )}

            <div className="space-y-3">
              {allocations.map(alloc => {
                const inv = invoices.find(i => i.id === alloc.invoiceId);
                const balance = inv ? Number(inv.total_amount) - Number(inv.amount_paid) : 0;
                return (
                  <div key={alloc.key} className="flex items-center gap-3">
                    <select
                      value={alloc.invoiceId}
                      onChange={e => updateAllocation(alloc.key, 'invoiceId', e.target.value)}
                      className="ff-select flex-1"
                    >
                      <option value="">Select invoice...</option>
                      {invoices.map(inv => (
                        <option key={inv.id} value={inv.id}>
                          {inv.invoice_number} — Balance: {formatCurrency(Number(inv.total_amount) - Number(inv.amount_paid))}
                        </option>
                      ))}
                    </select>
                    <input
                      type="number"
                      step="0.01"
                      min="0"
                      max={balance || undefined}
                      value={alloc.amount || ''}
                      onChange={e => updateAllocation(alloc.key, 'amount', Number(e.target.value))}
                      className="ff-input w-40"
                      placeholder="Amount"
                    />
                    {allocations.length > 1 && (
                      <button
                        type="button"
                        onClick={() => removeAllocation(alloc.key)}
                        className="p-2 text-red-400 hover:text-red-300"
                      >
                        <Trash2 className="h-4 w-4" />
                      </button>
                    )}
                  </div>
                );
              })}
            </div>

            <div className="pt-3 border-t border-[var(--ff-border-light)] flex justify-between">
              <span className="text-sm font-medium text-[var(--ff-text-secondary)]">Total Allocated</span>
              <span className="text-lg font-bold text-[var(--ff-text-primary)]">{formatCurrency(totalAllocated)}</span>
            </div>
          </div>

          {/* Submit */}
          <div className="flex justify-end gap-3">
            <Link href="/accounting/customer-payments" className="px-4 py-2 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]">
              Cancel
            </Link>
            <button
              type="submit"
              disabled={isSubmitting || totalAllocated <= 0}
              className="inline-flex items-center gap-2 px-6 py-2 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 disabled:opacity-50 transition-colors text-sm font-medium"
            >
              {isSubmitting && <Loader2 className="h-4 w-4 animate-spin" />}
              Create Payment
            </button>
          </div>
        </form>
      </div>
    </AppLayout>
  );
}

/**
 * Bank Statement Import Page
 * PRD-060 Phase 4: CSV + PDF upload with format detection
 */

import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import { ArrowLeft, Upload, Loader2, AlertCircle, CheckCircle2, Landmark, FileText } from 'lucide-react';

interface BankAccount { id: string; account_code: string; account_name: string; bank_account_number?: string | null }

type FileType = 'csv' | 'pdf' | 'ofx' | 'qif';

interface ImportForm {
  bankAccountId: string;
  statementDate: string;
  bankFormat: string;
  /** Raw text content for CSV files */
  csvContent: string;
  /** Base64 data-URL for PDF files */
  pdfBase64: string;
  fileName: string;
  fileType: FileType | '';
}

export default function BankStatementImportPage() {
  useRouter();
  const [bankAccounts, setBankAccounts] = useState<BankAccount[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState('');
  const [result, setResult] = useState<{
    batchId: string;
    transactionCount: number;
    errors: { row: number; error: string }[];
  } | null>(null);

  const [form, setForm] = useState<ImportForm>({
    bankAccountId: '',
    statementDate: new Date().toISOString().split('T')[0]!,
    bankFormat: 'auto',
    csvContent: '',
    pdfBase64: '',
    fileName: '',
    fileType: '',
  });

  useEffect(() => {
    fetch('/api/accounting/chart-of-accounts?subtype=bank')
      .then(r => r.json())
      .then(res => {
        const data = res.data || res;
        const accounts = Array.isArray(data) ? data : data.accounts || [];
        setBankAccounts(
          accounts.map((a: {
            id: string;
            accountCode?: string;
            account_code?: string;
            accountName?: string;
            account_name?: string;
            bankAccountNumber?: string;
            bank_account_number?: string;
          }) => ({
            id: a.id,
            account_code: a.accountCode || a.account_code || '',
            account_name: a.accountName || a.account_name || '',
            bank_account_number: a.bankAccountNumber || a.bank_account_number || null,
          })),
        );
      });
  }, []);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const lower = file.name.toLowerCase();
    const isPdf = lower.endsWith('.pdf') || file.type === 'application/pdf';
    const isCsv = lower.endsWith('.csv') || file.type === 'text/csv';
    const isOfx = lower.endsWith('.ofx') || lower.endsWith('.qfx');
    const isQif = lower.endsWith('.qif');

    if (!isPdf && !isCsv && !isOfx && !isQif) {
      setError('Only CSV, PDF, OFX, and QIF files are supported.');
      return;
    }

    setError('');

    if (isPdf) {
      const reader = new FileReader();
      reader.onload = (ev) => {
        setForm(f => ({
          ...f,
          pdfBase64: ev.target?.result as string || '',
          csvContent: '',
          fileName: file.name,
          fileType: 'pdf',
        }));
      };
      reader.readAsDataURL(file);
    } else {
      // CSV, OFX, and QIF are all read as text
      const detectedFileType: FileType = isOfx ? 'ofx' : isQif ? 'qif' : 'csv';
      const reader = new FileReader();
      reader.onload = (ev) => {
        const content = ev.target?.result as string || '';
        setForm(f => ({
          ...f,
          csvContent: content,
          pdfBase64: '',
          fileName: file.name,
          fileType: detectedFileType,
          // Auto-set bankFormat for OFX/QIF since format is unambiguous
          bankFormat: isOfx ? 'ofx' : isQif ? 'qif' : f.bankFormat,
        }));
      };
      reader.readAsText(file);
    }
  };

  const hasFile = form.fileType === 'pdf' ? !!form.pdfBase64 : !!form.csvContent;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setResult(null);
    setIsSubmitting(true);

    try {
      const body: Record<string, unknown> = {
        bankAccountId: form.bankAccountId,
        statementDate: form.statementDate,
        bankFormat: form.bankFormat === 'auto' ? undefined : form.bankFormat,
        fileType: form.fileType || 'csv',
      };

      if (form.fileType === 'pdf') {
        body.pdfBase64 = form.pdfBase64;
      } else {
        // csv, ofx, and qif all send csvContent (raw text)
        body.csvContent = form.csvContent;
      }

      const res = await fetch('/api/accounting/bank-transactions-import', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify(body),
      });

      const json = await res.json();
      if (!res.ok) throw new Error(json.message || json.error || 'Import failed');
      setResult(json.data || json);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Import failed');
    } finally {
      setIsSubmitting(false);
    }
  };

  const csvRowCount = form.fileType === 'csv' ? Math.max(0, form.csvContent.split('\n').length - 1) : 0;

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4">
            <Link
              href="/accounting/bank-reconciliation"
              className="inline-flex items-center gap-1 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] mb-2"
            >
              <ArrowLeft className="h-4 w-4" /> Back to Reconciliations
            </Link>
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-emerald-500/10">
                <Upload className="h-6 w-6 text-emerald-500" />
              </div>
              <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">Import Bank Statement</h1>
            </div>
          </div>
        </div>

        <div className="p-6 max-w-3xl space-y-6">
          {error && (
            <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 text-red-400 text-sm">
              <AlertCircle className="h-4 w-4" /> {error}
            </div>
          )}

          {result && (
            <div className="p-4 rounded-lg bg-emerald-500/10 border border-emerald-500/30 space-y-2">
              <div className="flex items-center gap-2 text-emerald-400 font-medium">
                <CheckCircle2 className="h-5 w-5" /> Import Successful
              </div>
              <p className="text-sm text-[var(--ff-text-secondary)]">
                Imported {result.transactionCount} transaction{result.transactionCount !== 1 ? 's' : ''}
              </p>
              {result.errors.length > 0 && (
                <div className="text-sm text-amber-400">
                  {result.errors.length} row{result.errors.length !== 1 ? 's' : ''} skipped:
                  <ul className="list-disc ml-5 mt-1 text-xs">
                    {result.errors.slice(0, 5).map((e, i) => (
                      <li key={i}>Row {e.row}: {e.error}</li>
                    ))}
                    {result.errors.length > 5 && <li>...and {result.errors.length - 5} more</li>}
                  </ul>
                </div>
              )}
              <div className="pt-2">
                <Link
                  href="/accounting/bank-reconciliation"
                  className="text-sm text-emerald-500 hover:text-emerald-400 font-medium"
                >
                  Start a reconciliation with these transactions
                </Link>
              </div>
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-6 space-y-4">
              <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">Statement Details</h2>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">
                    Bank Account *
                  </label>
                  <select
                    value={form.bankAccountId}
                    onChange={e => setForm(f => ({ ...f, bankAccountId: e.target.value }))}
                    className="ff-select w-full"
                    required
                  >
                    <option value="">Select bank account...</option>
                    {bankAccounts.map(a => (
                      <option key={a.id} value={a.id}>
                        {a.account_code} — {a.account_name}
                        {a.bank_account_number ? ` (****${a.bank_account_number.slice(-4)})` : ''}
                      </option>
                    ))}
                  </select>
                </div>

                <div>
                  <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">
                    Statement Date *
                  </label>
                  <input
                    type="date"
                    value={form.statementDate}
                    onChange={e => setForm(f => ({ ...f, statementDate: e.target.value }))}
                    className="ff-input w-full"
                    required
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">
                    Bank Format
                  </label>
                  <select
                    value={form.bankFormat}
                    onChange={e => setForm(f => ({ ...f, bankFormat: e.target.value }))}
                    className="ff-select w-full"
                  >
                    <option value="auto">Auto-detect</option>
                    <optgroup label="CSV Formats">
                      <option value="absa">ABSA</option>
                      <option value="capitec">Capitec</option>
                      <option value="fnb">FNB</option>
                      <option value="standard_bank">Standard Bank</option>
                      <option value="nedbank">Nedbank</option>
                    </optgroup>
                    <optgroup label="Other Formats">
                      <option value="ofx">OFX / QFX (Open Financial Exchange)</option>
                      <option value="qif">QIF (Quicken Interchange Format)</option>
                    </optgroup>
                  </select>
                </div>
              </div>
            </div>

            <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-6 space-y-4">
              <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">Statement File</h2>

              <div className="border-2 border-dashed border-[var(--ff-border-light)] rounded-lg p-8 text-center">
                {form.fileType === 'pdf' ? (
                  <FileText className="h-8 w-8 text-red-400 mx-auto mb-3" />
                ) : (
                  <Landmark className="h-8 w-8 text-[var(--ff-text-tertiary)] mx-auto mb-3" />
                )}
                <label className="block">
                  <span className="text-emerald-500 hover:text-emerald-400 cursor-pointer font-medium">
                    Choose CSV, PDF, OFX, or QIF file
                  </span>
                  <input
                    type="file"
                    accept=".csv,.pdf,.ofx,.qfx,.qif"
                    onChange={handleFileChange}
                    className="hidden"
                  />
                </label>
                {form.fileName ? (
                  <p className="mt-2 text-sm text-[var(--ff-text-secondary)]">
                    {form.fileName}
                    {form.fileType && (
                      <span className="ml-2 text-xs px-1.5 py-0.5 rounded bg-[var(--ff-bg-primary)] text-[var(--ff-text-tertiary)] uppercase">
                        {form.fileType}
                      </span>
                    )}
                  </p>
                ) : null}
                <p className="mt-1 text-xs text-[var(--ff-text-tertiary)]">
                  Supports CSV (ABSA, Capitec, FNB, Standard Bank, Nedbank), PDF, OFX/QFX, and QIF formats
                </p>
              </div>

              {form.fileType === 'csv' && form.csvContent && (
                <div className="text-sm text-[var(--ff-text-secondary)]">
                  {csvRowCount} data row{csvRowCount !== 1 ? 's' : ''} detected
                </div>
              )}

              {form.fileType === 'ofx' && form.csvContent && (
                <div className="text-sm text-[var(--ff-text-secondary)]">
                  OFX file loaded — transactions will be extracted on import
                </div>
              )}

              {form.fileType === 'qif' && form.csvContent && (
                <div className="text-sm text-[var(--ff-text-secondary)]">
                  QIF file loaded — transactions will be extracted on import
                </div>
              )}

              {form.fileType === 'pdf' && form.pdfBase64 && (
                <div className="text-sm text-[var(--ff-text-secondary)]">
                  PDF loaded — transactions will be extracted on import
                </div>
              )}
            </div>

            <div className="flex justify-end gap-3">
              <Link
                href="/accounting/bank-reconciliation"
                className="px-4 py-2 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]"
              >
                Cancel
              </Link>
              <button
                type="submit"
                disabled={isSubmitting || !hasFile || !form.bankAccountId}
                className="inline-flex items-center gap-2 px-6 py-2 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 disabled:opacity-50 transition-colors text-sm font-medium"
              >
                {isSubmitting && <Loader2 className="h-4 w-4 animate-spin" />}
                Import Statement
              </button>
            </div>
          </form>
        </div>
      </div>
    </AppLayout>
  );
}

/**
 * Bank Transactions — Sage "Process Bank" equivalent
 * Type: Account / Supplier / Customer — Selection changes accordingly
 * Full toolbar: Mark Reviewed, Delete, Batch Edit, Import, Export, Search
 */

import { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import {
  BankTxTable, type AllocType, type VatCode, type BankTx, type SelectOption, type RowSelection,
} from '@/components/accounting/BankTxTable';
import { SplitTransactionModal } from '@/components/accounting/SplitTransactionModal';
import { ExcludeReasonModal } from '@/components/accounting/ExcludeReasonModal';
import { FindMatchModal } from '@/components/accounting/FindMatchModal';
import { BankTxAttachmentsModal } from '@/components/accounting/BankTxAttachmentsModal';
import { CreateRuleModal, extractPattern } from '@/components/accounting/CreateRuleModal';
import { CreateEntityModal } from '@/components/accounting/CreateEntityModal';
import { StatementBalanceWidget } from '@/components/accounting/StatementBalanceWidget';
import {
  Loader2, AlertCircle, RefreshCw, CheckCheck, Upload, Download, Search, Trash2, Layers, Zap, Plus, FileText,
} from 'lucide-react';
import { toast } from 'react-hot-toast';
import Link from 'next/link';

function fmtCurrency(n: number): string {
  return new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(n);
}

interface BankAcct {
  id: string;
  accountCode: string;
  accountName: string;
  bankAccountNumber?: string | null;
  balance: number;
  reconciledBalance: number;
  unreconciledBalance: number;
  unreconciledCount: number;
}
type Tab = 'new' | 'reviewed' | 'excluded';
const PAGE_SIZE = 25;

/** Maps UI tabs to bank_transactions.status values */
function tabToStatus(tab: Tab): string {
  if (tab === 'new') return 'imported';
  if (tab === 'excluded') return 'excluded';
  return 'matched';
}

export default function BankTransactionsPage() {
  const [transactions, setTransactions] = useState<BankTx[]>([]);
  const [glAccounts, setGlAccounts] = useState<SelectOption[]>([]);
  const [suppliers, setSuppliers] = useState<SelectOption[]>([]);
  const [customers, setCustomers] = useState<SelectOption[]>([]);
  const [cc1Options, setCc1Options] = useState<SelectOption[]>([]);
  const [cc2Options, setCc2Options] = useState<SelectOption[]>([]);
  const [buOptions, setBuOptions] = useState<SelectOption[]>([]);
  const [bankAccounts, setBankAccounts] = useState<BankAcct[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');

  const [selectedBank, setSelectedBank] = useState('');
  const [tab, setTab] = useState<Tab>('new');
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);
  const [searchTerm, setSearchTerm] = useState('');
  const [debouncedSearch, setDebouncedSearch] = useState('');
  const [fromDate, setFromDate] = useState('');
  const [toDate, setToDate] = useState('');
  /** Minimum transaction amount filter (Rand value, empty = no lower bound) */
  const [fromAmount, setFromAmount] = useState('');
  /** Maximum transaction amount filter (Rand value, empty = no upper bound) */
  const [toAmount, setToAmount] = useState('');
  const debounceTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const amountDebounceTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [rowSelections, setRowSelections] = useState<Record<string, RowSelection>>({});
  const [showBatchEdit, setShowBatchEdit] = useState(false);
  const [batchType, setBatchType] = useState<AllocType>('account');
  const [batchSearch, setBatchSearch] = useState('');

  const [splitTxId, setSplitTxId] = useState<string | null>(null);
  /** ID of transaction awaiting an exclusion reason — shows ExcludeReasonModal when set */
  const [excludingTxId, setExcludingTxId] = useState<string | null>(null);
  const [findMatchTxId, setFindMatchTxId] = useState<string | null>(null);
  const [attachmentsTxId, setAttachmentsTxId] = useState<string | null>(null);
  const [createRuleTx, setCreateRuleTx] = useState<BankTx | null>(null);
  const [rulePrompt, setRulePrompt] = useState<{ tx: BankTx; matchCount: number } | null>(null);
  const [createEntityTxId, setCreateEntityTxId] = useState<string | null>(null);
  const [createEntityType, setCreateEntityType] = useState<AllocType | null>(null);

  // Load reference data — bank accounts, GL accounts, suppliers, customers
  useEffect(() => {
    fetch('/api/accounting/bank-accounts').then(r => r.json()).then(json => {
      const list = Array.isArray(json.data || json) ? (json.data || json) : [];
      setBankAccounts(list);
      if (list.length > 0) setSelectedBank(prev => prev || list[0].id);
    }).catch(() => {});

    fetch('/api/accounting/chart-of-accounts').then(r => r.json()).then(json => {
      const list = Array.isArray(json.data || json) ? (json.data || json) : [];
      setGlAccounts(list
        .filter((a: SelectOption & { accountSubtype?: string }) =>
          a.accountSubtype !== 'bank')
        .map((a: SelectOption & { accountCode?: string; accountName?: string; defaultVatCode?: string }) => ({
          id: a.id, code: a.accountCode || a.code, name: a.accountName || a.name,
          defaultVatCode: a.defaultVatCode,
        }))
      );
    }).catch(() => {});

    fetch('/api/suppliers?status=active').then(r => r.json()).then(json => {
      const list = Array.isArray(json.data) ? json.data : [];
      setSuppliers(list.map((s: { id: number | string; name: string; code?: string }) => ({
        id: String(s.id), name: s.name, code: s.code,
      })));
    }).catch(() => {});

    fetch('/api/clients').then(r => r.json()).then(json => {
      const list = Array.isArray(json.data) ? json.data : [];
      setCustomers(list.map((c: { id: string; name?: string; company_name?: string; companyName?: string }) => ({
        id: c.id, name: c.company_name || c.companyName || c.name || '',
      })));
    }).catch(() => {});

    fetch('/api/accounting/cost-centres?cc_type=cc1&active=true').then(r => r.json()).then(json => {
      const list = Array.isArray(json.data?.items) ? json.data.items : [];
      setCc1Options(list.map((c: { id: string; code: string; name: string }) => ({ id: c.id, code: c.code, name: c.name })));
    }).catch(() => {});

    fetch('/api/accounting/cost-centres?cc_type=cc2&active=true').then(r => r.json()).then(json => {
      const list = Array.isArray(json.data?.items) ? json.data.items : [];
      setCc2Options(list.map((c: { id: string; code: string; name: string }) => ({ id: c.id, code: c.code, name: c.name })));
    }).catch(() => {});

    fetch('/api/departments?isActive=true').then(r => r.json()).then(json => {
      const list = Array.isArray(json.data || json) ? (json.data || json) : [];
      setBuOptions(list.filter((d: { is_active?: boolean; isActive?: boolean }) => d.is_active !== false && d.isActive !== false)
        .map((d: { id: string; name: string; code?: string }) => ({ id: d.id, name: d.name, code: d.code })));
    }).catch(() => {});
  }, []);

  // Debounce search input — 500ms delay before firing server request
  useEffect(() => {
    if (debounceTimer.current) clearTimeout(debounceTimer.current);
    debounceTimer.current = setTimeout(() => {
      setDebouncedSearch(searchTerm);
      setPage(1);
    }, 500);
    return () => { if (debounceTimer.current) clearTimeout(debounceTimer.current); };
  }, [searchTerm]);

  // Load transactions — server-side filtering for search, dates, amount range, status
  const loadTransactions = useCallback(async () => {
    if (!selectedBank) return;
    setIsLoading(true);
    setError('');
    try {
      const status = tabToStatus(tab);
      const offset = (page - 1) * PAGE_SIZE;
      const params = new URLSearchParams({
        bank_account_id: selectedBank, status, limit: String(PAGE_SIZE), offset: String(offset),
      });
      if (fromDate) params.set('from_date', fromDate);
      if (toDate) params.set('to_date', toDate);
      if (fromAmount) params.set('from_amount', fromAmount);
      if (toAmount) params.set('to_amount', toAmount);
      if (debouncedSearch) params.set('search', debouncedSearch);
      const res = await fetch(`/api/accounting/bank-transactions?${params}`);
      const json = await res.json();
      const data = json.data || json;
      setTransactions(data.transactions || []);
      setTotal(data.total || 0);
    } catch {
      setError('Failed to load transactions');
    } finally {
      setIsLoading(false);
    }
  }, [selectedBank, tab, page, fromDate, toDate, fromAmount, toAmount, debouncedSearch]);

  useEffect(() => { loadTransactions(); }, [loadTransactions]);

  // Seed rowSelections from suggestion fields on newly-loaded transactions
  useEffect(() => {
    if (transactions.length === 0) return;
    const initialSelections: Record<string, RowSelection> = {};
    for (const tx of transactions) {
      // Skip only if user has already picked a specific entity — an empty selection (type set, no entity)
      // should be overridden by fresh DB suggestions (e.g. after Apply Rules runs)
      if (rowSelections[tx.id]?.entityId) continue;
      // VAT only applies to GL account allocations; supplier/customer VAT is handled on their own invoices
      const dimFields = { cc1Id: tx.cc1Id, cc2Id: tx.cc2Id, buId: tx.buId };
      if (tx.suggestedSupplierId) {
        initialSelections[tx.id] = {
          type: 'supplier' as AllocType,
          entityId: tx.suggestedSupplierId,
          label: tx.suggestedSupplierName || tx.suggestedCategory || '',
          vatCode: 'none', ...dimFields,
        };
      } else if (tx.suggestedClientId) {
        initialSelections[tx.id] = {
          type: 'customer' as AllocType,
          entityId: tx.suggestedClientId,
          label: tx.suggestedClientName || tx.suggestedCategory || '',
          vatCode: 'none', ...dimFields,
        };
      } else if (tx.suggestedGlAccountId) {
        initialSelections[tx.id] = {
          type: 'account' as AllocType,
          entityId: tx.suggestedGlAccountId,
          label: tx.suggestedGlAccountCode
            ? `${tx.suggestedGlAccountCode} ${tx.suggestedGlAccountName || ''}`
            : tx.suggestedGlAccountName || tx.suggestedCategory || '',
          vatCode: (tx.suggestedVatCode || 'none') as VatCode, ...dimFields,
        };
      }
    }
    if (Object.keys(initialSelections).length > 0) {
      // Merge: DB suggestions fill in empty slots; existing selections with an entityId win
      setRowSelections(prev => {
        const merged = { ...prev };
        for (const [id, sel] of Object.entries(initialSelections)) {
          if (!merged[id]?.entityId) merged[id] = sel;
        }
        return merged;
      });
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [transactions]);

  useEffect(() => {
    setPage(1);
    setSelectedIds(new Set());
    setRowSelections({});
  }, [selectedBank, tab]);

  // API helpers
  const callAction = async (body: Record<string, string>) => {
    const res = await fetch('/api/accounting/bank-transactions-action', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include',
      body: JSON.stringify(body),
    });
    const json = await res.json();
    if (!res.ok || json.success === false) {
      const msg = json.error?.message || json.message || (typeof json.error === 'string' ? json.error : 'Action failed');
      throw new Error(msg);
    }
    return json;
  };

  // Fire-and-forget: persist dropdown selection to DB so it survives page refresh
  const saveSelection = (txId: string, type: AllocType, entityId: string) => {
    fetch('/api/accounting/bank-transactions-action', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include',
      body: JSON.stringify({ action: 'save_selection', bankTransactionId: txId, selectionType: type, selectionEntityId: entityId || null }),
    }).catch(() => {});
  };

  // Fire-and-forget: persist CC1/CC2/BU dimension changes
  const saveDimensions = (txId: string, cc1Id: string, cc2Id: string, buId: string) => {
    fetch('/api/accounting/bank-transactions-action', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include',
      body: JSON.stringify({ action: 'save_dimensions', bankTransactionId: txId, cc1Id: cc1Id || null, cc2Id: cc2Id || null, buId: buId || null }),
    }).catch(() => {});
  };

  const handleAccept = async (txId: string) => {
    const sel = rowSelections[txId];
    if (!sel?.entityId) { toast.error('Select an account/supplier/customer first'); return; }
    const tx = transactions.find(t => t.id === txId);
    try {
      const body: Record<string, string> = {
        action: 'allocate', bankTransactionId: txId, allocationType: sel.type,
        vatCode: sel.vatCode || 'none',
      };
      if (sel.type === 'account') body.contraAccountId = sel.entityId;
      else body.entityId = sel.entityId;
      if (sel.cc1Id) body.cc1Id = sel.cc1Id;
      if (sel.cc2Id) body.cc2Id = sel.cc2Id;
      if (sel.buId) body.buId = sel.buId;
      await callAction(body);
      toast.success('Transaction allocated');
      loadTransactions();
      // After allocation, check if there are other similar unprocessed transactions
      // to suggest creating a categorisation rule
      if (tx?.description && selectedBank) {
        const pattern = extractPattern(tx.description);
        if (pattern.trim().length >= 3) {
          try {
            const params = new URLSearchParams({ pattern, matchType: 'contains', bankAccountId: selectedBank });
            const res = await fetch(`/api/accounting/bank-rules-preview?${params}`);
            const json = await res.json();
            const matchCount = json.data?.matchCount ?? 0;
            if (matchCount > 0) setRulePrompt({ tx, matchCount });
          } catch { /* non-critical — ignore preview errors */ }
        }
      }
    } catch (e) { toast.error(e instanceof Error ? e.message : 'Failed'); }
  };

  /** Opens the ExcludeReasonModal — actual API call happens in handleExcludeConfirm */
  const handleExclude = (txId: string) => {
    setExcludingTxId(txId);
  };

  /** Called by ExcludeReasonModal on confirm — posts to API with reason then reloads */
  const handleExcludeConfirm = async (reason: string) => {
    if (!excludingTxId) return;
    const txId = excludingTxId;
    setExcludingTxId(null);
    try {
      await callAction({ action: 'exclude', bankTransactionId: txId, excludeReason: reason });
      toast.success('Transaction excluded');
      loadTransactions();
    } catch (e) { toast.error(e instanceof Error ? e.message : 'Failed to exclude'); }
  };

  const handleUnmatch = async (txId: string) => {
    try {
      await callAction({ action: 'unmatch', bankTransactionId: txId });
      toast.success('Allocation undone');
      loadTransactions();
    } catch (e) { toast.error(e instanceof Error ? e.message : 'Failed'); }
  };

  const handleSplit = (txId: string) => {
    setSplitTxId(txId);
  };

  /**
   * Save notes/memo for a single bank transaction.
   * Updates local state optimistically so the cell does not flicker.
   */
  const handleUpdateNotes = async (txId: string, notes: string) => {
    // Optimistic local update — keep UI in sync without a reload
    setTransactions(prev =>
      prev.map(tx => tx.id === txId ? { ...tx, notes: notes || undefined } : tx)
    );
    try {
      const res = await fetch('/api/accounting/bank-transactions-action', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ action: 'update_notes', bankTransactionId: txId, notes }),
      });
      const json = await res.json();
      if (!res.ok || json.success === false) throw new Error(json.message || 'Failed to save note');
    } catch (e) {
      toast.error(e instanceof Error ? e.message : 'Failed to save note');
      // Revert optimistic update on error
      loadTransactions();
    }
  };

  const handleBatchAccept = async () => {
    const toAccept = Array.from(selectedIds).filter(id => rowSelections[id]?.entityId);
    if (toAccept.length === 0) { toast.error('Select transactions with accounts assigned'); return; }
    let ok = 0, fail = 0;
    for (const txId of toAccept) {
      try {
        const sel = rowSelections[txId];
        if (!sel) continue;
        const body: Record<string, string> = {
          action: 'allocate', bankTransactionId: txId, allocationType: sel.type,
          vatCode: sel.vatCode || 'none',
        };
        if (sel.type === 'account') body.contraAccountId = sel.entityId;
        else body.entityId = sel.entityId;
        if (sel.cc1Id) body.cc1Id = sel.cc1Id;
        if (sel.cc2Id) body.cc2Id = sel.cc2Id;
        if (sel.buId) body.buId = sel.buId;
        await callAction(body);
        ok++;
      } catch { fail++; }
    }
    toast.success(`${ok} allocated${fail ? `, ${fail} failed` : ''}`);
    setSelectedIds(new Set());
    loadTransactions();
  };

  const handleBatchDelete = async () => {
    if (selectedIds.size === 0) return;
    if (!window.confirm(`Delete ${selectedIds.size} transaction(s)? This cannot be undone.`)) return;
    try {
      await callAction({ action: 'delete', bankTransactionIds: Array.from(selectedIds) } as unknown as Record<string, string>);
      toast.success(`${selectedIds.size} transaction(s) deleted`);
      setSelectedIds(new Set());
      loadTransactions();
    } catch (e) { toast.error(e instanceof Error ? e.message : 'Delete failed'); }
  };

  const handleBulkAccept = async () => {
    if (selectedIds.size === 0) return;
    try {
      const res = await fetch('/api/accounting/bank-transactions-action', {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include',
        body: JSON.stringify({ action: 'bulk_accept', bankTransactionIds: Array.from(selectedIds) }),
      });
      const json = await res.json();
      if (!res.ok || json.success === false) throw new Error(json.message || 'Failed to mark as reviewed');
      toast.success(`${json.data?.accepted ?? selectedIds.size} transaction(s) marked as reviewed`);
      setSelectedIds(new Set());
      loadTransactions();
    } catch (e) { toast.error(e instanceof Error ? e.message : 'Failed to mark as reviewed'); }
  };

  const handleExport = () => {
    const rows = transactions.map(tx => ({
      Date: tx.transactionDate,
      Description: tx.description || '',
      Reference: tx.reference || '',
      Spent: tx.amount < 0 ? Math.abs(tx.amount) : '',
      Received: tx.amount > 0 ? tx.amount : '',
      Status: tx.status,
    }));
    const header = Object.keys(rows[0] || {}).join(',');
    const csv = [header, ...rows.map(r => Object.values(r).map(v => `"${v}"`).join(','))].join('\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `bank-transactions-${bank?.accountCode || 'export'}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  };

  // Apply batch edit selection to all selected rows
  const applyBatchEdit = (entityId: string, label: string) => {
    const updates: Record<string, RowSelection> = { ...rowSelections };
    let autoVat: VatCode | undefined;
    if (batchType === 'account' && entityId) {
      const acct = glAccounts.find(g => g.id === entityId);
      if (acct?.defaultVatCode && acct.defaultVatCode !== 'none') {
        autoVat = acct.defaultVatCode as VatCode;
      }
    }
    selectedIds.forEach(id => {
      const vatCode = autoVat ?? (updates[id]?.vatCode || 'none') as VatCode;
      updates[id] = { type: batchType, entityId, label, vatCode };
    });
    setRowSelections(updates);
    setShowBatchEdit(false);
    toast.success(`Applied ${batchType} "${label}" to ${selectedIds.size} rows`);
  };

  // Quick Win 4: Apply bank categorisation rules to current account's unreviewed transactions
  const handleApplyRules = async () => {
    if (!selectedBank) { toast.error('Select a bank account first'); return; }
    try {
      const res = await fetch('/api/accounting/bank-rules-action', {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include',
        body: JSON.stringify({ action: 'apply', bankAccountId: selectedBank }),
      });
      const json = await res.json();
      if (!res.ok || json.success === false) throw new Error(json.message || 'Apply failed');
      const result = json.data || {};
      toast.success(`${result.applied ?? 0} categorised, ${result.skipped ?? 0} skipped`);
      loadTransactions();
    } catch (e) { toast.error(e instanceof Error ? e.message : 'Failed to apply rules'); }
  };

  const handleReverse = async (txId: string) => {
    const tx = transactions.find(t => t.id === txId);
    const msg = tx?.status === 'allocated'
      ? 'Undo this allocation? The journal entry will be reversed.'
      : 'Reverse this transaction? The associated journal entry will also be reversed.';
    if (!window.confirm(msg)) return;
    try {
      await callAction({ action: 'reverse', bankTransactionId: txId });
      toast.success(tx?.status === 'allocated' ? 'Allocation undone' : 'Transaction reversed');
      loadTransactions();
    } catch (e) { toast.error(e instanceof Error ? e.message : 'Reverse failed'); }
  };

  const handleDownloadReport = async () => {
    if (!selectedBank) return;
    try {
      const res = await fetch(`/api/accounting/bank-reconciliation-report?bankAccountId=${selectedBank}`);
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed');
      const data = json.data || json;
      const { generateReconReport } = await import('@/modules/accounting/utils/reconReportPdf');
      const blob = generateReconReport(data);
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url; a.download = `recon-report-${bank?.accountCode || 'bank'}.pdf`;
      a.click(); URL.revokeObjectURL(url);
      toast.success('Report downloaded');
    } catch (e) { toast.error(e instanceof Error ? e.message : 'Report failed'); }
  };

  const bank = bankAccounts.find(b => b.id === selectedBank);
  const totalPages = Math.ceil(total / PAGE_SIZE);
  const allSelected = transactions.length > 0 && transactions.every(t => selectedIds.has(t.id));

  const toggleSelect = (id: string) => {
    setSelectedIds(prev => { const n = new Set(prev); n.has(id) ? n.delete(id) : n.add(id); return n; });
  };

  // Batch edit options
  const batchOptions = useMemo(() => {
    const opts = batchType === 'supplier' ? suppliers : batchType === 'customer' ? customers : glAccounts;
    if (!batchSearch) return opts.slice(0, 30);
    const q = batchSearch.toLowerCase();
    return opts.filter(o => (o.code || '').toLowerCase().includes(q) || o.name.toLowerCase().includes(q)).slice(0, 30);
  }, [batchType, batchSearch, glAccounts, suppliers, customers]);

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header — bank account cards */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <h1 className="text-2xl font-bold text-[var(--ff-text-primary)] mb-3">Banking</h1>
          <div className="flex items-center gap-3 flex-wrap">
            {bankAccounts.map(b => {
              const active = b.id === selectedBank;
              const gap = b.unreconciledBalance;
              const hasGap = Math.abs(gap) >= 0.01;
              return (
                <button key={b.id} onClick={() => setSelectedBank(b.id)}
                  className={`flex items-center gap-3 px-4 py-2.5 rounded-lg border-2 transition-all text-left ${
                    active
                      ? 'border-emerald-500 bg-emerald-500/10 shadow-lg shadow-emerald-500/10'
                      : 'border-[var(--ff-border-light)] bg-[var(--ff-bg-primary)] hover:border-[var(--ff-text-tertiary)]'
                  }`}>
                  <div className={`w-2 h-14 rounded-full shrink-0 ${active ? 'bg-emerald-500' : 'bg-[var(--ff-border-light)]'}`} />
                  <div>
                    <p className={`text-sm font-semibold ${active ? 'text-emerald-400' : 'text-[var(--ff-text-primary)]'}`}>
                      {b.accountName}
                    </p>
                    <p className="text-xs text-[var(--ff-text-tertiary)] font-mono">
                      {b.accountCode}
                      {b.bankAccountNumber && <span className="ml-1.5">| ****{b.bankAccountNumber.slice(-4)}</span>}
                    </p>
                  </div>
                  <div className="ml-3 text-right">
                    {/* Statement balance — sum of all imported transactions */}
                    <p className={`text-sm font-bold font-mono ${b.balance >= 0 ? 'text-emerald-400' : 'text-red-400'}`}>
                      {fmtCurrency(b.balance)}
                    </p>
                    {/* Reconciled vs unreconciled breakdown */}
                    <div className="flex items-center gap-2 mt-0.5">
                      <span className="text-[10px] text-emerald-500/80 font-mono" title="Allocated to GL entries">
                        ✓ {fmtCurrency(b.reconciledBalance)}
                      </span>
                      {hasGap && (
                        <span className="text-[10px] text-amber-400 font-mono" title={`${b.unreconciledCount} unallocated transaction${b.unreconciledCount !== 1 ? 's' : ''}`}>
                          Δ {fmtCurrency(Math.abs(gap))}
                        </span>
                      )}
                    </div>
                  </div>
                </button>
              );
            })}
            {bank && (
              <div className="ml-auto flex items-center gap-4">
                <StatementBalanceWidget bankAccountId={selectedBank} glBalance={bank.balance} />
                <div className="text-right">
                  <p className="text-2xl font-bold text-[var(--ff-text-primary)]">{total}</p>
                  <p className="text-xs text-[var(--ff-text-tertiary)]">
                    {tab === 'new' ? 'To be Reviewed' : tab === 'excluded' ? 'Excluded' : 'Reviewed'}
                  </p>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Tabs */}
        <div className="px-6 border-b border-[var(--ff-border-light)]">
          <div className="flex gap-0">
            {(['new', 'reviewed', 'excluded'] as Tab[]).map(t => (
              <button key={t} onClick={() => setTab(t)}
                className={`px-5 py-2.5 text-sm font-medium border-b-2 transition-colors ${
                  tab === t
                    ? t === 'excluded'
                      ? 'border-red-500 text-red-400'
                      : 'border-emerald-500 text-emerald-400'
                    : 'border-transparent text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]'
                }`}>
                {t === 'new' ? 'New Transactions' : t === 'excluded' ? 'Excluded' : 'Reviewed Transactions'}
              </button>
            ))}
          </div>
        </div>

        {/* Toolbar — matches Sage: Actions | Mark Reviewed | Delete | Batch Edit | Import | Export | Search */}
        <div className="px-6 py-2 border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]/30 flex items-center gap-2 flex-wrap">
          <button onClick={() => loadTransactions()} title="Refresh"
            className="flex items-center gap-1 text-xs text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]">
            <RefreshCw className="h-3.5 w-3.5" /> Actions
          </button>
          {tab === 'new' && (
            <>
              <button onClick={handleBulkAccept}
                disabled={selectedIds.size === 0}
                className="flex items-center gap-1 px-2 py-1 rounded text-xs text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] disabled:opacity-30">
                <CheckCheck className="h-3.5 w-3.5" /> Mark as Reviewed
              </button>
              {selectedIds.size > 0 && (
                <button onClick={handleBatchAccept}
                  className="flex items-center gap-1 px-2 py-1 rounded text-xs text-emerald-400 hover:text-emerald-300 bg-emerald-500/10 hover:bg-emerald-500/20">
                  <CheckCheck className="h-3.5 w-3.5" /> Batch Allocate
                </button>
              )}
              <button onClick={handleBatchDelete}
                disabled={selectedIds.size === 0}
                className="flex items-center gap-1 px-2 py-1 rounded text-xs text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] disabled:opacity-30">
                <Trash2 className="h-3.5 w-3.5" /> Delete
              </button>
              <button onClick={() => { setShowBatchEdit(!showBatchEdit); setBatchSearch(''); }}
                disabled={selectedIds.size === 0}
                className="flex items-center gap-1 px-2 py-1 rounded text-xs text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] disabled:opacity-30">
                <Layers className="h-3.5 w-3.5" /> Batch Edit
              </button>
            </>
          )}
          <div className="border-l border-[var(--ff-border-light)] h-5 mx-1" />
          <Link href="/accounting/bank-reconciliation/import"
            className="flex items-center gap-1 px-2.5 py-1 rounded border border-[var(--ff-border-light)] text-xs text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]">
            <Upload className="h-3.5 w-3.5" /> Import Bank Statements
          </Link>
          <button onClick={handleExport}
            className="flex items-center gap-1 px-2.5 py-1 rounded border border-[var(--ff-border-light)] text-xs text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]">
            <Download className="h-3.5 w-3.5" /> Export
          </button>
          {/* Quick Win 4: Apply Rules */}
          <button onClick={handleApplyRules} disabled={!selectedBank}
            className="flex items-center gap-1 px-2.5 py-1 rounded border border-yellow-500/40 text-xs text-yellow-500 hover:text-yellow-400 hover:border-yellow-400 disabled:opacity-30">
            <Zap className="h-3.5 w-3.5" /> Apply Rules
          </button>
          <Link href="/accounting/bank-transactions/new"
            className="flex items-center gap-1 px-2.5 py-1 rounded border border-emerald-500/60 text-xs text-emerald-400 hover:text-emerald-300 hover:border-emerald-400 font-medium">
            <Plus className="h-3.5 w-3.5" /> New Transaction
          </Link>
          <button onClick={handleDownloadReport} disabled={!selectedBank}
            className="flex items-center gap-1 px-2.5 py-1 rounded border border-[var(--ff-border-light)] text-xs text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] disabled:opacity-30">
            <FileText className="h-3.5 w-3.5" /> Recon Report
          </button>
          {/* Date range filter */}
          <div className="flex items-center gap-1 text-xs text-[var(--ff-text-secondary)]">
            <input type="date" value={fromDate} onChange={e => { setFromDate(e.target.value); setPage(1); }}
              className="px-2 py-1 rounded bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-xs text-[var(--ff-text-primary)]" />
            <span>to</span>
            <input type="date" value={toDate} onChange={e => { setToDate(e.target.value); setPage(1); }}
              className="px-2 py-1 rounded bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-xs text-[var(--ff-text-primary)]" />
          </div>
          {/* Amount range filter */}
          <div className="flex items-center gap-1 text-xs text-[var(--ff-text-secondary)]">
            <span className="shrink-0">Min R</span>
            <input
              type="number"
              step="0.01"
              value={fromAmount}
              onChange={e => {
                setFromAmount(e.target.value);
                if (amountDebounceTimer.current) clearTimeout(amountDebounceTimer.current);
                amountDebounceTimer.current = setTimeout(() => setPage(1), 500);
              }}
              placeholder="0"
              className="w-20 px-2 py-1 rounded bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-xs text-[var(--ff-text-primary)]"
            />
            <span className="shrink-0">Max R</span>
            <input
              type="number"
              step="0.01"
              value={toAmount}
              onChange={e => {
                setToAmount(e.target.value);
                if (amountDebounceTimer.current) clearTimeout(amountDebounceTimer.current);
                amountDebounceTimer.current = setTimeout(() => setPage(1), 500);
              }}
              placeholder="any"
              className="w-20 px-2 py-1 rounded bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-xs text-[var(--ff-text-primary)]"
            />
          </div>
          {/* Quick Win 2: Server-side search (debounced 500ms) */}
          <div className="ml-auto flex items-center gap-2">
            <div className="relative">
              <Search className="absolute left-2 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-[var(--ff-text-tertiary)]" />
              <input type="text" placeholder="Search..." value={searchTerm}
                onChange={e => setSearchTerm(e.target.value)}
                className="pl-7 pr-3 py-1 rounded-lg bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-xs text-[var(--ff-text-primary)] w-44" />
            </div>
            <span className="text-xs text-[var(--ff-text-tertiary)]">
              {total > 0 ? `${(page - 1) * PAGE_SIZE + 1}–${Math.min(page * PAGE_SIZE, total)}` : '0'} of {total}
            </span>
          </div>
        </div>

        {/* Batch Edit Panel */}
        {showBatchEdit && selectedIds.size > 0 && (
          <div className="px-6 py-3 border-b border-blue-500/30 bg-blue-500/5 flex items-center gap-3 flex-wrap">
            <span className="text-xs text-blue-400 font-medium">Batch Edit ({selectedIds.size} selected):</span>
            <select value={batchType} onChange={e => { setBatchType(e.target.value as AllocType); setBatchSearch(''); }}
              className="text-xs px-2 py-1 rounded bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)]">
              <option value="account">Account</option>
              <option value="supplier">Supplier</option>
              <option value="customer">Customer</option>
            </select>
            <div className="relative">
              <input type="text" placeholder={`Search ${batchType}s...`} value={batchSearch}
                onChange={e => setBatchSearch(e.target.value)}
                className="pl-2 pr-2 py-1 rounded bg-[var(--ff-bg-primary)] border border-[var(--ff-border-light)] text-xs text-[var(--ff-text-primary)] w-52"
                autoFocus />
              <div className="absolute z-50 top-full left-0 mt-1 w-72 bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-lg shadow-xl max-h-48 overflow-y-auto">
                {batchOptions.map(o => (
                  <button key={o.id} onClick={() => applyBatchEdit(o.id, o.code ? `${o.code} ${o.name}` : o.name)}
                    className="w-full text-left px-3 py-1.5 hover:bg-[var(--ff-bg-primary)] text-xs flex items-center gap-2">
                    {o.code && <span className="font-mono text-[var(--ff-text-tertiary)]">{o.code}</span>}
                    <span className="text-[var(--ff-text-primary)]">{o.name}</span>
                  </button>
                ))}
                {batchOptions.length === 0 && (
                  <div className="px-3 py-2 text-xs text-[var(--ff-text-tertiary)]">No results found</div>
                )}
              </div>
            </div>
            <button onClick={() => setShowBatchEdit(false)}
              className="text-xs text-[var(--ff-text-tertiary)] hover:text-[var(--ff-text-primary)]">Cancel</button>
          </div>
        )}

        {/* Rule suggestion banner — appears after allocating a transaction with similar matches */}
        {rulePrompt && (
          <div className="px-6 py-3 border-b border-yellow-500/30 bg-yellow-500/5 flex items-center gap-3 flex-wrap">
            <span className="text-xs text-yellow-400 font-medium">
              {rulePrompt.matchCount} similar transaction{rulePrompt.matchCount !== 1 ? 's' : ''} found matching
              &ldquo;{extractPattern(rulePrompt.tx.description || '')}&rdquo;.
              Create a rule to auto-categorise them?
            </span>
            <button
              onClick={() => { setCreateRuleTx(rulePrompt.tx); setRulePrompt(null); }}
              className="px-3 py-1 rounded bg-yellow-500/20 hover:bg-yellow-500/30 border border-yellow-500/40 text-xs text-yellow-400 font-medium transition-colors"
            >
              Create Rule
            </button>
            <button
              onClick={() => setRulePrompt(null)}
              className="px-3 py-1 rounded text-xs text-[var(--ff-text-tertiary)] hover:text-[var(--ff-text-secondary)]"
            >
              Dismiss
            </button>
          </div>
        )}

        {/* Table */}
        <div className="px-4 py-2">
          {isLoading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="h-8 w-8 animate-spin text-blue-500" />
            </div>
          ) : error ? (
            <div className="flex items-center gap-2 text-red-400 py-8 justify-center">
              <AlertCircle className="h-5 w-5" /><span>{error}</span>
            </div>
          ) : transactions.length === 0 ? (
            <div className="text-center py-12 text-[var(--ff-text-secondary)]">
              No {tab === 'new' ? 'new' : tab === 'excluded' ? 'excluded' : 'reviewed'} transactions for this account
            </div>
          ) : (
            <BankTxTable
              transactions={transactions}
              glAccounts={glAccounts}
              suppliers={suppliers}
              customers={customers}
              cc1Options={cc1Options}
              cc2Options={cc2Options}
              buOptions={buOptions}
              selectedIds={selectedIds}
              rowSelections={rowSelections}
              allSelected={allSelected}
              tab={tab}
              onToggleSelect={toggleSelect}
              onSelectAll={() => setSelectedIds(
                allSelected ? new Set() : new Set(transactions.map(t => t.id))
              )}
              onRowTypeChange={(txId, type) => {
                // VAT only applies to GL account allocations; supplier/customer VAT is handled on their invoices
                const vatCode = type === 'account' ? (rowSelections[txId]?.vatCode || 'none') : 'none';
                setRowSelections(prev => ({ ...prev, [txId]: { type, entityId: '', label: '', vatCode } }));
                saveSelection(txId, type, '');
              }}
              onRowEntityChange={(txId, entityId, label) => {
                const type = rowSelections[txId]?.type || 'account';
                let vatCode = (rowSelections[txId]?.vatCode || 'none') as VatCode;
                if (type === 'account' && entityId) {
                  const acct = glAccounts.find(g => g.id === entityId);
                  if (acct?.defaultVatCode && acct.defaultVatCode !== 'none') {
                    vatCode = acct.defaultVatCode as VatCode;
                  }
                }
                setRowSelections(prev => ({
                  ...prev,
                  [txId]: { ...prev[txId], type, entityId, label, vatCode },
                }));
                saveSelection(txId, type as AllocType, entityId);
              }}
              onRowVatChange={(txId, vatCode) =>
                setRowSelections(prev => ({
                  ...prev,
                  [txId]: { ...prev[txId], type: prev[txId]?.type || 'account', entityId: prev[txId]?.entityId || '', label: prev[txId]?.label || '', vatCode },
                }))
              }
              onRowDimensionChange={(txId, cc1Id, cc2Id, buId) => {
                setRowSelections(prev => ({ ...prev, [txId]: { ...prev[txId], type: prev[txId]?.type || 'account', entityId: prev[txId]?.entityId || '', label: prev[txId]?.label || '', vatCode: prev[txId]?.vatCode || 'none', cc1Id: cc1Id || undefined, cc2Id: cc2Id || undefined, buId: buId || undefined } }));
                saveDimensions(txId, cc1Id, cc2Id, buId);
              }}
              onAccept={handleAccept}
              onExclude={handleExclude}
              onUnmatch={handleUnmatch}
              onSplit={handleSplit}
              onUpdateNotes={handleUpdateNotes}
              onFindMatch={(txId) => setFindMatchTxId(txId)}
              onReverse={handleReverse}
              onAttachments={(txId) => setAttachmentsTxId(txId)}
              onCreateRule={(tx) => setCreateRuleTx(tx)}
              onCreateEntity={(txId, type) => { setCreateEntityTxId(txId); setCreateEntityType(type); }}
            />
          )}
        </div>

        {/* Pagination */}
        {totalPages > 1 && (
          <div className="px-6 py-3 border-t border-[var(--ff-border-light)] flex items-center justify-between">
            <div className="flex items-center gap-1">
              <button disabled={page <= 1} onClick={() => setPage(1)}
                className="px-2 py-1 rounded text-xs text-[var(--ff-text-secondary)] disabled:opacity-30">First</button>
              {Array.from({ length: Math.min(totalPages, 10) }, (_, i) => {
                const p = totalPages <= 10 ? i + 1
                  : page <= 5 ? i + 1
                  : page >= totalPages - 4 ? totalPages - 9 + i
                  : page - 5 + i;
                return (
                  <button key={p} onClick={() => setPage(p)}
                    className={`w-7 h-7 rounded text-xs ${
                      p === page ? 'bg-emerald-600 text-white font-bold'
                        : 'text-[var(--ff-text-secondary)] hover:bg-[var(--ff-bg-secondary)]'
                    }`}>{p}</button>
                );
              })}
              <button disabled={page >= totalPages} onClick={() => setPage(totalPages)}
                className="px-2 py-1 rounded text-xs text-[var(--ff-text-secondary)] disabled:opacity-30">Last</button>
            </div>
            <span className="text-xs text-[var(--ff-text-tertiary)]">
              Displaying {(page - 1) * PAGE_SIZE + 1}–{Math.min(page * PAGE_SIZE, total)} of {total}
            </span>
          </div>
        )}

        {/* Bottom bar — Sage-style: Mark Selected as Reviewed */}
        {tab === 'new' && transactions.length > 0 && (
          <div className="sticky bottom-0 bg-[var(--ff-bg-secondary)] border-t border-[var(--ff-border-light)] px-6 py-3 flex items-center justify-center gap-4">
            <button onClick={handleBulkAccept}
              disabled={selectedIds.size === 0}
              className="px-5 py-2 bg-emerald-600 hover:bg-emerald-700 disabled:opacity-50 text-white rounded-lg text-sm font-medium">
              Mark Selected as Reviewed ({selectedIds.size})
            </button>
          </div>
        )}
      </div>
      {/* Split Transaction Modal */}
      {splitTxId && (() => {
        const splitTx = transactions.find(t => t.id === splitTxId);
        if (!splitTx) return null;
        return (
          <SplitTransactionModal
            transaction={splitTx}
            glAccounts={glAccounts}
            onClose={() => setSplitTxId(null)}
            onSplit={() => {
              setSplitTxId(null);
              loadTransactions();
            }}
          />
        );
      })()}
      {/* Exclude Reason Modal */}
      {excludingTxId && (() => {
        const excludeTx = transactions.find(t => t.id === excludingTxId);
        if (!excludeTx) return null;
        return (
          <ExcludeReasonModal
            transaction={excludeTx}
            onClose={() => setExcludingTxId(null)}
            onExclude={(reason) => handleExcludeConfirm(reason)}
          />
        );
      })()}
      {/* Find & Match Modal */}
      {findMatchTxId && (() => {
        const matchTx = transactions.find(t => t.id === findMatchTxId);
        if (!matchTx) return null;
        return (
          <FindMatchModal
            transaction={{ id: matchTx.id, description: matchTx.description || '', amount: matchTx.amount, transactionDate: matchTx.transactionDate }}
            onClose={() => setFindMatchTxId(null)}
            onMatch={() => { setFindMatchTxId(null); loadTransactions(); }}
          />
        );
      })()}
      {/* Attachments Modal */}
      {attachmentsTxId && (
        <BankTxAttachmentsModal
          bankTransactionId={attachmentsTxId}
          transactionDescription={transactions.find(t => t.id === attachmentsTxId)?.description}
          onClose={() => setAttachmentsTxId(null)}
        />
      )}
      {/* Create Rule Modal */}
      {createRuleTx && (
        <CreateRuleModal
          transaction={createRuleTx}
          bankAccountId={selectedBank}
          glAccounts={glAccounts}
          suppliers={suppliers}
          clients={customers}
          onClose={() => setCreateRuleTx(null)}
          onCreated={() => {
            setCreateRuleTx(null);
            toast.success('Rule created — click "Apply Rules" to categorise matching transactions');
            loadTransactions();
          }}
        />
      )}
      {/* Create Entity Modal (GL Account / Supplier / Customer) */}
      {createEntityTxId && createEntityType && (
        <CreateEntityModal
          type={createEntityType}
          onClose={() => { setCreateEntityTxId(null); setCreateEntityType(null); }}
          onCreated={(entity) => {
            const label = entity.code ? `${entity.code} ${entity.name}` : entity.name;
            const option: SelectOption = { id: entity.id, code: entity.code, name: entity.name };
            if (createEntityType === 'account') {
              setGlAccounts(prev => [...prev, option].sort((a, b) => (a.code || '').localeCompare(b.code || '')));
            } else if (createEntityType === 'supplier') {
              setSuppliers(prev => [...prev, option]);
            } else {
              setCustomers(prev => [...prev, option]);
            }
            setRowSelections(prev => ({
              ...prev,
              [createEntityTxId]: {
                type: createEntityType,
                entityId: entity.id,
                label,
                vatCode: prev[createEntityTxId]?.vatCode || 'none',
              },
            }));
            setCreateEntityTxId(null);
            setCreateEntityType(null);
          }}
        />
      )}
    </AppLayout>
  );
}

/**
 * Create Credit Note Page
 * PRD-060 Phase 3: Customer & Supplier credit notes
 */

import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import { ArrowLeft, FileText, Loader2 } from 'lucide-react';

interface Client { id: string; company_name: string }
interface Supplier { id: number; name: string }

function formatCurrency(amount: number): string {
  return new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(amount);
}

export default function NewCreditNotePage() {
  const router = useRouter();
  const [clients, setClients] = useState<Client[]>([]);
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState('');

  const [form, setForm] = useState({
    type: 'customer' as 'customer' | 'supplier',
    clientId: '',
    supplierId: '',
    creditDate: new Date().toISOString().split('T')[0],
    reason: '',
    subtotal: 0,
    taxRate: 15,
  });

  const taxAmount = Math.round(form.subtotal * form.taxRate / 100 * 100) / 100;
  const totalAmount = form.subtotal + taxAmount;

  useEffect(() => {
    fetch('/api/clients').then(r => r.json()).then(res => {
      const data = res.data || res;
      setClients(Array.isArray(data) ? data : data.clients || []);
    });
    fetch('/api/suppliers').then(r => r.json()).then(res => {
      const data = res.data || res;
      setSuppliers(Array.isArray(data) ? data : data.suppliers || []);
    });
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setIsSubmitting(true);

    try {
      const res = await fetch('/api/accounting/credit-notes', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          type: form.type,
          clientId: form.type === 'customer' ? form.clientId : undefined,
          supplierId: form.type === 'supplier' ? form.supplierId : undefined,
          creditDate: form.creditDate,
          reason: form.reason || undefined,
          subtotal: form.subtotal,
          taxRate: form.taxRate,
        }),
      });

      const json = await res.json();
      if (!res.ok) throw new Error(json.message || json.error || 'Failed to create credit note');
      router.push('/accounting/credit-notes');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to create credit note');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)]">
          <div className="px-6 py-4">
            <Link href="/accounting/credit-notes" className="inline-flex items-center gap-1 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] mb-2">
              <ArrowLeft className="h-4 w-4" /> Back to Credit Notes
            </Link>
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-emerald-500/10">
                <FileText className="h-6 w-6 text-emerald-500" />
              </div>
              <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">New Credit Note</h1>
            </div>
          </div>
        </div>

        <form onSubmit={handleSubmit} className="p-6 max-w-3xl space-y-6">
          {error && (
            <div className="p-3 rounded-lg bg-red-500/10 text-red-400 text-sm">{error}</div>
          )}

          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-6 space-y-4">
            <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">Credit Note Details</h2>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Type *</label>
                <select
                  value={form.type}
                  onChange={e => setForm(f => ({ ...f, type: e.target.value as 'customer' | 'supplier', clientId: '', supplierId: '' }))}
                  className="ff-select w-full"
                >
                  <option value="customer">Customer Credit Note</option>
                  <option value="supplier">Supplier Credit Note</option>
                </select>
              </div>

              {form.type === 'customer' ? (
                <div>
                  <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Client *</label>
                  <select
                    value={form.clientId}
                    onChange={e => setForm(f => ({ ...f, clientId: e.target.value }))}
                    className="ff-select w-full"
                    required
                  >
                    <option value="">Select client...</option>
                    {clients.map(c => <option key={c.id} value={c.id}>{c.company_name}</option>)}
                  </select>
                </div>
              ) : (
                <div>
                  <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Supplier *</label>
                  <select
                    value={form.supplierId}
                    onChange={e => setForm(f => ({ ...f, supplierId: e.target.value }))}
                    className="ff-select w-full"
                    required
                  >
                    <option value="">Select supplier...</option>
                    {suppliers.map(s => <option key={s.id} value={String(s.id)}>{s.name}</option>)}
                  </select>
                </div>
              )}

              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Credit Date *</label>
                <input
                  type="date"
                  value={form.creditDate}
                  onChange={e => setForm(f => ({ ...f, creditDate: e.target.value }))}
                  className="ff-input w-full"
                  required
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Reason</label>
                <input
                  type="text"
                  value={form.reason}
                  onChange={e => setForm(f => ({ ...f, reason: e.target.value }))}
                  className="ff-input w-full"
                  placeholder="Reason for credit note"
                />
              </div>
            </div>
          </div>

          {/* Amounts */}
          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-6 space-y-4">
            <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">Amounts</h2>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">Subtotal (excl. VAT) *</label>
                <input
                  type="number"
                  step="0.01"
                  min="0"
                  value={form.subtotal || ''}
                  onChange={e => setForm(f => ({ ...f, subtotal: Number(e.target.value) }))}
                  className="ff-input w-full"
                  required
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">VAT Rate (%)</label>
                <input
                  type="number"
                  step="0.01"
                  min="0"
                  value={form.taxRate}
                  onChange={e => setForm(f => ({ ...f, taxRate: Number(e.target.value) }))}
                  className="ff-input w-full"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-[var(--ff-text-secondary)] mb-1">VAT Amount</label>
                <div className="ff-input w-full bg-[var(--ff-bg-primary)] text-[var(--ff-text-secondary)]">
                  {formatCurrency(taxAmount)}
                </div>
              </div>
            </div>

            <div className="pt-3 border-t border-[var(--ff-border-light)] flex justify-between items-center">
              <span className="text-sm font-medium text-[var(--ff-text-secondary)]">Total Amount</span>
              <span className="text-xl font-bold text-[var(--ff-text-primary)]">{formatCurrency(totalAmount)}</span>
            </div>
          </div>

          {/* Submit */}
          <div className="flex justify-end gap-3">
            <Link href="/accounting/credit-notes" className="px-4 py-2 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]">
              Cancel
            </Link>
            <button
              type="submit"
              disabled={isSubmitting || form.subtotal <= 0}
              className="inline-flex items-center gap-2 px-6 py-2 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 disabled:opacity-50 transition-colors text-sm font-medium"
            >
              {isSubmitting && <Loader2 className="h-4 w-4 animate-spin" />}
              Create Credit Note
            </button>
          </div>
        </form>
      </div>
    </AppLayout>
  );
}

/**
 * Credit Notes List Page
 * PRD-060 Phase 3: Customer & Supplier credit notes
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import {
  FileText, Plus, Loader2, AlertCircle, ChevronRight, Filter, Download,
} from 'lucide-react';
import type { CreditNote, CreditNoteStatus } from '@/modules/accounting/types/ar.types';

const STATUS_OPTIONS: { value: string; label: string }[] = [
  { value: '', label: 'All Statuses' },
  { value: 'draft', label: 'Draft' },
  { value: 'approved', label: 'Approved' },
  { value: 'applied', label: 'Applied' },
  { value: 'cancelled', label: 'Cancelled' },
];

const TYPE_OPTIONS: { value: string; label: string }[] = [
  { value: '', label: 'All Types' },
  { value: 'customer', label: 'Customer' },
  { value: 'supplier', label: 'Supplier' },
];

function StatusBadge({ status }: { status: string }) {
  const colors: Record<string, string> = {
    draft: 'bg-gray-500/20 text-gray-400',
    approved: 'bg-emerald-500/20 text-emerald-400',
    applied: 'bg-blue-500/20 text-blue-400',
    cancelled: 'bg-red-500/20 text-red-400',
  };
  return (
    <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ${colors[status] || 'bg-gray-500/20 text-gray-400'}`}>
      {status}
    </span>
  );
}

function TypeBadge({ type }: { type: string }) {
  const colors: Record<string, string> = {
    customer: 'bg-blue-500/20 text-blue-400',
    supplier: 'bg-orange-500/20 text-orange-400',
  };
  return (
    <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ${colors[type] || 'bg-gray-500/20 text-gray-400'}`}>
      {type}
    </span>
  );
}

function formatCurrency(amount: number): string {
  return new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(amount);
}

export default function CreditNotesPage() {
  const [creditNotes, setCreditNotes] = useState<CreditNote[]>([]);
  const [total, setTotal] = useState(0);
  const [statusFilter, setStatusFilter] = useState('');
  const [typeFilter, setTypeFilter] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');

  const loadCreditNotes = useCallback(async () => {
    setIsLoading(true);
    setError('');
    try {
      const params = new URLSearchParams();
      if (statusFilter) params.set('status', statusFilter);
      if (typeFilter) params.set('type', typeFilter);
      const res = await fetch(`/api/accounting/credit-notes?${params}`);
      const json = await res.json();
      const payload = json.data || json;
      setCreditNotes(payload.creditNotes || []);
      setTotal(payload.total || 0);
    } catch {
      setError('Failed to load credit notes');
    } finally {
      setIsLoading(false);
    }
  }, [statusFilter, typeFilter]);

  useEffect(() => { loadCreditNotes(); }, [loadCreditNotes]);

  const exportCSV = () => {
    const headers = ['CN #', 'Type', 'Client/Supplier', 'Invoice', 'Date', 'Amount', 'Status'];
    const rows = creditNotes.map(cn => [
      cn.creditNoteNumber, cn.type,
      cn.type === 'customer' ? cn.clientName : cn.supplierName || '',
      cn.invoiceNumber || '', new Date(cn.creditDate).toLocaleDateString('en-ZA'),
      cn.totalAmount, cn.status,
    ]);
