903→      {/* Attachments Modal */}
904→      {attachmentsTxId && (
905→        <BankTxAttachmentsModal
906→          bankTransactionId={attachmentsTxId}
907→          transactionDescription={transactions.find(t => t.id === attachmentsTxId)?.description}
908→          onClose={() => setAttachmentsTxId(null)}
909→        />
910→      )}
911→      {/* Create Rule Modal */}
912→      {createRuleTx && (
913→        <CreateRuleModal
914→          transaction={createRuleTx}
915→          bankAccountId={selectedBank}
916→          glAccounts={glAccounts}
917→          suppliers={suppliers}
918→          clients={customers}
919→          onClose={() => setCreateRuleTx(null)}
920→          onCreated={() => {
921→            setCreateRuleTx(null);
922→            toast.success('Rule created — click "Apply Rules" to categorise matching transactions');
923→            loadTransactions();
924→          }}
925→        />
926→      )}
927→      {/* Create Entity Modal (GL Account / Supplier / Customer) */}
928→      {createEntityTxId && createEntityType && (
929→        <CreateEntityModal
930→          type={createEntityType}
931→          onClose={() => { setCreateEntityTxId(null); setCreateEntityType(null); }}
932→          onCreated={(entity) => {
933→            const label = entity.code ? `${entity.code} ${entity.name}` : entity.name;
934→            const option: SelectOption = { id: entity.id, code: entity.code, name: entity.name };
935→            if (createEntityType === 'account') {
936→              setGlAccounts(prev => [...prev, option].sort((a, b) => (a.code || '').localeCompare(b.code || '')));
937→            } else if (createEntityType === 'supplier') {
938→              setSuppliers(prev => [...prev, option]);
